INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thinhtt264/SnapletApp/gradle-build-performance', 'gradle-build-performance', 'thinhtt264', 'SnapletApp', 'community', 'gradle-build-performance thinhtt264 SnapletApp community 使用Kotlin Jetpack Compose构建Locket Clone App，优化Gradle构建性能，提高开发效率 Kotlin Jetpack ComposeでLocket Clone Appを構築し、Gradleビルドパフォーマンスを最適化して開発効率を向上 Kotlin Jetpack Compose로 Locket Clone App를 구축하고 Gradle 빌드 성능을 최적화하여 개발 효율을 개선 La aplicación Locket Clone utiliza Kotlin y Jetpack Compose para mejorar el rendimiento de construcción de Gradle L''application Locket Clone utilise Kotlin et Jetpack Compose pour améliorer les performances de construction de Gradle Die Locket-Clone-App verwendet Kotlin und Jetpack Compose, um die Gradle-Build-Performance zu verbessern A ferramenta de IA para Gradle melhora o desempenho de build do seu projeto. Aprenda a utilizar a Locket Clone App com Kotlin Jetpack compose ИИ Агенты для Gradle улучшают производительность сборки вашего проекта. Узнайте, как использовать Locket Clone App с Kotlin Jetpack compose أدوات الذكاء الاصطناعي للجرادل تحسّن أداء بناء مشروعك. تعرّف على كيفية استخدام تطبيق Locket Clone مع Kotlin Jetpack compose Locket Clone App using Kotlin Jetpack compose Gradle构建性能优化 Kotlin Jetpack Compose Locket Clone App Android App开发 如何优化Gradle构建 Gradle构建性能优化工具 Kotlin开发 Jetpack Compose开发 Android开发最佳实践 Locket Clone App using Kotlin Jetpack compose');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cjjohansen/drone-web/event-storming', 'community', 'cjjohansen', 'drone-web', 'cjjohansen/drone-web', 'event-storming', 0, 0, 49, '2026-03-04T13:07:01.942Z', '2026-03-04T15:09:42.297Z', '7c8575383f69532b5e06dbcbc1747f75ac8e0a4feab0e8935fe303292dcbcb4c', '{"id":"cjjohansen/drone-web/event-storming","name":"event-storming","description":{"zh":"Event Storming是用于创建无人机电子商务网站的ADDR设计过程的一部分，帮助开发者设计和优化系统","ja":"イベントストーミングは、ドローンECサイトを作成するADDR設計プロセスの1つであり、開発者がシステムを設計および最適化するのに役立ちます","ko":"이벤트 스토밍은 드론 전자상거래 사이트를 생성하는 ADDR 디자인 프로세스의 일부로 개발자가 시스템을 설계 및 최적화하는 데 도움이 됩니다","es":"Event-storming es una técnica para diseñar sitios web de ecommerce de drones utilizando el proceso ADDR Design","fr":"L''event-storming est une technique pour concevoir des sites ecommerce de drones en utilisant le processus de conception ADDR","de":"Event-Storming ist eine Technik, um Drohnen-Ecommerce-Websites mithilfe des ADDR-Design-Prozesses zu entwerfen","pt":"Desenvolva um site de ecommerce de drones com o processo de design ADDR e tecnologias de inteligência artificial","ru":"Разработайте сайт электронной коммерции для дронов с помощью процесса дизайна ADDR и технологий ИИ","ar":"قم ببناء موقع إلكتروني للتجارة الإلكترونية للطائرات بدون طيار باستخدام عملية التصميم ADDR وتكنولوجيا الذكاء الاصطناعي","en":"drone ecommerce website using ADDR Design process"},"seo":{"title":{"zh":"AI智能代理 - 事件风暴 Event Storming","ja":"AIエージェント - イベントストーミング","ko":"AI 에이전트 - 이벤트 스토밍","es":"Herramientas de event-storming para sitios web de ecommer...","fr":"Outils d''event-storming pour les sites ecommerce de drones","de":"AI-Tools für Event-Storming auf Drohnen-Ecommerce-Websites","pt":"Ferramentas de Inteligência Artificial para Event Storming","ru":"ИИ Агенты для Event Storming","ar":"أدوات ذكاء اصطناعي لتصميم ADDR","en":"event-storming"},"description":{"zh":"Event 