INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('phidvss55/.net10/dotnet-core-expert', 'dotnet-core-expert', 'phidvss55', '.net10', 'community', 'dotnet-core-expert phidvss55 .net10 community The dotnet-core-expert skill enables senior .NET engineers to build high-performance, cloud-native applications with .NET 8 and modern C#. It benefits enterprise application developers. .NET Core 专家提供高性能、可扩展的应用程序开发解决方案，使用 .NET 8、C# 12 和最小 API .NET Core エキスパートは、高パフォーマンスでスケーラブルなクラウドネイティブアプリケーションを開発するための専門家です .NET Core 전문가는 고성능, 확장 가능한 클라우드 네이티브 애플리케이션 개발을 위한 전문가입니다 El experto en dotnet-core-expert es un especialista senior en .NET 8, C# 12 y aplicaciones en la nube L''expert dotnet-core-expert est un spécialiste senior en .NET 8, C# 12 et applications cloud Der dotnet-core-expert ist ein Senior-Spezialist für .NET 8, C# 12 und Cloud-Anwendungen O .NET Core Expert é um especialista sênior em .NET com experiência em .NET 8, C# 12, minimal APIs e desenvolvimento de aplicações nativas em nuvem ИИ Агент .NET Core Expert - это старший специалист по .NET с опытом работы с .NET 8, C# 12, минимальными API и разработкой облачных приложений خبير النيت كور هو خبير أول في النيت مع خبرة في النيت 8، سي شارب 12، واجهات برمجة التطبيقات المحدودة وتطوير التطبيقات الأصلية في السحابة dotnet-core-expert setup guide how to use dotnet-core-expert for cloud-native applications dotnet-core-expert vs .NET framework dotnet-core-expert install for enterprise applications what is dotnet-core-expert and its benefits dotnet-core-expert alternative for .NET development dotnet-core-expert tutorial for senior .NET engineers dotnet-core-expert best practices for scalable applications dotnet-core-expert and C# 12 development dotnet-core-expert for building minimal APIs .NET Core 专家 高性能应用开发 .NET 8 C# 12 最小 API 云原生应用程序 Entity Framework Core 高可扩展性应用程序 Builds minimal APIs with .NET 8 Utilizes Entity Framework Core for data access Supports cloud-native patterns for scalable applications Develops high-performance applications with clean architecture Leverages C# 12 for modern C# development Integrates with cloud-native services for enterprise applications dotnet-core-expert is a senior .NET Core specialist skill with expertise in .NET 8, minimal APIs, and cloud-native application development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flet-dev/flet/prepare-flet-release', 'community', 'flet-dev', 'flet', 'flet-dev/flet', 'prepare-flet-release', 15691, 626, 48, '2026-03-05T13:02:10Z', '2026-03-06T06:24:12.848Z', '09f44631b20930d607dc90285ee0947368b5d285757e23b6ec7e0b35c6c646e4', '{"id":"flet-dev/flet/prepare-flet-release","name":"prepare-flet-release","description":{"en":"The prepare-flet-release skill automates Flet versioning for developers, enabling easy build and release of real-time web, mobile, and desktop apps in Python. It benefits developers by simplifying the release process.","zh":"Flet 发布准备技能自动化 Flet 项目的版本更新和发布过程，支持 Python 语言。该技能可以自动更新版本号、刷新依赖项和生成变更日志。","ja":"Flet リリース準備スキルは、Flet プロジェクトのバージョン更新とリリースプロセスを自動化します。Python 言語をサポートし、バージョン番号の更新、依存関係の更新、変更ログの生成などを行います。","ko":"Flet 릴리즈 준비 스킬은 Flet 프로젝트의 버전 업데이트 및 릴리즈 프로세스를 자동화합니다. Python 언어를 지원하며 버전 번호 업데이트와 의존성 갱신 및 변경 로그 생성 등을 수행합니다.","es":"Prepare-flet-release es una herramienta que permite a los desarrolladores configurar fácilmente sus proyectos Flet para crear aplicaciones web, móviles y de escritorio en Python","fr":"Prepare-flet-release est un outil qui permet aux développeurs de configurer facilement leurs projets Flet pour créer des applications web, mobiles et de bureau en Python","de":"Prepare-flet-release ist ein Tool, das es Entwicklern ermöglicht, ihre Flet-Projekte einfach zu konfigurieren, um Web-, Mobile- und Desktop-Anwendungen in Python zu erstellen","pt":"O prepare-flet-release permite que desenvolvedores criem aplicações em Python sem experiência em frontend. Ele automatiza a atualização da versão do Flet e gera um novo registro de alterações.","ru":"Prepare-flet-release позволяет разработчикам создавать приложения на Python без опыта в frontend. Он автоматизирует обновление версии Flet и генерирует новый журнал изменений.","ar":"يسمح prepare-flet-release للمطورين بإنشاء تطبيقات بايثون بدون خبرة في واجهة المستخدم. ي自动 تحديث إصدار Flet وينشئ سجل تعديلات جديد"},"seo":{"title":{"en":"prepare-flet-release: Automated Flet Versioning Setup Gui...","zh":"Flet 发布准备指南 - AIエージェント工具","ja":"Flet リリース準備ガイド - AIエージェント","ko":"Flet 릴리즈 준비 가이드 - AI 에이전트","es":"Guía de Configuración para prepare-flet-release: Mejores ...","fr":"Guide de Configuration pour prepare-flet-release: Bonnes ...","de":"Konfigurationsleitfaden für prepare-flet-release: Best Pr...","pt":"Guia de Configuração do prepare-flet-release para Desenvo...","ru":"Настройка prepare-flet-release: Руководство для Разработч...","ar":"دليل إعداد prepare-flet-release لمنصة تطوير الأدوات الذكية"},"description":{"en":"Streamline your Flet development workflow with prepare-flet-release. Learn how to automate versioning and simplify your release process. Get started now!","zh":"使用 Flet 发布准备技能，轻松构建实时 Web、移动和桌面应用程序。了解如何自动化版本更新和发布过程。","ja":"Flet リリース準備スキルを使用して、リアルタイム Web、モバイル、デスクトップ アプリを簡単に構築します。バージョン更新とリリースプロセスの自動化方法について学びます。","ko":"Flet 릴리즈 준비 스킬을 사용하여 실시간 웹, 모바일, 데스크톱 앱을 쉽게 구축합니다. 버전 업데이트 및 릴리즈 프로세스의 자동화 방법에 대해 알아보세요.","es":"Aprende a configurar prepare-flet-release para tus proyectos de desarrollo de aplicaciones en Python con Flet, la herramienta de interfaz de usuario en tiemp...","fr":"Découvrez comment configurer prepare-flet-release pour vos projets de développement d''applications en Python avec Flet, l''outil d''interface utilisateur en te...","de":"Erfahren Sie, wie Sie prepare-flet-release für Ihre Python-Entwicklungsprojekte mit Flet, dem Tool für Server-seitige Benutzeroberflächen in Echtzeit, konfig...","pt":"Aprenda a configurar o prepare-flet-release para criar aplicações web, mobile e desktop em Python com facilidade","ru":"Узнайте, как настроить prepare-flet-release для создания веб-, мобильных и настольных приложений на Python с помощью ИИ Агентов","ar":"اكتشف كيفية إعداد prepare-flet-release لإنشاء تطبيقات الويب والأندرويد و سطح المكتب باستخدام بايثون على منصة الأدوات الذكية"},"definition":{"en":"prepare-flet-release is a skill that automates the Flet release process by incrementing version numbers and updating relevant files, such as pubspec.yaml and CHANGELOG.md.","zh":"Flet 发布准备技能是一种 AI 工具，用于自动化 Flet 项目的版本更新和发布过程。","ja":"Flet リリース準備スキルは、Flet プロジェクトのバージョン更新とリリースプロセスを自動化する AI エージェントです。","ko":"Flet 릴리즈 준비 스킬은 Flet 프로젝트의 버전 업데이트와 릴리즈 프로세스를 자동화하는 AI 에이전트입니다.","es":"Prepare-flet-release es una herramienta de línea de comandos que actualiza la versión de Flet y genera un registro de cambios para cada lanzamiento","fr":"Prepare-flet-release est un outil en ligne de commande qui met à jour la version de Flet et génère un journal des modifications pour chaque version","de":"Prepare-flet-release ist ein Kommandozeilen-Tool, das die Flet-Version aktualisiert und ein Änderungsprotokoll für jede Version generiert","pt":"O prepare-flet-release é uma ferramenta que automatiza a preparação de lançamentos do Flet, uma plataforma para criar aplicações web, mobile e desktop em Python","ru":"Prepare-flet-release - это инструмент, который автоматизирует подготовку выпусков Flet, платформы для создания веб-, мобильных и настольных приложений на Python","ar":"prepare-flet-release هو أداة تautomatize إعداد إصدارات Flet، وهي منصة لإنشاء تطبيقات الويب والأندرويد و سطح المكتب باستخدام بايثون"},"features":{"en":["Increments Flet version numbers based on minor or major release type","Updates pubspec.yaml with the new version number","Runs pub get to refresh pubspec.lock","Generates a new entry in CHANGELOG.md from git log","Supports automated release process for Flet apps"],"zh":["自动更新 Flet 项目的版本号","刷新依赖项并生成变更日志","支持 Python 语言","自动化版本更新和发布过程","集成 Git 日志以生成变更日志"],"ja":["Flet プロジェクトのバージョン番号を自動更新","依存関係を更新し、変更ログを生成","Python 言語をサポート","バージョン更新とリリースプロセスを自動化","Git ログを統合して変更ログを生成"],"ko":["Flet 프로젝트의 버전 번호 자동 업데이트","의존성 갱신 및 변경 로그 생성","Python 언어 지원","버전 업데이트 및 릴리즈 프로세스 자동화","Git 로그 통합을 통한 변경 로그 생성"],"es":["Actualiza la versión de Flet en el archivo pubspec.yaml","Ejecuta pub get para actualizar el archivo pubspec.lock","Genera un registro de cambios en el archivo CHANGELOG.md","Soporta lanzamientos menores y mayores","Compatible con Python y Flet","Permite la creación de aplicaciones web, móviles y de escritorio"],"fr":["Met à jour la version de Flet dans le fichier pubspec.yaml","Exécute pub get pour mettre à jour le fichier pubspec.lock","Génère un journal des modifications dans le fichier CHANGELOG.md","Prend en charge les versions mineures et majeures","Compatible avec Python et Flet","Permet la création d''applications web, mobiles et de bureau"],"de":["Aktualisiert die Flet-Version in der Datei pubspec.yaml","Führt pub get aus, um die Datei pubspec.lock zu aktualisieren","Generiert ein Änderungsprotokoll in der Datei CHANGELOG.md","Unterstützt kleine und große Veröffentlichungen","Kompatibel mit Python und Flet","Ermöglicht die Erstellung von Web-, Mobile- und Desktop-Anwendungen"],"pt":["Atualização automática da versão do Flet","Geração de novo registro de alterações","Compatibilidade com Python","Suporte a aplicações web, mobile e desktop","Integração com o Flutter","Atualização da versão no arquivo pubspec.yaml"],"ru":["Автоматическое обновление версии Flet","Генерация нового журнала изменений","Совместимость с Python","Поддержка веб-, мобильных и настольных приложений","Интеграция с Flutter","Обновление версии в файле pubspec.yaml"],"ar":["تحديث تلقائي لإصدار Flet","إنشاء سجل تعديلات جديد","التوافق مع بايثون","دعم تطبيقات الويب والأندرويد و سطح المكتب","التكامل مع Flutter","تحديث الإصدار في ملف pubspec.yaml"]},"keywords":{"en":["how to use prepare-flet-release","prepare-flet-release setup guide","Flet versioning automation","prepare-flet-release alternative","prepare-flet-release vs manual versioning","prepare-flet-release install","automated Flet release process","prepare-flet-release tutorial","Flet development workflow optimization"],"zh":["Flet 发布准备","AIエージェント工具","Python 实时应用","自动化版本更新","发布过程优化","Flet 项目管理","Git 日志集成","依存关系管理"],"ja":["Flet リリース準備","AIエージェント","Python リアルタイムアプリ","バージョン更新自動化","リリースプロセス最適化","Flet プロジェクト管理","Git ログ統合","依存関係管理"],"ko":["Flet 릴리즈 준비","AI 에이전트","Python 실시간 앱","버전 업데이트 자동화","릴리즈 프로세스 최적화","Flet 프로젝트 관리","Git 로그 통합","의존성 관리"],"es":["prepare-flet-release","Flet","Python","desarrollo de aplicaciones","herramientas de desarrollo","interfaz de usuario en tiempo real","aplicaciones web","aplicaciones móviles","aplicaciones de escritorio","Herramientas de línea de comandos"],"fr":["prepare-flet-release","Flet","Python","développement d''applications","outils de développement","interface utilisateur en temps réel","applications web","applications mobiles","applications de bureau","Outils en ligne de commande"],"de":["prepare-flet-release","Flet","Python","Anwendungsentwicklung","Entwicklungstools","Benutzeroberfläche in Echtzeit","Webanwendungen","Mobile Anwendungen","Desktop-Anwendungen","Kommandozeilen-Tools"],"pt":["prepare-flet-release","Flet","Python","aplicações web","aplicações mobile","aplicações desktop","Flutter","desenvolvimento de software","ferramentas de desenvolvimento","automatização de lançamentos"],"ru":["prepare-flet-release","Flet","Python","веб-приложения","мобильные приложения","настольные приложения","Flutter","разработка программного обеспечения","инструменты разработки","автоматизация выпусков","ИИ Агенты"],"ar":["prepare-flet-release","Flet","Python","تطبيقات الويب","تطبيقات الأندرويد","تطبيقات سطح المكتب","Flutter","تطوير البرمجيات","أدوات التطوير","الآليات التلقائية لإصدارات","الأدوات الذكية"]}},"owner":"flet-dev","repo":"flet","repoPath":"flet-dev/flet","stars":15691,"forks":626,"updatedAt":"2026-03-05T13:02:10Z","topics":["android","cross-platform","desktop","flutter","ios","python","server-driven-ui","web"],"category":"community","skillMd":{"name":"prepare-flet-release","description":"Use when asked to prepare new Flet release by bumping versions and author release notes.","bodyPreview":"## Inputs\n\n* Previous Flet version from repo tags.\n* Whether it''s minor or major release.\n\n## Steps\n\n* Take latest Flet release version from the repo and\n  increment third (patch) digit to get the next version if it''s a minor release\n  or second (minor) digit if it''s a major release.\n* Set new version in packages/flet/pubspec.yaml.\n* Run pub get in /client dir to refresh pubspec.lock with new version.\n* Add a new entry into packages/flet/CHANGELOG.md from a git log since the last release. Go thr","body":"## Inputs\n\n* Previous Flet version from repo tags.\n* Whether it''s minor or major release.\n\n## Steps\n\n* Take latest Flet release version from the repo and\n  increment third (patch) digit to get the next version if it''s a minor release\n  or second (minor) digit if it''s a major release.\n* Set new version in packages/flet/pubspec.yaml.\n* Run pub get in /client dir to refresh pubspec.lock with new version.\n* Add a new entry into packages/flet/CHANGELOG.md from a git log since the last release. Go through all commits and collect all mentioned issues and pull requests. There could be several issues done in a single PR (commit) - group them by creating a single descriptive change/fix/feature item and put all issues and PR links in `[#<issue_number>](<issue_url>)` format in braces next to it. Do not add chore/trivial/duplicate items.\n  Every changelog item must include both related issue link(s) and PR link(s) when available (issue first, PR second). If no issue exists, include PR link(s) only.\n  Also include issue-only items when a change was done via direct commit without PR (for example, an issue referenced in commit context but no PR exists).\n  As it''s a Flutter package prefer items having changes on Flutter side.\n* Add a new entry into /CHANGELOG.md. Do not add chore/trivial/duplicate items, add \"worth while\" items with related issue or PR.\n  Every changelog item must include both related issue link(s) and PR link(s) when available (issue first, PR second). If no issue exists, include PR link(s) only.\n  Also include issue-only items when a change was done via direct commit without PR (for example, an issue referenced in commit context but no PR exists).\n* If any changelog has an `Unreleased` section, convert that section into the new release section (`## {new_version}`), preserving and re-sorting its items. Do not leave duplicate release content in both `Unreleased` and `{new_version}`.\n* Sort items in changelogs as following:\n  * New features\n  * Improvements\n  * Bug fixes\n  * Other changes (chore, refactor, etc.)\n* Check that `{new_version}` branch (without `v`, just version number) exists in `flet/flet-build-template` repository.\n  If not, add/derive that branch from a previous version.\n* Check that `{new_version}` branch (without `v`, just version number) exists in `flet/flet-app-templates` repository.\n  If not, add/derive that branch from a previous version.\n"},"lastSynced":"2026-03-06T06:24:12.848Z","agentAnalysis":{"suitability":{"en":"Ideal for Python Development Agents requiring streamlined Flet versioning and release management for real-time web, mobile, and desktop applications.","zh":"适用于需要流畅的Flet版本管理和实时Web、移动和桌面应用程序的Python开发代理。","ja":"Python開発エージェント向けに、Fletのバージョニングとリリース管理をストリームライン化するために最適です。","ko":"실시간 웹, 모바일, 데스크톱 애플리케이션을 위한 Flet 버전 관리 및 릴리스 관리가 필요한 Python 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de Python que requieren una versión y administración de lanzamientos de Flet optimizadas para aplicaciones web, móviles y de escritorio en tiempo real.","fr":"Idéal pour les agents de développement Python nécessitant une version et une gestion de publication de Flet simplifiées pour les applications web, mobiles et de bureau en temps réel.","de":"Ideal für Python-Entwicklungsagenten, die eine optimierte Flet-Versionierung und -Veröffentlichungsverwaltung für Echtzeit-Web-, Mobile- und Desktop-Anwendungen benötigen.","pt":"Ideal para Agentes de Desenvolvimento Python que exigem versionamento e gerenciamento de lançamento do Flet otimizados para aplicações web, móveis e de desktop em tempo real.","ru":"Идеально подходит для агентов разработки Python, требующих оптимизированного управления версиями и выпусками Flet для веб-, мобильных и настольных приложений в режиме реального времени.","ar":"مثالي لعميل تطوير بايثون الذي يتطلب إدارة إصدار وتحديث فليت بخطوات سهلة لبرامج الويب والجوال والكمبيوتر في الوقت الفعلي."},"recommendation":{"en":"Empowers agents to automate Flet versioning by incrementing patch or minor digits, updating pubspec.yaml, and refreshing pubspec.lock, leveraging Git logs for CHANGELOG.md entries and supporting pub get protocols.","zh":"通过增量补丁或次要数字、更新pubspec.yaml和刷新pubspec.lock来实现Flet版本的自动化，同时利用Git日志来记录CHANGELOG.md条目并支持pub get协议。","ja":"パッチまたはマイナーバージョンのインクリメント、pubspec.yamlの更新、pubspec.lockの更新を行い、GitログからCHANGELOG.mdのエントリを生成し、pub getプロトコルをサポートすることで、Fletバージョニングを自動化します。","ko":"패치 또는 마이너 버전의 증분, pubspec.yaml의 업데이트 및 pubspec.lock의 갱신을 통해 Flet 버전을 자동화하고, Git 로그에서 CHANGELOG.md 항목을 생성하며 pub get 프로토콜을 지원합니다.","es":"Habilita a los agentes a automatizar la versión de Flet incrementando los dígitos de revisión o menores, actualizando pubspec.yaml y refrescando pubspec.lock, aprovechando los registros de Git para entradas de CHANGELOG.md y admitiendo protocolos pub get.","fr":"Autonomise les agents pour automatiser la version de Flet en incrémentant les chiffres de correction ou mineurs, en mettant à jour pubspec.yaml et en actualisant pubspec.lock, en exploitant les journaux Git pour les entrées de CHANGELOG.md et en prenant en charge les protocoles pub get.","de":"Ermächtigt die Agenten, die Flet-Version zu automatisieren, indem die Patch- oder Minor-Ziffern inkrementiert, pubspec.yaml aktualisiert und pubspec.lock aktualisiert werden, wobei die Git-Protokolle für CHANGELOG.md-Einträge genutzt und die pub get-Protokolle unterstützt werden.","pt":"Permite que os agentes automatizem o versionamento do Flet aumentando os dígitos de patch ou menor, atualizando o pubspec.yaml e atualizando o pubspec.lock, aproveitando os logs do Git para entradas do CHANGELOG.md e suportando protocolos pub get.","ru":"Позволяет агентам автоматизировать управление версиями Flet, увеличивая цифры патча или минора, обновляя pubspec.yaml и обновляя pubspec.lock, используя журналы Git для записей CHANGELOG.md и поддерживая протоколы pub get.","ar":"يمكن للعميل توفير إمكانية تلقائية لعميل لإدارة إصدار فليت عن طريق زيادة الرقم الصغير أو الرقم الكبير، وتحديث pubspec.yaml، وتحديث pubspec.lock، وتحسين سجلات جيت لمدخلات CHANGELOG.md ودعم بروتوكول pub get."},"useCases":{"en":["Automating Flet release versioning","Updating pubspec.yaml for new releases","Generating CHANGELOG.md entries from Git logs"],"zh":["自动化Flet版本管理","更新pubspec.yaml以进行新版本发布","从Git日志生成CHANGELOG.md条目"],"ja":["Fletリリースバージョニングの自動化","新しいリリースのためのpubspec.yamlの更新","GitログからCHANGELOG.mdエントリの生成"],"ko":["Flet 릴리스 버전 관리 자동화","새 릴리스를 위한 pubspec.yaml 업데이트","Git 로그에서 CHANGELOG.md 항목 생성"],"es":["Automatizar la versión de lanzamiento de Flet","Actualizar pubspec.yaml para nuevos lanzamientos","Generar entradas de CHANGELOG.md a partir de registros de Git"],"fr":["Automatiser la version de publication de Flet","Mettre à jour pubspec.yaml pour les nouvelles publications","Générer des entrées de CHANGELOG.md à partir des journaux Git"],"de":["Automatisieren der Flet-Veröffentlichungsversion","Aktualisieren von pubspec.yaml für neue Veröffentlichungen","Erstellen von CHANGELOG.md-Einträgen aus Git-Protokollen"],"pt":["Automatizar o versionamento de lançamento do Flet","Atualizar pubspec.yaml para novos lançamentos","Gerar entradas CHANGELOG.md a partir de logs do Git"],"ru":["Автоматизировать управление версиями выпуска Flet","Обновлять pubspec.yaml для новых выпусков","Генерировать записи CHANGELOG.md из журналов Git"],"ar":["تلقائية إدارة إصدار فليت","تحديث pubspec.yaml لإصدارات جديدة","إنشاء مدخلات CHANGELOG.md من سجلات جيت"]},"limitations":{"en":["Requires access to Flet repository and Git logs","Limited to Python environment","Dependent on pub get protocol"],"zh":["需要访问Flet存储库和Git日志","仅限Python环境","依赖于pub get协议"],"ja":["FletリポジトリとGitログへのアクセスが必要","Python環境のみ","pub getプロトコルに依存"],"ko":["Flet 저장소 및 Git 로그 액세스 필요","Python 환경 제한","pub get 프로토콜 종속"],"es":["Requiere acceso al repositorio de Flet y a los registros de Git","Limitado al entorno de Python","Dependiente del protocolo pub get"],"fr":["Nécessite un accès au référentiel Flet et aux journaux Git","Limité à l''environnement Python","Dépendant du protocole pub get"],"de":["Erfordert Zugriff auf das Flet-Repository und die Git-Protokolle","Begrenzt auf die Python-Umgebung","Abhängig vom pub get-Protokoll"],"pt":["Exige acesso ao repositório do Flet e aos logs do Git","Limitado ao ambiente Python","Dependente do protocolo pub get"],"ru":["Требует доступа к репозиторию Flet и журналам Git","Ограничен средой Python","Зависит от протокола pub get"],"ar":["يتطلب الوصول إلى مستودع فليت وسجلات جيت","محدود بالبيئة بايثون","متعلق ببروتوكول pub get"]},"version":4},"contentHash":"09f44631b20930d607dc90285ee0947368b5d285757e23b6ec7e0b35c6c646e4","qualityScore":48}');
