INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SynkraAI/aiox-core/aiox-analyst', 'aiox-analyst', 'SynkraAI', 'aiox-core', 'community', 'aiox-analyst SynkraAI aiox-core community agents ai ai-agents automation claude cli development framework fullstack nodejs orchestration typescript AIOX Analyst is a core framework for full stack development, providing AI-orchestrated system capabilities for market research and competitive analysis. AIOX 分析师是一个全栈开发的核心框架，提供 AI 编排系统功能，用于市场研究和竞争分析。 AIOX 分析者は、フルスタック開発のためのコアフレームワークであり、市場調査と競合分析のための AI オーケストレーションシステムの機能を提供する。 AIOX 분석가는 풀스택 개발을 위한 핵심 프레임워크로서, 시장 조사 및 경쟁 분석을 위한 AI 오케스트레이션 시스템 기능을 제공합니다. aiox-analyst es un agente de AI para la automatización de tareas de desarrollo full stack con NodeJS y TypeScript. Ayuda a mejorar la eficiencia en proyectos de desarrollo aiox-analyst est un agent d''IA pour l''automatisation des tâches de développement full stack avec NodeJS et TypeScript. Il aide à améliorer l''efficacité dans les projets de développement aiox-analyst ist ein KI-Agent für die Automatisierung von Entwicklungsaufgaben im Full-Stack-Bereich mit NodeJS und TypeScript. Er hilft bei der Verbesserung der Effizienz in Entwicklungsprojekten O AIOX Analyst é uma ferramenta de análise de negócios baseada em AI para desenvolvimento full stack com NodeJS e TypeScript AIOX Analyst - это инструмент бизнес-аналитики на основе ИИ для полного стека разработки с NodeJS и TypeScript AIOX Analyst هو أداة تحليل الأعمال بالكامل مبنية على الذكاء الاصطناعي لتحwicklung التطبيقات الكاملة مع NodeJS و TypeScript AIOX Analyst AI-orchestrated system full stack development market research competitive analysis Node.js TypeScript CLI AI agents AIOX 分析师 AI 编排系统 全栈开发 市场研究 竞争分析 Node.js TypeScript CLI AI 工具 AI-orchestrated system for full stack development Supports market research and competitive analysis Uses Node.js and TypeScript for development Adopts CLI for command system Loads .aiox-core/development/agents/analyst.md as source of truth AIOX Analyst is an AI-orchestrated system for full stack development, enabling market research and competitive analysis');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vicanso/zedis/generate-component-story', 'community', 'vicanso', 'zedis', 'vicanso/zedis', 'generate-component-story', 1698, 38, 48, '2026-03-01T01:30:59Z', '2026-03-06T06:26:05.495Z', 'e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa', '{"id":"vicanso/zedis/generate-component-story","name":"generate-component-story","description":{"en":"The generate-component-story skill generates comprehensive stories for components, following existing patterns and including all options, variants, and usage examples. It benefits developers working with Redis and GPUI.","zh":"generate-component-story 技术允许开发者基于 Rust 和 GPUI 架构创建高性能的 Redis GUI","ja":"generate-component-story は、AIエージェントによる Redis GUI 構築を可能にする技術です","ko":"generate-component-story는 Rust와 GPUI 기반의 Redis GUI 생성을 위한 기술입니다","es":"Zedis es una GUI de Redis nativa y rápida construida con Rust y GPUI, que permite crear componentes de historia de manera eficiente","fr":"Zedis est une GUI Redis native et rapide construite avec Rust et GPUI, qui permet de créer des composants d''histoire de manière efficace","de":"Zedis ist eine native und schnelle Redis-GUI, die mit Rust und GPUI erstellt wurde und das Erstellen von Komponenten-Geschichten ermöglicht","pt":"Zedis é uma GUI Redis nativa e rápida, construída com Rust e GPUI. Crie componentes de história com padrões existentes e section!","ru":"Zedis - быстрая и родная GUI Redis, построенная на Rust и GPUI. Создавайте компоненты истории с существующими шаблонами и section!","ar":"Zedis هو واجهة المستخدم الرسومية الخاصة ب Redis الأصلية والسريعة، مبنية على Rust و GPUI. أنشئ مكونات القصص مع الأنماط الموجودة و section!"},"seo":{"title":{"en":"generate-component-story: Comprehensive Story Generation ...","zh":"generate-component-story 快速指南：基于 Rust 和 GPUI 的 Redis GUI","ja":"generate-component-story セットアップガイド：AIエージェントによるRedis GUI構築","ko":"generate-component-story 설정 가이드: Rust와 GPUI 기반의 Redis GUI","es":"Guía de configuración para generar componentes de histori...","fr":"Guide de mise en place pour générer des composants d''hist...","de":"Einrichtungsleitfaden zum Erstellen von Komponenten-Gesch...","pt":"Guia de Configuração de Componentes com Zedis e GPUI","ru":"ИИ Агенты: Настройка Компонентов с Zedis и GPUI","ar":"إعداد مكونات القصص مع Zedis و GPUI"},"description":{"en":"Unlock the full potential of your AI agent with generate-component-story. Learn how to create comprehensive stories with sections, variants, and usage examples.","zh":"了解如何使用 generate-component-story 技术创建高性能的 Redis GUI，基于 Rust 和 GPUI 架构","ja":"generate-component-story を使用して、AIエージェントによる Redis GUI を構築する方法を学びましょう","ko":"generate-component-story를 사용하여 Rust와 GPUI 기반의 Redis GUI를 생성하는 방법에 대해 알아보세요","es":"Aprende a crear componentes de historia con Zedis, una GUI de Redis nativa y rápida, y GPUI, y mejora tu experiencia de desarrollo","fr":"Découvrez comment créer des composants d''histoire avec Zedis, une GUI Redis native et rapide, et GPUI, et améliorez votre expérience de développement","de":"Erfahren Sie, wie Sie Komponenten-Geschichten mit Zedis, einer nativen und schnellen Redis-GUI, und GPUI erstellen und Ihre Entwicklererfahrung verbessern","pt":"Aprenda a criar componentes de história com Zedis e GPUI. Siga os padrões existentes e organize com section!","ru":"Изучите создание компонентов истории с Zedis и GPUI. Следуйте существующим шаблонам и организуйте с помощью section!","ar":"تعلم كيفية إنشاء مكونات القصص مع Zedis و GPUI. اتبع الأنماط الموجودة وظمها باستخدام section!"},"definition":{"en":"generate-component-story is a skill that generates comprehensive stories for components, using sections and including various examples and usage scenarios.","zh":"generate-component-story 是一种用于创建 Redis GUI 的技术，基于 Rust 和 GPUI","ja":"generate-component-story は、Redis GUI 構築用の AIエージェント技術です","ko":"generate-component-story는 Redis GUI 생성을 위한 기술로, Rust와 GPUI를 기반으로 합니다","es":"Un componente de historia es una representación visual de un elemento de interfaz de usuario, creado con Zedis y GPUI","fr":"Un composant d''histoire est une représentation visuelle d''un élément d''interface utilisateur, créé avec Zedis et GPUI","de":"Ein Komponenten-Geschichte ist eine visuelle Darstellung eines Benutzeroberflächenelements, das mit Zedis und GPUI erstellt wird","pt":"O que é um componente de história? É uma unidade de código que demonstra a funcionalidade de um componente com Zedis e GPUI","ru":"Что такое компонент истории? Это единица кода, демонстрирующая функциональность компонента с Zedis и GPUI","ar":"ما هو مكون القصة؟ هو وحدة من الكود التي تُظهر وظيفة مكون مع Zedis و GPUI"},"features":{"en":["Follows existing patterns found in crates/story/src/stories","Organizes stories with section! calls for each major part","Includes comprehensive coverage of all options, variants, and usage examples","Supports creation of stories with basic usage examples","Allows for inclusion of different variants and states","Enables interactive story creation"],"zh":["基于 Rust 和 GPUI 架构","支持创建高性能的 Redis GUI","提供 comprehensive coverage 的 story 结构","包含基本使用示例和不同变体","支持 section! 调用以组织 story","遵循 existing patterns 和 styles"],"ja":["AIエージェントによる Redis GUI 構築","Rust と GPUI ベースのアーキテクチャ","高性能な Redis GUI の作成","包括的なストーリー構造","基本的な使用例と異なるバリアント","section! 呼び出しによるストーリーの組織化","既存のパターンとスタイルの遵守"],"ko":["Rust와 GPUI 기반의 아키텍처","고성능 Redis GUI 생성","전체적인 스토리 구조","기본 사용 예와 다른 변형","section! 호출을 통한 스토리 구성","既存 패턴과 스타일의 준수","Redis GUI 생성을 위한 기술"],"es":["Creación de componentes de historia con patrones existentes","Uso de secciones para organizar el contenido","Cobertura exhaustiva de todas las opciones y variantes","Compatibilidad con GPUI y Redis","Desarrollo rápido y eficiente con Rust"],"fr":["Création de composants d''histoire avec des modèles existants","Utilisation de sections pour organiser le contenu","Couverture exhaustive de toutes les options et variantes","Compatibilité avec GPUI et Redis","Développement rapide et efficace avec Rust"],"de":["Erstellung von Komponenten-Geschichten mit bestehenden Mustern","Verwendung von Abschnitten zur Organisation des Inhalts","Umfassende Abdeckung aller Optionen und Varianten","Kompatibilität mit GPUI und Redis","Schnelle und effiziente Entwicklung mit Rust"],"pt":["Criação de componentes de história com padrões existentes","Organização com section!","Cobertura abrangente de opções e variantes","Exemplos de uso básico e avançado","Integração com Zedis e GPUI","Desenvolvimento com Rust"],"ru":["Создание компонентов истории с существующими шаблонами","Организация с помощью section!","Полное покрытие опций и вариантов","Примеры базового и продвинутого использования","Интеграция с Zedis и GPUI","Разработка на Rust"],"ar":["إنشاء مكونات القصص مع الأنماط الموجودة","تنظيمها باستخدام section!","التغطية الشاملة للخيارات والمتغيرات","أمثلة للاستخدام الأساسي والمتقدم","التكامل مع Zedis و GPUI","التطوير باستخدام Rust"]},"keywords":{"en":["how to use generate-component-story","generate-component-story alternative","generate-component-story setup guide","what is generate-component-story","generate-component-story vs redis-client","generate-component-story install","generate-component-story for gpui","generate-component-story for redis","generate-component-story tutorial","generate-component-story examples"],"zh":["generate-component-story","Redis GUI","Rust","GPUI","AIエージェント","高性能 GUI","comprehensive coverage","section! 调用","existing patterns"],"ja":["generate-component-story","Redis GUI","AIエージェント","Rust","GPUI","高性能 GUI","包括的なストーリー構造","section! 呼び出し","既存のパターン"],"ko":["generate-component-story","Redis GUI","Rust","GPUI","고성능 GUI","전체적인 스토리 구조","section! 호출","既存 패턴","Redis GUI 생성"],"es":["Zedis","GPUI","Redis","GUI de Redis","componentes de historia","desarrollo de software","Rust","programación","herramientas de desarrollo"],"fr":["Zedis","GPUI","Redis","GUI Redis","composants d''histoire","développement de logiciels","Rust","programmation","outils de développement"],"de":["Zedis","GPUI","Redis","Redis-GUI","Komponenten-Geschichten","Software-Entwicklung","Rust","Programmierung","Entwicklertools"],"pt":["Zedis","GPUI","Redis","componentes de história","padrões existentes","section","Rust","desenvolvimento de software","GUI Redis","componentes de interface do usuário"],"ru":["Zedis","GPUI","Redis","компоненты истории","существующие шаблоны","section","Rust","разработка программного обеспечения","GUI Redis","компоненты интерфейса пользователя"],"ar":["Zedis","GPUI","Redis","مكونات القصص","الأنماط الموجودة","section","Rust","تطوير البرمجيات","واجهة المستخدم الرسومية ل Redis","مكونات واجهة المستخدم"]}},"owner":"vicanso","repo":"zedis","repoPath":"vicanso/zedis","stars":1698,"forks":38,"updatedAt":"2026-03-01T01:30:59Z","topics":["gpui","redis","redis-client"],"category":"community","skillMd":{"name":"generate-component-story","description":"Create story examples for components. Use when writing stories, creating examples, or demonstrating component usage.","bodyPreview":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactiv","body":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactive examples\n- Edge cases and error states\n"},"lastSynced":"2026-03-06T06:26:05.495Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Generation Agents needing comprehensive component documentation and storytelling capabilities for Redis and GPU-based applications.","zh":"非常适合需要全面组件文档和Redis及GPU应用故事讲述能力的代码生成代理。","ja":"RedisおよびGPUベースのアプリケーションに対する包括的なコンポーネントのドキュメントとストーリーテリング機能を必要とするコード生成エージェントに最適です。","ko":"Redis 및 GPU 기반 애플리케이션에 대한 포괄적인 컴포넌트 문서 및 스토리 텔링 기능이 필요한 코드 생성 에이전트에 적합합니다.","es":"Perfecto para agentes de generación de código que necesitan documentación de componentes completa y capacidades de narración para Redis y aplicaciones basadas en GPU.","fr":"Parfait pour les agents de génération de code nécessitant une documentation de composants complète et des capacités de narration pour Redis et les applications basées sur GPU.","de":"Perfekt für Code-Generierungsagenten, die umfassende Komponentendokumentation und Erzählungsfähigkeiten für Redis und GPU-basierte Anwendungen benötigen.","pt":"Perfeito para Agentes de Geração de Código que necessitam de documentação de componentes abrangente e capacidades de storytelling para Redis e aplicações baseadas em GPU.","ru":"Идеально подходит для агентов генерации кода, которым необходима всесторонняя документация компонентов и возможности рассказывания историй для Redis и приложений на основе GPU.","ar":"مثالي لعميل توليد الشيفرة الذي يحتاج إلى توثيق شامل للمكونات وقدرات السرد لل تطبيقات المستندة إلى Redis و GPU."},"recommendation":{"en":"Empowers agents to generate comprehensive stories for components, following existing patterns and including all options, variants, and usage examples, utilizing sections and organization through `section!` calls, ideal for crates like `story/src/stories` and files such as `tabs_story.rs` and `group_box_story.rs`.","zh":"赋予代理生成全面组件故事的能力，遵循既有的模式，并包括所有选项、变体和使用示例，利用部分和组织通过`section!`调用，非常适合类似`story/src/stories`的crate和诸如`tabs_story.rs`和`group_box_story.rs`的文件。","ja":"エージェントにコンポーネントの包括的なストーリーを生成する能力を与え、既存のパターンに従い、すべてのオプション、バリエーション、および使用例を含め、セクションと`section!`コールを介した組織を使用することができ、`story/src/stories`のようなcratesおよび`tabs_story.rs`や`group_box_story.rs`のようなファイルに最適です。","ko":"에이전트가 기존 패턴을 따르고 모든 옵션, 변형 및 사용 예를 포함하는 포괄적인 컴포넌트 스토리를 생성할 수 있도록 하며, 섹션과 `section!` 호출을 통해 조직화하여 `story/src/stories`와 같은 크레이트와 `tabs_story.rs` 및 `group_box_story.rs`와 같은 파일에 적합합니다.","es":"Habilita a los agentes a generar historias completas para componentes, siguiendo patrones existentes e incluyendo todas las opciones, variantes y ejemplos de uso, utilizando secciones y organización a través de llamadas `section!`, ideal para crates como `story/src/stories` y archivos como `tabs_story.rs` y `group_box_story.rs`.","fr":"Permet aux agents de générer des histoires complètes pour les composants, en suivant les modèles existants et en incluant toutes les options, les variantes et les exemples d''utilisation, en utilisant des sections et une organisation via des appels `section!`, idéal pour des crates comme `story/src/stories` et des fichiers tels que `tabs_story.rs` et `group_box_story.rs`.","de":"Ermöglicht es Agenten, umfassende Geschichten für Komponenten zu generieren, indem sie bestehende Muster befolgen und alle Optionen, Varianten und Nutzungbeispiele einbeziehen, unter Verwendung von Abschnitten und Organisation durch `section!`-Aufrufe, ideal für Crates wie `story/src/stories` und Dateien wie `tabs_story.rs` und `group_box_story.rs`.","pt":"Habilita os agentes a gerar histórias abrangentes para componentes, seguindo padrões existentes e incluindo todas as opções, variantes e exemplos de uso, utilizando seções e organização por meio de chamadas `section!`, ideal para caixas como `story/src/stories` e arquivos como `tabs_story.rs` e `group_box_story.rs`.","ru":"Наделяет агентов возможностью генерировать всесторонние истории для компонентов, следуя существующим шаблонам и включая все опции, вариации и примеры использования, используя разделы и организацию через вызовы `section!`, идеально подходит для крейтов seperti `story/src/stories` и файлов таких как `tabs_story.rs` и `group_box_story.rs`.","ar":"تمكّن الوكلاء من توليد قصص شاملة للمكونات، متبعة الأنماط الموجودة وإدراج جميع الخيارات والمرادفات وأمثلة الاستخدام، باستخدام الأقسام والتنظيم من خلال呼وف `section!`، مثالية للعلب مثل `story/src/stories` وملفات مثل `tabs_story.rs` و `group_box_story.rs`."},"useCases":{"en":["Generating detailed component stories for Redis integrations","Creating comprehensive documentation for GPU-accelerated components","Automating story generation for various component variants and states"],"zh":["为Redis集成生成详细的组件故事","为GPU加速组件创建全面文档","自动为各种组件变体和状态生成故事"],"ja":["Redis統合用の詳細なコンポーネントストーリーを生成する","GPUアクセラレーションコンポーネント用の包括的なドキュメントを作成する","さまざまなコンポーネントのバリエーションと状態のストーリーを自動生成する"],"ko":["Redis 통합을 위한詳細한 컴포넌트 스토리 생성","GPU 가속 컴포넌트를 위한 포괄적인 문서 생성","다양한 컴포넌트 변형 및 상태에 대한 스토리 자동 생성"],"es":["Generación de historias detalladas de componentes para integraciones de Redis","Creación de documentación completa para componentes acelerados por GPU","Automatización de la generación de historias para varias variantes y estados de componentes"],"fr":["Génération d''histoires détaillées de composants pour les intégrations Redis","Création d''une documentation complète pour les composants accélérés par GPU","Automatisation de la génération d''histoires pour les différentes variantes et états de composants"],"de":["Erzeugung detaillierter Komponentengeschichten für Redis-Integrationen","Erstellung umfassender Dokumentationen für GPU-beschleunigte Komponenten","Automatisierung der Geschichtenerzeugung für verschiedene Komponentenvarianten und -zustände"],"pt":["Geração de histórias detalhadas de componentes para integrações do Redis","Criação de documentação abrangente para componentes acelerados por GPU","Automatização da geração de histórias para variantes e estados de componentes variados"],"ru":["Генерация подробных историй компонентов для интеграций с Redis","Создание всесторонней документации для компонентов, ускоренных с помощью GPU","Автоматизация генерации историй для различных вариантов и состояний компонентов"],"ar":["توليد قصص مفصلة للمكونات لتكاملات Redis","إنشاء توثيق شامل للمكونات المعززة بواسطة GPU","تحسين توليد القصص لمرادفات وحالات مكونات متنوعة"]},"limitations":{"en":["Requires access to existing story patterns and examples","Specific to component-based development and storytelling"],"zh":["需要访问现有的故事模式和示例","特定于组件基于开发和故事讲述"],"ja":["既存のストーリーパターンと例へのアクセスが必要","コンポーネントベースの開発およびストーリーテリングに特有"],"ko":["기존 스토리 패턴 및 예제에 대한 액세스가 필요","컴포넌트 기반 개발 및 스토리 텔링에 특정"],"es":["Requiere acceso a patrones y ejemplos de historias existentes","Específico para el desarrollo y la narración de componentes"],"fr":["Nécessite l''accès à des modèles et des exemples d''histoires existants","Spécifique au développement et à la narration de composants"],"de":["Erfordert den Zugriff auf bestehende Geschichtsmuster und -beispiele","Spezifisch für die Komponentenentwicklung und -erzählung"],"pt":["Requer acesso a padrões e exemplos de histórias existentes","Específico para desenvolvimento baseado em componentes e storytelling"],"ru":["Требует доступа к существующим шаблонам и примерам историй","Является специфичным для компонентного развития и рассказывания историй"],"ar":["يتطلب الوصول إلى الأنماط والأمثلة القصصية الموجودة","محدد للتعاون القائم على المكونات والسرد"]},"version":4},"contentHash":"e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa","qualityScore":48}');
