INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vicanso/zedis/generate-component-story', 'generate-component-story', 'vicanso', 'zedis', 'community', 'generate-component-story vicanso zedis community gpui redis redis-client The generate-component-story skill generates comprehensive stories for components, following existing patterns and including all options, variants, and usage examples. It benefits developers working with Redis and GPUI. generate-component-story 技术允许开发者基于 Rust 和 GPUI 架构创建高性能的 Redis GUI generate-component-story は、AIエージェントによる Redis GUI 構築を可能にする技術です generate-component-story는 Rust와 GPUI 기반의 Redis GUI 생성을 위한 기술입니다 Zedis es una GUI de Redis nativa y rápida construida con Rust y GPUI, que permite crear componentes de historia de manera eficiente Zedis est une GUI Redis native et rapide construite avec Rust et GPUI, qui permet de créer des composants d''histoire de manière efficace Zedis ist eine native und schnelle Redis-GUI, die mit Rust und GPUI erstellt wurde und das Erstellen von Komponenten-Geschichten ermöglicht Zedis é uma GUI Redis nativa e rápida, construída com Rust e GPUI. Crie componentes de história com padrões existentes e section! Zedis - быстрая и родная GUI Redis, построенная на Rust и GPUI. Создавайте компоненты истории с существующими шаблонами и section! Zedis هو واجهة المستخدم الرسومية الخاصة ب Redis الأصلية والسريعة، مبنية على Rust و GPUI. أنشئ مكونات القصص مع الأنماط الموجودة و section! how to use generate-component-story generate-component-story alternative generate-component-story setup guide what is generate-component-story generate-component-story vs redis-client generate-component-story install generate-component-story for gpui generate-component-story for redis generate-component-story tutorial generate-component-story examples generate-component-story Redis GUI Rust GPUI AIエージェント 高性能 GUI comprehensive coverage section! 调用 existing patterns Follows existing patterns found in crates/story/src/stories Organizes stories with section! calls for each major part Includes comprehensive coverage of all options, variants, and usage examples Supports creation of stories with basic usage examples Allows for inclusion of different variants and states Enables interactive story creation generate-component-story is a skill that generates comprehensive stories for components, using sections and including various examples and usage scenarios.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vultisig/vultisig-windows/svg-icon-pattern', 'community', 'vultisig', 'vultisig-windows', 'vultisig/vultisig-windows', 'svg-icon-pattern', 13, 13, 48, '2026-02-27T07:55:13Z', '2026-03-06T06:44:25.858Z', '0f6cd2fa6203a867a7b114599fa66cfee0fb8876a88c1ee797e2c6b2933967b7', '{"id":"vultisig/vultisig-windows/svg-icon-pattern","name":"svg-icon-pattern","description":{"en":"The svg-icon-pattern skill ensures consistency and flexibility in icon creation by following specific standards. It benefits developers working with SVG icons in the lib/ui/icons directory.","zh":"SVG 图标模式是一种确保图标一致性和灵活性的标准，包括图标组件定义和 SvgProps 的使用","ja":"SVG アイコン パターンは、アイコンのコンシステンシーとフレキシビリティを確保するためのスタンダードであり、アイコンコンポーネント定義と SvgProps の使用が含まれる","ko":"SVG 아이콘 패턴은 아이콘의 일관성과 유연성을 보장하는 표준으로, 아이콘 컴포넌트 정의와 SvgProps 사용이 포함됩니다","es":"El patrón de iconos SVG proporciona una forma estandarizada de crear iconos en el directorio lib/ui/icons","fr":"Le modèle d''icônes SVG fournit un moyen normalisé de créer des icônes dans le répertoire lib/ui/icons","de":"Das SVG-Icon-Muster bietet eine standardisierte Möglichkeit, Icons im Verzeichnis lib/ui/icons zu erstellen","pt":"O padrão de ícone SVG é uma abordagem para criar ícones consistentes e flexíveis, utilizando componentes de ícone e propriedades de SVG.","ru":"Стандарт иконки SVG - это подход к созданию последовательных и гибких иконок, использующий компоненты иконок и свойства SVG с помощью ИИ Агентов","ar":"نمط الأيقونة SVG هو نهج لإنشاء رموز متسقة ومرنة، باستخدام مكونات الأيقونة وخصائص SVG مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"svg-icon-pattern: Best Practices for AI Agents | AI Agent...","zh":"SVG 图标模式设置指南","ja":"SVG アイコン パターン ベスト プラクティス","ko":"SVG 아이콘 패턴 설정 가이드","es":"Guía de Configuración de Patrones de Iconos SVG","fr":"Guide de Configuration des Modèles d''Icônes SVG","de":"Einrichtungsleitfaden für SVG-Icon-Muster","pt":"Guia de Configuração do Padrão de Ícone SVG","ru":"Настройка шаблона иконки SVG: ИИ Агенты","ar":"دليل إعداد نمط الأيقونة SVG باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create consistent and flexible icons with svg-icon-pattern. Learn the standards for icon component definition and SvgProps implementation.","zh":"了解 SVG 图标模式的技术细节，包括图标组件定义和 SvgProps 的使用","ja":"SVG アイコン パターンのテクニカル細節を学び、アイコンコンポーネント定義と SvgProps の使用方法を理解する","ko":"SVG 아이콘 패턴의 기술 세부 정보를 알아보고, 아이콘 컴포넌트 정의와 SvgProps 사용 방법을 이해하십시오","es":"Aprende a crear patrones de iconos SVG consistentes y flexibles con nuestros estándares de iconos","fr":"Découvrez comment créer des modèles d''icônes SVG cohérents et flexibles avec nos normes d''icônes","de":"Erfahren Sie, wie Sie konsistente und flexible SVG-Icon-Muster mit unseren Icon-Standards erstellen","pt":"Aprenda a criar ícones SVG consistentes e flexíveis com o padrão de ícone SVG, incluindo dicas de exportação de componentes e propriedades","ru":"Изучите стандарт иконки SVG для создания последовательных и гибких иконок, включая советы по экспорту компонентов и свойств с помощью ИИ Агентов","ar":"تعرف على كيفية إنشاء رموز SVG متسقة ومرنة باستخدام نمط الأيقونة SVG، بما في ذلك نصائح حول تصدير المكونات والخصائص باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"svg-icon-pattern is a set of standards for creating and updating icons in the lib/ui/icons directory, ensuring consistency and flexibility through proper icon component definition and SvgProps implementation.","zh":"SVG 图标模式是一种用于创建和更新图标的标准，确保图标的一致性和灵活性","ja":"SVG アイコン パターンは、アイコンの作成と更新に使用されるスタンダードであり、アイコンのコンシステンシーとフレキシビリティを確保する","ko":"SVG 아이콘 패턴은 아이콘을 생성하고 업데이트하는 데 사용되는 표준으로, 아이콘의 일관성과 유연성을 보장합니다","es":"Un patrón de iconos SVG es un estándar para crear iconos en formato SVG de manera consistente","fr":"Un modèle d''icônes SVG est une norme pour créer des icônes au format SVG de manière cohérente","de":"Ein SVG-Icon-Muster ist ein Standard für die Erstellung von Icons im SVG-Format auf konsistente Weise","pt":"O padrão de ícone SVG é uma definição de componente de ícone que recebe propriedades de SVG.","ru":"Стандарт иконки SVG - это определение компонента иконки, который получает свойства SVG","ar":"نمط الأيقونة SVG هو تعريف لمكون الأيقونة الذي يتلقى خصائص SVG"},"features":{"en":["Exports a named component that receives SvgProps from @lib/ui/props","Spreads SvgProps onto the svg element for consistency","Utilizes the @lib/ui/props library for SvgProps definition","Follows specific standards for icon creation in the lib/ui/icons directory","Ensures flexibility through proper icon component definition","Supports SvgProps implementation for customizable icons"],"zh":["图标组件定义","SvgProps 的使用","确保图标的一致性和灵活性","支持 TypeScript 和 React","使用 xmlns 和 width 属性"],"ja":["アイコンコンポーネント定義","SvgProps の使用","アイコンのコンシステンシーとフレキシビリティの確保","TypeScript と React のサポート","xmlns と width 属性の使用"],"ko":["아이콘 컴포넌트 정의","SvgProps 사용","아이콘의 일관성과 유연성 보장","TypeScript와 React 지원","xmlns와 width 속성 사용"],"es":["Utiliza la biblioteca @lib/ui/props para props de iconos","Crea componentes de iconos con SvgProps","Asigna props a elementos svg","Establece un ancho de icono de 1em","Utiliza la etiqueta svg con xmlns"],"fr":["Utilise la bibliothèque @lib/ui/props pour les propriétés d''icônes","Crée des composants d''icônes avec SvgProps","Attribue des propriétés aux éléments svg","Définit une largeur d''icône de 1em","Utilise la balise svg avec xmlns"],"de":["Verwenden der Bibliothek @lib/ui/props für Icon-Props","Erstellen von Icon-Komponenten mit SvgProps","Zuweisen von Props zu svg-Elementen","Festlegen einer Icon-Breite von 1em","Verwenden der svg-Tag mit xmlns"],"pt":["Utiliza componentes de ícone com propriedades de SVG","Exporta componentes de ícone com propriedades de SvgProps","Utiliza a biblioteca @lib/ui/props para propriedades de SVG","Cria ícones consistentes e flexíveis com o padrão de ícone SVG","Suporta a criação de ícones personalizados com o padrão de ícone SVG"],"ru":["Использует компоненты иконок с свойствами SVG","Экспортирует компоненты иконок с свойствами SvgProps","Использует библиотеку @lib/ui/props для свойств SVG","Создает последовательные и гибкие иконки с помощью стандарта иконки SVG","Поддерживает создание пользовательских иконок с помощью стандарта иконки SVG с ИИ Агентами"],"ar":["يستخدم مكونات الأيقونة مع خصائص SVG","يصدر مكونات الأيقونة مع خصائص SvgProps","يستخدم مكتبة @lib/ui/props لخصائص SVG","ينشئ رموز متسقة ومرنة بنمط الأيقونة SVG","يدعم إنشاء رموز مخصصة بنمط الأيقونة SVG مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use svg-icon-pattern","svg-icon-pattern best practices","svg-icon-pattern alternative","svg-icon-pattern vs icon libraries","svg-icon-pattern install","svg-icon-pattern setup guide","what is svg-icon-pattern","svg-icon-pattern tutorial","svg-icon-pattern for AI agents"],"zh":["SVG 图标模式","图标组件定义","SvgProps","React","TypeScript","xmlns","width","AIエージェント","AI工具"],"ja":["SVG アイコン パターン","アイコンコンポーネント定義","SvgProps","React","TypeScript","xmlns","width","AIエージェント","AIツール"],"ko":["SVG 아이콘 패턴","아이콘 컴포넌트 정의","SvgProps","React","TypeScript","xmlns","width","AI 에이전트","AI 툴"],"es":["patrones de iconos svg","iconos svg react","crear iconos svg","estándares de iconos","lib/ui/props","svgprops","desarrollo de iconos","herramientas de iconos svg"],"fr":["modèles d''icônes svg","icônes svg react","créer des icônes svg","normes d''icônes","lib/ui/props","svgprops","développement d''icônes","outils d''icônes svg"],"de":["svg-icon-muster","svg-icons react","erstellen von svg-icons","icon-standards","lib/ui/props","svgprops","entwicklung von icons","svg-icon-tools"],"pt":["padrão de ícone SVG","componentes de ícone","propriedades de SVG","SvgProps","criação de ícones personalizados","ícones consistentes e flexíveis","desenvolvimento de interfaces de usuário","bibliotecas de UI"],"ru":["стандарт иконки SVG","компоненты иконок","свойства SVG","SvgProps","создание пользовательских иконок","последовательные и гибкие иконки","разработка интерфейсов пользователя","библиотеки ИИ Агентов","инструменты ИИ"],"ar":["نمط الأيقونة SVG","مكونات الأيقونة","خصائص SVG","SvgProps","إنشاء رموز مخصصة","رموز متسقة ومرنة","تطوير واجهات المستخدم","مكتبات واجهات المستخدم","أدوات الذكاء الاصطناعي","رموز SVG مخصصة"]}},"owner":"vultisig","repo":"vultisig-windows","repoPath":"vultisig/vultisig-windows","stars":13,"forks":13,"updatedAt":"2026-02-27T07:55:13Z","topics":[],"category":"community","skillMd":{"name":"svg-icon-pattern","description":"Standards for creating and using SVG icons. Use SvgProps from @lib/ui/props and spread them on the svg element. Size icons via fontSize in the style prop at the usage site.","bodyPreview":"# SVG Icon Pattern\n\n## Instructions\n\nWhen creating or updating icons in the `lib/ui/icons` directory, follow these standards to ensure consistency and flexibility.\n\n### 1. Icon Component Definition\n\nExport a named component that receives `SvgProps` from `@lib/ui/props`. Spread these props onto the `svg` element.\n\n```tsx\n// ✅ Good: SvgProps pattern\nimport { SvgProps } from ''@lib/ui/props''\n\nexport const MyIcon = (props: SvgProps) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"1em\"","body":"# SVG Icon Pattern\n\n## Instructions\n\nWhen creating or updating icons in the `lib/ui/icons` directory, follow these standards to ensure consistency and flexibility.\n\n### 1. Icon Component Definition\n\nExport a named component that receives `SvgProps` from `@lib/ui/props`. Spread these props onto the `svg` element.\n\n```tsx\n// ✅ Good: SvgProps pattern\nimport { SvgProps } from ''@lib/ui/props''\n\nexport const MyIcon = (props: SvgProps) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"1em\"\n    height=\"1em\"\n    viewBox=\"0 0 24 24\"\n    fill=\"currentColor\"\n    {...props}\n  >\n    <path d=\"...\" />\n  </svg>\n)\n\n// ❌ Bad: IconWrapper inside icon definition\nexport const MyIcon = (props: any) => (\n  <IconWrapper {...props}>\n    <svg>...</svg>\n  </IconWrapper>\n)\n```\n\n### 2. Sizing and Dimensions\n\n- Calculate dimensions based on the `viewBox` attribute.\n- The largest dimension (width or height) should always be `1em`.\n- The smaller dimension should be calculated proportionally: `(smaller / larger)em`.\n- Neither width nor height should exceed `1em`.\n\n```tsx\n// Example for non-square icon (viewBox=\"0 0 22 20\")\n// height = 20/22 = 0.909\n<svg width=\"1em\" height=\"0.909em\" viewBox=\"0 0 22 20\" ...>\n```\n\n### 3. Styling and Colors\n\n- Use `fill=\"currentColor\"` or `stroke=\"currentColor\"` to allow the icon to inherit colors from its parent.\n- For multi-colored icons, use specific colors only where necessary.\n\n### 4. Usage and Sizing\n\nSize icons at the usage site using the `fontSize` property within the `style` prop. This leverages the `1em` base size defined in the icon component.\n\n```tsx\n// ✅ Good: Direct sizing via style\n<MyIcon style={{ fontSize: 24 }} />\n\n// ❌ Bad: Using size prop (requires IconWrapper)\n<MyIcon size={24} />\n```\n\n## Anti-Patterns to Avoid\n\n- **DO NOT** wrap icons with `IconWrapper` inside the icon component file.\n- **DO NOT** use hardcoded pixel values for `width` and `height` in the `svg` element.\n- **DO NOT** use `IconWrapper` at the usage site if simple `fontSize` styling is sufficient.\n"},"lastSynced":"2026-03-06T06:44:25.858Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents working with SVG icons in the lib/ui/icons directory, needing standardized icon creation and flexibility.","zh":"非常适合在lib/ui/icons目录中使用SVG图标的前端代理，需要标准化的图标创建和灵活性。","ja":"lib/ui/iconsディレクトリのSVGアイコンを使用するフロントエンドエージェントに最適で、標準化されたアイコン作成と柔軟性が必要です。","ko":"lib/ui/icons 디렉토리에서 SVG 아이콘을 사용하는 프론트엔드 에이전트에게 적합하며, 표준화된 아이콘 생성과 유연성이 필요합니다.","es":"Perfecto para Agentes de Frontend que trabajan con iconos SVG en el directorio lib/ui/icons, necesitan creación de iconos estandarizados y flexibilidad.","fr":"Parfait pour les agents Frontend travaillant avec des icônes SVG dans le répertoire lib/ui/icons, ayant besoin de création d''icônes standardisées et de flexibilité.","de":"Perfekt für Frontend-Agents, die mit SVG-Icons im Verzeichnis lib/ui/icons arbeiten und standardisierte Icon-Erstellung und Flexibilität benötigen.","pt":"Perfeito para Agentes Frontend que trabalham com ícones SVG no diretório lib/ui/icons, necessitando de criação de ícones padronizados e flexibilidade.","ru":"Идеально подходит для агентов Frontend, работающих с иконками SVG в директории lib/ui/icons, требующих стандартизированного создания иконок и гибкости.","ar":"مثالي للوكلاء الأمامية الذين يعملون مع الرموز SVG في دليل lib/ui/icons، بحاجة إلى إنشاء رموز معيارية ومرونة."},"recommendation":{"en":"Empowers agents to create consistent and flexible SVG icons by following specific standards, utilizing SvgProps from @lib/ui/props and ensuring compatibility with the lib/ui/icons directory, while supporting protocols like http://www.w3.org/2000/svg.","zh":"使代理能够通过遵循特定的标准，利用@lib/ui/props中的SvgProps，并确保与lib/ui/icons目录的兼容性，同时支持http://www.w3.org/2000/svg等协议，创建一致且灵活的SVG图标。","ja":"エージェントが特定の規格に従って一貫性と柔軟性のあるSVGアイコンを作成できるようにし、@lib/ui/propsからのSvgPropsを利用し、lib/ui/iconsディレクトリとの互換性を確保し、http://www.w3.org/2000/svgなどのプロトコルをサポートします。","ko":"에이전트가 특정 표준을 따르면서 일관성과 유연성을 가진 SVG 아이콘을 생성할 수 있도록 하며, @lib/ui/props의 SvgProps를 사용하며, lib/ui/icons 디렉토리와의 호환성을 보장하며, http://www.w3.org/2000/svg 등의 프로토콜을 지원합니다.","es":"Habilita a los agentes a crear iconos SVG coherentes y flexibles siguiendo estándares específicos, utilizando SvgProps desde @lib/ui/props y asegurando la compatibilidad con el directorio lib/ui/icons, mientras soporta protocolos como http://www.w3.org/2000/svg.","fr":"Permet aux agents de créer des icônes SVG cohérentes et flexibles en suivant des normes spécifiques, en utilisant SvgProps depuis @lib/ui/props et en assurant la compatibilité avec le répertoire lib/ui/icons, tout en supportant des protocoles comme http://www.w3.org/2000/svg.","de":"Ermächtigt die Agenten, konsistente und flexible SVG-Icons zu erstellen, indem sie spezifische Standards befolgen, SvgProps von @lib/ui/props verwenden und die Kompatibilität mit dem Verzeichnis lib/ui/icons sicherstellen, während sie Protokolle wie http://www.w3.org/2000/svg unterstützen.","pt":"Habilita os agentes a criar ícones SVG consistentes e flexíveis, seguindo padrões específicos, utilizando SvgProps do @lib/ui/props e garantindo compatibilidade com o diretório lib/ui/icons, enquanto suporta protocolos como http://www.w3.org/2000/svg.","ru":"Наделяет агентов возможностью создавать последовательные и гибкие иконки SVG, следуя конкретным стандартам, используя SvgProps из @lib/ui/props и обеспечивая совместимость с директорий lib/ui/icons, а также поддерживая протоколы, такие как http://www.w3.org/2000/svg.","ar":"تمكّن الوكلاء من إنشاء رموز SVG متسقة ومرنة من خلال اتباع معايير محددة، واستخدام SvgProps من @lib/ui/props وضمان التوافق مع دليل lib/ui/icons، مع دعم بروتوكولات مثل http://www.w3.org/2000/svg."},"useCases":{"en":["Standardizing icon creation in the lib/ui/icons directory","Generating consistent SVG icons with SvgProps","Updating existing icons to follow the svg-icon-pattern standards"],"zh":["在lib/ui/icons目录中标准化图标创建","使用SvgProps生成一致的SVG图标","更新现有的图标以遵循svg-icon-pattern标准"],"ja":["lib/ui/iconsディレクトリでのアイコン作成の標準化","SvgPropsを使用して一貫性のあるSVGアイコンを生成する","svg-icon-pattern規格に従うように既存のアイコンを更新する"],"ko":["lib/ui/icons 디렉토리에서 아이콘 생성을 표준화하는 것","SvgProps를 사용하여 일관된 SVG 아이콘을 생성하는 것","기존의 아이콘을 svg-icon-pattern 표준에 따라 업데이트하는 것"],"es":["Estandarizar la creación de iconos en el directorio lib/ui/icons","Generar iconos SVG coherentes con SvgProps","Actualizar iconos existentes para seguir los estándares svg-icon-pattern"],"fr":["Standardiser la création d''icônes dans le répertoire lib/ui/icons","Générer des icônes SVG cohérentes avec SvgProps","Mettre à jour les icônes existantes pour suivre les normes svg-icon-pattern"],"de":["Die Erstellung von Icons im Verzeichnis lib/ui/icons standardisieren","Konsistente SVG-Icons mit SvgProps generieren","Vorhandene Icons aktualisieren, um den svg-icon-pattern-Standards zu entsprechen"],"pt":["Padronizar a criação de ícones no diretório lib/ui/icons","Gerar ícones SVG consistentes com SvgProps","Atualizar ícones existentes para seguir os padrões svg-icon-pattern"],"ru":["Стандартизировать создание иконок в директории lib/ui/icons","Генерировать последовательные иконки SVG с помощью SvgProps","Обновлять существующие иконки для соответствия стандартам svg-icon-pattern"],"ar":["تقييس إنشاء الرموز في دليل lib/ui/icons","إنتاج رموز SVG متسقة مع SvgProps","تحديث الرموز الحالية لتتبع معايير svg-icon-pattern"]},"limitations":{"en":["Requires access to the lib/ui/icons directory","Specific to SVG icons","Must use SvgProps from @lib/ui/props"],"zh":["需要访问lib/ui/icons目录","仅针对SVG图标","必须使用@lib/ui/props中的SvgProps"],"ja":["lib/ui/iconsディレクトリへのアクセスが必要","SVGアイコンにのみ適用","@lib/ui/propsからのSvgPropsを使用する必要がある"],"ko":["lib/ui/icons 디렉토리에 접근 권한이 필요","SVG 아이콘만 해당","@lib/ui/props의 SvgProps를 사용해야 함"],"es":["Requiere acceso al directorio lib/ui/icons","Específico para iconos SVG","Debe utilizar SvgProps desde @lib/ui/props"],"fr":["Nécessite un accès au répertoire lib/ui/icons","Spécifique aux icônes SVG","Doit utiliser SvgProps depuis @lib/ui/props"],"de":["Erfordert Zugriff auf das Verzeichnis lib/ui/icons","Spezifisch für SVG-Icons","Muss SvgProps von @lib/ui/props verwenden"],"pt":["Requer acesso ao diretório lib/ui/icons","Específico para ícones SVG","Deve usar SvgProps do @lib/ui/props"],"ru":["Требует доступа к директории lib/ui/icons","Конкретно для иконок SVG","Должно использовать SvgProps из @lib/ui/props"],"ar":["يتطلب الوصول إلى دليل lib/ui/icons","محدد للرموز SVG","يجب استخدام SvgProps من @lib/ui/props"]},"version":4},"contentHash":"0f6cd2fa6203a867a7b114599fa66cfee0fb8876a88c1ee797e2c6b2933967b7","qualityScore":48}');
