INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vultisig/vultisig-windows/svg-icon-pattern', 'svg-icon-pattern', 'vultisig', 'vultisig-windows', 'community', 'svg-icon-pattern vultisig vultisig-windows community The svg-icon-pattern skill ensures consistency and flexibility in icon creation by following specific standards. It benefits developers working with SVG icons in the lib/ui/icons directory. SVG 图标模式是一种确保图标一致性和灵活性的标准，包括图标组件定义和 SvgProps 的使用 SVG アイコン パターンは、アイコンのコンシステンシーとフレキシビリティを確保するためのスタンダードであり、アイコンコンポーネント定義と SvgProps の使用が含まれる SVG 아이콘 패턴은 아이콘의 일관성과 유연성을 보장하는 표준으로, 아이콘 컴포넌트 정의와 SvgProps 사용이 포함됩니다 El patrón de iconos SVG proporciona una forma estandarizada de crear iconos en el directorio lib/ui/icons Le modèle d''icônes SVG fournit un moyen normalisé de créer des icônes dans le répertoire lib/ui/icons Das SVG-Icon-Muster bietet eine standardisierte Möglichkeit, Icons im Verzeichnis lib/ui/icons zu erstellen O padrão de ícone SVG é uma abordagem para criar ícones consistentes e flexíveis, utilizando componentes de ícone e propriedades de SVG. Стандарт иконки SVG - это подход к созданию последовательных и гибких иконок, использующий компоненты иконок и свойства SVG с помощью ИИ Агентов نمط الأيقونة SVG هو نهج لإنشاء رموز متسقة ومرنة، باستخدام مكونات الأيقونة وخصائص SVG مع أدوات الذكاء الاصطناعي how to use svg-icon-pattern svg-icon-pattern best practices svg-icon-pattern alternative svg-icon-pattern vs icon libraries svg-icon-pattern install svg-icon-pattern setup guide what is svg-icon-pattern svg-icon-pattern tutorial svg-icon-pattern for AI agents SVG 图标模式 图标组件定义 SvgProps React TypeScript xmlns width AIエージェント AI工具 Exports a named component that receives SvgProps from @lib/ui/props Spreads SvgProps onto the svg element for consistency Utilizes the @lib/ui/props library for SvgProps definition Follows specific standards for icon creation in the lib/ui/icons directory Ensures flexibility through proper icon component definition Supports SvgProps implementation for customizable icons svg-icon-pattern is a set of standards for creating and updating icons in the lib/ui/icons directory, ensuring consistency and flexibility through proper icon component definition and SvgProps implementation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bigalorm/bigal/enforcing-typescript-standards', 'community', 'bigalorm', 'bigal', 'bigalorm/bigal', 'enforcing-typescript-standards', 9, 2, 48, '2026-02-27T04:49:09Z', '2026-03-06T06:47:24.942Z', '4b3438ff1ce7938cadbdb4772a601dd11fdfdecb1ee44c554bc34a6e213f21cd', '{"id":"bigalorm/bigal/enforcing-typescript-standards","name":"enforcing-typescript-standards","description":{"en":"This skill enforces a project''s core TypeScript standards, ensuring explicit typing, import organization, and code safety rules for node.js and PostgreSQL developers","zh":"本技能强制执行 TypeScript 项目的核心标准，包括显式类型、导入组织、类成员排序和代码安全规则。适用于 Node.js 和 PostgreSQL 项目","ja":"このスキルは、TypeScript プロジェクトの核となる標準を強制します。明示的な型付け、インポートの組織化、クラスメンバーの順序付け、コードの安全性ルールなどが含まれます。Node.js と PostgreSQL プロジェクトに適しています","ko":"이 스킬은 TypeScript 프로젝트의 핵심 표준을 강제 실행합니다. 명시적 유형, 가져오기 조직, 클래스 멤버 순서 지정 및 코드 안전 규칙 등이 포함됩니다. Node.js 및 PostgreSQL 프로젝트에 적합합니다","es":"Esta habilidad de AI Agent garantiza el cumplimiento de los estandares de TypeScript, mejorando la calidad del código","fr":"Cette compétence d''Outil IA assure le respect des normes TypeScript, améliorant ainsi la qualité du code","de":"Diese Fähigkeit von KI-Tool gewährleistet die Einhaltung der TypeScript-Standards, verbessert die Codequalität","pt":"Este skill ajuda a aplicar padrões de TypeScript em projetos, garantindo explicit typing, import organization e code safety rules.","ru":"Этот навык помогает устанавливать стандарты TypeScript в проектах, гарантируя явное типизирование, организацию импорта и правила безопасности кода.","ar":"هذا المهارة يساعد على تطبيق معايير TypeScript في المشاريع، مما يضمن الكتابة 明确 وتنظيم الاستيراد وقواعد أمان الكود."},"seo":{"title":{"en":"Enforcing TypeScript Standards: Code Quality Setup Guide ...","zh":"TypeScript 标准强制执行设置指南","ja":"TypeScript 標準を強制するためのベストプラクティス","ko":"TypeScript 표준 강제 실행 가이드","es":"Guía de Configuración de Estandares de TypeScript con AI ...","fr":"Mise en Place des Normes TypeScript avec Outil IA","de":"Einrichtungsleitfaden für TypeScript-Standards mit KI-Tool","pt":"Configurando Padrões de TypeScript: Guia de Implementação","ru":"Установка стандартов TypeScript: Руководство по настройке...","ar":"تطبيق معايير TypeScript: دليل الإعداد للأدوات الذكية"},"description":{"en":"Discover how to enforce TypeScript standards in your project with this AI agent skill, ensuring explicit typing and code safety rules for optimal code quality","zh":"学习如何使用 AI 工具强制执行 TypeScript 项目的核心标准，包括显式类型、导入组织、类成员排序和代码安全规则","ja":"AI エージェントを使用してTypeScriptプロジェクトの核となる標準を強制する方法を学びます。明示的な型付け、インポートの組織化、クラスメンバーの順序付け、コードの安全性ルールなどが含まれます","ko":"AI 도구를 사용하여 TypeScript 프로젝트의 핵심 표준을 강제执行하는 방법을 학습하세요. 명시적 유형, 가져오기 조직, 클래스 멤버 순서 지정 및 코드 안전 규칙이 포함됩니다","es":"Aprende a aplicar estandares de TypeScript en tu proyecto con esta habilidad de AI Agent, incluyendo tipado explícito y organización de imports","fr":"Découvrez comment appliquer les normes TypeScript dans votre projet avec cette compétence d''Outil IA, y compris le typage explicite et l''organisation des imp...","de":"Erfahren Sie, wie Sie TypeScript-Standards in Ihrem Projekt mit dieser Fähigkeit von KI-Tool anwenden, einschließlich expliziter Typisierung und Importorgani...","pt":"Aprenda a aplicar padrões de TypeScript em seus projetos com este guia de implementação. Melhore a qualidade do código e a produtividade da equipe.","ru":"Узнайте, как устанавливать стандарты TypeScript в своих проектах с помощью этого руководства. Улучшите качество кода и производительность команды с помощью И...","ar":"تعرف على كيفية تطبيق معايير TypeScript في مشاريعك مع هذا الدليل. تحسين جودة الكود وزيادة إنتاجية الفريق مع الأدوات الذكية."},"definition":{"en":"enforcing-typescript-standards is a skill that enforces explicit typing, import organization, class member ordering, and code safety rules for TypeScript projects","zh":"TypeScript 标准强制执行是指使用 AI 工具强制执行 TypeScript 项目的核心标准","ja":"TypeScript 標準を強制するとは、AI エージェントを使用してTypeScriptプロジェクトの核となる標準を強制することです","ko":"TypeScript 표준 강제 실행은 AI 도구를 사용하여 TypeScript 프로젝트의 핵심 표준을 강제 실행하는 것을 의미합니다","es":"Un conjunto de reglas para garantizar la calidad del código TypeScript","fr":"Un ensemble de règles pour assurer la qualité du code TypeScript","de":"Ein Satz von Regeln zur Gewährleistung der Qualität des TypeScript-Codes","pt":"O que é Enforcing TypeScript Standards? É um skill que ajuda a aplicar padrões de TypeScript em projetos.","ru":"Что такое Enforcing TypeScript Standards? Это навык, который помогает устанавливать стандарты TypeScript в проектах.","ar":"ما هو تطبيق معايير TypeScript؟ هو مهارة تساعد على تطبيق معايير TypeScript في المشاريع."},"features":{"en":["Enforces explicit typing for TypeScript code","Organizes imports for cleaner code structure","Orders class members for improved readability","Applies code safety rules for secure coding practices","Triggers on keywords like ''write'', ''fix'', and ''review'' for TypeScript code"],"zh":["显式类型强制执行","导入组织和排序","类成员排序和安全规则","Node.js 和 PostgreSQL 项目支持","代码安全性和质量检查"],"ja":["明示的な型付けの強制","インポートの組織化とソート","クラスメンバーの順序付けと安全性ルール","Node.js と PostgreSQL プロジェクトのサポート","コードの安全性と品質のチェック"],"ko":["명시적 유형 강제 실행","가져오기 조직 및 정렬","클래스 멤버 순서 지정 및 안전 규칙","Node.js 및 PostgreSQL 프로젝트 지원","코드 안전성 및 품질 체크"],"es":["Tipado explícito","Organización de imports","Ordenación de miembros de clase","Reglas de seguridad de código","Compatibilidad con PostgreSQL y node.js"],"fr":["Typage explicite","Organisation des imports","Ordre des membres de classe","Règles de sécurité de code","Compatibilité avec PostgreSQL et node.js"],"de":["Explizite Typisierung","Importorganisation","Klassenmitglied-Reihenfolge","Code-Sicherheitsregeln","Kompatibilität mit PostgreSQL und node.js"],"pt":["Explicit typing","Import organization","Class member ordering","Code safety rules","Integração com Node.js e PostgreSQL"],"ru":["Явное типизирование","Организация импорта","Упорядочение членов класса","Правила безопасности кода","Интеграция с Node.js и PostgreSQL"],"ar":["كتابة明确","تنظيم الاستيراد","ترتيب أعضاء الفئة","قواعد أمان الكود","التكامل مع Node.js و PostgreSQL"]},"keywords":{"en":["how to use enforcing-typescript-standards","enforcing-typescript-standards setup guide","enforcing-typescript-standards vs tslint","enforcing-typescript-standards install","what is enforcing-typescript-standards","enforcing-typescript-standards for nodejs","enforcing-typescript-standards for postgres","enforcing-typescript-standards alternative","enforcing-typescript-standards best practices"],"zh":["TypeScript 标准","AI 工具","Node.js","PostgreSQL","代码安全性","代码质量","显式类型","导入组织"],"ja":["TypeScript 標準","AI エージェント","Node.js","PostgreSQL","コードの安全性","コードの品質","明示的な型付け","インポートの組織化"],"ko":["TypeScript 표준","AI 도구","Node.js","PostgreSQL","코드 안전성","코드 품질","명시적 유형","가져오기 조직"],"es":["estandares de TypeScript","AI Agent","Herramientas de desarrollo","node.js","PostgreSQL","ORM","tipado explícito","organización de imports"],"fr":["normes TypeScript","Outil IA","Outils de développement","node.js","PostgreSQL","ORM","typage explicite","organisation des imports"],"de":["TypeScript-Standards","KI-Tool","Entwicklungstools","node.js","PostgreSQL","ORM","explizite Typisierung","Importorganisation"],"pt":["TypeScript","Node.js","PostgreSQL","ORM","Padrões de código","Segurança de código","Desenvolvimento de software","Programação em TypeScript"],"ru":["TypeScript","Node.js","PostgreSQL","ORM","Стандарты кода","Безопасность кода","Разработка программного обеспечения","Программирование на TypeScript"],"ar":["TypeScript","Node.js","PostgreSQL","ORM","معايير الكود","أمان الكود","تطوير البرمجيات","برمجة بلغة TypeScript"]}},"owner":"bigalorm","repo":"bigal","repoPath":"bigalorm/bigal","stars":9,"forks":2,"updatedAt":"2026-02-27T04:49:09Z","topics":["hacktoberfest","hacktoberfest2022","hacktoberfest2023","nodejs","orm","postgres"],"category":"community","skillMd":{"name":"enforcing-typescript-standards","description":"Enforces the projects core TypeScript standards including explicit typing, import organization, class member ordering, and code safety rules. ALWAYS apply when creating, modifying, or reviewing any TypeScript (.ts/.tsx) file.","bodyPreview":"# Enforcing TypeScript Standards\n\nEnforces the project''s core TypeScript standards including explicit typing, import organization, class member ordering, and code safety rules.\n\n## Triggers\n\nActivate this skill when the user says or implies any of these:\n\n- \"write\", \"create\", \"implement\", \"add\", \"build\" (new TypeScript code)\n- \"fix\", \"update\", \"change\", \"modify\", \"refactor\" (existing TypeScript code)\n- \"review\", \"check\", \"improve\", \"clean up\" (code quality)\n- Any request involving `.ts` or `.tsx","body":"# Enforcing TypeScript Standards\n\nEnforces the project''s core TypeScript standards including explicit typing, import organization, class member ordering, and code safety rules.\n\n## Triggers\n\nActivate this skill when the user says or implies any of these:\n\n- \"write\", \"create\", \"implement\", \"add\", \"build\" (new TypeScript code)\n- \"fix\", \"update\", \"change\", \"modify\", \"refactor\" (existing TypeScript code)\n- \"review\", \"check\", \"improve\", \"clean up\" (code quality)\n- Any request involving `.ts` or `.tsx` files\n\nSpecific triggers:\n\n- Creating a new `.ts` or `.tsx` file\n- Modifying existing TypeScript code\n- Reviewing TypeScript code for compliance\n\n## Core Standards\n\n### Type Safety\n\n- **Explicit return types**: Prefer explicit return types when practical; omit when inference is obvious and adds no clarity\n- **Explicit member accessibility**: Class members require `public`, `private`, or `protected`\n- **Type-only imports**: Use `import type` for types: `import type { Foo } from ''./foo.js''`\n- **Sorted type constituents**: Union/intersection types must be alphabetically sorted\n- **Only throw Error objects**: Never throw strings or other primitives\n- **Avoid `any` and type assertions**: Prefer proper typing over `any` or `as` casts; use them only when truly necessary\n- **Type JSON fields explicitly**: Use `Record<string, unknown>` or specific interfaces for JSON data, never `any`\n- **Use Number() for conversion**: Prefer `Number(value)` over `parseInt(value, 10)` or `parseFloat(value)`\n- **Reuse existing types**: Before defining a new interface, search for existing types that can be reused directly, extended, or derived using `Pick`, `Omit`, `Partial`, or other utility types\n\n#### Alternatives to Type Assertions\n\nBefore using `as`, try these approaches in order:\n\n1. Proper typing at the source\n2. Type guards (`typeof`, `instanceof`)\n3. Type narrowing through control flow\n4. Custom type predicate functions\n5. Discriminated unions\n\n```ts\n// Bad\nconst user = data as User;\n\n// Good\nfunction isUser(data: unknown): data is User {\n  return typeof data === ''object'' && data !== null && ''id'' in data;\n}\nif (isUser(data)) {\n  // data is now typed as User\n}\n```\n\n### Import Organization\n\n- **Import order**: built-in → external → internal → parent → sibling → index (alphabetized within groups)\n- **No duplicate imports**: Consolidate imports from the same module\n- **Newline after imports**: Empty line required after import block\n\n### Class Member Ordering\n\n1. Signatures (call/construct)\n2. Fields: private → public → protected\n3. Constructors: public → protected → private\n4. Methods: public → protected → private\n\n### Code Style\n\n- **Simplicity over cleverness**: Straightforward, readable code is better than clever one-liners\n- **Early returns**: Use guard clauses to reduce nesting; return early for edge cases\n- **Nullish coalescing**: Prefer `??` over `||` for defaults (avoids false positives on `0` or `''''`)\n- **Optional chaining**: Use `?.` for safe property access\n- **Match existing patterns**: Follow conventions already established in the codebase\n- **Meaningful identifiers**: Names must be descriptive (exceptions: `_`, `i`, `j`, `k`, `e`, `x`, `y`)\n- **Function declarations**: Use `function foo()` not `const foo = function()`\n- **Prefer const**: Use `const` unless reassignment is needed\n- **No var**: Always use `const` or `let`\n- **Object shorthand**: Use `{ foo }` not `{ foo: foo }`\n- **Template literals**: Use `` `Hello ${name}` `` not `''Hello '' + name`\n- **Strict equality**: Use `===` except for null comparisons\n- **One class per file**: Maximum one class definition per file\n- **Avoid `reduce`**: Prefer `for...of` loops or other array methods for clarity\n- **Functions over classes**: Prefer exported functions over classes with static methods (unless state is needed)\n- **No nested functions**: Define helper functions at module level, not inside other functions\n- **Immutability**: Create new objects/arrays instead of mutating existing ones\n\n### Naming Conventions\n\n- **Enum members**: Use `PascalCase` (e.g., `MyValue`)\n- **No trailing underscores**: Identifiers cannot end with `_`\n\n### Comments\n\n- **No redundant comments**: Never comment what the code already expresses clearly\n- **No duplicate comments**: Don''t repeat information from function names, types, or nearby comments\n- **Meaningful only**: Only add comments to explain _why_, not _what_ — the code shows what it does\n\n### Boolean Expressions\n\n- **Prefer truthiness checks**: Use implicit truthy/falsy checks over explicit comparisons\n- **Exception**: Use explicit checks when distinguishing `0`/`''''` (valid values) from `null`/`undefined` is semantically important\n\n### Testing\n\n- **Minimize mocking**: Avoid mocking everything; use real implementations and data generators when available\n- **Test real behavior**: Testing mocks provides little value — test actual code paths\n- **Don''t be lazy**: Write thorough tests that cover edge cases, not just happy paths\n\n### Error Handling\n\n- **Specific error types**: Prefer specific error types over generic `Error` when meaningful\n- **Avoid silent failures**: Don''t swallow errors with empty catch blocks\n- **Handle rejections**: Always handle promise rejections\n- **Let errors propagate**: Don''t catch errors just to re-throw or log — let them bubble up to error handlers\n\n## Negative Knowledge\n\nAvoid these antipatterns:\n\n- `console.log()` statements in production code\n- `eval()` or `Function()` constructor\n- Nested ternary operators\n- `await` inside loops when `Promise.all` would be simpler (sequential awaits are fine when order matters or parallelism adds complexity)\n- Empty interfaces\n- Variable shadowing\n- Functions defined inside loops\n- `@ts-ignore` without explanation (use `@ts-expect-error` with 10+ char description)\n- Comments that restate the code: `// increment counter` above `counter++`\n- Comments that duplicate type information: `// returns a string` when return type is `: string`\n- Commented-out code (delete it; use version control)\n- Verbose boolean comparisons: `arr.length > 0`, `str !== ''''`, `obj !== null && obj !== undefined`\n- Disabling linter rules via comments (fix the code instead)\n- Overuse of `any` type or `as` type assertions\n- Over-mocking in tests instead of using real implementations or data generators\n- Empty catch blocks that silently swallow errors\n- Using `||` for defaults when `??` is more appropriate\n- Deep nesting when early returns would simplify\n- Catching errors just to re-throw or log them\n- Nested function definitions inside other functions\n- Mutating objects/arrays instead of creating new ones\n- TOCTOU: Checking file/resource existence before operating (try and handle errors instead)\n- Classes with only static methods (use plain functions instead)\n- Duplicating existing interfaces instead of reusing or deriving with `Pick`/`Omit`/`Partial`\n\n## Verification Workflow\n\n1. **Analyze**: Compare the code change against these TypeScript standards\n2. **Generate/Refactor**: Write or modify code to comply with all rules above\n3. **Simplify**: Review for opportunities to simplify — prefer clear, straightforward code over clever solutions\n4. **Review naming**: Verify variable and function names still make sense in context after changes\n5. **Build**: Verify types compile without errors (e.g., `npm run build` or `npx tsc --noEmit`)\n6. **Lint**: Run `npm run lint` to confirm compliance before completing the task\n\n## Examples\n\n### Comments Examples\n\n```ts\n// Standard\n// Retry with exponential backoff to handle transient network failures\nasync function fetchWithRetry(url: string, attempts = 3): Promise<Response> {\n  for (let i = 0; i < attempts; i++) {\n    try {\n      return await fetch(url);\n    } catch {\n      await sleep(2 ** i * 100);\n    }\n  }\n  throw new Error(`Failed after ${attempts} attempts`);\n}\n\n// Non-Standard\n/**\n * Fetches data from a URL with retry logic\n * @param url - The URL to fetch from\n * @param attempts - Number of attempts (default 3)\n * @returns A Promise that resolves to a Response\n */\nasync function fetchWithRetry(url: string, attempts = 3): Promise<Response> {\n  // Loop through attempts\n  for (let i = 0; i < attempts; i++) {\n    try {\n      // Try to fetch the URL\n      return await fetch(url);\n    } catch {\n      // Wait before retrying\n      await sleep(2 ** i * 100);\n    }\n  }\n  // Throw error if all attempts fail\n  throw new Error(`Failed after ${attempts} attempts`);\n}\n```\n\n### Boolean Expressions Examples\n\n```ts\n// Standard\nif (myArray.length) {\n}\nif (myString) {\n}\nif (myObject) {\n}\nif (!value) {\n}\n\n// Non-Standard\nif (myArray.length !== 0) {\n}\nif (myArray.length > 0) {\n}\nif (myString !== '''') {\n}\nif (myObject !== null && myObject !== undefined) {\n}\nif (value === null || value === undefined) {\n}\n```\n\n### Early Return Examples\n\n```ts\n// Standard\nfunction processUser(user: User | null): Result {\n  if (!user) {\n    return { error: ''No user provided'' };\n  }\n  if (!user.isActive) {\n    return { error: ''User is inactive'' };\n  }\n  return { data: transform(user) };\n}\n\n// Non-Standard\nfunction processUser(user: User | null): Result {\n  if (user) {\n    if (user.isActive) {\n      return { data: transform(user) };\n    } else {\n      return { error: ''User is inactive'' };\n    }\n  } else {\n    return { error: ''No user provided'' };\n  }\n}\n```\n\n### Functions Over Classes Examples\n\n```ts\n// Standard\nexport function calculateTotal(items: Item[]): number {\n  return items.reduce((sum, item) => sum + item.price, 0);\n}\n\nexport function formatCurrency(amount: number): string {\n  return `$${amount.toFixed(2)}`;\n}\n\n// Non-Standard\nexport class Calculator {\n  static calculateTotal(items: Item[]): number {\n    return items.reduce((sum, item) => sum + item.price, 0);\n  }\n\n  static formatCurrency(amount: number): string {\n    return `$${amount.toFixed(2)}`;\n  }\n}\n```\n\n### No Nested Functions Examples\n\n```ts\n// Standard\nfunction transformItem(item: Item): TransformedItem {\n  return { id: item.id, name: item.name.toUpperCase() };\n}\n\nasync function processItems(items: Item[]): Promise<TransformedItem[]> {\n  return items.map(transformItem);\n}\n\n// Non-Standard\nasync function processItems(items: Item[]): Promise<TransformedItem[]> {\n  function transformItem(item: Item): TransformedItem {\n    return { id: item.id, name: item.name.toUpperCase() };\n  }\n  return items.map(transformItem);\n}\n```\n\n### Immutability Examples\n\n```ts\n// Standard\nfunction addItem(items: Item[], newItem: Item): Item[] {\n  return [...items, newItem];\n}\n\nfunction removeItem(items: Item[], id: string): Item[] {\n  return items.filter((item) => item.id !== id);\n}\n\nfunction updateItem(items: Item[], id: string, updates: Partial<Item>): Item[] {\n  return items.map((item) => (item.id === id ? { ...item, ...updates } : item));\n}\n\n// Non-Standard\nfunction addItem(items: Item[], newItem: Item): Item[] {\n  items.push(newItem);\n  return items;\n}\n\nfunction removeItem(items: Item[], id: string): Item[] {\n  const index = items.findIndex((item) => item.id === id);\n  items.splice(index, 1);\n  return items;\n}\n```\n\n### Error Propagation Examples\n\n```ts\n// Standard\nasync function getUser(id: string): Promise<User> {\n  return userService.findById(id);\n}\n\n// Non-Standard\nasync function getUser(id: string): Promise<User> {\n  try {\n    return await userService.findById(id);\n  } catch (error) {\n    console.error(error);\n    throw error;\n  }\n}\n```\n\n### TOCTOU Examples\n\n```ts\n// Standard\nasync function readConfig(path: string): Promise<Config> {\n  try {\n    const content = await readFile(path, ''utf-8'');\n    return JSON.parse(content);\n  } catch (error) {\n    if (isNotFoundError(error)) {\n      return defaultConfig;\n    }\n    throw error;\n  }\n}\n\n// Non-Standard\nasync function readConfig(path: string): Promise<Config> {\n  if (await fileExists(path)) {\n    const content = await readFile(path, ''utf-8'');\n    return JSON.parse(content);\n  }\n  return defaultConfig;\n}\n```\n\n### Type Reuse Examples\n\n```ts\n// Given an existing type\ninterface User {\n  id: string;\n  email: string;\n  name: string;\n  passwordHash: string;\n  createdAt: Date;\n  updatedAt: Date;\n}\n\n// Standard - derive from existing type\ntype PublicUser = Omit<User, ''passwordHash''>;\ntype UserSummary = Pick<User, ''id'' | ''name''>;\ntype UserUpdate = Partial<Pick<User, ''email'' | ''name''>>;\n\n// Non-Standard - duplicating fields that already exist\ninterface PublicUser {\n  id: string;\n  email: string;\n  name: string;\n  createdAt: Date;\n  updatedAt: Date;\n}\n\ninterface UserSummary {\n  id: string;\n  name: string;\n}\n\ninterface UserUpdate {\n  email?: string;\n  name?: string;\n}\n```\n"},"lastSynced":"2026-03-06T06:47:24.942Z","agentAnalysis":{"suitability":{"en":"Essential for TypeScript Development Agents requiring strict code quality enforcement and standards compliance.","zh":"对于需要严格执行代码质量和标准合规性的 TypeScript 开发智能体至关重要。","ja":"コード品質の厳格な実施と標準への準拠を必要とする TypeScript 開発エージェントに不可欠です。","ko":"엄격한 코드 품질 시행 및 표준 준수가 필요한 TypeScript 개발 에이전트에 필수적입니다.","es":"Esencial para Agentes de Desarrollo de TypeScript que requieren una estricta aplicación de la calidad del código y el cumplimiento de normas.","fr":"Essentiel pour les Agents de Développement TypeScript nécessitant une application stricte de la qualité du code et la conformité aux normes.","de":"Wesentlich für TypeScript-Entwicklungsagenten, die eine strikte Durchsetzung der Codequalität und die Einhaltung von Standards erfordern.","pt":"Essencial para Agentes de Desenvolvimento TypeScript que exigem aplicação estrita de qualidade de código e conformidade com normas.","ru":"Необходимо для Агентов разработки TypeScript, требующих строгого контроля качества кода и соблюдения стандартов.","ar":"ضروري للوكلاء النمطية TypeScript الذين يتطلبون فرض جودة صارمة للكود ومواصفات المعايير."},"recommendation":{"en":"Enables automated enforcement of explicit typing, import organization, class member ordering, and code safety rules for Node.js and PostgreSQL TypeScript projects. Provides comprehensive static analysis capabilities for maintaining enterprise-grade code standards.","zh":"为 Node.js 和 PostgreSQL TypeScript 项目提供自动化的显式类型、导入组织、类成员排序和代码安全规则的强制执行能力。提供全面的静态分析功能，以维护企业级代码标准。","ja":"Node.js および PostgreSQL TypeScript プロジェクトにおいて、明示的な型付け、インポートの整理、クラスメンバーの順序付け、コード安全性ルールの自動的な実施を可能にします。エンタープライズグレードのコード標準を維持するための包括的な静的解析機能を提供します。","ko":"Node.js 및 PostgreSQL TypeScript 프로젝트를 위한 명시적 타입 지정, import 구성, 클래스 멤버 순서 지정 및 코드 안전성 규칙의 자동화된 시행을 가능하게 합니다. 엔터프라이즈급 코드 표준을 유지하기 위한 포괄적인 정적 분석 기능을 제공합니다.","es":"Permite la aplicación automatizada de la tipificación explícita, la organización de importaciones, el orden de los miembros de la clase y las reglas de seguridad del código para proyectos de TypeScript de Node.js y PostgreSQL. Proporciona capacidades de análisis estático completas para mantener los estándares de código de nivel empresarial.","fr":"Permet l''application automatisée de la typification explicite, de l''organisation des imports, de l''ordre des membres de la classe et des règles de sécurité du code pour les projets TypeScript de Node.js et PostgreSQL. Fournit des capacités d''analyse statique complètes pour maintenir les normes de code de niveau entreprise.","de":"Ermöglicht die automatisierte Durchsetzung der expliziten Typisierung, der Organisierung von Importen, der Reihenfolge der Klassenelemente und der Code-Sicherheitsregeln für Node.js- und PostgreSQL-TypeScript-Projekte. Bietet umfassende statische Analysefunktionen für die Aufrechterhaltung von Unternehmenscode-Standards.","pt":"Permite a aplicação automatizada de digitação explícita, organização de importação, ordenação de membros de classe e regras de segurança de código para projetos TypeScript do Node.js e PostgreSQL. Fornece capacidades de análise estática abrangentes para manter padrões de código de nível empresarial.","ru":"Позволяет автоматически обеспечивать явное типизирование, организацию импорта, упорядочение членов класса и правила безопасности кода для проектов TypeScript в Node.js и PostgreSQL. Предоставляет всесторонние возможности статического анализа для поддержания корпоративных стандартов кода.","ar":"يسمح بالتطبيق التلقائي للتصنيف الصريح، تنظيم الاستيراد، ترتيب أعضاء الفئة، وقواعد سلامة الكود لمشاريع TypeScript في Node.js وPostgreSQL. يوفر قابليات تحليل ثابتة شاملة للحفاظ على معايير الكود من الدرجة المؤسسية."},"useCases":{"en":["Automating code style enforcement in CI/CD pipelines","Refactoring existing code to meet TypeScript standards","Validating new TypeScript code against project-specific rules","Organizing imports and class member structure automatically"],"zh":["在 CI/CD 流水线中自动化执行代码风格","重构现有代码以符合 TypeScript 标准","根据项目特定规则验证新的 TypeScript 代码","自动组织导入和类成员结构"],"ja":["CI/CD パイプラインでのコードスタイル実施の自動化","TypeScript 標準に適合するための既存コードのリファクタリング","プロジェクト固有のルールに基づく新規 TypeScript コードの検証","import とクラスメンバー構造の自動的な整理"],"ko":["CI/CD 파이프라인에서 코드 스타일 시행 자동화","TypeScript 표준을 충족하도록 기존 코드 리팩토링","프로젝트별 규칙에 대한 새로운 TypeScript 코드 검증","import 및 클래스 멤버 구조 자동 구성"],"es":["Automatización de la aplicación del estilo de código en tuberías de CI/CD","Reestructuración del código existente para cumplir con los estándares de TypeScript","Validación de nuevo código TypeScript contra reglas específicas del proyecto","Organización automática de importaciones y estructura de miembros de la clase"],"fr":["Automatisation de l''application du style de code dans les pipelines de CI/CD","Réorganisation du code existant pour répondre aux normes de TypeScript","Validation du nouveau code TypeScript contre les règles spécifiques au projet","Organisation automatique des imports et de la structure des membres de la classe"],"de":["Automatisierung der Code-Stil-Anwendung in CI/CD-Pipelines","Umstrukturierung des bestehenden Codes, um die TypeScript-Standards zu erfüllen","Validierung des neuen TypeScript-Codes gegen projektspezifische Regeln","Automatische Organisation von Importen und Klassenmitglied-Struktur"],"pt":["Automatizar a aplicação do estilo de código em pipelines de CI/CD","Reorganizar o código existente para atender aos padrões TypeScript","Validar o novo código TypeScript contra regras específicas do projeto","Organizar importações e estrutura de membros de classe automaticamente"],"ru":["Автоматизировать применение стиля кода в конвейерах CI/CD","Перестроить существующий код для соответствия стандартам TypeScript","Проверить новый код TypeScript на соответствие проектным правилам","Автоматически организовать импорты и структуру членов класса"],"ar":["التحكم الآلي في تطبيق نمط الكود في أنابيب CI/CD","إعادة هيكلة الكود الحالي لتحقيق معايير TypeScript","التحقق من صحة الكود الجديد TypeScript ضد قواعد محددة للمشروع","تنظيم الاستيرادات وهيكل أعضاء الفئة تلقائيًا"]},"limitations":{"en":["TypeScript-specific (.ts/.tsx files only)","Requires project-specific configuration for custom rules","Node.js environment dependency"],"zh":["仅限 TypeScript 特定文件（仅 .ts/.tsx 文件）","自定义规则需要项目特定的配置","依赖 Node.js 环境"],"ja":["TypeScript 固有（.ts/.tsx ファイルのみ）","カスタムルールにはプロジェクト固有の設定が必要","Node.js 環境への依存"],"ko":["TypeScript 전용 (.ts/.tsx 파일만 해당)","사용자 정의 규칙에는 프로젝트별 구성 필요","Node.js 환경 종속성"],"es":["Específico de TypeScript (.ts/.tsx archivos solo)","Requiere configuración específica del proyecto para reglas personalizadas","Dependencia del entorno de Node.js"],"fr":["Spécifique à TypeScript (fichiers .ts/.tsx uniquement)","Nécessite une configuration spécifique au projet pour les règles personnalisées","Dépendance de l''environnement Node.js"],"de":["TypeScript-spezifisch (.ts/.tsx-Dateien nur)","Benötigt projektspezifische Konfiguration für benutzerdefinierte Regeln","Abhängigkeit von der Node.js-Umgebung"],"pt":["Específico do TypeScript (arquivos .ts/.tsx apenas)","Exige configuração específica do projeto para regras personalizadas","Dependência do ambiente Node.js"],"ru":["Специфичный для TypeScript (только файлы .ts/.tsx)","Требует проектной конфигурации для пользовательских правил","Зависимость от среды Node.js"],"ar":["محدد لنمطية TypeScript (ملفات .ts/.tsx فقط)","يتطلب cấuفة محددة للمشروع لقواعد مخصصة","اعتماد على بيئة Node.js"]},"version":4},"contentHash":"4b3438ff1ce7938cadbdb4772a601dd11fdfdecb1ee44c554bc34a6e213f21cd","qualityScore":48}');
