INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bigalorm/bigal/enforcing-typescript-standards', 'enforcing-typescript-standards', 'bigalorm', 'bigal', 'community', 'enforcing-typescript-standards bigalorm bigal community hacktoberfest hacktoberfest2022 hacktoberfest2023 nodejs orm postgres This skill enforces a project''s core TypeScript standards, ensuring explicit typing, import organization, and code safety rules for node.js and PostgreSQL developers 本技能强制执行 TypeScript 项目的核心标准，包括显式类型、导入组织、类成员排序和代码安全规则。适用于 Node.js 和 PostgreSQL 项目 このスキルは、TypeScript プロジェクトの核となる標準を強制します。明示的な型付け、インポートの組織化、クラスメンバーの順序付け、コードの安全性ルールなどが含まれます。Node.js と PostgreSQL プロジェクトに適しています 이 스킬은 TypeScript 프로젝트의 핵심 표준을 강제 실행합니다. 명시적 유형, 가져오기 조직, 클래스 멤버 순서 지정 및 코드 안전 규칙 등이 포함됩니다. Node.js 및 PostgreSQL 프로젝트에 적합합니다 Esta habilidad de AI Agent garantiza el cumplimiento de los estandares de TypeScript, mejorando la calidad del código Cette compétence d''Outil IA assure le respect des normes TypeScript, améliorant ainsi la qualité du code Diese Fähigkeit von KI-Tool gewährleistet die Einhaltung der TypeScript-Standards, verbessert die Codequalität Este skill ajuda a aplicar padrões de TypeScript em projetos, garantindo explicit typing, import organization e code safety rules. Этот навык помогает устанавливать стандарты TypeScript в проектах, гарантируя явное типизирование, организацию импорта и правила безопасности кода. هذا المهارة يساعد على تطبيق معايير TypeScript في المشاريع، مما يضمن الكتابة 明确 وتنظيم الاستيراد وقواعد أمان الكود. how to use enforcing-typescript-standards enforcing-typescript-standards setup guide enforcing-typescript-standards vs tslint enforcing-typescript-standards install what is enforcing-typescript-standards enforcing-typescript-standards for nodejs enforcing-typescript-standards for postgres enforcing-typescript-standards alternative enforcing-typescript-standards best practices TypeScript 标准 AI 工具 Node.js PostgreSQL 代码安全性 代码质量 显式类型 导入组织 Enforces explicit typing for TypeScript code Organizes imports for cleaner code structure Orders class members for improved readability Applies code safety rules for secure coding practices Triggers on keywords like ''write'', ''fix'', and ''review'' for TypeScript code enforcing-typescript-standards is a skill that enforces explicit typing, import organization, class member ordering, and code safety rules for TypeScript projects');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fantasy-cc/credit-card-tracker/add-new-credit-card', 'community', 'fantasy-cc', 'credit-card-tracker', 'fantasy-cc/credit-card-tracker', 'add-new-credit-card', 8, 2, 48, '2026-03-01T23:11:27Z', '2026-03-06T06:50:04.315Z', '718a4d532b274d9a58d8bf82675f2d7a5a6954cdeebc24bd51e507db4ea15b9b', '{"id":"fantasy-cc/credit-card-tracker/add-new-credit-card","name":"add-new-credit-card","description":{"en":"The add-new-credit-card skill guides users through adding new credit cards to the application''s catalog, benefiting developers and users alike.","zh":"本文介绍添加新信用卡到CouponCycle的步骤，包括收集卡信息和创建卡模板","ja":"新規クレジットカードを追加し、カードカタログを拡張するための手順を説明します","ko":"신용카드를 추가하고 카드 템플릿을 생성하는 방법을 설명합니다","es":"Esta habilidad te guía a través del proceso de agregar una nueva tarjeta de crédito al catálogo de tarjetas predefinidas de la aplicación","fr":"Cette compétence vous guide à travers le processus d''ajout d''une nouvelle carte de crédit au catalogue de cartes prédéfinies de l''application","de":"Diese Fähigkeit führt Sie durch den Prozess des Hinzufügens einer neuen Kreditkarte zum vordefinierten Kartenkatalog der Anwendung","pt":"Adicione um novo cartão de crédito ao catálogo de cartões pré-definidos da aplicação com este guia passo a passo","ru":"Добавьте новый кредитный карты в систему с помощью этого пошагового руководства","ar":"أضف بطاقة ائتمان جديدة إلى الفهرس المسبق للبطاقات في التطبيق مع هذا الدليل المفصل"},"seo":{"title":{"en":"add-new-credit-card: Setup Guide for AI Agents","zh":"添加新信用卡设置指南 - AIエージェント集成","ja":"新規クレジットカード追加ガイド - AIエージェントを使用したカードカタログの拡張","ko":"신용카드 추가 설정 가이드 - AI 도구를 사용한 카드 템플릿 생성","es":"Guía de configuración para agregar tarjetas de crédito","fr":"Guide d''ajout de cartes de crédit pour les développeurs","de":"Anleitung zum Hinzufügen von Kreditkarten für Entwickler","pt":"Guia de Configuração para Adiciona