INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fantasy-cc/credit-card-tracker/add-new-credit-card', 'add-new-credit-card', 'fantasy-cc', 'credit-card-tracker', 'community', 'add-new-credit-card fantasy-cc credit-card-tracker community The add-new-credit-card skill guides users through adding new credit cards to the application''s catalog, benefiting developers and users alike. 本文介绍添加新信用卡到CouponCycle的步骤，包括收集卡信息和创建卡模板 新規クレジットカードを追加し、カードカタログを拡張するための手順を説明します 신용카드를 추가하고 카드 템플릿을 생성하는 방법을 설명합니다 Esta habilidad te guía a través del proceso de agregar una nueva tarjeta de crédito al catálogo de tarjetas predefinidas de la aplicación Cette compétence vous guide à travers le processus d''ajout d''une nouvelle carte de crédit au catalogue de cartes prédéfinies de l''application Diese Fähigkeit führt Sie durch den Prozess des Hinzufügens einer neuen Kreditkarte zum vordefinierten Kartenkatalog der Anwendung Adicione um novo cartão de crédito ao catálogo de cartões pré-definidos da aplicação com este guia passo a passo Добавьте новый кредитный карты в систему с помощью этого пошагового руководства أضف بطاقة ائتمان جديدة إلى الفهرس المسبق للبطاقات في التطبيق مع هذا الدليل المفصل how to use add-new-credit-card add-new-credit-card setup guide what is add-new-credit-card add-new-credit-card alternative add-new-credit-card vs coupon management add-new-credit-card install add-new-credit-card tutorial couponcycle credit card integration 添加新信用卡 AIエージェント CouponCycle 卡片目录 卡模板 卡片优惠 下载卡片图片 Gathers card information, including card name and issuer Creates card templates with benefits Supports downloading card images Adds support for new card types Requires exact official card name and issuer details add-new-credit-card is a skill that enables users to add new credit cards to a predefined card catalog, requiring card name and issuer information');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dfirtnt/Huntable-CTI-Studio/rs', 'community', 'dfirtnt', 'Huntable-CTI-Studio', 'dfirtnt/Huntable-CTI-Studio', 'rs', 2, 0, 48, '2026-02-26T23:25:56Z', '2026-03-06T07:06:35.444Z', '69df80cce0d2f4e1423c63515501f4bd243448cb519732cc62e330fa640f3576', '{"id":"dfirtnt/Huntable-CTI-Studio/rs","name":"rs","description":{"en":"The rs skill is an open-source CTI platform for OSINT ingestion, observable extraction, and AI-assisted Sigma rule generation with validation, benefiting security analysts and threat hunters.","zh":"RS是一个开源的CTI平台，用于OSINT数据的摄取、可观测数据的提取和AI辅助的Sigma规则生成","ja":"RSはオープンソースのCTIプラットフォームで、OSINTデータのインジェスト、観測可能なデータの抽出、AIアシストのSigmaルール生成が可能","ko":"RS는 OSINT 데이터 수집, 관찰 가능한 데이터 추출 및 AI 지원 시그마 규칙 생성을 위한 오픈 소스 CTI 플랫폼입니다","es":"RS es una habilidad que permite rescorear artículos con Huntable CTI Studio, utilizando comandos como rescore y rescore-ml para mejorar la caza de amenazas","fr":"RS est une compétence qui permet de rescore des articles avec Huntable CTI Studio, en utilisant des commandes comme rescore et rescore-ml pour améliorer la chasse aux menaces","de":"RS ist eine Fähigkeit, die es ermöglicht, Artikel mit Huntable CTI Studio neu zu bewerten, indem Befehle wie rescore und rescore-ml verwendet werden, um die Bedrohungs-Suche zu verbessern","pt":"O rs é uma plataforma de CTI aberta que permite a ingestão de OSINT, extração de observáveis e geração de regras Sigma assistida por IA.","ru":"Rs — это открытая платформа CTI, которая позволяет ингестируйте OSINT, извлекать наблюдаемые данные и генерировать правила Sigma с помощью ИИ.","ar":"rs هي منصة CTI مفتوحة المصدر تسمح باستهلاك OSINT واستخراج المراقب وتوليد قواعد سيجما بمساعدة الذكاء الاصطناعي."},"seo":{"title":{"en":"rs: AI-Assisted Sigma Rule Generation Setup Guide | AI Ag...","zh":"RS AI工具：威胁狩猎评分和Sigma规则生成设置指南","ja":"RS AIエージェント：脅威ハンティングスコアリングとSigmaルール生成のベストプラクティス","ko":"RS AI 에이전트: 위협 사냥 평가 및 시그마 규칙 생성 가이드","es":"RS: Guía de configuración para rescore de artículos con H...","fr":"RS: Guide de configuration pour le rescore d''articles ave...","de":"RS: Konfigurationsleitfaden für Artikel-Rescore mit Hunta...","pt":"Guia de Configuração do rs: Plataforma de CTI Aberta para...","ru":"Настройка rs: Открытая платформа CTI для ингестии OSINT и...","ar":"دليل إعداد rs: منصة CTI مفتوحة المصدر لاستيعاب OSINT وتول..."},"description":{"en":"Discover how to leverage rs for OSINT ingestion and observable extraction. Learn to validate AI-assisted Sigma rules with our expert guide and maximize your ...","zh":"了解RS AI工具的功能和用途，包括威胁狩猎评分和Sigma规则生成，提高您的威胁检测能力","ja":"RS AIエージェントの機能と使い方を理解し、脅威検出能力を高める","ko":"RS AI 에이전트의 기능과 용도를 이해하고 위협 탐지 능력을 향상시키세요","es":"Aprende a utilizar RS para rescorear artículos con Huntable CTI Studio y mejora tus capacidades de caza de amenazas con Sigma rule generation","fr":"Découvrez comment utiliser RS pour rescore des articles avec Huntable CTI Studio et améliorez vos capacités de chasse aux menaces avec la génération de règle...","de":"Erfahren Sie, wie Sie RS verwenden, um Artikel mit Huntable CTI Studio neu zu bewerten und Ihre Bedrohungs-Suchfähigkeiten mit Sigma-Regelgenerierung zu verb...","pt":"Aprenda a configurar o rs, uma plataforma de CTI aberta para ingestão de OSINT, extração de observáveis e geração de regras Sigma assistida por IA","ru":"Узнайте, как настроить rs, открытую платформу CTI для ингестии OSINT, извлечения наблюдаемых данных и генерации правил Sigma с помощью ИИ","ar":"تعرف على كيفية إعداد rs، منصة CTI مفتوحة المصدر لاستيعاب OSINT واستخراج المراقب وإنشاء قواعد سيجما بمساعدة الذكاء الاصطناعي"},"definition":{"en":"rs is an open-source CTI platform that enables OSINT ingestion, observable extraction, and AI-assisted Sigma rule generation with validation","zh":"RS是一个开源的CTI平台，用于威胁狩猎和Sigma规则生成","ja":"RSはオープンソースのCTIプラットフォームで、脅威ハンティングとSigmaルール生成に使用","ko":"RS는 오픈 소스 CTI 플랫폼으로 위협 사