INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dfirtnt/Huntable-CTI-Studio/rs', 'rs', 'dfirtnt', 'Huntable-CTI-Studio', 'community', 'rs dfirtnt Huntable-CTI-Studio community The rs skill is an open-source CTI platform for OSINT ingestion, observable extraction, and AI-assisted Sigma rule generation with validation, benefiting security analysts and threat hunters. RS是一个开源的CTI平台，用于OSINT数据的摄取、可观测数据的提取和AI辅助的Sigma规则生成 RSはオープンソースのCTIプラットフォームで、OSINTデータのインジェスト、観測可能なデータの抽出、AIアシストのSigmaルール生成が可能 RS는 OSINT 데이터 수집, 관찰 가능한 데이터 추출 및 AI 지원 시그마 규칙 생성을 위한 오픈 소스 CTI 플랫폼입니다 RS es una habilidad que permite rescorear artículos con Huntable CTI Studio, utilizando comandos como rescore y rescore-ml para mejorar la caza de amenazas RS est une compétence qui permet de rescore des articles avec Huntable CTI Studio, en utilisant des commandes comme rescore et rescore-ml pour améliorer la chasse aux menaces RS ist eine Fähigkeit, die es ermöglicht, Artikel mit Huntable CTI Studio neu zu bewerten, indem Befehle wie rescore und rescore-ml verwendet werden, um die Bedrohungs-Suche zu verbessern O rs é uma plataforma de CTI aberta que permite a ingestão de OSINT, extração de observáveis e geração de regras Sigma assistida por IA. Rs — это открытая платформа CTI, которая позволяет ингестируйте OSINT, извлекать наблюдаемые данные и генерировать правила Sigma с помощью ИИ. rs هي منصة CTI مفتوحة المصدر تسمح باستهلاك OSINT واستخراج المراقب وتوليد قواعد سيجما بمساعدة الذكاء الاصطناعي. how to use rs rs setup guide rs alternative rs vs other CTI platforms what is rs rs install rs CTI studio AI-assisted Sigma rule generation OSINT ingestion tools RS AI工具 威胁狩猎 Sigma规则生成 OSINT数据摄取 可观测数据提取 AI辅助规则生成 CLI命令行工具 CTI平台 Runs rescore commands for keyword/regex hunt scores and ML hunt scores Utilizes `threat_hunting_score` in article metadata for scoring Leverages `ml_hunt_score` from chunk-level model predictions for ML-based scoring Executes `./run_cli.sh rescore --force` and `./run_cli.sh rescore-ml --force` commands Supports validation of AI-assisted Sigma rules rs is an open-source CTI platform that enables OSINT ingestion, observable extraction, and AI-assisted Sigma rule generation with validation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EPOCHDevs/ClaudeCodeResearch/build-job-data', 'community', 'EPOCHDevs', 'ClaudeCodeResearch', 'EPOCHDevs/ClaudeCodeResearch', 'build-job-data', 0, 0, 48, '2026-02-26T07:57:06Z', '2026-03-07T03:39:59.798Z', '789081bae30b0fb4e679ad65bba5b4d4b80feca66bc6c63313bac0445cc9d60f', '{"id":"EPOCHDevs/ClaudeCodeResearch/build-job-data","name":"build-job-data","description":{"en":"The build-job-data skill generates the `generate_job_data` binary, utilizing file locking to prevent concurrent builds, benefiting developers working with C++ tools.","zh":"Build Job Data是一种使用文件锁定防止并发构建的技术，支持Release和Debug构建","ja":"Build Job Dataは、ファイルロックを使用してコンカレントビルドを防ぐ技術で、リリースビルドとデバッグビルドをサポートしています","ko":"Build Job Data는 파일 잠금을 사용하여 동시 빌드를 방지하는 기술로 릴리스 빌드 및 디버그 빌드를 지원합니다","es":"Build-job-data es una herramienta que permite la compilación de datos de trabajo con bloqueo de archivos para evitar compilaciones concurrentes.","fr":"Build-job-data est un outil qui permet la compilation de données de travail avec verrouillage de fichiers pour éviter les compilations concurrentes.","de":"Build-job-data ist ein Tool, das die Kompilierung von Arbeitsdaten mit Dateisperre ermöglicht, um gleichzeitige Kompilierungen zu vermeiden.","pt":"O build-job-data é uma ferramenta que constrói dados de trabalho com flock e AddressSanitizer. Veja como configurá-lo","ru":"Build-job-data - это инструмент, который создает данные работы с помощью ИИ Агентов, flock и AddressSanitizer. Узнайте, как его настроить","ar":"build-job-data هو أداة لبناء بيانات الوظيفة مع وكيل إلكتروني و Flock و AddressSanitizer. تعرف على كيفية إعداده"},"seo":{"title":{"en":"build-job-data: Setup Guide for AI Agents | AI Agent Skill","zh":"Build Job Data_SETUP GUIDE：使用文件锁定防止并发构建","ja":"Build Job Data セットアップガイド: ファイルロックを使用してコンカレントビルドを防ぐ","ko":"Build Job Data 설정 가이드: 파일 잠금을 사용하여 동시 빌드를 방지합니다","es":"Guía de configuración de build-job-data para desarrolladores","fr":"Guide d''installation de build-job-data pour les développeurs","de":"Einrichtungsleitfaden für build-job-data-Entwickler","pt":"Guia de Configuração do build-job-data: Construindo Dados...","ru":"Настройка build-job-data: Создание Данных Работы с ИИ Аге...","ar":"دليل إعداد build-job-data: بناء بيانات الوظيفة مع وكيل إل..."},"description":{"en":"Unlock efficient build management with build-job-data. Learn how to prevent concurrent builds and utilize file locking with flock.","zh":"了解Build Job Data的技术细节，包括文件锁定和AddressSanitizer，实现高效的构建过程","ja":"Build Job Dataの技術的な詳細を学び、ファイルロックとAddressSanitizerを使用して効率的なビルドプロセスを実現する","ko":"Build Job Data의 기술적인 세부 사항을了解하고 파일 잠금 및 AddressSanitizer를 사용하여 효율적인 빌드 프로세스를 구현합니다","es":"Aprende a configurar build-job-data con bloqueo de archivos para evitar compilaciones concurrentes y mejora la eficiencia del desarrollo","fr":"Découvrez comment configurer build-job-data avec verrouillage de fichiers pour éviter les compilations concurrentes et améliorer l''efficacité du développement","de":"Erfahren Sie, wie Sie build-job-data mit Dateisperre konfigurieren, um gleichzeitige Kompilierungen zu vermeiden und die Entwicklungseffizienz zu verbessern","pt":"Aprenda a configurar o build-job-data para construir dados de trabalho de forma eficiente com flock e AddressSanitizer","ru":"Узнайте, как настроить build-job-data для создания данных работы с помощью ИИ Агентов, flock и AddressSanitizer","ar":"تعرف على كيفية إعداد build-job-data لبناء بيانات الوظيفة بفعالية مع وكيل إلكتروني و Flock و AddressSanitizer"},"definition":{"en":"build-job-data is a skill that builds the `generate_job_data` binary with file locking, ensuring exclusive build execution.","zh":"Build Job Data是一种构建工具，使用文件锁定防止并发构建，确保构建过程的安全性","ja":"Build Job Dataは、ファイルロックを使用してコンカレントビルドを防ぐビルドツールで、ビルドプロセスのセキュリティを確保します","ko":"Build Job Data는 파일 잠금을 사용하여 동시 빌드를 방지하는 빌드 도구로 빌드 프로세스의 보안을 보장합니다","es":"Build-job-data es una herramienta de desarrollo que utiliza flock para garantizar que solo una compilación se ejecute a la vez","fr":"Build-job-data est un outil de développement qui utilise flock pour garantir qu''une seule compilation s''exécute à la fois","de":"Build-job-data ist ein Entwicklungstool, das flock verwendet, um sicherzustellen, dass nur eine Kompilierung gleichzeitig ausgeführt wird","pt":"O build-job-data é uma ferramenta de linha de comando que constrói dados de trabalho com flock","ru":"Build-job-data - это консольная утилита, которая создает данные работы с помощью ИИ Агентов и flock","ar":"build-job-data هو أداة سطر أوامر لبناء بيانات الوظيفة مع وكيل إلكتروني و Flock"},"features":{"en":["Utilizes `flock` for file locking to prevent concurrent builds","Supports release builds using `/home/adesola/EpochDev/EpochBackend/build`","Supports debug builds with AddressSanitizer via `--asan` flag","Executes builds using `/home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/build_generate_job_data.sh` script","Prevents simultaneous build runs, ensuring data integrity","Leverages bash scripting for build automation"],"zh":["使用文件锁定防止并发构建","支持Release和Debug构建","集成AddressSanitizer进行内存错误检测","使用flock确保构建过程的排他性","支持命令行参数自定义构建过程"],"ja":["ファイルロックを使用してコンカレントビルドを防ぐ","リリースビルドとデバッグビルドをサポート","AddressSanitizerを使用してメモリエラーを検出","flockを使用してビルドプロセスの排他性を確保","コマンドラインパラメータを使用してビルドプロセスをカスタマイズ"],"ko":["파일 잠금을 사용하여 동시 빌드를 방지합니다","릴리스 빌드 및 디버그 빌드를 지원합니다","AddressSanitizer를 사용하여 메모리 오류를 감지합니다","flock를 사용하여 빌드 프로세스의 독점성을 보장합니다","명령줄 매개변수를 사용하여 빌드 프로세스를 사용자 지정합니다"],"es":["Utiliza flock para evitar compilaciones concurrentes","Permite compilaciones de lanzamiento y depuración con AddressSanitizer","Utiliza /home/adesola/EpochDev/EpochBackend/build para compilaciones de lanzamiento","Utiliza /home/adesola/EpochDev/EpochBackend/build para compilaciones de depuración con ASAN","Soporte para compilaciones de lanzamiento y depuración"],"fr":["Utilise flock pour éviter les compilations concurrentes","Permet les compilations de version et de débogage avec AddressSanitizer","Utilise /home/adesola/EpochDev/EpochBackend/build pour les compilations de version","Utilise /home/adesola/EpochDev/EpochBackend/build pour les compilations de débogage avec ASAN","Prise en charge des compilations de version et de débogage"],"de":["Verwendet flock, um gleichzeitige Kompilierungen zu vermeiden","Ermöglicht Release- und Debug-Kompilierungen mit AddressSanitizer","Verwendet /home/adesola/EpochDev/EpochBackend/build für Release-Kompilierungen","Verwendet /home/adesola/EpochDev/EpochBackend/build für Debug-Kompilierungen mit ASAN","Unterstützt Release- und Debug-Kompilierungen"],"pt":["Constrói dados de trabalho com flock","Suporta AddressSanitizer para depuração","Permite builds de lançamento e depuração","Usa /home/adesola/EpochDev/EpochBackend/build para builds de lançamento","Usa /home/adesola/EpochDev/EpochBackend/build para builds de depuração com AddressSanitizer"],"ru":["Создает данные работы с помощью ИИ Агентов и flock","Поддерживает AddressSanitizer для отладки","Позволяет выполнять сборки для выпуска и отладки","Использует /home/adesola/EpochDev/EpochBackend/build для сборок выпуска","Использует /home/adesola/EpochDev/EpochBackend/build для сборок отладки с AddressSanitizer"],"ar":["يبني بيانات الوظيفة مع وكيل إلكتروني و Flock","يدعم AddressSanitizer لتصحيح الأخطاء","يسمح بإجراء عمليات بناء للنشر والتصحيح","يستخدم /home/adesola/EpochDev/EpochBackend/build لعمليات بناء النشر","يستخدم /home/adesola/EpochDev/EpochBackend/build لعمليات بناء التصحيح مع AddressSanitizer"]},"keywords":{"en":["how to use build-job-data","build-job-data setup guide","what is build-job-data","build-job-data alternative","build-job-data vs concurrent build tools","build-job-data install","build-job-data flock usage","build-job-data AddressSanitizer"],"zh":["Build Job Data","文件锁定","AddressSanitizer","构建工具","并发构建","Release构建","Debug构建","AIエージェント"],"ja":["Build Job Data","ファイルロック","AddressSanitizer","ビルドツール","コンカレントビルド","リリースビルド","デバッグビルド","AIエージェント"],"ko":["Build Job Data","파일 잠금","AddressSanitizer","빌드 도구","동시 빌드","릴리스 빌드","디버그 빌드","AI 에이전트"],"es":["build-job-data","compilación de datos de trabajo","bloqueo de archivos","flock","AddressSanitizer","compilación de lanzamiento","compilación de depuración","desarrollo de software","herramientas de desarrollo"],"fr":["build-job-data","compilation de données de travail","verrouillage de fichiers","flock","AddressSanitizer","compilation de version","compilation de débogage","développement de logiciels","outils de développement"],"de":["build-job-data","Kompilierung von Arbeitsdaten","Dateisperre","flock","AddressSanitizer","Release-Kompilierung","Debug-Kompilierung","Software-Entwicklung","Entwicklungstools"],"pt":["build-job-data","flock","AddressSanitizer","construir dados de trabalho","depuração de código","linha de comando","ferramentas de desenvolvimento","build de lançamento","build de depuração"],"ru":["build-job-data","ИИ Агенты","flock","AddressSanitizer","создание данных работы","отладка кода","консольная утилита","инструменты разработки","сборка выпуска","сборка отладки"],"ar":["build-job-data","وكيل إلكتروني","Flock","AddressSanitizer","بناء بيانات الوظيفة","تصحيح الأخطاء","سطر أوامر","أدوات تطوير","بناء النشر","بناء التصحيح"]}},"owner":"EPOCHDevs","repo":"ClaudeCodeResearch","repoPath":"EPOCHDevs/ClaudeCodeResearch","stars":0,"forks":0,"updatedAt":"2026-02-26T07:57:06Z","topics":[],"category":"community","skillMd":{"name":"build-job-data","description":"Build generate_job_data binary (release or ASAN debug mode)","bodyPreview":"# Build Job Data\n\nBuild the `generate_job_data` binary with file locking to prevent concurrent builds.\n\n## Usage\n\n```bash\n# Release build (default)\n/build-job-data\n\n# Debug build with AddressSanitizer\n/build-job-data --asan\n```\n\n## Run\n\n```bash\n/home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/build_generate_job_data.sh $ARGUMENTS\n```\n\n## Notes\n\n- Uses `flock` to ensure only one build runs at a time\n- Release builds use `/home/adesola/EpochDev/EpochBackend/build`\n- ASAN builds use `/home/adeso","body":"# Build Job Data\n\nBuild the `generate_job_data` binary with file locking to prevent concurrent builds.\n\n## Usage\n\n```bash\n# Release build (default)\n/build-job-data\n\n# Debug build with AddressSanitizer\n/build-job-data --asan\n```\n\n## Run\n\n```bash\n/home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/build_generate_job_data.sh $ARGUMENTS\n```\n\n## Notes\n\n- Uses `flock` to ensure only one build runs at a time\n- Release builds use `/home/adesola/EpochDev/EpochBackend/build`\n- ASAN builds use `/home/adesola/EpochDev/EpochBackend/build-asan`\n"},"lastSynced":"2026-03-07T03:39:59.798Z","agentAnalysis":{"suitability":{"en":"Perfect for C++ Development Agents requiring concurrent build prevention and file locking capabilities.","zh":"非常适合需要并发构建防止和文件锁定功能的C++开发代理。","ja":"C++開発エージェントがコンカレントビルドの防止とファイルロック機能を必要とする場合に最適です。","ko":".concurrent 빌드 방지 및 파일 잠금 기능이 필요한 C++ 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de C++ que requieren la prevención de compilaciones concurrentes y capacidades de bloqueo de archivos.","fr":"Parfait pour les agents de développement C++ nécessitant une prévention de construction concurrente et des capacités de verrouillage de fichiers.","de":"Perfekt für C++-Entwicklungsagenten, die eine Verhinderung von gleichzeitigen Builds und Dateiblockierungsfunktionen erfordern.","pt":"Perfeito para Agentes de Desenvolvimento C++ que exigem prevenção de compilação concorrente e capacidades de bloqueio de arquivos.","ru":"Идеально подходит для агентов разработки C++, требующих предотвращения параллельной сборки и возможностей блокировки файлов.","ar":"مثالي لعميل تطوير C++ الذي يتطلب منع البناء المتزامن وقدرات قفل الملفات."},"recommendation":{"en":"Empowers agents to generate the `generate_job_data` binary with file locking using `flock`, preventing concurrent builds and ensuring data integrity, while also supporting debug builds with AddressSanitizer.","zh":"赋予代理生成带有文件锁定功能的`generate_job_data`二进制文件，使用`flock`防止并发构建，确保数据完整性，同时也支持使用AddressSanitizer进行调试构建。","ja":"`generate_job_data`バイナリをファイルロック(`flock`)で生成し、コンカレントビルドを防止し、データの完全性を確保し、AddressSanitizerを使用したデバッグビルドもサポートします。","ko":"`generate_job_data` 바이너리를 파일 잠금(`flock`)으로 생성하여.concurrent 빌드를 방지하고 데이터 무결성을 보장하며 AddressSanitizer를 사용한 디버깅 빌드도 지원합니다.","es":"Habilita a los agentes a generar el binario `generate_job_data` con bloqueo de archivos utilizando `flock`, lo que evita las compilaciones concurrentes y garantiza la integridad de los datos, y también admite compilaciones de depuración con AddressSanitizer.","fr":"Permet aux agents de générer le binaire `generate_job_data` avec un verrouillage de fichiers à l''aide de `flock`, empêchant ainsi les constructions concurrentes et garantissant l''intégrité des données, tout en prenant en charge les constructions de débogage avec AddressSanitizer.","de":"Ermöglicht es den Agenten, das Binärfile `generate_job_data` mit Dateiblockierung unter Verwendung von `flock` zu generieren, was gleichzeitige Builds verhindert und die Datenintegrität sicherstellt, und unterstützt auch Debug-Builds mit AddressSanitizer.","pt":"Habilita os agentes a gerar o binário `generate_job_data` com bloqueio de arquivos usando `flock`, impedindo compilações concorrentes e garantindo a integridade dos dados, além de suportar compilações de depuração com AddressSanitizer.","ru":"Наделяет агентов возможностью генерировать бинарный файл `generate_job_data` с блокировкой файлов, используя `flock`, предотвращая параллельную сборку и обеспечивая целостность данных, а также поддерживая отладочные сборки с AddressSanitizer.","ar":"تمكين العميل من توليد ثنائي `generate_job_data` مع قفل الملفات باستخدام `flock` ، ومنع البناء المتزامن وضمان سلامة البيانات ، بالإضافة إلى دعم بناء التنميق باستخدام AddressSanitizer."},"useCases":{"en":["Building release versions of the `generate_job_data` binary","Debugging C++ applications with AddressSanitizer","Preventing concurrent builds using file locking"],"zh":["构建`generate_job_data`二进制文件的发布版本","使用AddressSanitizer调试C++应用程序","使用文件锁定防止并发构建"],"ja":["`generate_job_data`バイナリのリリースバージョンのビルド","AddressSanitizerを使用したC++アプリケーションのデバッグ","ファイルロックを使用したコンカレントビルドの防止"],"ko":["`generate_job_data` 바이너리의 릴리즈 버전 빌드","AddressSanitizer를 사용한 C++ 애플리케이션 디버깅","파일 잠금을 사용한.concurrent 빌드 방지"],"es":["Construcción de versiones de lanzamiento del binario `generate_job_data`","Depuración de aplicaciones C++ con AddressSanitizer","Prevención de compilaciones concurrentes mediante bloqueo de archivos"],"fr":["Construction de versions de publication du binaire `generate_job_data`","Débogage d''applications C++ avec AddressSanitizer","Prévention de constructions concurrentes à l''aide d''un verrouillage de fichiers"],"de":["Erstellung von Release-Versionen des Binärfiles `generate_job_data`","Fehlersuche in C++-Anwendungen mit AddressSanitizer","Verhinderung von gleichzeitigen Builds durch Dateiblockierung"],"pt":["Construção de versões de lançamento do binário `generate_job_data`","Depuração de aplicações C++ com AddressSanitizer","Prevenção de compilações concorrentes usando bloqueio de arquivos"],"ru":["Сборка выпусков бинарного файла `generate_job_data`","Отладка приложений C++ с AddressSanitizer","Предотвращение параллельных сборок с помощью блокировки файлов"],"ar":["بناء إصدارات الإصدار من ثنائي `generate_job_data`","تصحيح الأخطاء في تطبيقات C++ مع AddressSanitizer","منع عمليات البناء المتزامنة باستخدام قفل الملفات"]},"limitations":{"en":["Requires C++ tools and compiler","Uses specific build directories (/home/adesola/EpochDev/EpochBackend/build and /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","Limited to C++ development environment"],"zh":["需要C++工具和编译器","使用特定的构建目录(/home/adesola/EpochDev/EpochBackend/build和/home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","仅限C++开发环境"],"ja":["C++ツールとコンパイラが必要","特定のビルDDirectory(/home/adesola/EpochDev/EpochBackend/buildと/home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)を使用","C++開発環境のみ"],"ko":["C++ 도구 및 컴파일러 필요","특정 빌드 디렉토리(/home/adesola/EpochDev/EpochBackend/build 및 /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/) 사용","C++ 개발 환경만"],"es":["Requiere herramientas y compilador de C++","Utiliza directorios de compilación específicos (/home/adesola/EpochDev/EpochBackend/build y /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","Limitado al entorno de desarrollo de C++"],"fr":["Nécessite des outils et un compilateur C++","Utilise des répertoires de construction spécifiques (/home/adesola/EpochDev/EpochBackend/build et /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","Limité à l''environnement de développement C++"],"de":["Benötigt C++-Tools und -Compiler","Verwendet spezifische Build-Verzeichnisse (/home/adesola/EpochDev/EpochBackend/build und /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","Begrenzt auf die C++-Entwicklungsumgebung"],"pt":["Exige ferramentas e compilador C++","Usa diretórios de compilação específicos (/home/adesola/EpochDev/EpochBackend/build e /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","Limitado ao ambiente de desenvolvimento C++"],"ru":["Требует инструментов и компилятора C++","Использует конкретные каталоги сборки (/home/adesola/EpochDev/EpochBackend/build и /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","Ограничен средой разработки C++"],"ar":["يتطلب أدوات ومترجم C++","يستخدم مجلدات بناء محددة (/home/adesola/EpochDev/EpochBackend/build و /home/adesola/EpochDev/ClaudeCodeResearch/cpp_tools/)","محدود بيئة تطوير C++"]},"version":4},"contentHash":"789081bae30b0fb4e679ad65bba5b4d4b80feca66bc6c63313bac0445cc9d60f","qualityScore":48}');
