INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LuoAndOrder/AgentScripts/slidev', 'slidev', 'LuoAndOrder', 'AgentScripts', 'community', 'slidev LuoAndOrder AgentScripts community The slidev skill helps developers create and edit presentation slides using a markdown-based framework. It supports generating presentations from content and working with Slidev-specific features. Slidev Skill 是一个使用 markdown 创建和编辑演示文稿的工具，支持生成和修改幻灯片 Slidev Skill は、markdown でプレゼンテーションを作成・編集するためのツールで、スライドの生成・変更をサポートします Slidev Skill은 markdown 기반의 프레젠테이션을 생성하고 편집하는 도구로, 슬라이드의 생성과 수정을 지원합니다 Slidev es un marco de trabajo de presentación basado en markdown que permite a los desarrolladores crear y editar diapositivas de presentación de manera eficiente. Slidev est un cadre de présentation basé sur markdown qui permet aux développeurs de créer et d''éditer des diapositives de présentation de manière efficace. Slidev ist ein markdown-basiertes Präsentationsframework, das es Entwicklern ermöglicht, Präsentationsfolien effizient zu erstellen und zu bearbeiten. O Slidev é um framework de apresentações baseado em Markdown que permite criar e editar slides de forma eficiente Slidev - это фреймворк для презентаций на основе Markdown, который позволяет создавать и редактировать слайды эффективно с помощью ИИ Агентов Slidev هو إطار عمل للعروض التقديمية بالماركداون الذي يسمح بإنشاء وتحرير الشرائح بفعالية how to use slidev what is slidev slidev setup guide slidev install markdown-based presentation framework slidev alternative slidev vs reveal.js Slidev markdown 演示文稿 AI 工具 幻灯片生成 演示文稿编辑 Slidev 设置指南 markdown 基本的演示文稿框架 Creates and edits presentation slides using markdown files (.slides.md or slides.md) Generates presentations from markdown content Supports Slidev-specific features for customizing slide decks Stores slides in the packages/slides/ directory Allows adding or modifying slide content slidev is a markdown-based presentation framework for developers, allowing them to create and edit slides using markdown files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yu-iskw/dbt-helpers/dbt-helpers-integration-testcontainers', 'community', 'yu-iskw', 'dbt-helpers', 'yu-iskw/dbt-helpers', 'dbt-helpers-integration-testcontainers', 0, 0, 48, '2026-02-21T06:51:20Z', '2026-03-07T03:47:51.588Z', '8ba71029526eb934211296a302a46a081538940c1526fca232f060ef2e3f7d48', '{"id":"yu-iskw/dbt-helpers/dbt-helpers-integration-testcontainers","name":"dbt-helpers-integration-testcontainers","description":{"en":"dbt-helpers-integration-testcontainers verifies adapter functionality against real infrastructure, ensuring correct handling of SQL dialect nuances and connection edge cases for developers.","zh":"dbt-helpers-integration-testcontainers是用于验证适配器对真实基础设施的正确性，确保SQL方言细微差别、连接边缘情况和文件系统行为的正确处理","ja":"dbt-helpers-integration-testcontainersは、リアルなインフラストラクチャに対するアダプタの正しさを検証するために使用され、SQLの方言のニュアンス、接続のエッジケース、ファイルシステムの動作を正しく処理します","ko":"dbt-helpers-integration-testcontainers는 실제 인프라스트럭처에 대한 어댑터의 정확성을 검증하기 위해 사용되며 SQL 방언의 세부 사항, 연결 에지 케이스, 파일 시스템 동작을 올바르게 처리합니다","es":"dbt-helpers-integration-testcontainers es una herramienta para pruebas de integración que utiliza contenedores para asegurar la compatibilidad con diferentes infraestructuras","fr":"dbt-helpers-integration-testcontainers est un outil de tests d''intégration qui utilise des conteneurs pour garantir la compatibilité avec différentes infrastructures","de":"dbt-helpers-integration-testcontainers ist ein Tool für Integrationstests, das Container verwendet, um die Kompatibilität mit verschiedenen Infrastrukturen sicherzustellen","pt":"O dbt-helpers-integration-testcontainers é uma ferramenta para testar adaptadores em infraestruturas reais, garantindo a correta manipulação de nuances de dialectos SQL e comportamentos de sistemas de arquivos.","ru":"dbt-helpers-integration-testcontainers - это инструмент для тестирования адаптеров в реальной инфраструктуре, обеспечивающий правильную обработку нюансов диалектов SQL и поведения файловых систем.","ar":"dbt-helpers-integration-testcontainers هو أداة لاختبار المحولات في البنية التحتية الحقيقية، مما يضمن التعامل الصحيح مع دقائق لغة SQL وسلوك أنظمة الملفات."},"seo":{"title":{"en":"dbt-helpers-integration-testcontainers: Setup Guide for A...","zh":"dbt-helpers-integration-testcontainers 集成测试容器设置指南","ja":"dbt-helpers-integration-testcontainers AIエージェントの統合テストコンテナ...","ko":"dbt-helpers-integration-testcontainers 통합 테스트 컨테이너 설정 가이드","es":"Guía de configuración de dbt-helpers-integration-testcont...","fr":"Guide de mise en place de dbt-helpers-integration-testcon...","de":"Einrichtungsleitfaden für dbt-helpers-integration-testcon...","pt":"Guia de Configuração dbt-helpers-integration-testcontainers","ru":"Настройка dbt-helpers-integration-testcontainers: ИИ Агенты","ar":"دليل إعداد dbt-helpers-integration-testcontainers لأدوات ..."},"description":{"en":"Discover how dbt-helpers-integration-testcontainers ensures adapters work correctly with real infrastructure, try it now and improve your testing efficiency","zh":"使用dbt-helpers-integration-testcontainers确保SQL方言细微差别、连接边缘情况和文件系统行为的正确处理，提高测试效率","ja":"dbt-helpers-integration-testcontainersを使用してSQLの方言のニュアンス、接続のエッジケース、ファイルシステムの動作を正しく処理し、テストの効率を高める","ko":"dbt-helpers-integration-testcontainers를 사용하여 SQL 방언의 세부 사항, 연결 에지 케이스, 파일 시스템 동작을 올바르게 처리하여 테스트 효율을 향상시키다","es":"Aprende a utilizar dbt-helpers-integration-testcontainers para pruebas de integración con contenedores, asegurando la compatibilidad con diferentes infraestr...","fr":"Découvrez comment utiliser dbt-helpers-integration-testcontainers pour les tests d''intégration avec des conteneurs, garantissant la compatibilité avec différ...","de":"Erfahren Sie, wie Sie dbt-helpers-integration-testcontainers für Integrationstests mit Containern verwenden, um die Kompatibilität mit verschiedenen Infrastr...","pt":"Aprenda a configurar dbt-helpers-integration-testcontainers para testar adaptadores em infraestruturas reais com isolamento e reprodução","ru":"Узнайте, как настроить dbt-helpers-integration-testcontainers для тестирования адаптеров в реальной инфраструктуре с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد dbt-helpers-integration-testcontainers لاختبار المحولات في البنية التحتية الحقيقية مع العزل والإعادة الإنتاج"},"definition":{"en":"dbt-helpers-integration-testcontainers is a testing framework that isolates test sessions using clean container instances and ensures reproducibility with specific image tags.","zh":"dbt-helpers-integration-testcontainers是一种用于集成测试的容器化解决方案","ja":"dbt-helpers-integration-testcontainersは、統合テストのためのコンテナ化されたソリューションです","ko":"dbt-helpers-integration-testcontainers는 통합 테스트를 위한 컨테이너화된 솔루션입니다","es":"dbt-helpers-integration-testcontainers es una herramienta de pruebas de integración que utiliza contenedores para verificar la compatibilidad con diferentes infraestructuras","fr":"dbt-helpers-integration-testcontainers est un outil de tests d''intégration qui utilise des conteneurs pour vérifier la compatibilité avec différentes infrastructures","de":"dbt-helpers-integration-testcontainers ist ein Tool für Integrationstests, das Container verwendet, um die Kompatibilité mit verschiedenen Infrastrukturen zu überprüfen","pt":"O dbt-helpers-integration-testcontainers é uma ferramenta de teste de integração para adaptadores de banco de dados.","ru":"dbt-helpers-integration-testcontainers - это инструмент для тестирования интеграции адаптеров баз данных.","ar":"dbt-helpers-integration-testcontainers هو أداة اختبار التكامل للمحولات قواعد البيانات."},"features":{"en":["Uses pytest fixtures with session scope for efficient testing","Ensures isolation with each test session having its own clean container instance","Utilizes specific image tags like duckdb:latest and postgres:15 for consistent results","Handles SQL dialect nuances and connection edge cases correctly","Supports reproducibility for reliable test outcomes","Works with real infrastructure for accurate adapter testing"],"zh":["使用pytest fixtures以提高测试效率","支持特定镜像标签（例如duckdb:latest，postgres:15）以确保一致的结果","每个测试会话都有自己的干净容器实例以实现隔离","支持Reproducibility以确保测试结果的一致性","使用ses以提高测试的效率"],"ja":["pytest fixturesを使用してテストの効率を高める","特定のイメージタグ（例：duckdb:latest、postgres:15）をサポートして一貫した結果を確保する","各テストセッションにcleanなコンテナインスタンスを提供して隔離を実現する","Reproducibilityをサポートしてテスト結果の一貫性を確保する","sesを使用してテストの効率を高める"],"ko":["pytest fixtures를 사용하여 테스트 효율을 높인다","특정 이미지 태그（예：duckdb:latest, postgres:15）를 지원하여 일관된 결과를 보장한다","각 테스트 세션에 깨끗한 컨테이너 인스턴스를 제공하여 격리를 구현한다","재현性을 지원하여 테스트 결과의 일관성을 보장한다","ses를 사용하여 테스트 효율을 높인다"],"es":["Utiliza contenedores para pruebas de integración","Soporta diferentes infraestructuras y dialectos SQL","Utiliza pytest fixtures para una mayor eficiencia","Permite la reproducción de resultados con etiquetas de imagen específicas","Garantiza el aislamiento de cada sesión de prueba","Soporta adapters para diferentes bases de datos"],"fr":["Utilise des conteneurs pour les tests d''intégration","Prend en charge différentes infrastructures et dialectes SQL","Utilise des fixtures pytest pour une plus grande efficacité","Permet la reproduction de résultats avec des étiquettes d''image spécifiques","Assure l''isolement de chaque session de test","Prend en charge des adaptateurs pour différentes bases de données"],"de":["Verwendet Container für Integrationstests","Unterstützt verschiedene Infrastrukturen und SQL-Dialekte","Verwendet pytest-Fixtures für eine höhere Effizienz","Ermöglicht die Reproduktion von Ergebnissen mit spezifischen Bildtags","Sichert die Isolation jeder Testsession","Unterstützt Adapter für verschiedene Datenbanken"],"pt":["Isolamento de cada sessão de teste em um contêiner próprio","Reprodução de resultados com imagens específicas (por exemplo, duckdb:latest, postgres:15)","Uso de pytest fixtures com sessões de teste eficientes","Suporte a dialectos SQL e comportamentos de sistemas de arquivos","Testes de integração para adaptadores de banco de dados","Compatibilidade com contêineres de teste"],"ru":["Изоляция каждой тестовой сессии в отдельном контейнере","Повторяемость результатов с помощью конкретных изображений (например, duckdb:latest, postgres:15)","Использование pytest fixtures с эффективными тестовыми сессиями","Поддержка диалектов SQL и поведения файловых систем","Тестирование интеграции адаптеров баз данных","Совместимость с контейнерами для тестирования"],"ar":["عزل كل جلسة اختبار في حاوية منفصلة","إعادة إنتاج النتائج باستخدام صور محددة (على سبيل المثال، duckdb:latest، postgres:15)","استخدام pytest fixtures مع جلسات اختبار فعالة","دعم لغات SQL وسلوك أنظمة الملفات","اختبار التكامل للمحولات قواعد البيانات","توافق مع حاويات الاختبار"]},"keywords":{"en":["how to use dbt-helpers-integration-testcontainers","dbt-helpers-integration-testcontainers setup guide","dbt-helpers-integration-testcontainers vs other testing frameworks","dbt-helpers-integration-testcontainers install","what is dbt-helpers-integration-testcontainers","dbt-helpers-integration-testcontainers alternative","dbt-helpers-integration-testcontainers for AI agents","dbt-helpers-integration-testcontainers testing efficiency","dbt-helpers-integration-testcontainers and pytest","dbt-helpers-integration-testcontainers for developers"],"zh":["dbt-helpers-integration-testcontainers","集成测试","容器化解决方案","pytest fixtures","SQL方言细微差别","连接边缘情况","文件系统行为"],"ja":["dbt-helpers-integration-testcontainers","AIエージェント","統合テスト","コンテナ化されたソリューション","pytest fixtures","SQLの方言のニュアンス","接続のエッジケース","ファイルシステムの動作"],"ko":["dbt-helpers-integration-testcontainers","AI Tools","통합 테스트","컨테이너화된 솔루션","pytest fixtures","SQL 방언의 세부 사항","연결 에지 케이스","파일 시스템 동작"],"es":["dbt-helpers-integration-testcontainers","pruebas de integración","contenedores","infraestructuras","dialectos SQL","pytest","eficiencia","reproducción de resultados","aislamiento de pruebas"],"fr":["dbt-helpers-integration-testcontainers","tests d''intégration","conteneurs","infrastructures","dialectes SQL","pytest","efficacité","reproduction de résultats","isolement des tests"],"de":["dbt-helpers-integration-testcontainers","Integrationstests","Container","Infrastrukturen","SQL-Dialekte","pytest","Effizienz","Reproduktion von Ergebnissen","Isolation von Testläufen"],"pt":["dbt-helpers-integration-testcontainers","testes de integração","adaptadores de banco de dados","infraestrutura real","isolamento de testes","reprodução de resultados","pytest fixtures","dialetos SQL","comportamentos de sistemas de arquivos"],"ru":["dbt-helpers-integration-testcontainers","тестирование интеграции","адаптеры баз данных","реальная инфраструктура","изоляция тестов","повторяемость результатов","pytest fixtures","диалекты SQL","поведение файловых систем"],"ar":["dbt-helpers-integration-testcontainers","اختبار التكامل","المحولات قواعد البيانات","البنية التحتية الحقيقية","عزل الاختبار","إعادة إنتاج النتائج","pytest fixtures","لغات SQL","سلوك أنظمة الملفات"]}},"owner":"yu-iskw","repo":"dbt-helpers","repoPath":"yu-iskw/dbt-helpers","stars":0,"forks":0,"updatedAt":"2026-02-21T06:51:20Z","topics":[],"category":"community","skillMd":{"name":"dbt-helpers-integration-testcontainers","description":"Set up and run integration tests using Testcontainers. Use when testing warehouse adapters against real database engines or verifying filesystem-dependent operations.","bodyPreview":"# dbt-helpers-integration-testcontainers\n\n## Purpose\n\nTo verify that our adapters work correctly against real infrastructure, ensuring that SQL dialect nuances, connection edge cases, and filesystem behaviors are correctly handled.\n\n## Core Principles\n\n1. **Isolation**: Each test session should have its own clean container instance.\n2. **Reproducibility**: Use specific image tags (e.g., `duckdb:latest`, `postgres:15`) to ensure consistent results.\n3. **Efficiency**: Use pytest fixtures with `ses","body":"# dbt-helpers-integration-testcontainers\n\n## Purpose\n\nTo verify that our adapters work correctly against real infrastructure, ensuring that SQL dialect nuances, connection edge cases, and filesystem behaviors are correctly handled.\n\n## Core Principles\n\n1. **Isolation**: Each test session should have its own clean container instance.\n2. **Reproducibility**: Use specific image tags (e.g., `duckdb:latest`, `postgres:15`) to ensure consistent results.\n3. **Efficiency**: Use pytest fixtures with `session` or `module` scope where appropriate to minimize container startup overhead.\n\n## Patterns\n\n### 1. Database Fixture\n\n```python\n@pytest.fixture(scope=\"session\")\ndef duckdb_container():\n    with DuckDBContainer(\"duckdb/duckdb:latest\") as duckdb:\n        yield duckdb\n\n@pytest.fixture\ndef catalog_client(duckdb_container):\n    return DuckDBCatalogClient(connection_url=duckdb_container.get_connection_url())\n```\n\n### 2. Cleanup\n\nAlways ensure containers are stopped and resources are cleaned up using context managers or `yield` fixtures.\n\n## Instructions\n\n### When writing integration tests\n\n1. Locate tests in `src/<package>/tests/integration/`.\n2. Use `testcontainers-python` for managing Docker instances.\n3. Verify the adapter''s behavior against the real engine (e.g., check that BQ partition info is correctly extracted).\n\n### When implementing a new warehouse adapter\n\n1. Create a corresponding integration test in the plugin package.\n2. Test both \"happy path\" and common failure modes (e.g., table not found, permission denied).\n\n## References\n\n- [ADR 0006: Nullable Infrastructure Testing Strategy](../../../docs/adr/0006-nullable-infrastructure-testing-strategy.md)\n- [Testcontainers for Python Documentation](https://testcontainers-python.readthedocs.io/)\n"},"lastSynced":"2026-03-07T03:47:51.588Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Engineering Agents requiring comprehensive testing of dbt adapters against real infrastructure","zh":"非常适合需要对 dbt 适配器进行全面测试的数据工程代理，特别是测试它们与真实基础设施的兼容性","ja":"データエンジニアリングエージェントが dbt アダプタを実際のインフラストラクチャに対して包括的にテストする必要がある場合に最適","ko":"데이터 엔지니어링 에이전트가 dbt 어댑터를 실제 인프라스트ラク처에 대해 종합적으로 테스트해야 하는 경우에 적합","es":"Perfecto para Agentes de Ingeniería de Datos que requieren pruebas exhaustivas de adaptadores dbt contra infraestructura real","fr":"Parfait pour les agents d''ingénierie de données nécessitant des tests complets d''adaptateurs dbt contre une infrastructure réelle","de":"Perfekt für Data-Engineering-Agents, die umfassende Tests von dbt-Adaptationen gegen reale Infrastruktur erfordern","pt":"Perfeito para Agentes de Engenharia de Dados que exigem testes abrangentes de adaptadores dbt contra infraestrutura real","ru":"Идеально подходит для агентов инженерии данных, требующих всестороннего тестирования адаптеров dbt против реальной инфраструктуры","ar":"مثالي لعمليات إngineering البيانات التي تتطلب اختبارات شاملة لملحقات dbt ضد البنية التحتية الفعلية"},"recommendation":{"en":"Empowers agents to verify adapter functionality using Testcontainers, ensuring correct handling of SQL dialect nuances and connection edge cases with libraries like pytest and specific image tags such as duckdb:latest and postgres:15","zh":"赋予代理验证适配器功能的能力，使用 Testcontainers 确保正确处理 SQL 方言细微差别和连接边缘情况，使用诸如 pytest 的库和特定的镜像标签，如 duckdb:latest 和 postgres:15","ja":"Testcontainers を使用して、アダプタの機能を検証するエージェントの能力を提供し、pytest などのライブラリと duckdb:latest や postgres:15 などの特定のイメージタグを使って、SQL ダイヤレクトのニュアンスや接続のエッジケースを正しく処理","ko":"테스트컨테이너를 사용하여 어댑터 기능을 검증할 수 있는 에이전트의 능력을 제공하며, pytest와 같은 라이브러리와 duckdb:latest 및 postgres:15와 같은 특정 이미지 태그를 사용하여 SQL 방언의 차이와 연결 에지 케이스를 올바르게 처리","es":"Habilita a los agentes para verificar la funcionalidad del adaptador utilizando Testcontainers, asegurando el manejo correcto de matices de dialectos SQL y casos de borde de conexión con bibliotecas como pytest y etiquetas de imagen específicas como duckdb:latest y postgres:15","fr":"Permet aux agents de vérifier la fonctionnalité de l''adaptateur en utilisant Testcontainers, en garantissant une prise en charge correcte des nuances des dialectes SQL et des cas de bordure de connexion avec des bibliothèques comme pytest et des balises d''image spécifiques comme duckdb:latest et postgres:15","de":"Ermächtigt die Agenten, die Funktionalität des Adapters mit Testcontainers zu überprüfen, wodurch eine korrekte Handhabung von SQL-Dialekt-Feinheiten und Verbindungskantenfällen mit Bibliotheken wie pytest und spezifischen Image-Tags wie duckdb:latest und postgres:15 sichergestellt wird","pt":"Habilita agentes a verificar a funcionalidade do adaptador usando Testcontainers, garantindo o tratamento correto das nuances do dialeto SQL e casos de bordo de conexão com bibliotecas como pytest e tags de imagem específicas como duckdb:latest e postgres:15","ru":"Наделяет агентов возможностью проверить функциональность адаптера с помощью Testcontainers, обеспечивая правильную обработку нюансов диалекта SQL и краевых случаев подключения с помощью библиотек như pytest и определенных тегов образов, таких как duckdb:latest и postgres:15","ar":"تمكين الوكلاء من التحقق من وظيفة المكون الإضافي باستخدام Testcontainers، ضمان التعامل الصحيح مع دقة لهجة SQL وحالات الحافة للاتصال مع مكتبات مثل pytest ووسوم الصورة المحددة مثل duckdb:latest وpostgres:15"},"useCases":{"en":["Verifying dbt adapter functionality against various database infrastructure","Testing SQL dialect nuances and connection edge cases","Ensuring reproducibility of test results using specific image tags"],"zh":["验证 dbt 适配器功能与各种数据库基础设施的兼容性","测试 SQL 方言细微差别和连接边缘情况","使用特定的镜像标签确保测试结果的可重复性"],"ja":["さまざまなデータベースインフラストラクチャに対する dbt アダプタの機能を検証","SQL ダイヤレクトのニュアンスや接続のエッジケースをテスト","特定のイメージタグを使用してテスト結果の再現性を確保"],"ko":["다양한 데이터베이스 인프라스트ラク처에 대한 dbt 어댑터 기능을 검증","SQL 방언의 차이와 연결 에지 케이스를 테스트","특정 이미지 태그를 사용하여 테스트 결과의 재현성을 보장"],"es":["Verificar la funcionalidad del adaptador dbt contra varias infraestructuras de base de datos","Probar matices de dialectos SQL y casos de borde de conexión","Asegurar la reproducibilidad de los resultados de las pruebas utilizando etiquetas de imagen específicas"],"fr":["Vérifier la fonctionnalité de l''adaptateur dbt contre diverses infrastructures de base de données","Tester les nuances des dialectes SQL et les cas de bordure de connexion","Assurer la reproductibilité des résultats des tests en utilisant des balises d''image spécifiques"],"de":["Überprüfen der Funktionalität des dbt-Adapters gegen verschiedene Datenbank-Infrastrukturen","Testen von SQL-Dialekt-Feinheiten und Verbindungskantenfällen","Sicherstellen der Reproduzierbarkeit der Testergebnisse unter Verwendung spezifischer Image-Tags"],"pt":["Verificar a funcionalidade do adaptador dbt contra várias infraestruturas de banco de dados","Testar nuances do dialeto SQL e casos de bordo de conexão","Garantir a reprodutibilidade dos resultados de teste usando tags de imagem específicas"],"ru":["Проверка функциональности адаптера dbt против различных баз данных","Тестирование нюансов диалекта SQL и краевых случаев подключения","Обеспечение воспроизводимости результатов тестирования с помощью определенных тегов образов"],"ar":["التحقق من وظيفة مكون dbt الإضافي ضد بنى تحتية قواعد البيانات المختلفة","اختبار دقة لهجة SQL وحالات الحافة للاتصال","ضمان إعادة إنتاج نتائج الاختبار باستخدام وسوم الصورة المحددة"]},"limitations":{"en":["Requires Docker and Testcontainers setup","Limited to testing dbt adapters","Needs specific image tags for consistent results"],"zh":["需要 Docker 和 Testcontainers 设置","仅限于测试 dbt 适配器","需要特定的镜像标签来获得一致的结果"],"ja":["Docker と Testcontainers の設定が必要","dbt アダプタのテストのみに限定","一貫した結果を得るために特定のイメージタグが必要"],"ko":["도커와 테스트컨테이너 설정이 필요","dbt 어댑터 테스트에만 한정","일관된 결과를 얻기 위해 특정 이미지 태그가 필요"],"es":["Requiere configuración de Docker y Testcontainers","Limitado a la prueba de adaptadores dbt","Necesita etiquetas de imagen específicas para resultados consistentes"],"fr":["Nécessite une configuration de Docker et Testcontainers","Limité aux tests d''adaptateurs dbt","Nécessite des balises d''image spécifiques pour des résultats cohérents"],"de":["Benötigt eine Docker- und Testcontaine