INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yu-iskw/dbt-helpers/dbt-helpers-integration-testcontainers', 'dbt-helpers-integration-testcontainers', 'yu-iskw', 'dbt-helpers', 'community', 'dbt-helpers-integration-testcontainers yu-iskw dbt-helpers community dbt-helpers-integration-testcontainers verifies adapter functionality against real infrastructure, ensuring correct handling of SQL dialect nuances and connection edge cases for developers. dbt-helpers-integration-testcontainers是用于验证适配器对真实基础设施的正确性，确保SQL方言细微差别、连接边缘情况和文件系统行为的正确处理 dbt-helpers-integration-testcontainersは、リアルなインフラストラクチャに対するアダプタの正しさを検証するために使用され、SQLの方言のニュアンス、接続のエッジケース、ファイルシステムの動作を正しく処理します dbt-helpers-integration-testcontainers는 실제 인프라스트럭처에 대한 어댑터의 정확성을 검증하기 위해 사용되며 SQL 방언의 세부 사항, 연결 에지 케이스, 파일 시스템 동작을 올바르게 처리합니다 dbt-helpers-integration-testcontainers es una herramienta para pruebas de integración que utiliza contenedores para asegurar la compatibilidad con diferentes infraestructuras dbt-helpers-integration-testcontainers est un outil de tests d''intégration qui utilise des conteneurs pour garantir la compatibilité avec différentes infrastructures dbt-helpers-integration-testcontainers ist ein Tool für Integrationstests, das Container verwendet, um die Kompatibilität mit verschiedenen Infrastrukturen sicherzustellen O dbt-helpers-integration-testcontainers é uma ferramenta para testar adaptadores em infraestruturas reais, garantindo a correta manipulação de nuances de dialectos SQL e comportamentos de sistemas de arquivos. dbt-helpers-integration-testcontainers - это инструмент для тестирования адаптеров в реальной инфраструктуре, обеспечивающий правильную обработку нюансов диалектов SQL и поведения файловых систем. dbt-helpers-integration-testcontainers هو أداة لاختبار المحولات في البنية التحتية الحقيقية، مما يضمن التعامل الصحيح مع دقائق لغة SQL وسلوك أنظمة الملفات. how to use dbt-helpers-integration-testcontainers dbt-helpers-integration-testcontainers setup guide dbt-helpers-integration-testcontainers vs other testing frameworks dbt-helpers-integration-testcontainers install what is dbt-helpers-integration-testcontainers dbt-helpers-integration-testcontainers alternative dbt-helpers-integration-testcontainers for AI agents dbt-helpers-integration-testcontainers testing efficiency dbt-helpers-integration-testcontainers and pytest dbt-helpers-integration-testcontainers for developers dbt-helpers-integration-testcontainers 集成测试 容器化解决方案 pytest fixtures SQL方言细微差别 连接边缘情况 文件系统行为 Uses pytest fixtures with session scope for efficient testing Ensures isolation with each test session having its own clean container instance Utilizes specific image tags like duckdb:latest and postgres:15 for consistent results Handles SQL dialect nuances and connection edge cases correctly Supports reproducibility for reliable test outcomes Works with real infrastructure for accurate adapter testing dbt-helpers-integration-testcontainers is a testing framework that isolates test sessions using clean container instances and ensures reproducibility with specific image tags.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jfish-fishj/philly-evict/table-output', 'community', 'jfish-fishj', 'philly-evict', 'jfish-fishj/philly-evict', 'table-output', 0, 0, 48, '2026-03-07T04:46:12Z', '2026-03-07T13:06:09.576Z', '691f95dad56fde211498a2a7c7e665fb299d5137eb96dbb4a99a67d319dc4332', '{"id":"jfish-fishj/philly-evict/table-output","name":"table-output","description":{"en":"The table-output skill generates model results and group summaries in machine-readable tables and publication-ready LaTeX format, benefiting data analysts and researchers.","zh":"table-output 技术用于生成机器可读表格和 LaTeX 输出，支持数据分析和研究","ja":"table-output は、AIエージェントを使用してテーブル出力を生成し、データ分析と研究をサポートします","ko":"table-output은 머신 리더블 테이블과 LaTeX 출력을 생성하여 데이터 분석과 연구를 지원합니다","es":"El table-output es una habilidad que permite producir resultados de modelos y resúmenes de grupos de manera eficiente con R y LaTeX","fr":"Le table-output est une compétence qui permet de produire des résultats de modèles et des résumés de groupes de manière efficace avec R et LaTeX","de":"Das table-output ist eine Fähigkeit, die die effiziente Erzeugung von Modellergebnissen und Gruppenzusammenfassungen mit R und LaTeX ermöglicht","pt":"A saída de tabela é uma habilidade que permite produzir resultados de modelo e resumos de grupo de forma eficiente. Ela inclui recursos como escrita de tabelas em disco e preferência por saída LaTeX em scripts R","ru":"Вывод таблицы - это навык, который позволяет производить результаты модели и сводки групп эффективно. Он включает функции, такие как запись таблиц на диск и предпочтение вывода LaTeX в скриптах R","ar":"إخراج الجدول هو مهارة يسمح بإنتاج نتائج نموذجية وملخصات مجموعة بفعالية. وهي تشمل ميزات مثل كتابة الجداول على القرص وتفضيل إخراج LaTeX في سكريبتات R"},"seo":{"title":{"en":"table-output: LaTeX Table Generation Setup Guide | AI Age...","zh":"table-output 技术指南：生成机器可读表格","ja":"table-output セットアップガイド：AIエージェントを使用したテーブル出力","ko":"table-output 설정 가이드: 머신 리더블 테이블 생성","es":"Guía de configuración de table-output para análisis de datos","fr":"Configurer le table-output pour l''analyse de données","de":"Einrichtungsleitfaden für table-output bei Datenanalyse","pt":"Guia de Configuração de Saída de Tabela para Ferramentas ...","ru":"Настройка вывода таблицы для ИИ Агентов","ar":"دليل إعداد إخراج الجدول لآلات الإيضاح الإصطناعي"},"description":{"en":"Unlock efficient data analysis with table-output. Learn how to produce machine-readable tables and publication-ready LaTeX output with fixest::etable and kni...","zh":"了解如何使用 table-output 技术生成机器可读表格和 LaTeX 输出，提高数据分析效率","ja":"AIエージェントを使用してテーブル出力を生成する方法を学び、データ分析を効率化しましょう","ko":"table-output을 사용하여 머신 리더블 테이블과 LaTeX 출력을 생성하고 데이터 분석을 효율화하는 방법을 알아보세요","es":"Aprende a configurar table-output para producir resultados de modelos y resúmenes de grupos de manera eficiente con R y LaTeX","fr":"Découvrez comment configurer le table-output pour produire des résultats de modèles et des résumés de groupes de manière efficace avec R et LaTeX","de":"Erfahren Sie, wie Sie table-output für die effiziente Erzeugung von Modellergebnissen und Gruppenzusammenfassungen mit R und LaTeX einrichten","pt":"Aprenda a configurar a saída de tabela para ferramentas de IA, incluindo dicas para produzir resultados de modelo e resumos de grupo","ru":"Узнайте, как настроить вывод таблицы для ИИ Агентов, включая советы для получения результатов модели и сводок групп","ar":"تعلم كيفية إعداد إخراج الجدول لآلات الإيضاح الإصطناعي، بما في ذلك نصائح لإنتاج نتائج نموذجية وملخصات مجموعة"},"definition":{"en":"table-output is a skill that produces model results and group summaries in machine-readable tables and publication-ready LaTeX format using tools like fixest::etable and knitr::kable.","zh":"table-output 是一种生成机器可读表格和 LaTeX 输出的技术","ja":"table-output は、テーブル出力を生成する AI エージェントの技術です","ko":"table-output은 머신 리더블 테이블과 LaTeX 출력을 생성하는 기술입니다","es":"El table-output es una herramienta de AI que produce resultados de modelos y resúmenes de grupos en formato de tabla","fr":"Le table-output est un outil d''IA qui produit des résultats de modèles et des résumés de groupes au format tableau","de":"Das table-output ist ein AI-Tool, das Modellergebnisse und Gruppenzusammenfassungen in Tabellenformat erzeugt","pt":"Saída de tabela é uma habilidade de IA que gera resultados de modelo e resumos de grupo em formato de tabela","ru":"Вывод таблицы - это навык ИИ, который генерирует результаты модели и сводки групп в формате таблицы","ar":"إخراج الجدول هو مهارة الإيضاح الإصطناعي التي تولد نتائج نموذجية وملخصات مجموعة في شكل جدول"},"features":{"en":["Writes machine-readable tables to disk in .csv format","Produces publication-ready tables in .tex format using LaTeX","Utilizes fixest::etable and knitr::kable for table generation","Supports config-driven output paths using p_out(cfg, ...)","Includes key meta information in output tables"],"zh":["生成机器可读表格（.csv）","生成 LaTeX 输出（.tex）","支持 R 脚本中的 fixest::etable、knitr::kable 和 gt","输出路径配置驱动（p_out(cfg, ...)）","包含关键元数据"],"ja":["テーブル出力（.csv）を生成","LaTeX 出力（.tex）を生成","R スクリプトでの fixest::etable、knitr::kable、gt をサポート","出力パスを構成駆動（p_out(cfg, ...)）","重要なメタデータを含む"],"ko":["머신 리더블 테이블(.csv) 생성","LaTeX 출력(.tex) 생성","R 스크립트에서 fixest::etable, knitr::kable, gt 지원","출력 경로 구성 주도(p_out(cfg, ...))","중요한 메타데이터 포함"],"es":["Producción de resultados de modelos con coeficientes y efectos marginales","Generación de resúmenes de grupos con medias, participaciones y tasas","Compatibilidad con R y LaTeX para una salida de publicación de alta calidad","Ruta de salida configurable con p_out(cfg, ...)","Inclusión de metadatos clave en la salida"],"fr":["Production de résultats de modèles avec coefficients et effets marginaux","Génération de résumés de groupes avec moyennes, parts et taux","Compatibilité avec R et LaTeX pour une sortie de publication de haute qualité","Chemin de sortie configurable avec p_out(cfg, ...)","Inclusion de métadonnées clés dans la sortie"],"de":["Erzeugung von Modellergebnissen mit Koeffizienten und marginalen Effekten","Generierung von Gruppenzusammenfassungen mit Mittelwerten, Anteilen und Raten","Kompatibilität mit R und LaTeX für eine Ausgabe von hoher Qualität","Ausgabepfad konfigurierbar mit p_out(cfg, ...)","Einclusion von Schlüsselmetadaten in der Ausgabe"],"pt":["Escrita de tabelas em disco em formato CSV","Geração de tabelas de publicação em formato TeX","Preferência por saída LaTeX em scripts R","Caminhos de saída configuráveis via p_out(cfg, ...)","Inclusão de metadados importantes"],"ru":["Запись таблиц на диск в формате CSV","Генерация таблиц публикаций в формате TeX","Предпочтение вывода LaTeX в скриптах R","Конфигурируемые пути вывода через p_out(cfg, ...)","Включение важных метаданных"],"ar":["كتابة الجداول على القرص في شكل CSV","إنتاج جداول النشر في شكل TeX","تفضيل إخراج LaTeX في سكريبتات R","مسارات إخراج قابلة للتكوين عبر p_out(cfg, ...)","إدراج بيانات وصفية مهمة"]},"keywords":{"en":["how to use table-output","table-output alternative","table-output setup guide","what is table-output","table-output vs pandas","table-output install","LaTeX table generation","machine-readable table output","fixest::etable tutorial"],"zh":["table-output","机器可读表格","LaTeX 输出","数据分析","R 脚本","fixest::etable","knitr::kable","gt"],"ja":["table-output","AIエージェント","テーブル出力","LaTeX 出力","データ分析","R スクリプト","fixest::etable","knitr::kable","gt"],"ko":["table-output","머신 리더블 테이블","LaTeX 출력","데이터 분석","R 스크립트","fixest::etable","knitr::kable","gt"],"es":["table-output","análisis de datos","R","LaTeX","resultados de modelos","resúmenes de grupos","AI","herramientas de AI","producción de tablas","configuración de table-output"],"fr":["table-output","analyse de données","R","LaTeX","résultats de modèles","résumés de groupes","IA","outils d''IA","production de tableaux","configuration du table-output"],"de":["table-output","Datenanalyse","R","LaTeX","Modellergebnisse","Gruppenzusammenfassungen","KI","KI-Tools","Erzeugung von Tabellen","Konfiguration von table-output"],"pt":["saída de tabela","ferramentas de IA","produção de resultados de modelo","resumos de grupo","R scripts","LaTeX","CSV","TeX"],"ru":["вывод таблицы","ИИ Агенты","получение результатов модели","сводки групп","скрипты R","LaTeX","CSV","TeX"],"ar":["إخراج الجدول","آلات الإيضاح الإصطناعي","إنتاج نتائج نموذجية","ملخصات مجموعة","سكريبتات R","LaTeX","CSV","TeX"]}},"owner":"jfish-fishj","repo":"philly-evict","repoPath":"jfish-fishj/philly-evict","stars":0,"forks":0,"updatedAt":"2026-03-07T04:46:12Z","topics":[],"category":"community","skillMd":{"name":"table-output","description":"Create and present analysis tables consistently. Use when writing R analysis outputs with coefficients or summary statistics; prefer LaTeX table artifacts on disk and present key numeric results as terminal tables in responses.","bodyPreview":"## When to use\n- Produce model results (coefficients, marginal effects, event-study/LP estimates).\n- Produce group summaries (means, shares, counts, rates).\n- Update an analysis script that currently writes only free-form text.\n\n## Rules\n- Write a machine-readable table to disk (`.csv`) and a publication table to disk (`.tex`).\n- Prefer LaTeX output in R scripts (`fixest::etable`, `knitr::kable`, or `gt`).\n- Keep output paths config-driven (`p_out(cfg, ...)`), never hardcoded.\n- Include key meta","body":"## When to use\n- Produce model results (coefficients, marginal effects, event-study/LP estimates).\n- Produce group summaries (means, shares, counts, rates).\n- Update an analysis script that currently writes only free-form text.\n\n## Rules\n- Write a machine-readable table to disk (`.csv`) and a publication table to disk (`.tex`).\n- Prefer LaTeX output in R scripts (`fixest::etable`, `knitr::kable`, or `gt`).\n- Keep output paths config-driven (`p_out(cfg, ...)`), never hardcoded.\n- Include key metadata columns when relevant: sample, spec, outcome, reference group, FE/cluster notes.\n- Keep column names stable and explicit (`estimate`, `std_error`, `p_value`, `n_obs`).\n\n## R patterns\n- Prefer `fixest::etable(..., tex = TRUE)` for regression tables.\n- Prefer a paired coefficients CSV extracted from `summary(model)$coeftable`.\n- Use `knitr::kable(..., format = \"latex\", booktabs = TRUE)` or `gt::as_latex()` for non-regression tables.\n\n```r\n# Regression table (LaTeX)\ntex_lines <- capture.output(fixest::etable(list(m1, m2), se.below = TRUE, digits = 3, tex = TRUE))\nwriteLines(tex_lines, con = p_out(cfg, \"tables\", \"model_main.tex\"))\n\n# Coefficient CSV\nct <- data.table::as.data.table(summary(m1)$coeftable, keep.rownames = \"term\")\ndata.table::setnames(ct, c(\"Estimate\", \"Std. Error\", \"Pr(>|t|)\"), c(\"estimate\", \"std_error\", \"p_value\"))\ndata.table::fwrite(ct, p_out(cfg, \"tables\", \"model_main_coefficients.csv\"))\n```\n\n## Terminal presentation\n- Present key results as a compact Markdown table in terminal responses.\n- Show at minimum: term/group, estimate, standard error, p-value, and sample/spec label.\n- State reference category directly above or below the table.\n- Round for readability (typically 3-4 decimals) while preserving sign and significance.\n"},"lastSynced":"2026-03-07T13:06:09.576Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing advanced table output capabilities in LaTeX and CSV formats.","zh":"适合需要高级表格输出功能的数据分析代理，支持LaTeX和CSV格式。","ja":"データ分析エージェントが高度な表形式の出力機能を必要とする場合に最適です。LaTeXおよびCSV形式をサポートしています。","ko":"데이터 분석 에이전트가 고급 테이블 출력 기능을 필요한 경우에 적합합니다. LaTeX 및 CSV 형식을 지원합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan capacidades de salida de tabla avanzadas en LaTeX y formatos CSV.","fr":"Parfait pour les Agents d''Analyse de Données ayant besoin de capacités de sortie de tableau avancées en LaTeX et formats CSV.","de":"Perfekt für Data-Analytics-Agents, die erweiterte Tabellenausgabefunktionen in LaTeX und CSV-Formaten benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de capacidades de saída de tabela avançadas em LaTeX e formatos CSV.","ru":"Идеально для агентов анализа данных, которым необходимы расширенные возможности вывода таблиц в форматах LaTeX и CSV.","ar":"مثالي للوكلاء الذين يحتاجون إلى قدرات إخراج جدول متقدمة في تنسيقات LaTeX و CSV."},"recommendation":{"en":"Empowers agents to generate machine-readable tables in .csv format and publication-ready tables in .tex format using libraries like fixest, knitr, or gt, while keeping output paths config-driven with p_out(cfg, ...).","zh":"赋予代理生成机器可读的表格以.csv格式，并使用类似fixest、knitr或gt的库生成出版就绪的表格以.tex格式，同时使用p_out(cfg, ...)保持输出路径的配置驱动。","ja":"エージェントが、.csv形式のマシンリーダブルな表を生成し、fixest、knitr、またはgtなどのライブラリを使用して.tex形式の出版用テーブルを生成できるようにし、p_out(cfg, ...)を使用して出力パスを設定駆動に保つ。","ko":"에이전트가 .csv 형식의 머신리더블한 표를 생성하고 fixest, knitr 또는 gt 등의 라이브러리를 사용하여 .tex 형식의 출판 준비가 된 표를 생성할 수 있도록 하며, p_out(cfg, ...)를 사용하여 출력 경로를 구성 驱动에 유지합니다.","es":"Habilita a los agentes a generar tablas legibles por máquina en formato .csv y tablas listas para publicación en formato .tex utilizando bibliotecas como fixest, knitr o gt, manteniendo las rutas de salida configuradas con p_out(cfg, ...).","fr":"Permet aux agents de générer des tableaux lisibles par machine au format .csv et des tableaux prêts pour publication au format .tex en utilisant des bibliothèques comme fixest, knitr ou gt, tout en gardant les chemins de sortie config-drivés avec p_out(cfg, ...).","de":"Ermächtigt Agenten, maschinenlesbare Tabellen im .csv-Format und publikationsbereite Tabellen im .tex-Format zu generieren, indem Bibliotheken wie fixest, knitr oder gt verwendet werden, während die Ausgabepfade mit p_out(cfg, ...) konfiguriert werden.","pt":"Habilita os agentes a gerar tabelas legíveis por máquina no formato .csv e tabelas prontas para publicação no formato .tex, utilizando bibliotecas como fixest, knitr ou gt, mantendo os caminhos de saída configurados com p_out(cfg, ...).","ru":"Позволяет агентам генерировать машиночитаемые таблицы в формате .csv и публикационные таблицы в формате .tex, используя такие библиотеки, как fixest, knitr или gt, сохраняя конфигурируемые пути вывода с помощью p_out(cfg, ...).","ar":"تمكن الوكلاء من توليد جداول يمكن للآلة قراءتها في صيغة .csv وجداول جاهزة للنشر في صيغة .tex، باستخدام مكتبات مثل fixest و knitr أو gt، مع الحفاظ على مسارات الإخراج قيد التشغيل مع p_out(cfg, ...)."},"useCases":{"en":["Generating model results in LaTeX tables","Producing group summaries in CSV format","Updating analysis scripts to include table output","Creating publication-ready tables with key meta information"],"zh":["生成模型结果的LaTeX表格","生成CSV格式的组摘要","更新分析脚本以包含表输出","创建包含关键元信息的出版就绪表格"],"ja":["モデル結果のLaTeX表形式で出力する","CSV形式のグループサマリーを生成する","分析スクリプトをテーブル出力機能を含むように更新する","重要なメタ情報を含む出版用テーブルを作成する"],"ko":["모델 결과를 LaTeX 표 형식으로 출력하기","CSV 형식의 그룹 요약을 생성하기","분석 스크립트를 테이블 출력 기능을 포함하도록 업데이트하기","중요한 메타 정보를 포함한 출판 준비가 된 표를 생성하기"],"es":["Generar resultados de modelo en tablas LaTeX","Producir resúmenes de grupo en formato CSV","Actualizar scripts de análisis para incluir la salida de tablas","Crear tablas listas para publicación con metainformación clave"],"fr":["Générer des résultats de modèle dans des tableaux LaTeX","Produire des résumés de groupe au format CSV","Mettre à jour les scripts d''analyse pour inclure la sortie de tableaux","Créer des tableaux prêts pour publication avec des métadonnées clés"],"de":["Modellergebnisse in LaTeX-Tabellen generieren","Gruppenzusammenfassungen im CSV-Format produzieren","Analyse-Skripte aktualisieren, um Tabellenausgaben zu enthalten","Publikationsbereite Tabellen mit wichtigen Metainformationen erstellen"],"pt":["Gerar resultados de modelo em tabelas LaTeX","Produzir resumos de grupo em formato CSV","Atualizar scripts de análise para incluir saída de tabela","Criar tabelas prontas para publicação com metainformações-chave"],"ru":["Генерировать результаты модели в таблицах LaTeX","Производить сводки групп в формате CSV","Обновлять скрипты анализа для включения вывода таблиц","Создавать публикационные таблицы с ключевой метаинформацией"],"ar":["генерировать نتائج نموذج في جداول LaTeX","إنتاج ملخصات المجموعة في صيغة CSV","تحديث برامج تحليل لإضافة إخراج جدول","إنشاء جداول جاهزة للنشر مع معلومات واصفة رئيسية"]},"limitations":{"en":["Requires R scripting environment","Output paths must be config-driven","LaTeX output preferred in R scripts"],"zh":["需要R脚本环境","输出路径必须是配置驱动的","LaTeX输出在R脚本中优先"],"ja":["Rスクリプト環境が必要","出力パスは設定駆動でなければならない","LaTeX出力はRスクリプトで優先される"],"ko":["R 스크립트 환경이 필요함","출력 경로는 구성 驱动이어야 함","LaTeX 출력은 R 스크립트에서 우선적"],"es":["Requiere entorno de scripting R","Las rutas de salida deben estar configuradas","La salida LaTeX es preferida en los scripts R"],"fr":["Nécessite un environnement de scripting R","Les chemins de sortie doivent être config-drivés","La sortie LaTeX est préférée dans les scripts R"],"de":["Benötigt R-Skriptumgebung","Ausgabepfade müssen konfiguriert werden","LaTeX-Ausgabe wird in R-Skripten bevorzugt"],"pt":["Requer ambiente de script R","Os caminhos de saída devem ser configurados","Saída LaTeX preferida em scripts R"],"ru":["Требуется среда сценариев R","Пути вывода должны быть конфигурируемыми","Вывод LaTeX предпочтителен в скриптах R"],"ar":["يتطلب بيئة برمجة R","يجب أن تكون مسارات الإخراج قيد التشغيل","الإخراج LaTeX مفضّل في برامج R"]},"version":4},"contentHash":"691f95dad56fde211498a2a7c7e665fb299d5137eb96dbb4a99a67d319dc4332","qualityScore":48}');
