INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jfish-fishj/philly-evict/table-output', 'table-output', 'jfish-fishj', 'philly-evict', 'community', 'table-output jfish-fishj philly-evict community The table-output skill generates model results and group summaries in machine-readable tables and publication-ready LaTeX format, benefiting data analysts and researchers. table-output 技术用于生成机器可读表格和 LaTeX 输出，支持数据分析和研究 table-output は、AIエージェントを使用してテーブル出力を生成し、データ分析と研究をサポートします table-output은 머신 리더블 테이블과 LaTeX 출력을 생성하여 데이터 분석과 연구를 지원합니다 El table-output es una habilidad que permite producir resultados de modelos y resúmenes de grupos de manera eficiente con R y LaTeX Le table-output est une compétence qui permet de produire des résultats de modèles et des résumés de groupes de manière efficace avec R et LaTeX Das table-output ist eine Fähigkeit, die die effiziente Erzeugung von Modellergebnissen und Gruppenzusammenfassungen mit R und LaTeX ermöglicht A saída de tabela é uma habilidade que permite produzir resultados de modelo e resumos de grupo de forma eficiente. Ela inclui recursos como escrita de tabelas em disco e preferência por saída LaTeX em scripts R Вывод таблицы - это навык, который позволяет производить результаты модели и сводки групп эффективно. Он включает функции, такие как запись таблиц на диск и предпочтение вывода LaTeX в скриптах R إخراج الجدول هو مهارة يسمح بإنتاج نتائج نموذجية وملخصات مجموعة بفعالية. وهي تشمل ميزات مثل كتابة الجداول على القرص وتفضيل إخراج LaTeX في سكريبتات R how to use table-output table-output alternative table-output setup guide what is table-output table-output vs pandas table-output install LaTeX table generation machine-readable table output fixest::etable tutorial table-output 机器可读表格 LaTeX 输出 数据分析 R 脚本 fixest::etable knitr::kable gt Writes machine-readable tables to disk in .csv format Produces publication-ready tables in .tex format using LaTeX Utilizes fixest::etable and knitr::kable for table generation Supports config-driven output paths using p_out(cfg, ...) Includes key meta information in output tables table-output is a skill that produces model results and group summaries in machine-readable tables and publication-ready LaTeX format using tools like fixest::etable and knitr::kable.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('briankeane/node-react-scaffold/create-endpoint', 'community', 'briankeane', 'node-react-scaffold', 'briankeane/node-react-scaffold', 'create-endpoint', 0, 0, 48, '2026-03-01T21:28:42Z', '2026-03-07T04:06:07.688Z', 'e979456a7effcd60329df8c952c08ef4355d569fe687c46c8eb8a40dd889d066', '{"id":"briankeane/node-react-scaffold/create-endpoint","name":"create-endpoint","description":{"en":"The create-endpoint skill facilitates endpoint development for AI agents by providing a structured workflow. It benefits developers by guiding them through writing tests, implementing endpoints, and documenting APIs.","zh":"创建端点的技术指南，涵盖写入集成测试、实现端点和更新文档等步骤","ja":"エンドポイントを作成するための技術ガイド。テストの書き込み、エンドポイントの実装、ドキュメントの更新など","ko":"엔드포인트를 생성하는 기술 가이드. 통합 테스트 작성, 엔드포인트 구현, 문서 업데이트 등","es":"Crear endpoint es un proceso que implica escribir pruebas de integración, implementar el endpoint y documentar el proceso. Nuestra guía te ayudará a hacerlo de manera efectiva.","fr":"La création d''un point de terminaison est un processus qui implique l''écriture de tests d''intégration, la mise en œuvre du point de terminaison et la documentation du processus. Notre guide vous aidera à le faire de manière efficace.","de":"Das Erstellen eines Endpunkts ist ein Prozess, der das Schreiben von Integrationstests, die Implementierung des Endpunkts und die Dokumentation des Prozesses beinhaltet. Unser Leitfaden hilft Ihnen, dies effektiv zu tun.","pt":"O create-endpoint é uma habilidade que permite aos desenvolvedores criar endpoints com testes de integração e documentação","ru":"Создание эндпоинта - это навык, который позволяет разработчикам создавать эндпоинты с помощью тестов интеграции и документации для ИИ Агентов","ar":"إنشاء نهاية هي مهارة تسمح للمطورين بإنشاء نقاط النهاية مع الاختبارات المتكاملة والتوثيق لأدوات الإي الأجنت"},"seo":{"title":{"en":"create-endpoint: Endpoint Development Setup Guide | AI Ag...","zh":"创建端点 Setup Guide - AIエージェント开发最佳实践","ja":"エンドポイントの作成 Setup Guide - AIエージェント開発ベストプラクティス","ko":"엔드포인트 생성 Setup Guide - AI 에이전트 개발 모범 사례","es":"Crear Endpoint: Guía de Configuración para Desarrolladores","fr":"Créer un Point de Terminaison: Meilleures Pratiques pour ...","de":"Endpoint Erstellen: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do Create-Endpoint para Desenvolvedores","ru":"Настройка Создания Эндпоинта: Лучшие Практики для Разрабо...","ar":"دليل إعداد نهاية Endpoint للبرمجة مع أدوات الإي الأجنت"},"description":{"en":"Streamline endpoint development with create-endpoint. Learn how to write integration tests, implement controllers, and generate OpenAPI specs. Get started now!","zh":"学习如何使用AIエージェント创建端点，包括写入集成测试、实现端点和更新文档等步骤","ja":"AIエージェントを使用してエンドポイントを作成する方法を学びます。テストの書き込み、エンドポイントの実装、ドキュメントの更新など","ko":"AI 에이전트를 사용하여 엔드포인트를 생성하는 방법을 알아보세요. 통합 테스트 작성, 엔드포인트 구현, 문서 업데이트 등","es":"Aprende a crear endpoints de manera efectiva con nuestra guía paso a paso para desarrolladores, incluyendo pruebas de integración y documentación","fr":"Découvrez comment créer des points de terminaison de manière efficace avec notre guide étape par étape pour les développeurs, y compris les tests d''intégrati...","de":"Erfahren Sie, wie Sie Endpunkte effektiv erstellen, mit unserem Schritt-für-Schritt-Leitfaden für Entwickler, einschließlich Integrationstests und Dokumentation","pt":"Aprenda a criar endpoints com testes de integração, implementação e documentação usando make e OpenAPI","ru":"Узнайте, как создавать эндпоинты с помощью тестов интеграции, реализации и документации, используя make и OpenAPI для ИИ Агентов","ar":"تعرف على كيفية إنشاء نقاط النهاية مع الاختبارات المتكاملة والتنفيذ والتوثيق باستخدام make و OpenAPI لأدوات الإي الأجنت"},"definition":{"en":"create-endpoint is a skill that enables AI agents to develop endpoints through a step-by-step process, including testing, implementation, and documentation.","zh":"创建端点是AIエージェント开发中的一个关键步骤，涉及写入集成测试和实现端点","ja":"エンドポイントの作成はAIエージェント開発における重要なステップであり、テストの書き込みとエンドポイントの実装を含みます","ko":"엔드포인트 생성은 AI 에이전트 개발의 핵심 단계로, 통합 테스트 작성과 엔드포인트 구현을 포함합니다","es":"Crear endpoint es el proceso de definir y configurar un punto de acceso a una API para que los desarrolladores puedan interactuar con ella","fr":"La création d''un point de terminaison est le processus de définition et de configuration d''un point d''accès à une API pour que les développeurs puissent interagir avec elle","de":"Das Erstellen eines Endpunkts ist der Prozess der Definition und Konfiguration eines Zugriffspunkts auf eine API, damit Entwickler mit ihr interagieren können","pt":"Create-endpoint é uma habilidade de desenvolvimento que cria endpoints com testes e documentação","ru":"Создание эндпоинта - это навык разработки, который создает эндпоинты с помощью тестов и документации","ar":"إنشاء نهاية هي مهارة تطوير تنشئ نقاط النهاية مع الاختبارات والتوثيق"},"features":{"en":["Writes integration tests in [module].api.test.ts","Implements endpoint controllers and routing","Generates OpenAPI specs in [module].api.docs.yaml","Supports testing with `make test-server-file` command","Verifies endpoint creation with `make build-server`"],"zh":["写入集成测试","实现端点（控制器和路由）","更新OpenAPI文档","使用Makefile进行测试和构建","支持多语言开发"],"ja":["テストの書き込み","エンドポイントの実装（コントローラーとルーティング）","OpenAPIドキュメントの更新","Makefileを使用したテストとビルド","多言語開発のサポート"],"ko":["통합 테스트 작성","엔드포인트 구현（컨트롤러와 라우팅）","OpenAPI 문서 업데이트","Makefile을 사용한 테스트와 빌드","다중 언어 개발 지원"],"es":["Escribir pruebas de integración con make test-server-file","Implementar el endpoint con controlador y enrutamiento","Documentar el proceso con OpenAPI spec en [module].api.docs.yaml","Verificar el endpoint con make build-server","Confirmar la aparición del endpoint en http://localhost","Utilizar comandos CLI como make test-server-file y make build-server"],"fr":["Écrire des tests d''intégration avec make test-server-file","Mettre en œuvre le point de terminaison avec controleur et routage","Documenter le processus avec OpenAPI spec en [module].api.docs.yaml","Vérifier le point de terminaison avec make build-server","Confirmer l''apparition du point de terminaison en http://localhost","Utiliser des commandes CLI comme make test-server-file et make build-server"],"de":["Schreiben von Integrationstests mit make test-server-file","Implementierung des Endpunkts mit Controller und Routing","Dokumentation des Prozesses mit OpenAPI-Spezifikation in [module].api.docs.yaml","Überprüfung des Endpunkts mit make build-server","Bestätigung des Auftretens des Endpunkts in http://localhost","Verwendung von CLI-Befehlen wie make test-server-file und make build-server"],"pt":["Testes de integração com make","Implementação de endpoints com controller e routing","Documentação com OpenAPI","Verificação com make build-server","Suporte a desenvolvimento de endpoints com testes e documentação"],"ru":["Тесты интеграции с помощью make","Реализация эндпоинтов с контроллером и маршрутизацией","Документация с помощью OpenAPI","Проверка с помощью make build-server","Поддержка разработки эндпоинтов с тестами и документацией для ИИ Агентов"],"ar":["الاختبارات المتكاملة مع make","تنفيذ نقاط النهاية مع التحكم والتنقل","التوثيق مع OpenAPI","التحقق مع make build-server","دعم تطوير نقاط النهاية مع الاختبارات والتوثيق لأدوات الإي الأجنت"]},"keywords":{"en":["how to use create-endpoint","create-endpoint setup guide","endpoint development workflow","create-endpoint alternative","create-endpoint vs API gateway","install create-endpoint","create-endpoint documentation","OpenAPI spec generation","integration testing with create-endpoint"],"zh":["AIエージェント开发","创建端点","集成测试","OpenAPI文档","Makefile","多语言开发","API开发","后端开发","软件开发"],"ja":["AIエージェント開発","エンドポイントの作成","テストの書き込み","OpenAPIドキュメント","Makefile","多言語開発","API開発","バックエンド開発","ソフトウェア開発"],"ko":["AI 에이전트 개발","엔드포인트 생성","통합 테스트","OpenAPI 문서","Makefile","다중 언어 개발","API 개발","백엔드 개발","소프트웨어 개발"],"es":["crear endpoint","desarrollo de API","pruebas de integración","OpenAPI spec","make test-server-file","make build-server","CLI","desarrollo de software","ingeniería de software","herramientas de desarrollo"],"fr":["créer un point de terminaison","développement d''API","tests d''intégration","OpenAPI spec","make test-server-file","make build-server","CLI","développement de logiciel","ingénierie de logiciel","outils de développement"],"de":["Endpoint erstellen","API-Entwicklung","Integrationstests","OpenAPI-Spezifikation","make test-server-file","make build-server","CLI","Software-Entwicklung","Software-Ingenieurwesen","Entwicklertools"],"pt":["create endpoint","desenvolvimento de endpoint","testes de integração","OpenAPI","make","desenvolvedores","ferramentas de desenvolvimento","criar endpoint","documentação de API"],"ru":["создание эндпоинта","разработка эндпоинта","тесты интеграции","OpenAPI","make","разработчики","инструменты разработки","ИИ Агенты","документация API"],"ar":["إنشاء نهاية","تطوير نهاية","الاختبارات المتكاملة","OpenAPI","make","مطورون","أدوات التطوير","أدوات الإي الأجنت","توثيق واجهة برمجة التطبيقات"]}},"owner":"briankeane","repo":"node-react-scaffold","repoPath":"briankeane/node-react-scaffold","stars":0,"forks":0,"updatedAt":"2026-03-01T21:28:42Z","topics":[],"category":"community","skillMd":{"name":"create-endpoint","description":"Step-by-step workflow for creating REST API endpoints with integration tests and OpenAPI docs","bodyPreview":"# Endpoint Development\n\n## Development Workflow\n\n1. Write integration tests first (in `[module].api.test.ts`)\n2. See them fail (red): `make test-server-file GREP=\"ModuleName\"`\n3. Implement the endpoint (controller + routing)\n4. See them pass (green): `make test-server-file GREP=\"ModuleName\"`\n5. Add/update documentation:\n   - `[module].api.docs.yaml` — OpenAPI spec\n   - Tag in `server/src/docs/index.ts` (if adding tags)\n6. Verify: `make build-server`, then confirm endpoints appear in `http://loca","body":"# Endpoint Development\n\n## Development Workflow\n\n1. Write integration tests first (in `[module].api.test.ts`)\n2. See them fail (red): `make test-server-file GREP=\"ModuleName\"`\n3. Implement the endpoint (controller + routing)\n4. See them pass (green): `make test-server-file GREP=\"ModuleName\"`\n5. Add/update documentation:\n   - `[module].api.docs.yaml` — OpenAPI spec\n   - Tag in `server/src/docs/index.ts` (if adding tags)\n6. Verify: `make build-server`, then confirm endpoints appear in `http://localhost:10020/swagger.json`\n7. Final check: `make prettier-server && make lint-server && make build-server && make test-server`\n\n## Reference Implementation\n\nStudy `server/src/api/healthCheck/` before creating a new endpoint. It shows the exact file structure, controller pattern, test pattern, and OpenAPI docs format used in this project.\n\n## Integration Testing\n\n### Philosophy\n\nThese are **integration tests** that test all functionality through the full stack. Test real behavior without mocking anything internally.\n\n### Mocking Rules\n\n**Only mock at borders** — calls to outside services:\n- External APIs (Spotify, AWS S3, etc.)\n- Email services\n- Push notification services\n- Third-party webhooks\n\n**Never mock** internal services, database calls, or library functions.\n\nUse `nock` for HTTP mocking (already set up in `mochaSetup.test.ts`).\n\n### Test Data Generation\n\nAlways use `server/src/test/testDataGenerator.ts` for generating test models:\n\n```typescript\nimport { createUser } from \"../../test/testDataGenerator\";\n```\n\n**DO NOT manually create users with hardcoded emails:**\n\n```typescript\n// BAD - can cause duplicate email conflicts between tests\nconst adminUser = await db.models.User.create({\n  email: \"admin@example.com\",\n  role: \"admin\",\n});\n\n// GOOD - let testDataGenerator handle unique emails\nconst adminUser = await createUser(db, { role: \"admin\" });\n```\n\n### Generating Tokens\n\n```typescript\nimport { generateToken } from \"../../utils/jwt\";\n\nconst user = await createUser(db);\nconst token = await generateToken(user);\n```\n\nIf `generateToken` doesn''t exist yet, create a JWT token directly using the user''s `jwtRepr()` method and the JWT_SECRET from config.\n\n### Test File Location\n\n`server/src/api/[module]/[module].api.test.ts` (co-located with controller)\n\n### Test Pattern\n\n```typescript\nimport { assert } from \"chai\";\nimport request from \"supertest\";\nimport app from \"../../server\";\nimport db from \"../../db\";\nimport { createUser } from \"../../test/testDataGenerator\";\n\ndescribe(\"[Module] API\", function () {\n  describe(\"GET /v1/[module]\", function () {\n    it(\"returns the resource\", async function () {\n      const user = await createUser(db, { role: \"admin\" });\n      // generate token for auth...\n\n      const res = await request(app)\n        .get(\"/v1/[module]\")\n        .set(\"Authorization\", `Bearer ${token}`)\n        .expect(200);\n\n      assert.exists(res.body.id);\n    });\n\n    it(\"returns 401 without auth\", async function () {\n      await request(app).get(\"/v1/[module]\").expect(401);\n    });\n  });\n});\n```\n\n## REST Conventions\n\n### URL Structure\n\n- All endpoints prefixed with `/v1/`\n- Routes mounted in `server/src/api/routes.ts`\n- Use kebab-case: `/audio-blocks`, not `/audioBlocks`\n- Use plural nouns: `/users`, `/stations`\n- Use lowercase\n\n### The `/:userId/` Pattern with `me`\n\nUser-related endpoints use `/:userId/` where `me` resolves to the authenticated user''s ID via the `isOperatingOnSelf` middleware.\n\n```\nGET  /v1/users/me           → Get current user\nGET  /v1/users/:userId      → Get specific user (admin)\n```\n\n### HTTP Methods & Status Codes\n\n| Method | Purpose | Success Code |\n|--------|---------|-------------|\n| GET | Retrieve resource(s) | 200 |\n| POST | Create resource | 201 |\n| PUT | Update resource | 200 |\n| DELETE | Remove resource | 200 |\n\n| Error Code | Usage |\n|------------|-------|\n| 400 | Validation error, bad request |\n| 401 | Authentication failure |\n| 403 | Permission/authorization failure |\n| 404 | Resource not found |\n| 409 | Conflict error |\n\n### Authentication & Authorization Middleware Stack\n\nApply middleware in this order on protected routes:\n\n```typescript\nrouter.get(\n  \"/:id\",\n  authenticate,                           // 1. Validate JWT\n  validateUUIDsInParams([\"id\"]),          // 2. Validate UUID format\n  requireRoleOfAtLeast(\"user\"),           // 3. Check permissions\n  controller.get,                          // 4. Handler\n);\n\nrouter.post(\n  \"/\",\n  authenticate,\n  checkBodyFor([\"name\", \"email\"]),         // Required fields\n  checkBodyForNoExtraFields([\"name\", \"email\", \"role\"]),  // No extra fields\n  validateUUIDsInBody([\"relatedId\"]),     // UUID format in body\n  controller.create,\n);\n```\n\n**Permission Middleware Options:**\n\n```typescript\nrequireRoleOfAtLeast(\"admin\")         // Roles: guest < user < admin\nisOperatingOnSelf(\"userId\")           // User can only operate on own data\noneOf([                               // OR logic\n  isOperatingOnSelf(\"userId\"),\n  requireRoleOfAtLeast(\"admin\"),\n])\n```\n\n### Error Handling\n\n**Error Classes (in `utils/errors.ts`):**\n- `NotFoundError` → 404\n- `AuthenticationError` → 401\n- `PermissionError` → 403\n- `ValidationError` → 400\n- `ConflictError` → 409\n\n```typescript\n// Use centralized error messages\nthrow new NotFoundError(ErrorMessages.RESOURCE_NOT_FOUND);\nthrow new ValidationError(ErrorMessages.invalidUuidFormat(\"userId\"));\n```\n\n**Controller pattern:**\n```typescript\nasync function handler(req: Request, res: Response, next: NextFunction) {\n  try {\n    // ... implementation\n    res.status(200).json(result);\n  } catch (error) {\n    next(error);\n  }\n}\n```\n\n### Response Structure\n\n**Single resource:** `{ \"id\": \"uuid\", \"name\": \"value\", ... }`\n\n**Collection:** `[{ \"id\": \"uuid1\", ... }, { \"id\": \"uuid2\", ... }]`\n\n**Error:** `{ \"error\": { \"message\": \"Error description\" } }`\n\n## File Organization\n\n```\nserver/src/api/\n├── routes.ts                     # Main route mounting\n├── security.ts                   # Auth middleware\n├── validation.ts                 # Validation middleware\n├── [module]/\n│   ├── index.ts                  # Route definitions (Express Router)\n│   ├── [module].api.ts           # Controller (handler functions)\n│   ├── [module].api.test.ts      # Integration tests\n│   └── [module].api.docs.yaml    # OpenAPI documentation\n```\n\n## API Documentation\n\n### Creating Docs\n\n1. **`[module].api.docs.yaml`** — OpenAPI 3.0 spec. See `healthCheck/healthCheck.api.docs.yaml` for reference.\n2. **Tag registration** — Add the module''s tag to the `tags` array in `server/src/docs/index.ts` if you''re using tags.\n3. The YAML files are auto-discovered by the glob pattern in `docs/index.ts`.\n\n### Verification\n\n```bash\nmake build-server\n# Then check: http://localhost:10020/swagger.json\n```\n\n## Route Registration\n\nIn `server/src/api/routes.ts`, add the new route:\n\n```typescript\nimport moduleApi from \"./[module]\";\n\nfunction addRoutes(app: Application) {\n  // ... existing routes\n  app.use(\"/v1/[module]\", moduleApi);\n}\n```\n\n## Anti-Patterns to Avoid\n\n**DON''T:** Handle errors with `res.status().json()` — throw typed errors instead.\n\n**DON''T:** Use `/mine` or implicit user endpoints — use `/:userId/` with `me` support.\n\n**DON''T:** Mock internal services — only mock at external boundaries.\n\n## Quality Gates\n\n- [ ] Integration tests written and passing\n- [ ] Controller follows try-catch-next pattern\n- [ ] Proper error classes used (not raw status codes)\n- [ ] Route registered in `routes.ts`\n- [ ] OpenAPI docs in `.api.docs.yaml`\n- [ ] `make prettier-server` passes\n- [ ] `make lint-server` passes\n- [ ] `make build-server` passes\n- [ ] `make test-server` passes\n"},"lastSynced":"2026-03-07T04:06:07.688Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing streamlined endpoint development with OpenAPI specifications and automated testing.","zh":"非常适合需要使用OpenAPI规范和自动化测试进行流线化端点开发的全栈代理。","ja":"OpenAPI仕様と自動テストを使用したエンドポイント開発のストリーミングが必要なフルスタックエージェントに最適。","ko":"OpenAPI 사양 및 자동화 테스트를 사용하여 최적화된 엔드ポイント 개발이 필요한 풀스택 에이전트에 적합합니다.","es":"Perfecto para Agentes Full Stack que necesitan un desarrollo de puntos de conexión optimizado con especificaciones OpenAPI y pruebas automatizadas.","fr":"Parfait pour les agents Full Stack qui ont besoin d''un développement de points de terminaison rationalisé avec des spécifications OpenAPI et des tests automatisés.","de":"Perfekt für Full-Stack-Agents, die ein optimiertes Endpunktentwicklung mit OpenAPI-Spezifikationen und automatisierter Testung benötigen.","pt":"Perfeito para Agentes Full Stack que precisam de desenvolvimento de endpoint otimizado com especificações OpenAPI e testes automatizados.","ru":"Идеально подходит для агентов Full Stack, которым необходим упрощенный разработки конечных точек с использованием спецификаций OpenAPI и автоматизированного тестирования.","ar":"مثالي للوكلاء ستريملاين Full Stack الذين يحتاجون إلى تطوير نقطة النهاية مع مواصفات OpenAPI واختبارات آلية."},"recommendation":{"en":"Empowers agents to implement robust endpoints with integration tests, controller routing, and OpenAPI documentation using YAML files and GREP testing protocols, ensuring seamless API development and validation.","zh":"赋予代理实现使用YAML文件和GREP测试协议的强大端点，集成测试，控制器路由和OpenAPI文档，确保API开发和验证的无缝对接。","ja":"エージェントに、YAMLファイルとGREPテストプロトコルを使用した強力なエンドポイントを実装する能力を付与し、統合テスト、コントローラルーティング、OpenAPIドキュメントを提供し、API開発と検証のシームレスな接続を確保する。","ko":"에이전트가 YAML 파일 및 GREP 테스트 프로토콜을 사용하여 강력한 엔드포인트를 구현할 수 있는 능력을 부여하여 통합 테스트, 컨트롤러 라우팅 및 OpenAPI 문서를 제공하고 API 개발 및 검증의 무결점 연결을 보장합니다.","es":"Habilita a los agentes a implementar puntos de conexión robustos con pruebas de integración, enrutamiento de controladores y documentación OpenAPI utilizando archivos YAML y protocolos de prueba GREP, garantizando un desarrollo y validación de API sin problemas.","fr":"Permet aux agents de mettre en œuvre des points de terminaison robustes avec des tests d''intégration, un routage de contrôleurs et une documentation OpenAPI en utilisant des fichiers YAML et des protocoles de test GREP, assurant un développement et une validation d''API sans heurts.","de":"Ermächtigt Agents, robuste Endpunkte mit Integrationstests, Controller-Routing und OpenAPI-Dokumentation zu implementieren, indem YAML-Dateien und GREP-Testprotokolle verwendet werden, um eine reibungslose API-Entwicklung und -Validierung zu gewährleisten.","pt":"Habilita os agentes a implementar endpoints robustos com testes de integração, roteamento de controlador e documentação OpenAPI usando arquivos YAML e protocolos de teste GREP, garantindo o desenvolvimento e validação de API sem problemas.","ru":"Позволяет агентам реализовывать надежные конечные точки с помощью тестов интеграции, маршрутизации контроллера и документации OpenAPI с использованием файлов YAML и протоколов тестирования GREP, обеспечивая бесперебойное развитие и проверку API.","ar":"تمكن الوكلاء من تنفيذ نقاط النهاية القوية مع اختبارات التكامل وتوجيه التحكم وتوثيق OpenAPI باستخدام ملفات YAML وبروتوكولات اختبار GREP، مما يضمن تطوير API وتحققها دون مشاكل."},"useCases":{"en":["Implementing secure API endpoints with red-green testing","Generating OpenAPI documentation for API gateway integration","Automating endpoint testing with makefile scripts"],"zh":["使用红绿测试实现安全的API端点","为API网关集成生成OpenAPI文档","使用makefile脚本自动化端点测试"],"ja":["レッドグリーンテストを使用してセキュアなAPIエンドポイントを実装する","APIゲートウェイ統合のためにOpenAPIドキュメントを生成する","makefileスクリプトを使用してエンドポイントテストを自動化する"],"ko":["레드그린 테스트를 사용하여 보안 API 엔드포인트를 구현하는 것","API 게이트웨이 통합을 위해 OpenAPI 문서를 생성하는 것","makefile 스크립트를 사용하여 엔드포인트 테스트를 자동화하는 것"],"es":["Implementar puntos de conexión de API seguros con pruebas de rojo-verde","Generar documentación OpenAPI para la integración de la pue