INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lwhguge-dot/Online-Education-Platform/address-github-comments', 'address-github-comments', 'lwhguge-dot', 'Online-Education-Platform', 'community', 'address-github-comments lwhguge-dot Online-Education-Platform community The address-github-comments skill helps developers efficiently manage GitHub comments using the GitHub CLI. It ensures all feedback is addressed systematically, benefiting developers and teams working on GitHub projects. Address GitHub Comments是一个使用GitHub CLI（gh）来高效处理PR审查评论或问题反馈的工具，确保所有反馈都被系统地处理 Address GitHub Commentsは、GitHub CLI（gh）を使用してPRレビューコメントやイシュー反馈を効率的に処理するツールであり、すべてのフィードバックが体系的に処理されることを保証 Address GitHub Comments는 GitHub CLI（gh）를 사용하여 PR 리뷰 댓글이나 이슈 피드백을 효율적으로 처리하는 도구로, 모든 피드백이 체계적으로 처리되도록 합니다 Address-github-comments es una habilidad que utiliza la CLI de GitHub para abordar sistemáticamente los comentarios de revisión de PR y la retroalimentación de problemas Address-github-comments est une compétence qui utilise la CLI GitHub pour aborder systématiquement les commentaires de révision de PR et les retours de problèmes Address-github-comments ist eine Fähigkeit, die die GitHub-CLI verwendet, um PR-Überprüfungskommentare und Problemfeedback systematisch zu bearbeiten O Address GitHub Comments é uma habilidade que ajuda a gerenciar comentários de PR e issues no GitHub de forma eficiente usando o GitHub CLI ИИ Агент Address GitHub Comments - это навык, который помогает систематически решать комментарии и отзывы в GitHub с помощью GitHub CLI أداة التعليقات على GitHub هي أداة تقنية تساعد في التعامل مع التعليقات والآراء في GitHub بفعالية باستخدام واجهة سطر الأوامر GitHub how to use address-github-comments address-github-comments setup guide github cli comment management address-github-comments alternative what is address-github-comments address-github-comments install github pr comment workflow address-github-comments vs github cli systematic github comment management Address GitHub Comments GitHub CLI PR审查评论 问题反馈 AI工具 gh auth 代码审查 版本控制 Fetches comments for the current branch''s PR using `gh pr view --comments` Categorizes comments for systematic addressing Utilizes the GitHub CLI (`gh`) for authentication and comment management Supports custom scripts for listing threads Ensures all feedback is addressed systematically address-github-comments is a skill that utilizes the GitHub CLI to efficiently address PR review comments and issue feedback, ensuring systematic management of GitHub comments');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('amo-tech-ai/rocket-path-ai/cicd-pipeline', 'community', 'amo-tech-ai', 'rocket-path-ai', 'amo-tech-ai/rocket-path-ai', 'cicd-pipeline', 0, 0, 48, '2026-03-07T00:51:02Z', '2026-03-07T03:57:56.567Z', 'a01b9a3dbc7876e9e428866556333f0409bf8bef343b7e581607ae4e2588c6b3', '{"id":"amo-tech-ai/rocket-path-ai/cicd-pipeline","name":"cicd-pipeline","description":{"en":"The cicd-pipeline skill sets up continuous integration and deployment with GitHub Actions, enabling automated build verification and deployment gates for developers. It streamlines CI/CD workflows from scratch to production deployment.","zh":"CI/CD 流水线设置指南，使用 GitHub Actions 实现自动化构建、测试和部署","ja":"CI/CD パイプライン設定ガイド - GitHub Actions を使用して自動化ビルド、テスト、デプロイメントを実現します","ko":"CI/CD 파이프라인 설정 가이드 - GitHub Actions를 사용하여 자동화된 빌드, 테스트, 배포를 실현하세요","es":"El pipeline CI/CD permite la integración y entrega continua de código con GitHub Actions. Configura verificación de compilación y despliegue automatizado","fr":"Le pipeline CI/CD permet l''intégration et le déploiement continus de code avec GitHub Actions. Configurez la vérification de build et le déploiement automatique","de":"Die CI/CD-Pipeline ermöglicht die kontinuierliche Integration und Bereitstellung von Code mit GitHub Actions. Konfigurieren Sie die Build-Verifizierung und den automatischen Bereitstellungsprozess","pt":"Configure um pipeline CI/CD com GitHub Actions para automatizar verificações de build e deploy. Aprenda a usar `.github/workflows/ci.yml` para criar um workflow de CI","ru":"Настройте конвейер CI/CD с помощью ИИ Агентов и GitHub Actions для автоматизации проверок сборки и развертывания. Узнайте, как использовать `.github/workflows/ci.yml` для создания рабочего процесса CI","ar":"إعداد трубة CI/CD مع إجراءات GitHub لتحديث التكامل والتحقق من بناء. تعلم كيفية استخدام `.github/workflows/ci.yml` لإنشاء سير عمل CI"},"seo":{"title":{"en":"cicd-pipeline: Setup Guide for AI Agents | CI/CD Pipeline","zh":"CI/CD 流水线设置指南","ja":"CI/CD パイプライン設定ガイド - AIエージェント","ko":"CI/CD 파이프라인 설정 가이드 - AI Tools","es":"Guía de configuración de CI/CD Pipeline con GitHub Actions","fr":"Guide de mise en place d''un pipeline CI/CD avec GitHub Ac...","de":"Einrichtungsleitfaden für CI/CD-Pipeline mit GitHub Actions","pt":"Guia de Configuração de Pipeline CI/CD com GitHub Actions","ru":"Настройка конвейера CI/CD с помощью ИИ Агентов и GitHub A...","ar":"دليل إعداد трубة CI/CD مع إجراءات GitHub"},"description":{"en":"Unlock efficient deployment with cicd-pipeline. Learn how to set up continuous integration and deployment with GitHub Actions and automate your workflow today!","zh":"了解如何使用 GitHub Actions 设置 CI/CD 流水线，实现自动化构建、测试和部署","ja":"GitHub Actions を使用して CI/CD パイプラインを設定し、自動化ビルド、テスト、デプロイメントを実現します - AIエージェント","ko":"GitHub Actions를 사용하여 CI/CD 파이프라인을 설정하고 자동화된 빌드, 테스트, 배포를 실현하세요 - AI Tools","es":"Aprende a configurar un pipeline de integración y entrega continua con GitHub Actions, verificación de compilación y puertas de despliegue","fr":"Découvrez comment configurer un pipeline d''intégration et de déploiement continu avec GitHub Actions, vérification de build et portes de déploiement","de":"Erfahren Sie, wie Sie eine Pipeline für die kontinuierliche Integration und Bereitstellung mit GitHub Actions, Build-Verifizierung und Bereitstellungs-Gates ...","pt":"Aprenda a configurar um pipeline de integração e entrega contínua com GitHub Actions, incluindo verificações de build e portas de deploy","ru":"Узнайте, как настроить конвейер непрерывной интеграции и доставки с помощью ИИ Агентов и GitHub Actions, включая проверки сборки и ворота развертывания","ar":"تعلم كيفية إعداد трубة للتكامل والتحديث المستمر مع إجراءات GitHub، بما في ذلك عمليات التحقق من بناء وبوابات النشر"},"definition":{"en":"cicd-pipeline is a skill that automates continuous integration and deployment using GitHub Actions, facilitating build checks, automated test runs, and production deployment automation.","zh":"CI/CD 流水线是一种自动化的软件开发流程，使用 GitHub Actions 实现构建、测试和部署","ja":"CI/CD パイプラインは、GitHub Actions を使用してビルド、テスト、デプロイメントを自動化するソフトウェア開発プロセスです","ko":"CI/CD 파이프라인은 GitHub Actions를 사용하여 빌드, 테스트, 배포를 자동화하는 소프트웨어 개발 프로세스입니다","es":"Un pipeline CI/CD es un proceso automático que combina la integración y entrega continua de código","fr":"Un pipeline CI/CD est un processus automatique qui combine l''intégration et le déploiement continus de code","de":"Eine CI/CD-Pipeline ist ein automatisierter Prozess, der die kontinuierliche Integration und Bereitstellung von Code kombiniert","pt":"Um pipeline CI/CD é um conjunto de etapas automatizadas para build, testar e deploy de software","ru":"Конвейер CI/CD - это набор автоматизированных этапов для сборки, тестирования и развертывания программного обеспечения","ar":"تروب CI/CD هي مجموعة من الخطوات التي يتم تشغيلها تلقائيًا لبناء واختبار ونشر البرامج"},"features":{"en":["Configures GitHub Actions for continuous integration and deployment","Automates build verification using `.github/workflows/ci.yml` files","Supports deployment gates for controlled production releases","Triggers automated test runs on pull requests and push events","Utilizes `ubuntu-latest` environment for build and deployment jobs"],"zh":["使用 GitHub Actions 设置 CI/CD 流水线","自动化构建和测试","配置部署门槛","支持 PR 检查和自动化测试运行"],"ja":["GitHub Actions を使用して CI/CD パイプラインを設定","自動化ビルドとテスト","デプロイメントゲートの設定","PR チェックと自動化テスト実行のサポート"],"ko":["GitHub Actions를 사용하여 CI/CD 파이프라인을 설정","자동화된 빌드와 테스트","배포 게이트 설정","PR 검사와 자동화된 테스트 실행 지원"],"es":["Configuración de GitHub Actions para CI/CD","Verificación de compilación y pruebas automatizadas","Despliegue automatizado en producción","Uso de archivos de flujo de trabajo como `.github/workflows/ci.yml`","Compatibilidad con desencadenadores de eventos como `push` y `pull_request`"],"fr":["Configuration de GitHub Actions pour CI/CD","Vérification de build et tests automatisés","Déploiement automatique en production","Utilisation de fichiers de workflow tels que `.github/workflows/ci.yml`","Compatibilité avec les déclencheurs d''événements tels que `push` et `pull_request`"],"de":["Konfiguration von GitHub Actions für CI/CD","Build-Verifizierung und automatisierte Tests","Automatischer Bereitstellungsprozess in Produktion","Verwendung von Workflow-Dateien wie `.github/workflows/ci.yml`","Kompatibilität mit Ereignis-Trigger wie `push` und `pull_request`"],"pt":["Configuração de workflow de CI com `.github/workflows/ci.yml`","Verificações de build automatizadas","Deploy automático com portas de deploy","Integração com GitHub Actions","Suporte a branches e pull requests"],"ru":["Настройка рабочего процесса CI с помощью `.github/workflows/ci.yml`","Автоматизированные проверки сборки","Автоматическое развертывание с воротами развертывания","Интеграция с ИИ Агентами и GitHub Actions","Поддержка веток и запросов на слияние"],"ar":["إعداد سير عمل CI مع `.github/workflows/ci.yml`","عمليات التحقق من بناء آلي","نشر آلي مع بوابات النشر","التكامل مع إجراءات GitHub","الدعم للفروع وطلبات الدمج"]},"keywords":{"en":["how to use cicd-pipeline","cicd-pipeline setup guide","github actions ci cd","continuous integration and deployment tutorial","cicd-pipeline vs jenkins","automated deployment with github actions","cicd-pipeline install","what is cicd-pipeline","cicd-pipeline alternative"],"zh":["CI/CD 流水线","GitHub Actions","自动化构建","自动化测试","部署自动化","CI/CD 设置指南"],"ja":["CI/CD パイプライン","GitHub Actions","自動化ビルド","自動化テスト","デプロイメント自動化","CI/CD 設定ガイド","AIエージェント"],"ko":["CI/CD 파이프라인","GitHub Actions","자동화된 빌드","자동화된 테스트","배포 자동화","CI/CD 설정 가이드","AI Tools"],"es":["pipeline CI/CD","GitHub Actions","integración continua","entrega continua","verificación de compilación","despliegue automatizado","configuración de CI/CD"],"fr":["pipeline CI/CD","GitHub Actions","intégration continue","déploiement continu","vérification de build","déploiement automatique","configuration de CI/CD"],"de":["CI/CD-Pipeline","GitHub Actions","kontinuierliche Integration","kontinuierliche Bereitstellung","Build-Verifizierung","automatischer Bereitstellungsprozess","Konfiguration von CI/CD"],"pt":["pipeline CI/CD","GitHub Actions","configuração de workflow","verificações de build","deploy automático","integração contínua","entrega contínua","desenvolvimento de software"],"ru":["конвейер CI/CD","ИИ Агенты","GitHub Actions","настройка рабочего процесса","автоматизированные проверки сборки","автоматическое развертывание","непрерывная интеграция","непрерывная доставка","разработка программного обеспечения"],"ar":["تروب CI/CD","إجراءات GitHub","إعداد سير عمل","عمليات التحقق من بناء","نشر آلي","التكامل المستمر","التحديث المستمر","تطوير البرمجيات"]}},"owner":"amo-tech-ai","repo":"rocket-path-ai","repoPath":"amo-tech-ai/rocket-path-ai","stars":0,"forks":0,"updatedAt":"2026-03-07T00:51:02Z","topics":[],"category":"community","skillMd":{"name":"cicd-pipeline","description":"Use when setting up GitHub Actions, automated testing, build checks, or deployment workflows. Triggers on CI/CD, pipeline, GitHub Actions, deploy, automated testing, build check.","bodyPreview":"# CI/CD Pipeline\n\n## Overview\n\nSet up continuous integration and deployment with GitHub Actions, build verification, and deployment gates.\n\n## When to Use\n\n- Setting up CI/CD from scratch\n- Adding build checks to PRs\n- Configuring automated test runs\n- Production deployment automation\n\n## Workflow\n\n### Phase 1: CI Workflow\n\n`.github/workflows/ci.yml`:\n```yaml\nname: CI\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:","body":"# CI/CD Pipeline\n\n## Overview\n\nSet up continuous integration and deployment with GitHub Actions, build verification, and deployment gates.\n\n## When to Use\n\n- Setting up CI/CD from scratch\n- Adding build checks to PRs\n- Configuring automated test runs\n- Production deployment automation\n\n## Workflow\n\n### Phase 1: CI Workflow\n\n`.github/workflows/ci.yml`:\n```yaml\nname: CI\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n          cache: npm\n      - run: npm ci\n      - run: npm run lint\n      - run: npm run build\n      - run: npm run test\n\n  edge-functions:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: denoland/setup-deno@v2\n      - run: deno check supabase/functions/*/index.ts\n```\n\n### Phase 2: Deploy Workflow\n\n```yaml\n  deploy:\n    needs: [build, edge-functions]\n    if: github.ref == ''refs/heads/main''\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with: { node-version: 20, cache: npm }\n      - run: npm ci && npm run build\n      # Deploy to hosting + edge functions\n```\n\n### Phase 3: Branch Protection\n\n1. Require CI pass before merge\n2. Require PR review\n3. No force push to main\n\n## Checklist\n\n- [ ] CI runs on push + PRs\n- [ ] Build, lint, test steps\n- [ ] Edge function type check\n- [ ] Deploy only on main after checks pass\n- [ ] Secrets in GitHub Actions secrets\n- [ ] Branch protection rules enabled\n"},"lastSynced":"2026-03-07T03:57:56.567Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated build verification and deployment gates with GitHub Actions","zh":"适用于需要使用 GitHub Actions 进行自动化构建验证和部署门控的 DevOps Agent","ja":"GitHub Actions を使用した自動化されたビルドの検証とデプロイゲートが必要な DevOps エージェントに最適","ko":"GitHub Actions를 사용하여 자동화된 빌드 확인 및 배포 게이트가 필요한 DevOps 에이전트에 적합","es":"Ideal para agentes de DevOps que requieren una verificación de compilación automatizada y puertas de implementación con GitHub Actions","fr":"Idéal pour les agents DevOps nécessitant une vérification de build automatisée et des portes de déploiement avec GitHub Actions","de":"Ideal für DevOps-Agents, die eine automatisierte Build-Verifizierung und Deploy-Gates mit GitHub Actions benötigen","pt":"Ideal para Agentes DevOps que exigem verificação de compilação automatizada e portas de implantação com GitHub Actions","ru":"Идеально для агентов DevOps, требующих автоматизированной верификации сборки и ворот развертывания с GitHub Actions","ar":"مثالي للوكلاء DevOps الذين يتطلبون التحقق التلقائي من البناء وأبواب النشر مع GitHub Actions"},"recommendation":{"en":"Empowers agents to streamline CI/CD workflows with GitHub Actions, facilitating automated test runs, build checks, and production deployment automation using YAML configurations like `.github/workflows/ci.yml`","zh":"赋予代理人使用 GitHub Actions 简化 CI/CD 工作流的能力，实现自动化测试运行、构建检查和使用 YAML 配置（如 `.github/workflows/ci.yml`）的生产环境部署自动化","ja":"GitHub Actions を使用して CI/CD ワークフローを簡素化するエージェントの能力を付与し、自動化されたテストの実行、ビルドの確認、および YAML 構成（`.github/workflows/ci.yml` など）を使用した生产環境への自動デプロイを実現する","ko":"에이전트가 GitHub Actions를 사용하여 CI/CD 워크플ロー를 단순화하는 능력을 부여하여 자동화된 테스트 실행, 빌드 확인 및 YAML 구성(예: `.github/workflows/ci.yml`)을 사용한 프로덕션 환경 자동 배포를 구현","es":"Habilita a los agentes a simplificar flujos de trabajo de CI/CD con GitHub Actions, facilitando la ejecución automática de pruebas, comprobaciones de compilación y automatización de la implementación en producción utilizando configuraciones YAML como `.github/workflows/ci.yml`","fr":"Permet aux agents de simplifier les flux de travail CI/CD avec GitHub Actions, en facilitant les exécutions de tests automatisées, les vérifications de build et l''automatisation du déploiement en production en utilisant des configurations YAML comme `.github/workflows/ci.yml`","de":"Ermöglicht es Agenten, CI/CD-Workflows mit GitHub Actions zu vereinfachen, indem automatisierte Testläufe, Build-Checks und Automatisierung der Produktionsbereitstellung mithilfe von YAML-Konfigurationen wie `.github/workflows/ci.yml` ermöglicht werden","pt":"Habilita agentes a otimizar fluxos de trabalho de CI/CD com GitHub Actions, facilitando execuções de teste automatizadas, verificações de compilação e automação de implantação em produção usando configurações YAML como `.github/workflows/ci.yml`","ru":"Наделяет агентов возможностью оптимизировать рабочие процессы CI/CD с помощью GitHub Actions, облегчая автоматизированное выполнение тестов, проверки сборки и автоматизацию развертывания в производстве с использованием конфигураций YAML, таких как `.github/workflows/ci.yml`","ar":"يمنح الوكلاء القدرة على تبسيط سير عمل CI/CD باستخدام GitHub Actions، وتسهيل تشغيل الاختبارات التلقائي، وعمليات بناء التحقق، وتأتمة النشر في الإنتاج باستخدام تكوينات YAML مثل `.github/workflows/ci.yml`"},"useCases":{"en":["Automating build verification for pull requests","Configuring deployment gates for production environments","Streamlining CI/CD workflows from scratch to deployment"],"zh":["自动化拉取请求的构建验证","为生产环境配置部署门控","从头开始到部署的 CI/CD 工作流的简化"],"ja":["プルリクエストのビルドの検証の自動化","生产環境のデプロイゲートの設定","スクラッチからデプロイまでの CI/CD ワークフローの簡素化"],"ko":["풀 요청에 대한 빌드 확인 자동화","프로덕션 환경에 대한 배포 게이트 구성","처음부터 배포까지의 CI/CD 워크플로 단순화"],"es":["Automatizar la verificación de compilación para solicitudes de extracción","Configurar puertas de implementación para entornos de producción","Simplificar flujos de trabajo de CI/CD desde cero hasta la implementación"],"fr":["Automatiser la vérification de build pour les demandes d''extraction","Configurer des portes de déploiement pour les environnements de production","Simplifier les flux de travail CI/CD de zéro à la mise en production"],"de":["Automatisierung der Build-Verifizierung für Pull-Requests","Konfigurieren von Deploy-Gates für Produktionsumgebungen","Vereinfachen von CI/CD-Workflows von Null bis zur Bereitstellung"],"pt":["Automatizar verificação de compilação para solicitações de pull","Configurar portas de implantação para ambientes de produção","Otimizar fluxos de trabalho de CI/CD desde a criação até a implantação"],"ru":["Автоматизировать верификацию сборки для запросов на включение","Настроить ворота развертывания для производственных сред","Оптимизировать рабочие процессы CI/CD от начала до конца"],"ar":["التحقق التلقائي من بناء طلبات السحب","تكوين أبواب النشر للبيئات الإنتاجية","تبسيط سير عمل CI/CD من البداية إلى النهاية"]},"limitations":{"en":["Requires GitHub Actions setup","Limited to GitHub repositories","Dependent on YAML workflow files like `.github/workflows/ci.yml`"],"zh":["需要 GitHub Actions 设置","仅限 GitHub仓库","依赖于 YAML 工作流文件，如 `.github/workflows/ci.yml`"],"ja":["GitHub Actions の設定が必要","GitHub リポジトリのみ","`.github/workflows/ci.yml` などの YAML ワークフロー ファイルに依存"],"ko":["GitHub Actions 설정이 필요","GitHub 저장소만 해당","`.github/workflows/ci.yml`과 같은 YAML 워크플ロー 파일에 의존"],"es":["Requiere configuración de GitHub Actions","Limitado a repositorios de GitHub","Dependiente de archivos de flujo de trabajo YAML como `.github/workflows/ci.yml`"],"fr":["Nécessite une configuration de GitHub Actions","Limité aux référentiels GitHub","Dépendant de fichiers de workflow YAML comme `.github/workflows/ci.yml`"],"de":["Benötigt GitHub Actions-Konfiguration","Begrenzt auf GitHub-Repositorys","Abhängig von YAML-Workflow-Dateien wie `.github/workflows/ci.yml`"],"pt":["Exige configuração do GitHub Actions","Limitado a repositórios GitHub","Dependente de arquivos de fluxo de trabalho YAML como `.github/workflows/ci.yml`"],"ru":["Требует настройки GitHub Actions","Ограничен репозиториями GitHub","Зависит от файлов рабочего процесса YAML, таких как `.github/workflows/ci.yml`"],"ar":["يتطلب إعداد GitHub Actions","محدود بمخازن GitHub","يعتمد على ملفات سير العمل YAML مثل `.github/workflows/ci.yml`"]},"version":4},"contentHash":"a01b9a3dbc7876e9e428866556333f0409bf8bef343b7e581607ae4e2588c6b3","qualityScore":48}');
