INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('szeyu/open-ssyok-finance/slidev-styling', 'slidev-styling', 'szeyu', 'open-ssyok-finance', 'community', 'slidev-styling szeyu open-ssyok-finance community The slidev-styling skill enables developers to customize Slidev presentations using UnoCSS utilities, custom CSS, and advanced styling techniques. It benefits developers who need to create engaging and responsive slide layouts. Slidev样式设置技能涵盖UnoCSS、自定义CSS、作用域样式和高级样式技术 Slidevスタイリングスキルでは、UnoCSS、カスタムCSS、スコープスタイル、そして高度なスタイリングテクニックを扱います Slidev 스타일링 스킬은 UnoCSS, 커스텀 CSS, 스코프 스타일 및 고급 스타일링 기술을 다룹니다 Slidev-Styling permite personalizar la apariencia de tus diapositivas con UnoCSS, CSS personalizado y técnicas de estilismo avanzadas. Le style Slidev permet de personnaliser l''apparence de vos diapositives avec UnoCSS, CSS personnalisé et techniques de stylisme avancées. Slidev-Styling ermöglicht die Anpassung der Ansicht Ihrer Folien mit UnoCSS, benutzerdefiniertem CSS und erweiterten Stiltechniken. O skill slidev-styling fornece técnicas avançadas de customização para Slidev, incluindo UnoCSS e CSS personalizado Навык slidev-styling предоставляет продвинутые техники настройки для Slidev, включая UnoCSS и пользовательский CSS مهارة slidev-styling توفر تقنيات تخصيص متقدمة لبرنامج Slidev، بما في ذلك UnoCSS و CSS مخصص how to use slidev-styling what is slidev-styling slidev-styling vs tailwind css slidev-styling setup guide slidev-styling install customizing slidev presentations UnoCSS tutorial slidev styling best practices Slidev样式设置 UnoCSS 自定义CSS 作用域样式 高级样式技术 幻灯片设计 AIエージェント 前端开发 Utilizes UnoCSS, an atomic CSS framework similar to Tailwind CSS Supports inline classes for customizing slide elements Enables creation of reusable style patterns and custom colors Allows implementation of animations and responsive layouts Includes scoped styles for precise control over slide design slidev-styling is a skill that covers all styling options in Slidev, including UnoCSS utilities, custom CSS, scoped styles, and advanced techniques for customizing slide appearance and behavior.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('termos-dev/agent-workbench/awb', 'community', 'termos-dev', 'agent-workbench', 'termos-dev/agent-workbench', 'awb', 0, 0, 48, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:21.771Z', '04fd26f1dac60b864f405eb83f18c2c09f3cf3c75b605f189d85d0c34a55b2b2', '{"id":"termos-dev/agent-workbench/awb","name":"awb","description":{"en":"awb provides an interactive development environment for Claude Code, allowing developers to run and test components efficiently. It benefits AI agent developers and testers.","zh":"AWB 是一个 Interactive Development Environment，用于 Claude Code 的开发。它提供了多种组件，如 confirm、checklist、ask 等，帮助开发者高效地构建应用。","ja":"AWB は、Claude Code 用のインタラクティブ開発環境です。confirm、checklist、ask などのコンポーネントを提供し、開発者が効率的にアプリケーションを構築できるようにします。","ko":"AWB는 Claude Code를 위한 인터랙티브 개발 환경으로, confirm, checklist, ask 등의 컴포넌트를 제공하여 개발자가 효율적으로 애플리케이션을 구축할 수 있도록 합니다.","es":"awb es un entorno de desarrollo interactivo para Claude Code que ofrece componentes interactivos y de visualización para mejorar la productividad","fr":"awb est un environnement de développement interactif pour Claude Code qui propose des composants interactifs et de visualisation pour améliorer la productivité","de":"awb ist eine interaktive Entwicklungsumgebung für Claude Code, die interaktive und Anzeigekomponenten zur Steigerung der Produktivität bietet","pt":"O awb é um ambiente de desenvolvimento interativo para Claude Code, permitindo a execução de componentes e a interação com o usuário","ru":"awb - это интерактивная среда разработки для ИИ Агентов, позволяющая выполнять компоненты и взаимодействовать с пользователем","ar":"awb هو بيئة تطوير تفاعلية لآلة الكلود، مما يسمح بتنفيذ المكونات والتفاعل مع المستخدم"},"seo":{"title":{"en":"awb: Interactive Development Environment Setup Guide | AI...","zh":"AWB Setup Guide: Interactive Development Environment","ja":"AWB セットアップガイド: Claude Code 用インタラクティブ開発環境","ko":"AWB 설정 가이드: Claude Code를 위한 인터랙티브 개발 환경","es":"Guía de Configuración de awb: Entorno de Desarrollo Inter...","fr":"Guide de Configuration awb : Environnement de Développeme...","de":"awb-Setup-Leitfaden: Interaktive Entwicklungsumgebung für...","pt":"Guia de Configuração do awb - Ambiente de Desenvolvimento...","ru":"Настройка awb - Интерактивная Среда Разработки ИИ Агентов","ar":"دليل إعداد awb - بيئة تطوير تفاعلية لآلة الكلود"},"description":{"en":"Discover how to use awb for AI agent development. Learn to run components with awb run and optimize your workflow with awb wait. Get started now!","zh":"了解 AWB 的功能和用途，掌握 Interactive Development Environment 的使用方法","ja":"AWB の機能と使い方をマスターし、Claude Code 用のインタラクティブ開発環境を活用する","ko":"AWB의 기능과 사용 방법을 알아보고 Claude Code를 위한 인터랙티브 개발 환경을 활용해 보세요","es":"Aprende a configurar awb para Claude Code y aprovecha al máximo sus componentes interactivos y de visualización","fr":"Découvrez comment configurer awb pour Claude Code et exploitez au maximum ses composants interactifs et de visualisation","de":"Erfahren Sie, wie Sie awb für Claude Code konfigurieren und seine interaktiven und Anzeigekomponenten optimal nutzen","pt":"Aprenda a configurar o awb, um ambiente de desenvolvimento interativo para Claude Code, e explore suas funcionalidades","ru":"Узнайте, как настроить awb, интерактивную среду разработки для ИИ Агентов, и откройте для себя ее возможности","ar":"تعرف على كيفية إعداد awb، بيئة تطوير تفاعلية لآلة الكلود، واستكشف ميزاتها"},"definition":{"en":"awb is an interactive development environment for Claude Code, enabling developers to create and test AI agent components using commands like awb run and awb wait.","zh":"AWB 是一个用于 Claude Code 的 Interactive Development Environment","ja":"AWB は Claude Code 用のインタラクティブ開発環境です","ko":"AWB는 Claude Code를 위한 인터랙티브 개발 환경입니다","es":"awb es un entorno de desarrollo interactivo que permite a los desarrolladores crear y probar componentes para Claude Code","fr":"awb est un environnement de développement interactif qui permet aux développeurs de créer et de tester des composants pour Claude Code","de":"awb ist eine interaktive Entwicklungsumgebung, die es Entwicklern ermöglicht, Komponenten für Claude Code zu erstellen und zu testen","pt":"O awb é um ambiente de desenvolvimento que fornece uma interface interativa para desenvolvedores trabalharem com Claude Code","ru":"awb - это среда разработки, предоставляющая интерактивный интерфейс для разработчиков, работающих с ИИ Агентами","ar":"awb هو بيئة تطوير توفر واجهة تفاعلية للمطورين للعمل مع آلة الكلود"},"features":{"en":["Runs interactive components like confirm, checklist, and ask","Supports display components such as code, table, markdown, plan-viewer, and html","Requires --title for every awb run command","Utilizes awb wait to read JSON responses","Provides help documentation with awb run --help"],"zh":["支持多种组件，如 confirm、checklist、ask","提供 Interactive Development Environment","使用 awb ui 打开 playground","使用 awb run 运行组件","支持 JSON 响应"],"ja":["コンポーネントのサポート（confirm、checklist、ask など）","インタラクティブ開発環境の提供","awb ui で playground を開く","awb run でコンポーネントを実行する","JSON 応答のサポート"],"ko":["컴포넌트 지원（confirm, checklist, ask 등）","인터랙티브 개발 환경 제공","awb ui로 playground 열기","awb run으로 컴포넌트 실행","JSON 응답 지원"],"es":["Componentes interactivos como confirm, checklist y ask","Componentes de visualización como code, table, markdown y plan-viewer","Compatibilidad con la línea de comandos (CLI) para ejecutar componentes","Opción de espera para leer respuestas JSON","Requisito de título para cada ejecución de componente"],"fr":["Composants interactifs tels que confirm, checklist et ask","Composants de visualisation tels que code, table, markdown et plan-viewer","Compatibilité avec la ligne de commande (CLI) pour exécuter des composants","Option d''attente pour lire les réponses JSON","Exigence de titre pour chaque exécution de composant"],"de":["Interaktive Komponenten wie confirm, checklist und ask","Anzeigekomponenten wie code, table, markdown und plan-viewer","Kompatibilität mit der Befehlszeile (CLI) zum Ausführen von Komponenten","Wartefunktion zum Lesen von JSON-Antworten","Titelvoraussetzung für jede Komponentenausführung"],"pt":["Execução de componentes interativos, como confirm, checklist e ask","Suporte a componentes de exibição, como code, table, markdown e plan-viewer","Interface de linha de comando (CLI) para execução de comandos awb","Obrigatório uso de --title para cada execução de awb run","Suporte a JSON para resposta de comandos awb"],"ru":["Выполнение интерактивных компонентов, таких как confirm, checklist и ask","Поддержка компонентов отображения, таких как code, table, markdown и plan-viewer","Интерфейс командной строки (CLI) для выполнения команд awb","Обязательное использование --title для каждой выполнения awb run","Поддержка JSON для ответа команд awb"],"ar":["تنفيذ مكونات تفاعلية، مثل confirm و checklist و ask","دعم مكونات العرض، مثل code و table و markdown و plan-viewer","واجهة سطر الأوامر (CLI) لتنفيذ أوامر awb","استخدام --title إلزامي لكل تنفيذ awb run","دعم JSON لاستجابة أوامر awb"]},"keywords":{"en":["how to use awb","awb setup guide","awb vs Claude Code","awb install","what is awb","awb alternative","awb run command","awb wait function","awb interactive development environment"],"zh":["AWB","Interactive Development Environment","Claude Code","AI开发工具","AWB setup","AWB 使用方法"],"ja":["AWB","インタラクティブ開発環境","Claude Code","AIエージェント","AWB セットアップ","AWB 使い方"],"ko":["AWB","인터랙티브 개발 환경","Claude Code","AI 에이전트","AWB 설정","AWB 사용 방법"],"es":["awb","Claude Code","entorno de desarrollo interactivo","componentes interactivos","visualización de código","línea de comandos","desarrollo de software","herramientas de desarrollo","Agentes de IA","Herramientas de IA"],"fr":["awb","Claude Code","environnement de développement interactif","composants interactifs","visualisation de code","ligne de commande","développement de logiciels","outils de développement","Agents IA","Outils IA"],"de":["awb","Claude Code","interaktive Entwicklungsumgebung","interaktive Komponenten","Code-Anzeige","Befehlszeile","Software-Entwicklung","Entwicklungstools","KI-Agents","KI-Tools"],"pt":["awb","ambiente de desenvolvimento interativo","Claude Code","componentes interativos","CLI","JSON","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["awb","интерактивная среда разработки","ИИ Агенты","интерактивные компоненты","CLI","JSON","разработка программного обеспечения","инструменты разработки"],"ar":["awb","بيئة تطوير تفاعلية","آلة الكلود","مكونات تفاعلية","CLI","JSON","تطوير البرمجيات","أدوات التطوير"]}},"owner":"termos-dev","repo":"agent-workbench","repoPath":"termos-dev/agent-workbench","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.272Z","topics":[],"category":"community","skillMd":{"name":"awb","description":"Run Agent Workbench (awb) interactive UI components from Codex or the CLI. Use when the user needs a confirmation, checklist, input, table, code or markdown view, or a visual playground. Always follow interactive runs with awb wait and the returned ID. Use tmux for long-running commands (see awb --help).","bodyPreview":"# Agent Workbench (awb)\n\n## Quick Start\n\n1. Ensure the user has the playground open with `awb ui`.\n2. Run a component with `awb run --title \"...\" <component> [args]`.\n3. Always call `awb wait <id>` and read the JSON response.\n\n## Components\n\nInteractive: `confirm`, `checklist`, `ask`\nDisplay: `code`, `table`, `markdown`, `plan-viewer`, `html`\n\n## Essential Rules\n\n- Require `--title` for every `awb run`.\n- Run `awb run --help` before using a component you are unsure about.\n- If `awb` is not on PA","body":"# Agent Workbench (awb)\n\n## Quick Start\n\n1. Ensure the user has the playground open with `awb ui`.\n2. Run a component with `awb run --title \"...\" <component> [args]`.\n3. Always call `awb wait <id>` and read the JSON response.\n\n## Components\n\nInteractive: `confirm`, `checklist`, `ask`\nDisplay: `code`, `table`, `markdown`, `plan-viewer`, `html`\n\n## Essential Rules\n\n- Require `--title` for every `awb run`.\n- Run `awb run --help` before using a component you are unsure about.\n- If `awb` is not on PATH, ask the user to install or run the local CLI.\n\n## Interactive Runs (Always wait)\n\n`awb run` returns immediately with an ID. Always call `awb wait <id>` to get the response.\n\n```bash\nID=$(awb run --title \"Q1\" confirm --prompt \"Approve?\")\nawb wait $ID\n```\n\nFire multiple at once, then wait for each:\n\n```bash\nID1=$(awb run --title \"Q1\" confirm --prompt \"Approve?\")\nID2=$(awb run --title \"Q2\" checklist --items \"A,B,C\")\nawb wait $ID1\nawb wait $ID2\n```\n\n## Wait Results\n\n`awb wait <id>` returns JSON with the user''s response:\n\n```json\n{\"confirmed\": true}\n{\"items\": [{\"text\":\"A\",\"checked\":true}]}\n{\"answers\": {\"key\": \"value\"}}\n```\n\n## Examples\n\nconfirm\n```bash\nawb run --title \"Deploy\" confirm --prompt \"Deploy to production?\"\n```\n\nchecklist\n```bash\nawb run --title \"Tasks\" checklist --items \"Build,Test,Deploy\"\n```\n\nask (1-4 questions)\n```bash\nawb run --title \"Name\" ask --questions ''[{\"question\":\"Your name?\",\"header\":\"name\"}]''\nawb run --title \"Pick\" ask --questions ''[{\"question\":\"Language?\",\"header\":\"lang\",\"options\":[{\"label\":\"TypeScript\"},{\"label\":\"Python\"}]}]''\nawb run --title \"Features\" ask --questions ''[{\"question\":\"Enable?\",\"header\":\"feat\",\"multiSelect\":true,\"options\":[{\"label\":\"Auth\"},{\"label\":\"API\"}]}]''\n```\n\ntable\n```bash\nawb run --title \"Data\" table --data ''[{\"name\":\"Alice\",\"age\":30},{\"name\":\"Bob\",\"age\":25}]''\n```\n\ncode (file only)\n```bash\nawb run --title \"Source\" code --file ./src/index.ts\n```\n\nmarkdown\n```bash\nawb run --title \"Docs\" markdown --file ./README.md\nawb run --title \"Notes\" markdown --content \"# Hello\\n\\nWorld\"\n```\n\nhtml\n```bash\nawb run --title \"Config\" html --content ''<html>...</html>''\n```\n\nplan-viewer\n```bash\nawb run --title \"Plan\" plan-viewer --file ./plan.md\n```\n\n## Background Processes with tmux\n\nUse tmux for long-running processes. Run `awb --help` to see your tmux session name.\n\n```bash\ntmux new-session -A -d -s <session-name>\ntmux new-window -t <session-name> -n \"dev\" \"npm run dev\"\ntmux capture-pane -t <session-name>:dev -p\ntmux send-keys -t <session-name>:dev \"npm test\" Enter\ntmux kill-window -t <session-name>:dev\n```\n"},"lastSynced":"2026-03-08T02:00:21.771Z","agentAnalysis":{"suitability":{"en":"Perfect for Claude Code Developers needing an interactive development environment for efficient component testing and validation.","zh":"非常适合需要交互式开发环境以便于高效组件测试和验证的 Claude Code 开发人员。","ja":"Claude Code 開発者が効率的なコンポーネントのテストと検証のためのインタラクティブな開発環境を必要とする場合に最適です。","ko":"효율적인 컴포넌트 테스트 및 검증을 위한 인터랙티브 개발 환경이 필요한 Claude Code 개발자에게 적합합니다.","es":"Perfecto para desarrolladores de Claude Code que necesitan un entorno de desarrollo interactivo para pruebas y validación de componentes eficientes.","fr":"Parfait pour les développeurs de Claude Code ayant besoin d''un environnement de développement interactif pour des tests et une validation de composants efficaces.","de":"Perfekt für Claude Code-Entwickler, die ein interaktives Entwicklungsumfeld für effiziente Komponententests und -validierung benötigen.","pt":"Perfeito para desenvolvedores Claude Code que necessitam de um ambiente de desenvolvimento interativo para testar e validar componentes de forma eficiente.","ru":"Идеально подходит для разработчиков Claude Code, которым необходим интерактивная среда разработки для эффективного тестирования и проверки компонентов.","ar":"مثالي للمطورين Claude Code الذين يحتاجون إلى بيئة تطوير تفاعلية لاختبار وتحقق مكونات فعال"},"recommendation":{"en":"Empowers agents to run and test components efficiently using awb''s interactive UI, supporting various components such as confirm, checklist, and code display, all while utilizing JSON responses for seamless integration.","zh":"赋予代理人使用 awb 的交互式 UI 高效运行和测试组件的能力，支持诸如 confirm、checklist 和代码显示等各种组件，同时利用 JSON 响应实现无缝集成。","ja":"awb のインタラクティブ UI を使用してコンポーネントを効率的に実行およびテストするエージェントを可能にし、confirm、checklist、コード表示などのさまざまなコンポーネントをサポートし、同時に JSON 応答を使用してシームレスな統合を実現します。","ko":"awb의 인터랙티브 UI를 사용하여 컴포넌트를 효율적으로 실행 및 테스트할 수 있는 에이전트를 가능하게 하며, 확인, 체크리스트 및 코드 표시와 같은 다양한 컴포넌트를 지원하며,同時에 JSON 응답을 사용하여 무결점 통합을 구현합니다.","es":"Habilita a los agentes a ejecutar y probar componentes de forma eficiente utilizando la interfaz de usuario interactiva de awb, que admite varios componentes como confirm, checklist y visualización de código, todo mientras utiliza respuestas JSON para una integración sin problemas.","fr":"Permet aux agents d''exécuter et de tester des composants de manière efficace en utilisant l''interface utilisateur interactive d''awb, qui prend en charge divers composants tels que confirm, checklist et affichage de code, le tout en utilisant des réponses JSON pour une intégration sans accroc.","de":"Ermöglicht es Agenten, Komponenten effizient auszuführen und zu testen, indem sie die interaktive Benutzeroberfläche von awb verwenden, die verschiedene Komponenten wie Bestätigung, Checkliste und Codeanzeige unterstützt, und zwar unter Verwendung von JSON-Antworten für eine nahtlose Integration.","pt":"Habilita os agentes a executar e testar componentes de forma eficiente usando a interface do usuário interativa do awb, suportando vários componentes, como confirm, checklist e exibição de código, tudo isso utilizando respostas JSON para integração transparente.","ru":"Наделяет агентов возможностью запускать и тестировать компоненты эффективно с помощью интерактивного интерфейса awb, поддерживающего различные компоненты, такие как подтверждение, список проверок и отображение кода, все это при использовании ответов JSON для бесшовной интеграции.","ar":"تمكين الوكلاء من تشغيل واختبار المكونات بفعالية باستخدام واجهة المستخدم التفاعلية awb، ودعم المكونات المختلفة مثل التأكيد وقائمة التحقق وعرض الكود، وكل ذلك باستخدام استجابات JSON للتكامل السلس"},"useCases":{"en":["Debugging components with awb run and awb wait","Testing interactive components like confirm and checklist","Displaying code and markdown components for development feedback"],"zh":["使用 awb run 和 awb wait 调试组件","测试交互式组件，如 confirm 和 checklist","显示代码和 markdown 组件以获得开发反馈"],"ja":["awb run および awb wait を使用してコンポーネントをデバッグする","confirm や checklist などのインタラクティブ コンポーネントをテストする","コードおよび markdown コンポーネントを表示して開発者向けのフィードバックを取得する"],"ko":["awb run 및 awb wait를 사용하여 컴포넌트를 디버깅하는 것","확인 및 체크리스트와 같은 인터랙티브 컴포넌트를 테스트하는 것","코드 및 마크다운 컴포넌트를 표시하여 개발자용 피드백을 얻는 것"],"es":["Depuración de componentes con awb run y awb wait","Pruebas de componentes interactivos como confirm y checklist","Visualización de componentes de código y markdown para comentarios de desarrollo"],"fr":["Débogage de composants avec awb run et awb wait","Test de composants interactifs tels que confirm et checklist","Affichage de composants de code et markdown pour des commentaires de développement"],"de":["Fehlerbehebung von Komponenten mit awb run und awb wait","Testen interaktiver Komponenten wie Bestätigung und Checkliste","Anzeige von Code- und Markdown-Komponenten für Entwicklungskommentare"],"pt":["Depuração de componentes com awb run e awb wait","Teste de componentes interativos como confirm e checklist","Exibição de código e componentes de markdown para feedback de desenvolvimento"],"ru":["Отладка компонентов с помощью awb run и awb wait","Тестирование интерактивных компонентов, таких как подтверждение и список проверок","Отображение кода и компонентов markdown для обратной связи разработки"],"ar":["تصحيح أخطاء المكونات باستخدام awb run و awb wait","اختبار المكونات التفاعلية مثل التأكيد وقائمة التحقق","عرض الكود ومكونات markdown لتعليقات التطوير"]},"limitations":{"en":["Requires --title for every awb run","Must call awb wait for JSON response","Specific to Claude Code development environment"],"zh":["需要为每个 awb run 指定 --title","必须调用 awb wait 以获得 JSON 响应","仅适用于 Claude Code 开发环境"],"ja":["各 awb run に対して --title を指定する必要がある","JSON 応答を取得するために awb wait を呼び出す必要がある","Claude Code 開発環境にのみ特化している"],"ko":["각 awb run에 대해 --title을 지정해야 함","JSON 응답을 얻기 위해 awb wait를 호출해야 함","Claude Code 개발 환경에만 특화되어 있음"],"es":["Requiere --title para cada awb run","Deben llamar a awb wait para la respuesta JSON","Específico del entorno de desarrollo de Claude Code"],"fr":["Nécessite --title pour chaque awb run","Doit appeler awb wait pour la réponse JSON","Spécifique à l''environnement de développement de Claude Code"],"de":["Benötigt --title für jeden awb run","Muss awb wait für die JSON-Antwort aufrufen","Spezifisch für die Claude Code-Entwicklungsumgebung"],"pt":["Exige --title para cada awb run","Deve chamar awb wait para resposta JSON","Específico para ambiente de desenvolvimento Claude Code"],"ru":["Требует --title для каждого awb run","Должен вызывать awb wait для ответа JSON","Конкретно для среды разработки Claude Code"],"ar":["يتطلب --title لكل awb run","يجب استدعاء awb wait لاستجابة JSON","محدد لبيئة تطوير Claude Code"]},"version":4},"contentHash":"04fd26f1dac60b864f405eb83f18c2c09f3cf3c75b605f189d85d0c34a55b2b2","qualityScore":48}');
