INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dmmulroy/better-result/better-result-adopt', 'better-result-adopt', 'dmmulroy', 'better-result', 'community', 'better-result-adopt dmmulroy better-result community better-result-adopt is a lightweight Result type for TypeScript that enables generator-based composition. It helps developers migrate existing error handling to typed Result-based error handling. better-result-adopt是一种轻量级结果类型，为TypeScript提供了generator-based composition better-result-adoptはTypeScriptの軽量結果タイプであり、ジェネレーターベースのコンポジションを提供する better-result-adopt는 TypeScript의 경량 결과 유형으로 generator-based composition을 제공 better-result-adopt es una solución ligera para el manejo de errores en TypeScript, que utiliza composición basada en generadores better-result-adopt est une solution légère pour la gestion des erreurs dans TypeScript, qui utilise une composition basée sur les générateurs better-result-adopt ist eine leichte Lösung für die Fehlerbehandlung in TypeScript, die eine generatorbasierte Komposition verwendet O better-result-adopt é uma biblioteca leve para TypeScript que permite a composição baseada em geradores para tratamento de erros. better-result-adopt - это легковесная библиотека для TypeScript, которая предоставляет генераторную композицию для обработки ошибок. better-result-adopt هو مكتبة خفيفة الوزن للنوعية TypeScript تسمح بالتركيب القائم على المولِّد للتعامل مع الأخطاء. how to use better-result-adopt better-result-adopt alternative better-result-adopt vs TypeScript better-result-adopt install better-result-adopt setup guide typed Result-based error handling generator-based composition railway-oriented programming better-result-adopt TypeScript轻量级结果类型 错误处理 结果组合 generator-based composition typed Result-based错误处理 AIエージェント TypeScript开发 Migrates existing try/catch blocks to Result types Replaces thrown exceptions with typed errors Supports Promise-based code migration to Result.tryPromise Introduces railway-oriented programming patterns Enables adoption in existing codebases Starts migration at boundaries better-result-adopt is a TypeScript library that provides a typed Result-based error handling mechanism with generator-based composition.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SterlingChin/marvin-template/start', 'community', 'SterlingChin', 'marvin-template', 'SterlingChin/marvin-template', 'start', 0, 0, 48, '2026-03-08T01:57:15.277Z', '2026-03-08T02:00:44.248Z', 'c299ccc89aed3501d3e0595a80df49cffa82595f067d1e2fd676a2c875ca7e65', '{"id":"SterlingChin/marvin-template/start","name":"start","description":{"en":"The start skill initiates MARVIN sessions with full context loading and daily briefing, benefiting developers who need to connect to essential apps and manage their day efficiently.","zh":"MARVIN启动会话，加载上下文和每日简报，帮助开发者提高效率","ja":"MARVINを使用してセッションを開始し、コンテキストと毎日ブリーフィングをロードします","ko":"MARVIN을 사용하여 세션을 시작하고 컨텍스트 및 일일 브리핑을 로드하여 개발자에게 도움을 제공합니다","es":"El skill ''start'' inicializa sesiones de MARVIN con carga de contexto y resumen diario para mejorar la productividad","fr":"Le skill ''start'' démarre des sessions MARVIN avec chargement de contexte et briefing quotidien pour améliorer la productivité","de":"Das ''start''-Skill initialisiert MARVIN-Sitzungen mit Kontextladen und täglichem Bericht, um die Produktivität zu steigern","pt":"O skill Start é uma funcionalidade que inicializa sessões com carregamento de contexto e briefing diário para melhorar a produtividade.","ru":"Навык Start - это функция, которая запускает сессии с загрузкой контекста и ежедневным брифингом для повышения производительности.","ar":"مهارة بدء هي ميزة ت 初始化 الجلسات مع تحميل السياق والتقرير اليومي لتحسين الإنتاجية."},"seo":{"title":{"en":"Start: Session Setup Guide for AI Agents | AI Assistant S...","zh":"MARVIN启动指南：初始化会话和每日简报","ja":"MARVINスタートガイド：セッション開始と毎日ブリーフィング","ko":"MARVIN 시작 가이드: 세션 시작 및 일일 브리핑","es":"Guía de Configuración de ''start'' para Agentes de IA","fr":"Guide de Démarrage de ''start'' pour Outils d''IA","de":"Einrichtungsanleitung für ''start'' bei KI-Agents","pt":"Guia de Configuração do Sk