INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SterlingChin/marvin-template/start', 'start', 'SterlingChin', 'marvin-template', 'community', 'start SterlingChin marvin-template community The start skill initiates MARVIN sessions with full context loading and daily briefing, benefiting developers who need to connect to essential apps and manage their day efficiently. MARVIN启动会话，加载上下文和每日简报，帮助开发者提高效率 MARVINを使用してセッションを開始し、コンテキストと毎日ブリーフィングをロードします MARVIN을 사용하여 세션을 시작하고 컨텍스트 및 일일 브리핑을 로드하여 개발자에게 도움을 제공합니다 El skill ''start'' inicializa sesiones de MARVIN con carga de contexto y resumen diario para mejorar la productividad Le skill ''start'' démarre des sessions MARVIN avec chargement de contexte et briefing quotidien pour améliorer la productivité Das ''start''-Skill initialisiert MARVIN-Sitzungen mit Kontextladen und täglichem Bericht, um die Produktivität zu steigern O skill Start é uma funcionalidade que inicializa sessões com carregamento de contexto e briefing diário para melhorar a produtividade. Навык Start - это функция, которая запускает сессии с загрузкой контекста и ежедневным брифингом для повышения производительности. مهارة بدء هي ميزة ت 初始化 الجلسات مع تحميل السياق والتقرير اليومي لتحسين الإنتاجية. how to use start skill MARVIN session setup start skill alternative start vs other AI assistants start install guide start setup for developers what is start skill start skill tutorial start skill for task management MARVIN启动会话 AI工具 AIエージェント 初始化会话 每日简报 CLI命令 React开发 Python开发 Establishes current date using `date +%Y-%m-%d` command Loads context from `state/current.md` and `sessions/{TODAY}` files Supports daily briefing and task management Initiates MARVIN sessions with full context loading Uses `bash` commands for date formatting and file naming Start is a session initiation skill that loads current date, priorities, and state to provide a daily briefing and facilitate task management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('northseadl/skillwisp/security-ownership-map', 'community', 'northseadl', 'skillwisp', 'northseadl/skillwisp', 'security-ownership-map', 0, 0, 48, '2026-03-08T01:57:15.278Z', '2026-03-08T02:00:47.117Z', 'f06c1a59247569326702c945f397af163ea96cf2ecfdf2dde280605bf89a3ec8', '{"id":"northseadl/skillwisp/security-ownership-map","name":"security-ownership-map","description":{"en":"security-ownership-map generates a bipartite graph of people and files from git history, computing ownership risk and exporting graph artifacts for Neo4j/Gephi. It benefits developers and security teams.","zh":"Security Ownership Map 是一个用于构建安全风险评估模型的 AI 编程助手技能，使用 Python 和 networkx 库","ja":"Security Ownership Map は、Python と networkx ライブラリを使用してセキュリティリスク評価モデルを構築する AI エージェントのスキルです","ko":"Security Ownership Map 는 Python 및 networkx 라이브러리를 사용하여 보안 위험 평가 모델을 구축하는 AI 에이전트의 스킬입니다","es":"Security Ownership Map es una herramienta que analiza la propiedad de seguridad en proyectos de código abierto utilizando git y networkx","fr":"Security Ownership Map est un outil qui analyse la propriété de sécurité dans les projets de code open source en utilisant git et networkx","de":"Security Ownership Map ist ein Tool, das die Sicherheitseigentümerschaft in Open-Source-Projekten mithilfe von git und networkx analysiert","pt":"O security-ownership-map é uma ferramenta que constrói um grafo bipartido de pessoas e arquivos do histórico do Git para calcular o risco de propriedade e exportar artefatos de grafo para Neo4j/Gephi","ru":"Security-ownership-map - это инструмент, который строит двудольный граф людей и файлов из истории Git для расчета риска владения и экспорта графических артефактов для Neo4j/Gephi","ar":"security-ownership-map هو أداة تبني رسمًا بيانيًا ثنائيًا للأشخاص والملفات من تاريخ Git لحساب مخاطر الملكية وتصدير مكونات الرسم البياني لNeo4j/Gephi"},"seo":{"title":{"en":"security-ownership-map: Build & Analyze Code Ownership | ...","zh":"Security Ownership Map 安装指南 - AI 编程助手安全风险评估","ja":"Security Ownership Map セットアップガイド - AI エージェントによるセキュリティリスク評価","ko":"Security Ownership Map 설정 가이드 - AI 에이전트를 이용한 보안 위험 평가","es":"Guía de configuración de Security Ownership Map para Agen...","fr":"Guide de configuration de Security Ownership Map pour les...","de":"Einrichtungsleitfaden für Security Ownership Map in AI-Tools","pt":"Guia de Configuração do security-ownership-map para Desen...","ru":"Руководство по настройке security-ownership-map для разра...","ar":"دليل إعداد security-ownership-map للطورين باستخدام أدوات ..."},"description":{"en":"Discover how to build a bipartite graph of people and files from git history and compute ownership risk with security-ownership-map. Get started now!","zh":"了解 Security Ownership Map 的功能和特点，使用 AI 编程助手构建安全风险评估模型，优化代码安全性","ja":"Security Ownership Map の機能と特徴を学び、AI エージェントを使用してセキュリティリスク評価モデルを構築する","ko":"Security Ownership Map 의 기능과 특징을 알아보고 AI 에이전트를 사용하여 보안 위험 평가 모델을 구축하십시오","es":"Aprende a utilizar Security Ownership Map con Python y networkx para analizar la propiedad de seguridad en tus proyectos de código abierto","fr":"Découvrez comment utiliser Security Ownership Map avec Python et networkx pour analyser la propriété de sécurité dans vos projets de code open source","de":"Erfahren Sie, wie Sie Security Ownership Map mit Python und networkx verwenden, um die Sicherheitseigentümerschaft in Ihren Open-Source-Projekten zu analysieren","pt":"Aprenda a configurar o security-ownership-map para melhorar a segurança do seu código com um grafo bipartido de pessoas e arquivos do histórico do Git","ru":"Узнайте, как настроить security-ownership-map, чтобы улучшить безопасность вашего кода с помощью двудольного графа людей и файлов из истории Git","ar":"تعلم كيفية إعداد security-ownership-map لتحسين أمان кодك باستخدام رسم بياني ثنائي للناس والملفات من تاريخ Git"},"definition":{"en":"security-ownership-map is a skill that builds a bipartite graph of people and files from git history to compute ownership risk and export graph artifacts.","zh":"Security Ownership Map 是一种使用 git 历史构建双分图并计算所有权风险的 AI 编程助手技能","ja":"Security Ownership Map は、git の履歴から二部グラフを構築し、所有権リスクを計算する AI エージェントのスキルです","ko":"Security Ownership Map 는 git 기록에서 이분 그래프를 구축하고 소유권 위험을 계산하는 AI 에이전트의 스킬입니다","es":"Security Ownership Map es una herramienta de análisis de propiedad de seguridad que utiliza grafos bipartitos y detección de comunidades","fr":"Security Ownership Map est un outil d''analyse de propriété de sécurité qui utilise des graphes bipartites et la détection de communautés","de":"Security Ownership Map ist ein Tool zur Analyse der Sicherheitseigentümerschaft, das bipartite Grafiken und Community-Erkennung verwendet","pt":"O que é security-ownership-map? É uma ferramenta de código aberto que calcula o risco de propriedade de arquivos com base no histórico do Git","ru":"Что такое security-ownership-map? Это открытый инструмент, который рассчитывает риск владения файлами на основе истории Git","ar":"ما هو security-ownership-map؟ هو أداة مفتوحة المصدر لحساب مخاطر ملكية الملفات بناءً على تاريخ Git"},"features":{"en":["Builds a bipartite graph of people and files from git history","Computes ownership risk and exports graph artifacts for Neo4j/Gephi","Constructs a file co-change graph using Jaccard similarity on shared commits","Clusters files by how they move together, ignoring large, noisy commits","Utilizes Python 3 and the networkx library for community detection","Installs via pip with the command `pip install networkx`"],"zh":["使用 Python 3 构建安全风险评估模型","利用 networkx 库进行社区检测","构建双分图和文件共同更改图","计算所有权风险和导出图形","支持 Neo4j 和 Gephi"],"ja":["Python 3 を使用してセキュリティリスク評価モデルを構築する","networkx ライブラリを使用してコミュニティ検出を実行する","二部グラフとファイル共同変更グラフを構築する","所有権リスクを計算し、グラフをエクスポートする","Neo4j と Gephi をサポートする"],"ko":["Python 3을 사용하여 보안 위험 평가 모델을 구축합니다","networkx 라이브러리를 사용하여 커뮤니티 감지를 수행합니다","이분 그래프와 파일 공동 변경 그래프를 구축합니다","소유권 위험을 계산하고 그래프를导出합니다","Neo4j 및 Gephi를 지원합니다"],"es":["Análisis de propiedad de seguridad utilizando grafos bipartitos","Detección de comunidades con networkx","Exportación de artefactos de grafo para Neo4j y Gephi","Creación de un grafo de co-cambio de archivos con similitud de Jaccard","Soporte para Python 3","Instalación con pip"],"fr":["Analyse de propriété de sécurité à l''aide de graphes bipartites","Détection de communautés avec networkx","Exportation d''artefacts de graphique pour Neo4j et Gephi","Création d''un graphique de co-changement de fichiers avec similarité de Jaccard","Prise en charge de Python 3","Installation avec pip"],"de":["Analyse der Sicherheitseigentümerschaft mithilfe bipartiter Grafiken","Community-Erkennung mit networkx","Export von Grafikartefakten für Neo4j und Gephi","Erstellung eines Grafiks für den Co-Change von Dateien mit Jaccard-Ähnlichkeit","Unterstützung für Python 3","Installation mit pip"],"pt":["Constrói um grafo bipartido de pessoas e arquivos do histórico do Git","Calcula o risco de propriedade com base na história de commits","Exporta artefatos de grafo para Neo4j/Gephi","Utiliza a biblioteca networkx para detecção de comunidades","Suporta Python 3","Permite a clusterização de arquivos por similaridade de commits"],"ru":["Строит двудольный граф людей и файлов из истории Git","Рассчитывает риск владения на основе истории коммитов","Экспортирует графические артефакты для Neo4j/Gephi","Использует библиотеку networkx для обнаружения сообществ","Поддерживает Python 3","Позволяет кластеризовать файлы по подобию коммитов"],"ar":["يبني رسمًا بيانيًا ثنائيًا للأشخاص والملفات من تاريخ Git","يحسب مخاطر الملكية بناءً على تاريخ الالتزامات","يصدر مكونات الرسم البياني لNeo4j/Gephi","يستخدم مكتبة networkx للكشف عن المجتمعات","يدعم Python 3","يسمح بتشكيل الملفات حسب التشابه في الالتزامات"]},"keywords":{"en":["how to use security-ownership-map","security-ownership-map alternative","security-ownership-map install","what is security-ownership-map","security-ownership-map vs graphdb","security-ownership-map setup guide","security-ownership-map neo4j integration","security-ownership-map gephi export"],"zh":["Security Ownership Map","AI 编程助手","安全风险评估","Python 3","networkx","git 历史","双分图","文件共同更改图"],"ja":["Security Ownership Map","AI エージェント","セキュリティリスク評価","Python 3","networkx","git 履歴","二部グラフ","ファイル共同変更グラフ"],"ko":["Security Ownership Map","AI 에이전트","보안 위험 평가","Python 3","networkx","git 기록","이분 그래프","파일 공동 변경 그래프"],"es":["Security Ownership Map","análisis de propiedad de seguridad","grafos bipartitos","networkx","Python 3","Neo4j","Gephi","Agentes de IA","herramientas de IA","seguridad de código abierto"],"fr":["Security Ownership Map","analyse de propriété de sécurité","graphes bipartites","networkx","Python 3","Neo4j","Gephi","outils d''IA","propriété de sécurité","sécurité de code open source"],"de":["Security Ownership Map","Analyse der Sicherheitseigentümerschaft","bipartite Grafiken","networkx","Python 3","Neo4j","Gephi","AI-Tools","Sicherheitseigentümerschaft","Sicherheit von Open-Source-Code"],"pt":["security-ownership-map","segurança de código","grafo bipartido","histórico do Git","risco de propriedade","Neo4j","Gephi","networkx","Python 3","desenvolvimento de software"],"ru":["security-ownership-map","безопасность кода","двудольный граф","история Git","риск владения","Neo4j","Gephi","networkx","Python 3","разработка программного обеспечения"],"ar":["security-ownership-map","أمان الكود","رسم بياني ثنائي","تاريخ Git","مخاطر الملكية","Neo4j","Gephi","networkx","Python 3","تطوير البرمجيات"]}},"owner":"northseadl","repo":"skillwisp","repoPath":"northseadl/skillwisp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.278Z","topics":[],"category":"community","skillMd":{"name":"security-ownership-map","description":"Analyze git repositories to build a security ownership topology (people-to-file), compute bus factor and sensitive-code ownership, and export CSV/JSON for graph databases and visualization. Trigger only when the user explicitly wants a security-oriented ownership or bus-factor analysis grounded in git history (for example: orphaned sensitive code, security maintainers, CODEOWNERS reality checks for risk, sensitive hotspots, or ownership clusters). Do not trigger for general maintainer lists or non-security ownership questions.","bodyPreview":"# Security Ownership Map\n\n## Overview\n\nBuild a bipartite graph of people and files from git history, then compute ownership risk and export graph artifacts for Neo4j/Gephi. Also build a file co-change graph (Jaccard similarity on shared commits) to cluster files by how they move together while ignoring large, noisy commits.\n\n## Requirements\n\n- Python 3\n- `networkx` (required; community detection is enabled by default)\n\nInstall with:\n\n```bash\npip install networkx\n```\n\n## Workflow\n\n1. Scope the re","body":"# Security Ownership Map\n\n## Overview\n\nBuild a bipartite graph of people and files from git history, then compute ownership risk and export graph artifacts for Neo4j/Gephi. Also build a file co-change graph (Jaccard similarity on shared commits) to cluster files by how they move together while ignoring large, noisy commits.\n\n## Requirements\n\n- Python 3\n- `networkx` (required; community detection is enabled by default)\n\nInstall with:\n\n```bash\npip install networkx\n```\n\n## Workflow\n\n1. Scope the repo and time window (optional `--since/--until`).\n2. Decide sensitivity rules (use defaults or provide a CSV config).\n3. Build the ownership map with `scripts/run_ownership_map.py` (co-change graph is on by default; use `--cochange-max-files` to ignore supernode commits).\n4. Communities are computed by default; graphml output is optional (`--graphml`).\n5. Query the outputs with `scripts/query_ownership.py` for bounded JSON slices.\n6. Persist and visualize (see `references/neo4j-import.md`).\n\nBy default, the co-change graph ignores common “glue” files (lockfiles, `.github/*`, editor config) so clusters reflect actual code movement instead of shared infra edits. Override with `--cochange-exclude` or `--no-default-cochange-excludes`. Dependabot commits are excluded by default; override with `--no-default-author-excludes` or add patterns via `--author-exclude-regex`.\n\nIf you want to exclude Linux build glue like `Kbuild` from co-change clustering, pass:\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo /path/to/linux \\\n  --out ownership-map-out \\\n  --cochange-exclude \"**/Kbuild\"\n```\n\n## Quick start\n\nRun from the repo root:\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo . \\\n  --out ownership-map-out \\\n  --since \"12 months ago\" \\\n  --emit-commits\n```\n\nDefaults: author identity, author date, and merge commits excluded. Use `--identity committer`, `--date-field committer`, or `--include-merges` if needed.\n\nExample (override co-change excludes):\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo . \\\n  --out ownership-map-out \\\n  --cochange-exclude \"**/Cargo.lock\" \\\n  --cochange-exclude \"**/.github/**\" \\\n  --no-default-cochange-excludes\n```\n\nCommunities are computed by default. To disable:\n\n```bash\npython skills/skills/security-ownership-map/scripts/run_ownership_map.py \\\n  --repo . \\\n  --out ownership-map-out \\\n  --no-communities\n```\n\n## Sensitivity rules\n\nBy default, the script flags common auth/crypto/secret paths. Override by providing a CSV file:\n\n```\n# pattern,tag,weight\n**/auth/**,auth,1.0\n**/crypto/**,crypto,1.0\n**/*.pem,secrets,1.0\n```\n\nUse it with `--sensitive-config path/to/sensitive.csv`.\n\n## Output artifacts\n\n`ownership-map-out/` contains:\n\n- `people.csv` (nodes: people)\n- `files.csv` (nodes: files)\n- `edges.csv` (edges: touches)\n- `cochange_edges.csv` (file-to-file co-change edges with Jaccard weight; omitted with `--no-cochange`)\n- `summary.json` (security ownership findings)\n- `commits.jsonl` (optional, if `--emit-commits`)\n- `communities.json` (computed by default from co-change edges when available; includes `maintainers` per community; disable with `--no-communities`)\n- `cochange.graph.json` (NetworkX node-link JSON with `community_id` + `community_maintainers`; falls back to `ownership.graph.json` if no co-change edges)\n- `ownership.graphml` / `cochange.graphml` (optional, if `--graphml`)\n\n`people.csv` includes timezone detection based on author commit offsets: `primary_tz_offset`, `primary_tz_minutes`, and `timezone_offsets`.\n\n## LLM query helper\n\nUse `scripts/query_ownership.py` to return small, JSON-bounded slices without loading the full graph into context.\n\nExamples:\n\n```bash\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out people --limit 10\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out files --tag auth --bus-factor-max 1\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out person --person alice@corp --limit 10\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out file --file crypto/tls\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out cochange --file crypto/tls --limit 10\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section orphaned_sensitive_code\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out community --id 3\n```\n\nUse `--community-top-owners 5` (default) to control how many maintainers are stored per community.\n\n## Basic security queries\n\nRun these to answer common security ownership questions with bounded output:\n\n```bash\n# Orphaned sensitive code (stale + low bus factor)\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section orphaned_sensitive_code\n\n# Hidden owners for sensitive tags\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section hidden_owners\n\n# Sensitive hotspots with low bus factor\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out summary --section bus_factor_hotspots\n\n# Auth/crypto files with bus factor <= 1\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out files --tag auth --bus-factor-max 1\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out files --tag crypto --bus-factor-max 1\n\n# Who is touching sensitive code the most\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out people --sort sensitive_touches --limit 10\n\n# Co-change neighbors (cluster hints for ownership drift)\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out cochange --file path/to/file --min-jaccard 0.05 --limit 20\n\n# Community maintainers (for a cluster)\npython skills/skills/security-ownership-map/scripts/query_ownership.py --data-dir ownership-map-out community --id 3\n\n# Monthly maintainers for the community containing a file\npython skills/skills/security-ownership-map/scripts/community_maintainers.py \\\n  --data-dir ownership-map-out \\\n  --file network/card.c \\\n  --since 2025-01-01 \\\n  --top 5\n\n# Quarterly buckets instead of monthly\npython skills/skills/security-ownership-map/scripts/community_maintainers.py \\\n  --data-dir ownership-map-out \\\n  --file network/card.c \\\n  --since 2025-01-01 \\\n  --bucket quarter \\\n  --top 5\n```\n\nNotes:\n- Touches default to one authored commit (not per-file). Use `--touch-mode file` to count per-file touches.\n- Use `--window-days 90` or `--weight recency --half-life-days 180` to smooth churn.\n- Filter bots with `--ignore-author-regex ''(bot|dependabot)''`.\n- Use `--min-share 0.1` to show stable maintainers only.\n- Use `--bucket quarter` for calendar quarter groupings.\n- Use `--identity committer` or `--date-field committer` to switch from author attribution.\n- Use `--include-merges` to include merge commits (excluded by default).\n\n### Summary format (default)\n\nUse this structure, add fields if needed:\n\n```json\n{\n  \"orphaned_sensitive_code\": [\n    {\n      \"path\": \"crypto/tls/handshake.rs\",\n      \"last_security_touch\": \"2023-03-12T18:10:04+00:00\",\n      \"bus_factor\": 1\n    }\n  ],\n  \"hidden_owners\": [\n    {\n      \"person\": \"alice@corp\",\n      \"controls\": \"63% of auth code\"\n    }\n  ]\n}\n```\n\n## Graph persistence\n\nUse `references/neo4j-import.md` when you need to load the CSVs into Neo4j. It includes constraints, import Cypher, and visualization tips.\n\n## Notes\n\n- `bus_factor_hotspots` in `summary.json` lists sensitive files with low bus factor; `orphaned_sensitive_code` is the stale subset.\n- If `git log` is too large, narrow with `--since` or `--until`.\n- Compare `summary.json` against CODEOWNERS to highlight ownership drift.\n"},"lastSynced":"2026-03-08T02:00:47.117Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced git history visualization and ownership risk assessment capabilities.","zh":"适用于需要高级 git 历史可视化和所有权风险评估能力的代码分析代理。","ja":"コード分析エージェントが高度な Git 歴史の視覚化と所有権リスク評価機能を必要とする場合に最適です。","ko":"고급 깃 기록 시각화 및 소유권 위험 평가 기능이 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan una visualización avanzada de historial de git y capacidades de evaluación de riesgo de propiedad.","fr":"Parfait pour les agents d''analyse de code nécessitant une visualisation avancée de l''historique git et des capacités d''évaluation des risques de propriété.","de":"Perfekt für Code-Analyse-Agenten, die eine erweiterte Visualisierung der Git-Historie und eine Eigentumsrisikobewertung benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de visualização avançada de histórico do git e capacidades de avaliação de risco de propriedade.","ru":"Идеально подходит для Агентов Анализа Кодов, которым необходима продвинутая визуализация истории git и возможности оценки риска владения.","ar":"مثالي لعمليات تحليل الشفرة التي تحتاج إلى تصور متقدم لتاريخ git وتقييم مخاطر الملكية."},"recommendation":{"en":"Empowers agents to compute ownership risk and export graph artifacts for Neo4j/Gephi using Python 3 and the networkx library, enabling advanced data visualization and community detection for security teams and developers.","zh":"赋予代理计算所有权风险并使用 Python 3 和 networkx 库将图形制品导出到 Neo4j/Gephi，以实现安全团队和开发人员的高级数据可视化和社区检测。","ja":"Python 3 と networkx ライブラリを使用して、エージェントが所有権リスクを計算し、Neo4j/Gephi 分析用のグラフ・アーティファクトをエクスポートできるようにし、セキュリティチームと開発者向けの高度なデータ可視化とコミュニティ検出を可能にします。","ko":"Python 3 및 networkx 라이브러리를 사용하여 에이전트가 소유권 위험을 계산하고 Neo4j/Gephi 분석을 위한 그래프 아티팩트를 내보내도록 하여 보안 팀과 개발자용 고급 데이터 시각화 및 커뮤니티 탐지를 가능하게 합니다.","es":"Habilita a los agentes para calcular el riesgo de propiedad y exportar artefactos de gráficos para Neo4j/Gephi utilizando Python 3 y la biblioteca networkx, lo que permite una visualización avanzada de datos y detección de comunidades para equipos de seguridad y desarrolladores.","fr":"Permet aux agents de calculer le risque de propriété et d''exporter des artefacts de graphiques pour Neo4j/Gephi en utilisant Python 3 et la bibliothèque networkx, ce qui permet une visualisation avancée des données et une détection de communautés pour les équipes de sécurité et les développeurs.","de":"Ermöglicht es den Agenten, das Eigentumsrisiko zu berechnen und Graphartefakte für Neo4j/Gephi mit Python 3 und der networkx-Bibliothek zu exportieren, was eine erweiterte Datenvisualisierung und Community-Erkennung für Sicherheitsteams und Entwickler ermöglicht.","pt":"Habilita os agentes a computar o risco de propriedade e exportar artefatos de gráfico para Neo4j/Gephi usando Python 3 e a biblioteca networkx, permitindo visualização de dados avançada e detecção de comunidades para equipes de segurança e desenvolvedores.","ru":"Наделяет агентов возможностью вычислять риск владения и экспортировать графические артефакты для Neo4j/Gephi с помощью Python 3 и библиотеки networkx, что позволяет выполнять продвинутую визуализацию данных и обнаружение сообществ для команд безопасности и разработчиков.","ar":"يمنح الوكلاء القدرة على حساب مخاطر الملكية وتصدير مكونات الرسم البياني لبرنامج Neo4j/Gephi باستخدام Python 3 ومكتبة networkx، مما يتيح تحليل بيانات متقدم وتحديد المجتمعات لأفرقة الأمن والمطورين."},"useCases":{"en":["Generating bipartite graphs of people and files from git history","Computing ownership risk for code repositories","Exporting graph artifacts for Neo4j/Gephi analysis"],"zh":["从 git 历史生成人员和文件的二分图","计算代码仓库的所有权风险","导出图形制品用于 Neo4j/Gephi 分析"],"ja":["Git 歴史から人物とファイルの二部グラフを生成する","コードリポジトリの所有権リスクを計算する","Neo4j/Gephi 分析用のグラフ・アーティファクトをエクスポートする"],"ko":["깃 기록에서 사람과 파일의 쌍을 그래프를 생성하는 것","코드 저장소의 소유권 위험을 계산하는 것","Neo4j/Gephi 분석을 위한 그래프 아티팩트를 내보내는 것"],"es":["Generación de grafos bipartitos de personas y archivos a partir del historial de git","Cálculo del riesgo de propiedad para repositorios de código","Exportación de artefactos de gráficos para análisis de Neo4j/Gephi"],"fr":["Génération de graphes bipartites de personnes et de fichiers à partir de l''historique git","Calcul du risque de propriété pour les référentiels de code","Exportation d''artefacts de graphiques pour l''analyse Neo4j/Gephi"],"de":["Erstellung von bipartiten Graphen von Personen und Dateien aus der Git-Historie","Berechnung des Eigentumsrisikos für Code-Repositorys","Export von Graphartefakten für Neo4j/Gephi-Analyse"],"pt":["Geração de grafos bipartidos de pessoas e arquivos a partir do histórico do git","Cálculo do risco de propriedade para repositórios de código","Exportação de artefatos de gráfico para análise Neo4j/Gephi"],"ru":["Генерация двудольных графов людей и файлов из истории git","Расчет риска владения для хранилищ кода","Экспорт графических артефактов для анализа Neo4j/Gephi"],"ar":["إنشاء رسومات بيانية ثنائية للناس والملفات من تاريخ git","حساب مخاطر الملكية لمخازن الشفرة","تصدير مكونات الرسم البياني لتحليل Neo4j/Gephi"]},"limitations":{"en":["Requires Python 3","Dependent on networkx library","Limited to git history analysis"],"zh":["需要 Python 3","依赖于 networkx 库","仅限 git 历史分析"],"ja":["Python 3 が必要","networkx ライブラリに依存している","Git 歴史分析のみに限定されている"],"ko":["Python 3 필요","networkx 라이브러리 의존","깃 기록 분석만 가능"],"es":["Requiere Python 3","Dependiente de la biblioteca networkx","Limitado al análisis de historial de git"],"fr":["Nécessite Python 3","Dépendant de la bibliothèque networkx","Limité à l''analyse de l''historique git"],"de":["Benötigt Python 3","Abhängig von der networkx-Bibliothek","Begrenzt auf die Analyse der Git-Historie"],"pt":["Requer Python 3","Dependente da biblioteca networkx","Limitado à análise do histórico do git"],"ru":["Требуется Python 3","Зависит от библиотеки networkx","Ограничен анализом истории git"],"ar":["يتطلب Python 3","يعتمد على مكتبة networkx","محدود بتحليل تاريخ git"]},"version":4},"contentHash":"f06c1a59247569326702c945f397af163ea96cf2ecfdf2dde280605bf89a3ec8","qualityScore":48}');
