INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('northseadl/skillwisp/security-ownership-map', 'security-ownership-map', 'northseadl', 'skillwisp', 'community', 'security-ownership-map northseadl skillwisp community security-ownership-map generates a bipartite graph of people and files from git history, computing ownership risk and exporting graph artifacts for Neo4j/Gephi. It benefits developers and security teams. Security Ownership Map 是一个用于构建安全风险评估模型的 AI 编程助手技能，使用 Python 和 networkx 库 Security Ownership Map は、Python と networkx ライブラリを使用してセキュリティリスク評価モデルを構築する AI エージェントのスキルです Security Ownership Map 는 Python 및 networkx 라이브러리를 사용하여 보안 위험 평가 모델을 구축하는 AI 에이전트의 스킬입니다 Security Ownership Map es una herramienta que analiza la propiedad de seguridad en proyectos de código abierto utilizando git y networkx Security Ownership Map est un outil qui analyse la propriété de sécurité dans les projets de code open source en utilisant git et networkx Security Ownership Map ist ein Tool, das die Sicherheitseigentümerschaft in Open-Source-Projekten mithilfe von git und networkx analysiert O security-ownership-map é uma ferramenta que constrói um grafo bipartido de pessoas e arquivos do histórico do Git para calcular o risco de propriedade e exportar artefatos de grafo para Neo4j/Gephi Security-ownership-map - это инструмент, который строит двудольный граф людей и файлов из истории Git для расчета риска владения и экспорта графических артефактов для Neo4j/Gephi security-ownership-map هو أداة تبني رسمًا بيانيًا ثنائيًا للأشخاص والملفات من تاريخ Git لحساب مخاطر الملكية وتصدير مكونات الرسم البياني لNeo4j/Gephi how to use security-ownership-map security-ownership-map alternative security-ownership-map install what is security-ownership-map security-ownership-map vs graphdb security-ownership-map setup guide security-ownership-map neo4j integration security-ownership-map gephi export Security Ownership Map AI 编程助手 安全风险评估 Python 3 networkx git 历史 双分图 文件共同更改图 Builds a bipartite graph of people and files from git history Computes ownership risk and exports graph artifacts for Neo4j/Gephi Constructs a file co-change graph using Jaccard similarity on shared commits Clusters files by how they move together, ignoring large, noisy commits Utilizes Python 3 and the networkx library for community detection Installs via pip with the command `pip install networkx` security-ownership-map is a skill that builds a bipartite graph of people and files from git history to compute ownership risk and export graph artifacts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cooper538/eshop-demo/finish-phase', 'community', 'cooper538', 'eshop-demo', 'cooper538/eshop-demo', 'finish-phase', 0, 0, 48, '2026-03-08T01:57:15.293Z', '2026-03-08T02:01:06.784Z', '887ea8829d5476d95d287285e497204650ef00735ef91ddb6a2ee197a02147a0', '{"id":"cooper538/eshop-demo/finish-phase","name":"finish-phase","description":{"en":"The finish-phase skill allows developers to manually complete a phase by updating its status and scope checklist. This is useful for reviewing or editing scope checklists before marking a phase as complete.","zh":"finish-phase 是用于完成阶段的命令，支持手动完成阶段和预览更改","ja":"finish-phase はステージを完了するためのコマンドで、手動でのステージ完了と変更のプレビューをサポートしています","ko":"finish-phase는 단계를 완료하는 명령으로 수동 완료와 변경 사항 미리보기를 지원합니다","es":"finish-phase es una herramienta de AI que permite completar fases manualmente en arquitecturas de microservicios .NET. Utiliza la línea de comandos para actualizar el estado y la lista de verificación del alcance.","fr":"finish-phase est un outil d''IA qui permet de terminer manuellement les phases dans les architectures de microservices .NET. Il utilise la ligne de commande pour mettre à jour l''état et la liste de vérification de la portée.","de":"finish-phase ist ein AI-Tool, das das manuelle Abschließen von Phasen in .NET-Mikrodienstarchitekturen ermöglicht. Es verwendet die Befehlszeile, um den Status und die Prüfliste des Umfangs zu aktualisieren.","pt":"O Finish-Phase é uma ferramenta para concluir fases manualmente em arquiteturas de microsserviços .NET. Ele permite atualizar o status e a lista de verificação de escopo.","ru":"Finish-Phase - это инструмент для ручного завершения фаз в архитектуре микросервисов .NET. Он позволяет обновлять статус и список контрольных пунктов.","ar":"Finish-Phase هو أداة لإكمال المراحل يدوياً في بنية ميكروسيرفيس .NET. يمكنه تحديث الحالة وقائمة التحقق من النطاق."},"seo":{"title":{"en":"finish-phase: Manual Phase Completion Setup Guide | AI Ag...","zh":"finish-phase Setup Guide: .NET 微服务架构示例","ja":"finish-phase の設定方法: .NET マイクロサービス アーキテクチャのデモ","ko":"finish-phase 설정 가이드: .NET 마이크로 서비스 아키텍처 데모","es":"Guía de Configuración de finish-phase para Arquitectura d...","fr":"Guide d''Installation de finish-phase pour l''Architecture ...","de":"Einrichtungsanleitung für finish-phase in .NET-Mikrodiens...","pt":"Guia de Configuração do Finish-Phase para Arquitetura de ...","ru":"Настройка Finish-Phase для архитектуры микросервисов .NET...","ar":"دليل إعداد Finish-Phase لعمارة ميكروسيرفيس .NET باستخدام ..."},"description":{"en":"Discover how to manually complete phases with finish-phase. Learn to update status and scope checklist with ease. Get started now!","zh":"了解 finish-phase 的用法和参数，优化 .NET 微服务架构的开发流程","ja":"finish-phase の使い方とパラメータを理解して、.NET マイクロサービス アーキテクチャの開発プロセスを最適化する","ko":"finish-phase의 사용법과 매개변수를 이해하여 .NET 마이크로 서비스 아키텍처 개발 프로세스를 최적화 하세요","es":"Descubre cómo utilizar finish-phase para completar fases manualmente en arquitecturas de microservicios .NET con este tutorial paso a paso","fr":"Découvrez comment utiliser finish-phase pour terminer manuellement les phases dans les architectures de microservices .NET avec ce didacticiel étape par étape","de":"Erfahren Sie, wie Sie finish-phase verwenden, um Phasen manuell in .NET-Mikrodienstarchitekturen abzuschließen, mit diesem Schritt-für-Schritt-Tutorial","pt":"Aprenda a usar o Finish-Phase para concluir fases manualmente e gerenciar checklist de escopo em sua arquitetura de microsserviços .NET","ru":"Изучите, как использовать Finish-Phase для ручного завершения фаз и управления списком контрольных пунктов в вашей архитектуре микросервисов .NET с помощью И...","ar":"تعلم كيفية استخدام Finish-Phase لإكمال المراحل يدوياً وإدارة قائمة التحقق من النطاق في بنية ميكروسيرفيس .NET باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"finish-phase is a command-line tool that enables manual completion of phases by updating their status and scope checklist","zh":"finish-phase 是一个用于完成阶段的 AI 工具命令","ja":"finish-phase はステージを完了するための AI エージェント コマンドです","ko":"finish-phase는 단계를 완료하는 AI 도구 명령어입니다","es":"finish-phase es una herramienta de AI que permite completar fases manualmente en arquitecturas de microservicios .NET","fr":"finish-phase est un outil d''IA qui permet de terminer manuellement les phases dans les architectures de microservices .NET","de":"finish-phase ist ein AI-Tool, das das manuelle Abschließen von Phasen in .NET-Mikrodienstarchitekturen ermöglicht","pt":"O Finish-Phase é uma ferramenta de microsserviços que permite concluir fases manualmente.","ru":"Finish-Phase - это инструмент микросервисов, который позволяет завершать фазы вручную.","ar":"Finish-Phase هو أداة ميكروسيرفيس التي تمكن من إكمال المراحل يدوياً."},"features":{"en":["Manually completes a phase by updating its status","Updates scope checklist for a specific phase","Supports dry-run mode to preview changes without applying","Accepts phase number as an argument (e.g., 03, 3)","Allows adding notes to the phase''s Notes section"],"zh":["手动完成阶段","预览更改","支持 .NET 微服务架构","使用 CLI 参数自定义操作","添加阶段的备注","手动更新阶段的范围检查清单"],"ja":["手動でのステージ完了","変更のプレビュー",".NET マイクロサービス アーキテクチャのサポート","CLI パラメータを使用した操作のカスタマイズ","ステージのノートの追加","ステージの範囲チェックリストの手動更新"],"ko":["수동 단계 완료","변경 사항 미리보기",".NET 마이크로 서비스 아키텍처 지원","CLI 매개변수를 사용한 사용자 정의","단계 노트 추가","단계 범위 확인 목록의 수동 업데이트"],"es":["Completa fases manualmente en arquitecturas de microservicios .NET","Actualiza el estado y la lista de verificación del alcance","Soporta la opción --dry-run para previsualizar cambios","Permite agregar notas a la sección de Notas de la fase","Utiliza la línea de comandos para interactuar con la herramienta"],"fr":["Termine les phases manuellement dans les architectures de microservices .NET","Met à jour l''état et la liste de vérification de la portée","Prend en charge l''option --dry-run pour prévisualiser les modifications","Permet d''ajouter des notes à la section de Notes de la phase","Utilise la ligne de commande pour interagir avec l''outil"],"de":["Schließt Phasen manuell in .NET-Mikrodienstarchitekturen ab","Aktualisiert den Status und die Prüfliste des Umfangs","Unterstützt die Option --dry-run, um Änderungen vorab zu überprüfen","Ermöglicht das Hinzufügen von Notizen zum Notizbereich der Phase","Verwendet die Befehlszeile, um mit dem Tool zu interagieren"],"pt":["Conclusão manual de fases","Atualização do status da fase","Gerenciamento da lista de verificação de escopo","Suporte à opção --dry-run para pré-visualizar alterações","Integração com arquitetura de microsserviços .NET"],"ru":["Ручное завершение фаз","Обновление статуса фазы","Управление списком контрольных пунктов","Поддержка опции --dry-run для предварительного просмотра изменений","Интеграция с архитектурой микросервисов .NET"],"ar":["إكمال المراحل يدوياً","تحديث حالة المرحلة","إدارة قائمة التحقق من النطاق","دعم خيار --dry-run لمعاينة التغييرات","التكامل مع بنية ميكروسيرفيس .NET"]},"keywords":{"en":["how to use finish-phase","finish-phase setup guide","finish-phase alternative","finish-phase vs auto-detection","manual phase completion","scope checklist management","finish-phase install","finish-phase command-line tool"],"zh":["finish-phase",".NET 微服务架构","AI 工具","CLI 命令","手动完成阶段","预览更改","阶段管理","范围检查清单","AIエージェント"],"ja":["finish-phase",".NET マイクロサービス アーキテクチャ","AI エージェント","CLI コマンド","手動でのステージ完了","変更のプレビュー","ステージ管理","範囲チェックリスト","AIツール"],"ko":["finish-phase",".NET 마이크로 서비스 아키텍처","AI 도구","CLI 명령","수동 단계 완료","변경 사항 미리보기","단계 관리","범위 확인 목록","AI 에이전트"],"es":["finish-phase","arquitectura de microservicios .NET","herramienta de AI","completar fases manualmente","actualizar estado y lista de verificación","línea de comandos","opción --dry-run","agregar notas a la sección de Notas"],"fr":["finish-phase","architecture de microservices .NET","outil d''IA","terminer les phases manuellement","mettre à jour l''état et la liste de vérification","ligne de commande","option --dry-run","ajouter des notes à la section de Notes"],"de":["finish-phase",".NET-Mikrodienstarchitektur","AI-Tool","Phasen manuell abschließen","Status und Prüfliste des Umfangs aktualisieren","Befehlszeile","Option --dry-run","Notizen zum Notizbereich der Phase hinzufügen"],"pt":["Finish-Phase","microsserviços .NET","conclusão de fases","gerenciamento de escopo","arquitetura de microsserviços","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Finish-Phase","микросервисы .NET","завершение фаз","управление списком контрольных пунктов","архитектура микросервисов","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["Finish-Phase","ميكروسيرفيس .NET","إكمال المراحل","إدارة قائمة التحقق من النطاق","بنية ميكروسيرفيس","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"cooper538","repo":"eshop-demo","repoPath":"cooper538/eshop-demo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.293Z","topics":[],"category":"community","skillMd":{"name":"finish-phase","description":"Manually complete a phase and update phase.md. Use when you want to manually review/edit phase completion, or when auto-detection didnt trigger.","bodyPreview":"# Finish Phase\n\nManually complete a phase by updating its status and scope checklist. Use this when:\n- You want to manually review/edit scope checklist before marking complete\n- Auto-detection in `/finish-task` didn''t trigger (e.g., already on main branch)\n- You want to add notes to the phase''s Notes section\n\n## Usage\n\n```\n/finish-phase 03              # Complete phase 03\n/finish-phase 03 --dry-run    # Preview changes without applying\n```\n\n## Arguments\n\n- `$1` - Phase number (e.g., `03`, `3`, `","body":"# Finish Phase\n\nManually complete a phase by updating its status and scope checklist. Use this when:\n- You want to manually review/edit scope checklist before marking complete\n- Auto-detection in `/finish-task` didn''t trigger (e.g., already on main branch)\n- You want to add notes to the phase''s Notes section\n\n## Usage\n\n```\n/finish-phase 03              # Complete phase 03\n/finish-phase 03 --dry-run    # Preview changes without applying\n```\n\n## Arguments\n\n- `$1` - Phase number (e.g., `03`, `3`, `phase-03`)\n- `--dry-run` - Preview changes without modifying files\n- `$ARGUMENTS` - Full arguments passed to the skill\n\n## Process\n\n### Step 1: Parse Arguments\n\nExtract phase number from arguments:\n- Phase number: `03`, `3`, or `phase-03` → normalize to `03`\n\n```bash\n# Extract phase number\nPHASE_NUM=$(echo \"$ARGUMENTS\" | grep -oE ''[0-9]+'' | head -1)\nPHASE_NUM=$(printf \"%02d\" \"$PHASE_NUM\")\n```\n\n### Step 2: Locate Phase Directory\n\nFind the phase specification file:\n\n```bash\nPHASE_DIR=$(find specification -maxdepth 1 -type d -name \"phase-${PHASE_NUM}-*\" | head -1)\n```\n\nIf not found, show available phases and exit.\n\n### Step 3: Check Task Status\n\nRead all tasks in the phase and check their status:\n\n```bash\nfor task_file in \"$PHASE_DIR/tasks/\"task-*.md; do\n    # Extract status from each task\ndone\n```\n\nReport:\n- Total tasks\n- Completed tasks\n- Pending/in-progress tasks (warn if any)\n\nIf there are incomplete tasks, ask user for confirmation:\n> \"Phase has X incomplete tasks. Are you sure you want to mark the phase as complete?\"\n\n### Step 4: Preview Changes\n\nShow what will be changed:\n\n1. **Phase Status** - Current → `✅ completed`\n2. **Scope Checklist** - Which items will be checked off based on task names\n\nDisplay preview:\n```\n📋 Phase XX Completion Preview\n\nStatus: ⚪ pending → ✅ completed\n\nScope checklist updates:\n- [x] SharedKernel package (matched: task-01 SharedKernel)\n- [x] Contracts package (matched: task-02 Contracts)\n- [ ] Some other item (no match found)\n\nTasks: 5/5 completed\n\nApply changes? (y/n)\n```\n\n### Step 5: Apply Changes\n\nIf user approves (or `--dry-run` not specified):\n\n1. Update phase.md status to `✅ completed`\n2. Check off matched scope items\n3. Optionally ask if user wants to add notes\n\n### Step 6: Commit Changes\n\n```bash\ngit add \"$PHASE_DIR/phase.md\"\ngit commit -m \"[${PHASE_NUM}-00] docs: mark phase as completed\" --no-verify\n```\n\n### Step 7: Final Report\n\n```\n✅ Phase XX marked as completed!\n\nUpdated:\n- Status: ✅ completed\n- Scope: X/Y items checked\n\nGit commit: [XX-00] docs: mark phase as completed\n\nNext steps:\n- /task-status - see remaining phases\n- /start-task XX - start next phase''s first task\n```\n\n## Manual Scope Editing\n\nIf scope matching isn''t accurate, inform user:\n> \"Some scope items couldn''t be automatically matched. You can manually edit the phase.md file to check them off.\"\n\nOffer to open the file:\n> \"Would you like me to show you the scope section for manual review?\"\n\n## Error Handling\n\n| Error | Message |\n|-------|---------|\n| Phase not found | \"Phase XX not found. Available: phase-01, phase-02...\" |\n| Already completed | \"Phase XX is already marked as completed.\" |\n| No tasks exist | \"Phase XX has no tasks. Create tasks first with /phase-breakdown XX\" |\n\n## Safety Rules\n\n1. NEVER mark phase complete if user declines after incomplete task warning\n2. ALWAYS show preview before making changes\n3. ALWAYS commit changes after modifying phase.md\n4. NEVER modify task files (only phase.md)\n\n## Example Session\n\n```\nUser: /finish-phase 01\n\nClaude: 📂 Found phase: specification/phase-01-foundation/phase.md\n\nChecking tasks...\n- task-01: ✅ completed\n- task-02: ✅ completed\n- task-03: ✅ completed\n- task-04: ✅ completed\n- task-05: ✅ completed\n\nAll 5 tasks completed!\n\n📋 Phase 01 Completion Preview\n\nStatus: ⚪ pending → ✅ completed\n\nScope checklist updates:\n- [x] SharedKernel package (matched: task-01)\n- [x] Contracts package (matched: task-02)\n- [x] EShop.Common (matched: task-05)\n\nApply changes? (y/n)\n\nUser: y\n\nClaude: ✅ Phase 01 marked as completed!\n\nCommitted: [01-00] docs: mark phase as completed\n\nNext steps:\n- /task-status - see remaining phases\n- /phase-breakdown 02 - prepare next phase\n```\n"},"lastSynced":"2026-03-08T02:01:06.784Z","agentAnalysis":{"suitability":{"en":"Ideal for Project Management Agents requiring precise phase completion and scope checklist editing capabilities.","zh":"适用于需要精确完成项目阶段和范围清单编辑功能的项目管理代理。","ja":"プロジェクト管理エージェントが正確なフェーズ完了とスコープチェックリストの編集機能を必要とする場合に適しています。","ko":"정확한 프로젝트 단계 완료 및 범위 체크 목록 편집 기능이 필요한 프로젝트 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Proyectos que requieren una finalización de fases precisa y capacidades de edición de listas de verificación de alcance.","fr":"Idéal pour les agents de gestion de projet nécessitant une completion de phase précise et des capacités d''édition de listes de vérification de portée.","de":"Ideal für Projektmanagement-Agents, die eine präzise Phasenabschluss und Bearbeitungsfunktionen für Umfangs-Checklisten erfordern.","pt":"Ideal para Agentes de Gerenciamento de Projetos que exigem conclusão precisa de fases e capacidades de edição de listas de verificação de escopo.","ru":"Идеально подходит для агентов по управлению проектами, требующих точного завершения фаз и возможностей редактирования контрольных списков объема.","ar":"مثالية للوكلاء لإدارة المشاريع الذين يطلبون إكمال مرحلة دقيق وسمات تحرير قائمة التحقق من نطاق."},"recommendation":{"en":"Empowers agents to manually complete phases by updating status and scope checklists, enabling review and editing before marking as complete, and utilizing commands like `/finish-phase` with options like `--dry-run` for previewing changes.","zh":"赋予代理手动完成阶段的能力，通过更新状态和范围清单，实现完成前审查和编辑，并利用命令如 `/finish-phase` 选项如 `--dry-run` 预览更改。","ja":"エージェントが手動でフェーズを完了できるようにし、ステータスとスコープチェックリストを更新して完了前に確認と編集を行い、コマンド `/finish-phase` とオプション `--dry-run` を使用して変更をプレビューします。","ko":"에이전트가 수동으로 단계를 완료할 수 있도록 하며, 상태 및 범위 체크 목록을 업데이트하여 완료 전 검토 및 편집을 수행하며, 명령 `/finish-phase`와 옵션 `--dry-run`을 사용하여 변경 사항을 미리 보입니다.","es":"Habilita a los agentes a completar manualmente las fases actualizando el estado y las listas de verificación de alcance, permitiendo la revisión y edición antes de marcar como completado, y utilizando comandos como `/finish-phase` con opciones como `--dry-run` para previsualizar los cambios.","fr":"Permet aux agents de compléter manuellement les phases en mettant à jour le statut et les listes de vérification de portée, permettant la révision et l''édition avant de les marquer comme complétées, et en utilisant des commandes comme `/finish-phase` avec des options comme `--dry-run` pour prévisualiser les modifications.","de":"Ermächtigt die Agenten, Phasen manuell abzuschließen, indem sie den Status und die Umfangs-Checklisten aktualisieren, sodass eine Überprüfung und Bearbeitung vor dem Markieren als abgeschlossen möglich ist, und indem Befehle wie `/finish-phase` mit Optionen wie `--dry-run` für die Vorschau von Änderungen verwendet werden.","pt":"Habilita os agentes a concluir manualmente as fases atualizando o status e as listas de verificação de escopo, permitindo revisar e editar antes de marcar como concluída, e utilizando comandos como `/finish-phase` com opções como `--dry-run` para visualizar as alterações.","ru":"Позволяет агентам вручную завершать фазы, обновляя статус и контрольные списки объема, что позволяет просматривать и редактировать перед отметкой как завершенной, и использовать команды типа `/finish-phase` с опциями типа `--dry-run` для предварительного просмотра изменений.","ar":"تمكن الوكلاء من إكمال المراحل يدويا عن طريق تحديث الحالة وقوائم التحقق من نطاق، مما يتيح للمراجعة والتعديل قبل إظهارها على أنها مكتملة، واستخدام أوامر مثل `/finish-phase` مع خيارات مثل `--dry-run` لمعاينة التغييرات."},"useCases":{"en":["Manually completing phases with custom scope checklists","Reviewing and editing phase scope checklists before completion","Adding notes to phase Notes sections for enhanced documentation"],"zh":["使用自定义范围清单手动完成阶段","完成前审查和编辑阶段范围清单","在阶段备注部分添加备注以增强文档"],"ja":["カスタムのスコープチェックリストを使用して手動でフェーズを完了する","完了前にフェーズのスコープチェックリストを確認して編集する","フェーズのノートセクションにノートを追加してドキュメントを強化する"],"ko":["사용자 정의 범위 체크 목록으로 수동으로 단계를 완료하는 것","완료 전 단계 범위 체크 목록을 검토 및 편집하는 것","단계 노트 섹션에 노트를 추가하여 문서를 강화하는 것"],"es":["Completar manualmente las fases con listas de verificación de alcance personalizadas","Revisar y editar las listas de verificación de alcance de las fases antes de completarlas","Agregar notas a las secciones de notas de las fases para una documentación mejorada"],"fr":["Compléter manuellement les phases avec des listes de vérification de portée personnalisées","Réviser et éditer les listes de vérification de portée des phases avant de les compléter","Ajouter des notes aux sections de notes des phases pour une documentation améliorée"],"de":["Manuell Phasen mit benutzerdefinierten Umfangs-Checklisten abschließen","Phasen-Umfangs-Checklisten vor dem Abschließen überprüfen und bearbeiten","Notizen in die Notizbereiche der Phasen hinzufügen, um die Dokumentation zu verbessern"],"pt":["Concluindo fases manualmente com listas de verificação de escopo personalizadas","Revisando e editando listas de verificação de escopo de fases antes da conclusão","Adicionando notas às seções de Notas de fases para documentação aprimorada"],"ru":["Ручное завершение фаз с настраиваемыми контрольными списками объема","Просмотр и редактирование контрольных списков объема фаз до завершения","Добавление заметок в разделы заметок фаз для расширенной документации"],"ar":["إكمال المراحل يدويا بقوائم التحقق من نطاق مخصصة","مراجعة وتحرير قوائم التحقق من نطاق المراحل قبل الإكمال","إضافة ملاحظات إلى أقسام الملاحظات للمراحل لتوثيق محسن"]},"limitations":{"en":["Requires manual invocation using the `/finish-phase` command","Dependent on correct phase numbering (e.g., `03`, `3`) for accurate identification"],"zh":["需要使用 `/finish-phase` 命令手动调用","依赖于正确的阶段编号（例如 `03`、`3`）以进行准确的标识"],"ja":["コマンド `/finish-phase` を使用して手動で呼び出す必要がある","正確な識別のために正しいフェーズ番号（例： `03`、`3`）に依存する"],"ko":["`/finish-phase` 명령을 사용하여 수동으로 호출해야 함","정확한 식별을 위해 올바른 단계 번호(예: `03`, `3`)에 의존함"],"es":["Requiere una invocación manual utilizando el comando `/finish-phase`","Depende de una numeración de fases correcta (p. ej., `03`, `3`) para una identificación precisa"],"fr":["Nécessite une invocation manuelle en utilisant la commande `/finish-phase`","Dépend d''une numérotation de phase correcte (par exemple, `03`, `3`) pour une identification précise"],"de":["Benötigt eine manuelle Aufruf mit dem Befehl `/finish-phase`","Hängt von einer korrekten Phasennumerierung (z. B. `03`, `3`) für eine genaue Identifizierung ab"],"pt":["Exige invocação manual usando o comando `/finish-phase`","Depende da numeração de fases correta (por exemplo, `03`, `3`) para identificação precisa"],"ru":["Требует ручного вызова с помощью команды `/finish-phase`","Зависит от правильной нумерации фаз (например, `03`, `3`) для точной идентификации"],"ar":["يتطلب استدعاء يدوي باستخدام الأمر `/finish-phase`","يعتمد على ترقيم مرحلة صحيح (على سبيل المثال `03`، `3`) لتحديد دقيق"]},"version":4},"contentHash":"887ea8829d5476d95d287285e497204650ef00735ef91ddb6a2ee197a02147a0","qualityScore":48}');
