INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cooper538/eshop-demo/finish-phase', 'finish-phase', 'cooper538', 'eshop-demo', 'community', 'finish-phase cooper538 eshop-demo community The finish-phase skill allows developers to manually complete a phase by updating its status and scope checklist. This is useful for reviewing or editing scope checklists before marking a phase as complete. finish-phase 是用于完成阶段的命令，支持手动完成阶段和预览更改 finish-phase はステージを完了するためのコマンドで、手動でのステージ完了と変更のプレビューをサポートしています finish-phase는 단계를 완료하는 명령으로 수동 완료와 변경 사항 미리보기를 지원합니다 finish-phase es una herramienta de AI que permite completar fases manualmente en arquitecturas de microservicios .NET. Utiliza la línea de comandos para actualizar el estado y la lista de verificación del alcance. finish-phase est un outil d''IA qui permet de terminer manuellement les phases dans les architectures de microservices .NET. Il utilise la ligne de commande pour mettre à jour l''état et la liste de vérification de la portée. finish-phase ist ein AI-Tool, das das manuelle Abschließen von Phasen in .NET-Mikrodienstarchitekturen ermöglicht. Es verwendet die Befehlszeile, um den Status und die Prüfliste des Umfangs zu aktualisieren. O Finish-Phase é uma ferramenta para concluir fases manualmente em arquiteturas de microsserviços .NET. Ele permite atualizar o status e a lista de verificação de escopo. Finish-Phase - это инструмент для ручного завершения фаз в архитектуре микросервисов .NET. Он позволяет обновлять статус и список контрольных пунктов. Finish-Phase هو أداة لإكمال المراحل يدوياً في بنية ميكروسيرفيس .NET. يمكنه تحديث الحالة وقائمة التحقق من النطاق. how to use finish-phase finish-phase setup guide finish-phase alternative finish-phase vs auto-detection manual phase completion scope checklist management finish-phase install finish-phase command-line tool finish-phase .NET 微服务架构 AI 工具 CLI 命令 手动完成阶段 预览更改 阶段管理 范围检查清单 AIエージェント Manually completes a phase by updating its status Updates scope checklist for a specific phase Supports dry-run mode to preview changes without applying Accepts phase number as an argument (e.g., 03, 3) Allows adding notes to the phase''s Notes section finish-phase is a command-line tool that enables manual completion of phases by updating their status and scope checklist');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Fergana-Labs/claude_agent_desktop/word', 'community', 'Fergana-Labs', 'claude_agent_desktop', 'Fergana-Labs/claude_agent_desktop', 'word', 0, 0, 48, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:09.259Z', '8b9d9ae1ce0c39adcb4038a640526af18c425f2bdaa409923fad60f5fd2ca33a', '{"id":"Fergana-Labs/claude_agent_desktop/word","name":"word","description":{"en":"The Word skill allows developers to work with Microsoft Word documents using Node.js tools, enabling them to read, create, and modify .docx files.","zh":"Word 文档工具允许您使用 Node.js 工具创建、读取和修改 Microsoft Word 文档。它提供了读取、创建、修改和提取文档结构和格式的功能。","ja":"Word ドキュメントツールは、Node.js ツールを使用して Microsoft Word ドキュメントを作成、読み取り、変更することを可能にします。ドキュメントの読み取り、作成、変更、構造と形式の抽出などの機能を提供します。","ko":"Word 문서 도구는 Node.js 도구를 사용하여 Microsoft Word 문서를 생성, 읽기 및 수정할 수 있습니다. 문서 읽기, 생성, 수정 및 구조 및 형식 추출 등의 기능을 제공합니다.","es":"El skill de Word es una herramienta para crear, leer y modificar documentos Word utilizando Node.js. Permite extraer texto, crear documentos nuevos y modificar estructuras existentes.","fr":"Le skill de Word est un outil pour créer, lire et modifier des documents Word en utilisant Node.js. Il permet d''extraire du texte, de créer de nouveaux documents et de modifier des structures existantes.","de":"Das Word-Skill ist ein Tool zum Erstellen, Lesen und Modifizieren von Word-Dokumenten mit Node.js. Es ermöglicht das Extrahieren von Text, das Erstellen neuer Dokumente und das Modifizieren bestehender Strukturen.","pt":"A ferramenta de documento Word é uma GUI wrapper construída em cima do Claude Agent SDK, permitindo criar, ler e modificar documentos do Microsoft Word com Node.js.","ru":"Инструмент документа Word - это GUI-оболочка, построенная на основе Claude Agent SDK, позволяющая создавать, читать и изменять документы Microsoft Word с помощью Node.js.","ar":"أداة وثائق الوورد هي غلاف واجهة المستخدم الرسومية مبني على SDK Agent Claude، مما يسمح بإنشاء و阅读 وتعديل مستندات مايكروسوفت وورد باستخدام Node.js."},"seo":{"title":{"en":"Word: GUI Wrapper for Claude Agent SDK | AI Agent Skill","zh":"Word 文档工具 Setup Guide - 基于 Claude Agent SDK 的 GUI 包装器","ja":"Word ドキュメントツールのベストプラクティス - Claude Agent SDK の GUI ラッパー","ko":"Word 문서 도구 설정 가이드 - Claude Agent SDK 기반 GUI 래퍼","es":"Guía de configuración de Word: Creación y manipulación de...","fr":"Guide de mise en place de Word : Création et manipulation...","de":"Word-Setup-Anleitung: Erstellung und Manipulation von Dok...","pt":"Guia de Configuração do Word: Ferramenta de Documento com...","ru":"Настройка ИИ Агента Word: Инструмент для работы с докумен...","ar":"دليل إعداد أداة الوورد: أداة وثائق مع أدوات Node.js"},"description":{"en":"Unlock Word document automation with our GUI wrapper, built on Claude Agent SDK. Learn how to read, create, and modify .docx files with Node.js tools today!","zh":"使用 Node.js 工具创建、读取和修改 Microsoft Word 文档。了解 Word 文档工具的功能和用例。","ja":"Node.js ツールを使用して Microsoft Word ドキュメントを作成、読み取り、変更します。Word ドキュメント ツールの機能と使用例について学習します。","ko":"Node.js 도구를 사용하여 Microsoft Word 문서를 생성, 읽기 및 수정합니다. Word 문서 도구의 기능 및 사용 사례에 대해 알아보세요.","es":"Descubre cómo crear, leer y modificar documentos Word con nuestra guía de configuración y mejores prácticas para desarrolladores","fr":"Découvrez comment créer, lire et modifier des documents Word avec notre guide de mise en place et les meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie Word-Dokumente erstellen, lesen und modifizieren können, mit unserer Setup-Anleitung und Best Practices für Entwickler","pt":"Aprenda a trabalhar com documentos do Microsoft Word usando a ferramenta de documento Word com Node.js e descubra como criar, ler e modificar documentos","ru":"Узнайте, как работать с документами Microsoft Word, используя инструмент документа Word с Node.js и узнайте, как создавать, читать и изменять документы","ar":"تعلم كيفية العمل مع مستندات مايكروسوفت وورد باستخدام أداة وثائق الوورد مع أدوات Node.js واكتشف كيفية إنشاء و阅读 وتعديل المستندات"},"definition":{"en":"Word is a GUI wrapper built on top of Claude Agent SDK, enabling automation of Microsoft Word documents","zh":"Word 文档工具是一种基于 Claude Agent SDK 的 GUI 包装器，用于创建、读取和修改 Microsoft Word 文档。","ja":"Word ドキュメントツールは、Claude Agent SDK の GUI ラッパーであり、Microsoft Word ドキュメントを作成、読み取り、変更するために使用されます。","ko":"Word 문서 도구는 Claude Agent SDK 기반의 GUI 래퍼로서 Microsoft Word 문서를 생성, 읽기 및 수정하는 데 사용됩니다.","es":"Un skill de Word es una herramienta de software que permite a los desarrolladores interactuar con documentos Word utilizando Node.js","fr":"Un skill de Word est un outil de logiciel qui permet aux développeurs d''interagir avec des documents Word en utilisant Node.js","de":"Ein Word-Skill ist ein Software-Tool, das es Entwicklern ermöglicht, mit Word-Dokumenten über Node.js zu interagieren","pt":"O que é a ferramenta de documento Word? É uma GUI wrapper que permite trabalhar com documentos do Microsoft Word usando Node.js.","ru":"Что такое инструмент документа Word? Это GUI-оболочка, позволяющая работать с документами Microsoft Word, используя Node.js.","ar":"ما هي أداة وثائق الوورد؟ هي غلاف واجهة المستخدم الرسومية التي تمكن من العمل مع مستندات مايكروسوفت وورد باستخدام Node.js."},"features":{"en":["Read existing Word documents and extract text content","Create new Word documents with formatted text, headings, and paragraphs","Modify existing documents by appending content","Extract document structure and formatting","Supports .docx file format"],"zh":["使用 Node.js 工具读取现有的 Word 文档和提取文本内容","创建新的 Word 文档，具有格式化的文本、标题、段落和表格","修改现有的文档，追加内容","提取文档结构和格式","基于 Claude Agent SDK 的 GUI 包装器"],"ja":["Node.js ツールを使用して既存の Word ドキュメントを読み取り、テキスト内容を抽出","新しい Word ドキュメントを作成、形式化されたテキスト、見出し、段落、表などを含む","既存のドキュメントを変更、内容を追加","ドキュメント構造と形式を抽出","Claude Agent SDK の GUI ラッパー"],"ko":["Node.js 도구를 사용하여 기존의 Word 문서를 읽고 텍스트 내용을 추출","새로운 Word 문서를 생성, 형식화된 텍스트, 제목, 단락, 표 등 포함","기존의 문서를 수정, 내용 추가","문서 구조 및 형식을 추출","Claude Agent SDK 기반의 GUI 래퍼"],"es":["Creación de documentos Word nuevos con texto formateado","Lectura de documentos Word existentes y extracción de texto","Modificación de documentos existentes mediante la adición de contenido","Extracción de la estructura y el formato de los documentos","Utilización de Node.js para la manipulación de documentos","Compatibilidad con Microsoft Word documents (.docx)"],"fr":["Création de nouveaux documents Word avec du texte formatté","Lecture de documents Word existants et extraction de texte","Modification de documents existants en ajoutant du contenu","Extraction de la structure et du format des documents","Utilisation de Node.js pour la manipulation de documents","Compatibilité avec les documents Microsoft Word (.docx)"],"de":["Erstellung neuer Word-Dokumente mit formatiertem Text","Lesen von bestehenden Word-Dokumenten und Extrahieren von Text","Modifizieren bestehender Dokumente durch Hinzufügen von Inhalt","Extrahieren der Struktur und des Formats der Dokumente","Verwendung von Node.js für die Manipulation von Dokumenten","Kompatibilität mit Microsoft Word-Dokumenten (.docx)"],"pt":["Leitura de documentos do Microsoft Word existentes","Criação de novos documentos do Microsoft Word com texto formatado","Modificação de documentos existentes","Extração da estrutura e formatação do documento"],"ru":["Чтение существующих документов Microsoft Word","Создание новых документов Microsoft Word с форматированным текстом","Изменение существующих документов","Извлечение структуры и форматирования документа"],"ar":["قراءة المستندات الحالية لمايكروسوفت وورد","إنشاء مستندات جديدة لمايكروسوفت وورد مع نص معالج","تعديل المستندات الحالية","استخراج هيكل وتنسيق المستند"]},"keywords":{"en":["how to use word with Node.js","what is word gui wrapper","word alternative to manual editing","word vs claude agent sdk","word install guide for developers","word setup for ai agents"],"zh":["Word 文档工具","Claude Agent SDK","GUI 包装器","Node.js 工具","Microsoft Word 文档","文档创建","文档读取","文档修改","AI 에이전트","AI 工具"],"ja":["Word ドキュメントツール","Claude Agent SDK","GUI ラッパー","Node.js ツール","Microsoft Word ドキュメント","ドキュメント作成","ドキュメント読み取り","ドキュメント変更","AI エージェント","AI ツール"],"ko":["Word 문서 도구","Claude Agent SDK","GUI 래퍼","Node.js 도구","Microsoft Word 문서","문서 생성","문서 읽기","문서 수정","AI 에이전트","AI 도구"],"es":["skill de Word","creación de documentos Word","lectura de documentos Word","modificación de documentos Word","Node.js para Word","herramientas de Word para desarrolladores","guía de configuración de Word","mejores prácticas para Word","documentos Word en Node.js"],"fr":["skill de Word","création de documents Word","lecture de documents Word","modification de documents Word","Node.js pour Word","outils de Word pour développeurs","guide de mise en place de Word","meilleures pratiques pour Word","documents Word en Node.js"],"de":["Word-Skill","Erstellung von Word-Dokumenten","Lesen von Word-Dokumenten","Modifizieren von Word-Dokumenten","Node.js für Word","Word-Tools für Entwickler","Word-Setup-Anleitung","Best Practices für Word","Word-Dokumente in Node.js"],"pt":["ferramenta de documento Word","Node.js","Microsoft Word","GUI wrapper","Claude Agent SDK","criar documento Word","ler documento Word","modificar documento Word"],"ru":["инструмент документа Word","Node.js","Microsoft Word","GUI-оболочка","Claude Agent SDK","создать документ Word","читать документ Word","изменить документ Word"],"ar":["أداة وثائق الوورد","Node.js","مايكروسوفت وورد","غلاف واجهة المستخدم الرسومية","SDK Agent Claude","إنشاء مستند وورد","قراءة مستند وورد","تعديل مستند وورد"]}},"owner":"Fergana-Labs","repo":"claude_agent_desktop","repoPath":"Fergana-Labs/claude_agent_desktop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"word","description":"Create, read, edit, and manipulate Microsoft Word documents (.docx files). Use when users ask to work with Word files, create documents, read .docx files, or format text documents.","bodyPreview":"# Word Document Tool\n\nThis skill allows you to work with Microsoft Word documents using Node.js tools.\n\n## Capabilities\n\n- **Read** existing Word documents and extract text content\n- **Create** new Word documents with formatted text, headings, paragraphs, and tables\n- **Modify** existing documents by appending content\n- **Extract** document structure and formatting\n\n## When to Use\n\nInvoke this skill when the user:\n- Mentions Word documents, .docx files, or document creation\n- Asks to read, creat","body":"# Word Document Tool\n\nThis skill allows you to work with Microsoft Word documents using Node.js tools.\n\n## Capabilities\n\n- **Read** existing Word documents and extract text content\n- **Create** new Word documents with formatted text, headings, paragraphs, and tables\n- **Modify** existing documents by appending content\n- **Extract** document structure and formatting\n\n## When to Use\n\nInvoke this skill when the user:\n- Mentions Word documents, .docx files, or document creation\n- Asks to read, create, modify, or format text documents\n- Needs to generate reports, letters, or formatted documents\n- Wants to extract text from existing Word files\n\n## How to Use\n\nThe Word tool is implemented as a TypeScript script at `src/tools/word-tool.ts`. You can invoke it using the Bash tool:\n\n### Reading a Document\n```bash\nts-node src/tools/word-tool.ts read \"/path/to/document.docx\"\n```\n\n### Creating a Document\n```bash\nts-node src/tools/word-tool.ts create \"/path/to/new-document.docx\" ''{\"title\":\"My Document\",\"paragraphs\":[\"First paragraph\",\"Second paragraph\"]}''\n```\n\n## JSON Structure for Creating Documents\n\nWhen creating documents, use this JSON format:\n```json\n{\n  \"title\": \"Document Title\",\n  \"paragraphs\": [\"Paragraph 1\", \"Paragraph 2\"],\n  \"headings\": [{\"text\": \"Section 1\", \"level\": 1}],\n  \"tables\": [{\"headers\": [\"Col1\", \"Col2\"], \"rows\": [[\"A\", \"B\"]]}]\n}\n```\n\n## Implementation\n\nUses the `docx` and `mammoth` npm libraries for reading and writing Word documents.\n"},"lastSynced":"2026-03-08T02:01:09.259Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Processing Agents needing to manipulate Microsoft Word documents using Node.js tools.","zh":"非常适合需要使用 Node.js 工具操作 Microsoft Word 文档的文档处理代理。","ja":"Node.js ツールを使用して Microsoft Word ドキュメントを操作する必要があるドキュメント処理エージェントに最適です。","ko":"Node.js 도구를 사용하여 Microsoft Word 문서를 조작해야 하는 문서 처리 에이전트에 적합합니다.","es":"Perfecto para agentes de procesamiento de documentos que necesitan manipular documentos de Microsoft Word utilizando herramientas de Node.js.","fr":"Parfait pour les agents de traitement de documents ayant besoin de manipuler des documents Microsoft Word à l''aide d''outils Node.js.","de":"Perfekt für Dokumentenverarbeitungsagenten, die Microsoft Word-Dokumente mit Node.js-Tools manipulieren müssen.","pt":"Perfeito para Agentes de Processamento de Documentos que precisam manipular documentos do Microsoft Word usando ferramentas Node.js.","ru":"Идеально подходит для агентов обработки документов, которым необходимо манипулировать документами Microsoft Word с помощью инструментов Node.js.","ar":"مثالي لوكلاء معالجة المستندات الذين يحتاجون إلى التعامل مع مستندات Microsoft Word باستخدام أدوات Node.js."},"recommendation":{"en":"Empowers agents to read, create, and modify .docx files, extracting text content, and appending new content with formatted text, headings, paragraphs, and tables using Node.js.","zh":"赋予代理读取、创建和修改 .docx 文件的能力，提取文本内容，并使用 Node.js 以格式化文本、标题、段落和表格追加新内容。","ja":"エージェントが .docx ファイルを読み取り、作成、変更できるようにし、テキスト内容を抽出し、Node.js を使用して整形されたテキスト、見出し、段落、テーブルで新しい内容を追加します。","ko":"에이전트가 .docx 파일을 읽고, 생성하고, 수정할 수 있도록 하며, 텍스트 내용을 추출하고, Node.js를 사용하여 서식된 텍스트, 제목, 단락 및 표에서 새 콘텐츠를 추가합니다.","es":"Habilita a los agentes a leer, crear y modificar archivos .docx, extrayendo contenido de texto y agregando nuevo contenido con texto formateado, encabezados, párrafos y tablas utilizando Node.js.","fr":"Permet aux agents de lire, de créer et de modifier des fichiers .docx, en extrayant le contenu texte et en ajoutant du nouveau contenu avec du texte formaté, des en-têtes, des paragraphes et des tableaux à l''aide de Node.js.","de":"Ermächtigt die Agenten, .docx-Dateien zu lesen, zu erstellen und zu bearbeiten, Textinhalt zu extrahieren und neuen Inhalt mit formatiertem Text, Überschriften, Absätzen und Tabellen mithilfe von Node.js hinzuzufügen.","pt":"Habilita os agentes a lerem, criarem e modificarem arquivos .docx, extrair o conteúdo de texto e anexar novo conteúdo com texto formatado, títulos, parágrafos e tabelas usando Node.js.","ru":"Наделяет агентов возможностью читать, создавать и изменять файлы .docx, извлекать текстовое содержимое и добавлять новый контент с форматированным текстом, заголовками, абзацами и таблицами с помощью Node.js.","ar":"يمنح الوكلاء القدرة على قراءة وإنشاء وتعديل ملفات .docx، واستخراج المحتوى النصي وإضافة محتوى جديد مع نص مصفوف، عناوين،فقرات و جداول باستخدام Node.js."},"useCases":{"en":["Automating document generation","Extracting data from existing Word documents","Modifying document structures and formatting"],"zh":["自动化文档生成","从现有 Word 文档中提取数据","修改文档结构和格式"],"ja":["ドキュメントの自動生成","既存の Word ドキュメントからデータを抽出","ドキュメント構造と書式の変更"],"ko":["문서 생성 자동화","기존 Word 문서에서 데이터 추출","문서 구조 및 서식 수정"],"es":["Automatización de la generación de documentos","Extracción de datos de documentos Word existentes","Modificación de estructuras y formatos de documentos"],"fr":["Automatisation de la génération de documents","Extraction de données de documents Word existants","Modification des structures et des formats de documents"],"de":["Automatisierung der Dokumentenerstellung","Extraktion von Daten aus vorhandenen Word-Dokumenten","Modifizierung von Dokumentenstrukturen und -formaten"],"pt":["Automação da geração de documentos","Extração de dados de documentos Word existentes","Modificação de estruturas e formatação de documentos"],"ru":["Автоматизация генерации документов","Извлечение данных из существующих документов Word","Модификация структур и форматирования документов"],"ar":["أتمتة إنشاء المستندات","استخراج البيانات من المستندات Word الحالية","تعديل هياكل المستندات وتشكيلها"]},"limitations":{"en":["Requires Node.js environment","Limited to .docx file format"],"zh":["需要 Node.js 环境","仅限 .docx 文件格式"],"ja":["Node.js 環境が必要",".docx ファイル形式のみ"],"ko":["Node.js 환경 필요",".docx 파일 형식만 해당"],"es":["Requiere entorno de Node.js","Limitado al formato de archivo .docx"],"fr":["Nécessite un environnement Node.js","Limité au format de fichier .docx"],"de":["Benötigt Node.js-Umgebung","Begrenzt auf .docx-Dateiformat"],"pt":["Requer ambiente Node.js","Limitado ao formato de arquivo .docx"],"ru":["Требуется окружение Node.js","Ограничен форматом файла .docx"],"ar":["يتطلب بيئة Node.js","محدود بتنسيق ملف .docx"]},"version":4},"contentHash":"8b9d9ae1ce0c39adcb4038a640526af18c425f2bdaa409923fad60f5fd2ca33a","qualityScore":48}');
