INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Fergana-Labs/claude_agent_desktop/word', 'word', 'Fergana-Labs', 'claude_agent_desktop', 'community', 'word Fergana-Labs claude_agent_desktop community The Word skill allows developers to work with Microsoft Word documents using Node.js tools, enabling them to read, create, and modify .docx files. Word 文档工具允许您使用 Node.js 工具创建、读取和修改 Microsoft Word 文档。它提供了读取、创建、修改和提取文档结构和格式的功能。 Word ドキュメントツールは、Node.js ツールを使用して Microsoft Word ドキュメントを作成、読み取り、変更することを可能にします。ドキュメントの読み取り、作成、変更、構造と形式の抽出などの機能を提供します。 Word 문서 도구는 Node.js 도구를 사용하여 Microsoft Word 문서를 생성, 읽기 및 수정할 수 있습니다. 문서 읽기, 생성, 수정 및 구조 및 형식 추출 등의 기능을 제공합니다. El skill de Word es una herramienta para crear, leer y modificar documentos Word utilizando Node.js. Permite extraer texto, crear documentos nuevos y modificar estructuras existentes. Le skill de Word est un outil pour créer, lire et modifier des documents Word en utilisant Node.js. Il permet d''extraire du texte, de créer de nouveaux documents et de modifier des structures existantes. Das Word-Skill ist ein Tool zum Erstellen, Lesen und Modifizieren von Word-Dokumenten mit Node.js. Es ermöglicht das Extrahieren von Text, das Erstellen neuer Dokumente und das Modifizieren bestehender Strukturen. A ferramenta de documento Word é uma GUI wrapper construída em cima do Claude Agent SDK, permitindo criar, ler e modificar documentos do Microsoft Word com Node.js. Инструмент документа Word - это GUI-оболочка, построенная на основе Claude Agent SDK, позволяющая создавать, читать и изменять документы Microsoft Word с помощью Node.js. أداة وثائق الوورد هي غلاف واجهة المستخدم الرسومية مبني على SDK Agent Claude، مما يسمح بإنشاء و阅读 وتعديل مستندات مايكروسوفت وورد باستخدام Node.js. how to use word with Node.js what is word gui wrapper word alternative to manual editing word vs claude agent sdk word install guide for developers word setup for ai agents Word 文档工具 Claude Agent SDK GUI 包装器 Node.js 工具 Microsoft Word 文档 文档创建 文档读取 文档修改 AI 에이전트 AI 工具 Read existing Word documents and extract text content Create new Word documents with formatted text, headings, and paragraphs Modify existing documents by appending content Extract document structure and formatting Supports .docx file format Word is a GUI wrapper built on top of Claude Agent SDK, enabling automation of Microsoft Word documents');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jasonmichaelbell78-creator/sonash-v0/task-next', 'community', 'jasonmichaelbell78-creator', 'sonash-v0', 'jasonmichaelbell78-creator/sonash-v0', 'task-next', 0, 0, 48, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:21.555Z', '0c5dcdde46283624f995ecde962cac8aadb412c92ac9450c0332f6d5ba27505b', '{"id":"jasonmichaelbell78-creator/sonash-v0/task-next","name":"task-next","description":{"en":"The task-next skill provides dependency-aware task selection, showing ready-to-work tasks based on resolution. It benefits developers by streamlining task management.","zh":"Task Next是依赖感知任务选择的AI工具，帮助开发者选择可执行的任务","ja":"Task Nextは依存関係解決によるタスク選択のAIエージェントです","ko":"Task Next는 의존성 인식 작업 선택을 구현하는 AI 도구입니다","es":"Task-next es una habilidad que muestra las tareas listas para trabajar en función de la resolución de dependencias","fr":"Task-next est une compétence qui affiche les tâches prêtes à être traitées en fonction de la résolution des dépendances","de":"Task-next ist eine Fähigkeit, die Aufgaben anzeigt, die bereit sind, basierend auf der Auflösung von Abhängigkeiten","pt":"O Task-Next é uma habilidade que mostra tarefas prontas com base na resolução de dependência. Ele pode ser invocado explicitamente com `/task-next`.","ru":"Task-Next - это навык, который показывает готовые задачи на основе разрешения зависимостей. Он может быть явно вызван с помощью `/task-next` для ИИ Агенты.","ar":"Task-Next هو مهارة يعرض المهام الجاهزة بالاعتماد على حل الاعتماد. يمكن استدعاؤها явно باستخدام `/task-next`"},"seo":{"title":{"en":"task-next: Dependency-Aware Task Selection Setup Guide | ...","zh":"Task Next_SETUP GUIDE：依赖感知任务选择","ja":"Task Nextベストプラクティス：依存関係解決によるタスク選択","ko":"Task Next 시작하기: 의존성 인식 작업 선택","es":"Guía de configuración de task-next para selección de tareas","fr":"Guide de démarrage de task-next pour la sélection de tâches","de":"Einrichtungsleitfaden für task-next zur Aufgabenverwaltung","pt":"Guia de Configuração do Task-Next: Seleção de Tarefas com...","ru":"Руководство по настройке Task-Next: Выбор задач с учетом ...","ar":"دليل إعداد Task-Next: اختيار المهام بالاعتماد على حل الاع..."},"description":{"en":"Unlock efficient task management with task-next! Learn how to invoke /task-next and resolve dependencies to boost your workflow. Get started now!","zh":"了解Task Next的使用方法和功能，实现依赖感知任务选择，AIエージェント","ja":"Task Nextの使い方と機能を紹介。依存関係解決によるタスク選択を実現するAIエージェント","ko":"Task Next의 사용법과 기능을 알아보세요. 의존성 인식 작업 선택을 구현하는 AI 도구","es":"Aprende a utilizar task-next para seleccionar tareas dependientes de manera efectiva y mejora tu productividad","fr":"Découvrez comment utiliser task-next pour sélectionner des tâches dépendantes de manière efficace et améliorer votre productivité","de":"Erfahren Sie, wie Sie task-next verwenden, um abhängige Aufgaben effektiv auszuwählen und Ihre Produktivität zu steigern","pt":"Aprenda a usar o Task-Next para mostrar tarefas prontas com base na resolução de dependência. Confira o guia de configuração e melhores práticas.","ru":"Узнайте, как использовать Task-Next для отображения готовых задач на основе разрешения зависимостей. Проверьте руководство по настройке и лучшие практики для...","ar":"تعلم كيفية استخدام Task-Next لعرض المهام الجاهزة بالاعتماد على حل الاعتماد. استعرض دليل الإعداد وأفضل الممارسات"},"definition":{"en":"task-next is a dependency-aware task selection skill that displays ready tasks based on dependency resolution, utilizing commands like /task-next and /task-next --all.","zh":"Task Next：一种依赖感知任务选择的AI工具","ja":"Task Next：依存関係解決によるタスク選択のAIエージェント","ko":"Task Next：의존성 인식 작업 선택을 구현하는 AI 도구","es":"Task-next es una herramienta de selección de tareas que utiliza la resolución de dependencias para determinar las tareas listas","fr":"Task-next est un outil de sélection de tâches qui utilise la résolution des dépendances pour déterminer les tâches prêtes","de":"Task-next ist ein Tool zur Aufgabenverwaltung, das die Auflösung von Abhängigkeiten verwendet, um die bereiten Aufgaben zu bestimmen","pt":"O Task-Next é uma ferramenta de seleção de tarefas que resolve dependências para mostrar tarefas prontas.","ru":"Task-Next - это инструмент выбора задач, который решает зависимости для отображения готовых задач для ИИ Агенты.","ar":"Task-Next هو أداة اختيار المهام التي تحل الاعتماد لتظهر المهام الجاهزة"},"features":{"en":["Shows ready (unblocked) tasks using /task-next command","Displays ready, blocked, and completed tasks with /task-next --all option","Supports explicit invocation of /task-next for customized task selection","Resolves dependencies to determine task readiness","Provides a scope-based approach to task management, checking related skills for specific tasks"],"zh":["依赖感知任务选择","显示可执行任务","支持命令行接口（CLI）","任务依赖关系解析","显示阻塞和完成任务"],"ja":["依存関係解決によるタスク選択","実行可能なタスクの表示","コマンドラインインターフェース（CLI）対応","タスク依存関係解析","ブロックと完了タスクの表示"],"ko":["의존성 인식 작업 선택","실행 가능한 작업 표시","커맨드 라인 인터페이스（CLI） 지원","작업 의존성 관계 분석","블록 및 완료 작업 표시"],"es":["Muestra tareas listas para trabajar en función de la resolución de dependencias","Permite al usuario invocar explícitamente la función /task-next","Ofrece la opción de mostrar todas las tareas, incluyendo las bloqueadas y completadas","Utiliza la línea de comandos (CLI) para interactuar con la función","Permite la selección de tareas dependientes de manera efectiva"],"fr":["Affiche les tâches prêtes à être traitées en fonction de la résolution des dépendances","Permet à l''utilisateur d''invoker explicitement la fonction /task-next","Offre l''option d''afficher toutes les tâches, y compris les tâches bloquées et terminées","Utilise la ligne de commande (CLI) pour interagir avec la fonction","Permet la sélection de tâches dépendantes de manière efficace"],"de":["Zeigt Aufgaben an, die bereit sind, basierend auf der Auflösung von Abhängigkeiten","Ermöglicht dem Benutzer, die Funktion /task-next explizit aufzurufen","Bietet die Option, alle Aufgaben anzuzeigen, einschließlich der blockierten und abgeschlossenen","Verwendet die Kommandozeile (CLI) zur Interaktion mit der Funktion","Ermöglicht die Auswahl von abhängigen Aufgaben auf effektive Weise"],"pt":["Mostra tarefas prontas com base na resolução de dependência","Pode ser invocado explicitamente com `/task-next`","Suporta opção `--all` para mostrar tarefas prontas, bloqueadas e concluídas","Permite aos usuários selecionar tarefas com base na resolução de dependência","Fornece uma solução para gerenciar tarefas complexas com dependências"],"ru":["Показывает готовые задачи на основе разрешения зависимостей","Может быть явно вызван с помощью `/task-next` для ИИ Агенты","Поддерживает опцию `--all` для отображения готовых, заблокированных и завершенных задач","Позволяет пользователям выбирать задачи на основе разрешения зависимостей","Предоставляет решение для управления сложными задачами с зависимостями для ИИ Агенты"],"ar":["يعرض المهام الجاهزة بالاعتماد على حل الاعتماد","يمكن استدعاؤها явно باستخدام `/task-next`","يدعم خيار `--all` لعرض المهام الجاهزة والمنعقة والمنتهية","يسمح للمستخدمين باختيار المهام بالاعتماد على حل الاعتماد","يقدم حلًا لإدارة المهام المعقدة بالاعتماد"]},"keywords":{"en":["how to use task-next","task-next alternative","task-next setup guide","what is task-next","task-next vs dependency management tools","task-next install","dependency-aware task selection","task-next skill for AI agents","task management with task-next"],"zh":["Task Next","AIエージェント","依赖感知任务选择","命令行接口","任务管理","依赖关系解析","AI工具"],"ja":["Task Next","AIエージェント","依存関係解決","タスク選択","コマンドラインインターフェース","タスク管理","依存関係解析"],"ko":["Task Next","AI 도구","의존성 인식 작업 선택","커맨드 라인 인터페이스","작업 관리","의존성 관계 분석","AI 에이전트"],"es":["task-next","selección de tareas","resolución de dependencias","herramientas de productividad","gestión de tareas","CLI","línea de comandos","Agente de Inteligencia Artificial","herramientas de Inteligencia Artificial"],"fr":["task-next","sélection de tâches","résolution des dépendances","outils de productivité","gestion de tâches","CLI","ligne de commande","Agent d''Intelligence Artificielle","outils d''Intelligence Artificielle"],"de":["task-next","Aufgabenverwaltung","Auflösung von Abhängigkeiten","Produktivitätstools","Aufgabenmanagement","CLI","Kommandozeile","Künstliche Intelligenz Agent","Künstliche Intelligenz Tools"],"pt":["task-next","seleção de tarefas","resolução de dependência","gerenciamento de tarefas","ferramentas de produtividade","desenvolvimento de software","CLI","tarefas prontas","tarefas bloqueadas"],"ru":["task-next","выбор задач","разрешение зависимостей","управление задачами","инструменты производительности","разработка программного обеспечения","CLI","готовые задачи","заблокированные задачи","ИИ Агенты"],"ar":["task-next","اختيار المهام","حل الاعتماد","إدارة المهام","أدوات الإنتاجية","تطوير البرمجيات","CLI","المهام الجاهزة","المهام المنعقة","أدوات الذكاء الاصطناعي"]}},"owner":"jasonmichaelbell78-creator","repo":"sonash-v0","repoPath":"jasonmichaelbell78-creator/sonash-v0","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"task-next","description":"Show dependency-resolved next tasks from ROADMAP.md active sprint","bodyPreview":"# Task Next - Dependency-Aware Task Selection\n\nShows which tasks are ready to work on based on dependency resolution.\n\n## When to Use\n\n- Tasks related to task-next\n- User explicitly invokes `/task-next`\n\n## When NOT to Use\n\n- When the task doesn''t match this skill''s scope -- check related skills\n- When a more specialized skill exists for the specific task\n\n## Usage\n\n```\n/task-next              # Show ready (unblocked) tasks\n/task-next --all        # Show ready, blocked, and completed\n/task-next","body":"# Task Next - Dependency-Aware Task Selection\n\nShows which tasks are ready to work on based on dependency resolution.\n\n## When to Use\n\n- Tasks related to task-next\n- User explicitly invokes `/task-next`\n\n## When NOT to Use\n\n- When the task doesn''t match this skill''s scope -- check related skills\n- When a more specialized skill exists for the specific task\n\n## Usage\n\n```\n/task-next              # Show ready (unblocked) tasks\n/task-next --all        # Show ready, blocked, and completed\n/task-next --blocked    # Show only blocked tasks\n```\n\n## How It Works\n\n1. Reads ROADMAP.md and finds all task items (`- [ ] **ID:** Description`)\n2. Parses `[depends: X1, X2]` annotations on each task\n3. Builds a directed acyclic graph (DAG) of dependencies\n4. Runs Kahn''s topological sort to determine execution order\n5. Reports which tasks are ready (all dependencies completed) vs blocked\n\n## Steps\n\n### 1. Run the dependency resolver\n\n```bash\nnode scripts/tasks/resolve-dependencies.js\n```\n\n### 2. Present results to the user\n\nFormat the output clearly:\n\n**Ready tasks** — these can be started now:\n\n- List each with its ID, description, and satisfied dependencies\n- Suggest the highest-priority one based on track ordering\n\n**Blocked tasks** — these are waiting on other tasks:\n\n- List each with what it''s waiting for\n- Highlight if a blocker is close to completion\n\n### 3. Help the user pick\n\nIf the user wants to work on a task:\n\n1. Confirm the task ID\n2. Mark it as the active task in TodoWrite\n3. Begin implementation\n\n### 4. After completing a task\n\nWhen a task is done:\n\n1. Check off the item in ROADMAP.md (`- [ ]` -> `- [x]`)\n2. Re-run the resolver to see what''s newly unblocked\n3. Tell the user what tasks are now available\n\n## Dependency Annotation Format\n\nAdd `[depends: X1, X2]` to any task item in ROADMAP.md:\n\n```markdown\n- [ ] **B3:** Lighthouse CI Integration [depends: B1, B2]\n- [ ] **B5:** Lighthouse Dashboard Tab [depends: B3, B4]\n```\n\nRules:\n\n- Dependencies reference task IDs (B1, B3, CANON-0011, DEBT-0944, etc.)\n- Multiple dependencies separated by commas\n- Annotation must be in square brackets at the end of the line\n- Tasks without `[depends:]` are considered independent (always ready)\n- Circular dependencies are detected and reported as errors\n\n---\n\n## Version History\n\n| Version | Date       | Description            |\n| ------- | ---------- | ---------------------- |\n| 1.0     | 2026-02-25 | Initial implementation |\n"},"lastSynced":"2026-03-08T02:01:21.555Z","agentAnalysis":{"suitability":{"en":"Ideal for Project Management Agents requiring dependency-aware task selection and streamlined workflow optimization.","zh":"适用于需要依赖感知任务选择和优化工作流的项目管理代理。","ja":"依存関係に応じたタスクの選択とワークフローの最適化が必要なプロジェクト管理エージェントに適している。","ko":"의존성 인식 태스크 선택 및 워크플로 최적화가 필요한 프로젝트 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Proyectos que requieren selección de tareas con conciencia de dependencias y optimización de flujo de trabajo simplificada.","fr":"Idéal pour les Agents de Gestion de Projet nécessitant une sélection de tâches tenant compte des dépendances et une optimisation de flux de travail simplifiée.","de":"Ideal für Projektmanagement-Agenten, die eine abhängigkeitsbewusste Aufgabenwahl und eine optimierte Arbeitsablauf-Optimierung erfordern.","pt":"Ideal para Agentes de Gerenciamento de Projetos que exigem seleção de tarefas cientes de dependências e otimização de fluxo de trabalho simplificada.","ru":"Идеально подходит для агентов управления проектами, требующих осведомленности о зависимостях при выборе задач и оптимизации рабочего процесса.","ar":"مثالي لوكلاء إدارة المشاريع الذين يتطلبون اختيار المهام المتأثر بالاعتماد وتحسين تدفق العمل المُيسر."},"recommendation":{"en":"Empowers agents to manage tasks efficiently by providing dependency resolution, showing ready-to-work tasks, and supporting commands like `/task-next` for easy workflow navigation, utilizing dependency-aware algorithms and command-line interfaces.","zh":"通过提供依赖解析、显示可工作任务并支持诸如 `/task-next` 的命令来使代理高效地管理任务，利用依赖感知算法和命令行接口实现轻松的工作流导航。","ja":"依存関係の解決を提供し、実行可能なタスクを表示し、`/task-next` などのコマンドをサポートすることで、エージェントがタスクを効率的に管理できるようにし、依存関係に応じたアルゴリズムとコマンドラインインターフェイスを利用してワークフローのナビゲーションを容易にする。","ko":"의존성 해석을 제공하고, 작업 가능한 태스크를 표시하며, `/task-next`와 같은 명령어를 지원하여 에이전트가 태스크를 효율적으로 관리할 수 있도록 하며, 의존성 인식 알고리즘과 명령줄 인터페이스를 사용하여 워크플로우 탐색을 쉽게 합니다.","es":"Permite a los agentes gestionar tareas de manera eficiente proporcionando resolución de dependencias, mostrando tareas listas para trabajar y soportando comandos como `/task-next` para una fácil navegación de flujo de trabajo, utilizando algoritmos y interfaces de línea de comandos con conciencia de dependencias.","fr":"Permet aux agents de gérer les tâches de manière efficace en fournissant une résolution de dépendances, en affichant les tâches prêtes à être travaillées et en supportant des commandes comme `/task-next` pour une navigation de flux de travail facile, en utilisant des algorithmes et des interfaces de ligne de commande tenant compte des dépendances.","de":"Ermächtigt Agenten, Aufgaben effizient zu verwalten, indem es Abhängigkeitsauflösung bereitstellt, bereite Aufgaben anzeigt und Befehle wie `/task-next` für eine einfache Arbeitsablaufnavigation unterstützt, unter Verwendung von abhängigkeitsbewussten Algorithmen und Kommandozeilen-Schnittstellen.","pt":"Habilita os agentes a gerenciar tarefas de forma eficiente, fornecendo resolução de dependência, mostrando tarefas prontas para trabalhar e suportando comandos como `/task-next` para navegação fácil no fluxo de trabalho, utilizando algoritmos cientes de dependência e interfaces de linha de comando.","ru":"Наделяет агентов возможностью эффективно управлять задачами, предоставляя разрешение зависимостей, показывая готовые к работе задачи и поддерживая команды, такие как `/task-next`, для простой навигации по рабочему процессу, используя алгоритмы, осведомленные о зависимостях, и командные интерфейсы.","ar":"تمكّن الوكلاء من إدارة المهام بفعالية من خلال توفير حل للاعتماد، وإظهار المهام الجاهزة للعمل، ودعم أوامر مثل `/task-next` لتسهيل التنقل في تدفق العمل، باستخدام الخوارزميات المتأثرة بالاعتماد وواجهات سطر الأوامر."},"useCases":{"en":["Streamlining task management workflows","Identifying ready-to-work tasks based on dependency resolution","Automating task prioritization with `/task-next` commands"],"zh":["优化任务管理工作流","根据依赖解析确定可工作任务","使用 `/task-next` 命令自动化任务优先级"],"ja":["タスク管理ワークフローの最適化","依存関係の解決に基づいて実行可能なタスクの特定","`/task-next` コマンドを使用したタスクの優先順位の自動化"],"ko":["태스크 관리 워크플로우 최적화","의존성 해석을 기반으로 작업 가능한 태스크 식별","`/task-next` 명령어를 사용한 태스크 우선순위 자동화"],"es":["Optimización de flujos de trabajo de gestión de tareas","Identificación de tareas listas para trabajar en función de la resolución de dependencias","Automatización de la priorización de tareas con comandos `/task-next`"],"fr":["Optimisation des flux de travail de gestion de tâches","Identification des tâches prêtes à être travaillées en fonction de la résolution de dépendances","Automatisation de la priorisation des tâches avec des commandes `/task-next`"],"de":["Optimierung von Arbeitsabläufen für Aufgabenverwaltung","Identifizierung von bereiten Aufgaben basierend auf Abhängigkeitsauflösung","Automatisierung der Priorisierung von Aufgaben mit `/task-next`-Befehlen"],"pt":["Otimização do fluxo de trabalho de gerenciamento de tarefas","Identificação de tarefas prontas para trabalhar com base na resolução de dependência","Automatização da priorização de tarefas com comandos `/task-next`"],"ru":["Оптимизация рабочего процесса управления задачами","Определение готовых к работе задач на основе разрешения зависимостей","Автоматизация приоритизации задач с помощью команд `/task-next`"],"ar":["تسهيل تدفق عمل إدارة المهام","تحديد المهام الجاهزة للعمل بناءً على حل للاعتماد","تأتمة تحديد الأولوية للمهام بأوامر `/task-next`"]},"limitations":{"en":["Requires explicit user invocation or specific task context","Limited to tasks with defined dependencies"],"zh":["需要显式用户调用或特定任务上下文","仅限于具有定义依赖关系的任务"],"ja":["明示的なユーザー呼び出しまたは特定のタスクコンテキストが必要","定義された依存関係を持つタスクに限定される"],"ko":["명시적인 사용자 호출 또는 특정 태스크 컨텍스트가 필요","정의된 의존성 관계를 갖는 태스크에만 제한"],"es":["Requiere invocación explícita del usuario o contexto de tarea específico","Limitado a tareas con dependencias definidas"],"fr":["Nécessite une invocation explicite de l''utilisateur ou un contexte de tâche spécifique","Limité aux tâches avec des dépendances définies"],"de":["Benötigt explizite Benutzeraufruf oder spezifischen Aufgabenkontext","Begrenzt auf Aufgaben mit definierten Abhängigkeiten"],"pt":["Exige invocação explícita do usuário ou contexto de tarefa específico","Limitado a tarefas com dependências definidas"],"ru":["Требует явного вызова пользователя или конкретного контекста задачи","Ограничен задачами с определенными зависимостями"],"ar":["يتطلب استدعاء صريح من المستخدم أو سياق مهمة محدد","محدود بالمهام التي لها اعتمادات محددة"]},"version":4},"contentHash":"0c5dcdde46283624f995ecde962cac8aadb412c92ac9450c0332f6d5ba27505b","qualityScore":48}');
