INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jasonmichaelbell78-creator/sonash-v0/task-next', 'task-next', 'jasonmichaelbell78-creator', 'sonash-v0', 'community', 'task-next jasonmichaelbell78-creator sonash-v0 community The task-next skill provides dependency-aware task selection, showing ready-to-work tasks based on resolution. It benefits developers by streamlining task management. Task Next是依赖感知任务选择的AI工具，帮助开发者选择可执行的任务 Task Nextは依存関係解決によるタスク選択のAIエージェントです Task Next는 의존성 인식 작업 선택을 구현하는 AI 도구입니다 Task-next es una habilidad que muestra las tareas listas para trabajar en función de la resolución de dependencias Task-next est une compétence qui affiche les tâches prêtes à être traitées en fonction de la résolution des dépendances Task-next ist eine Fähigkeit, die Aufgaben anzeigt, die bereit sind, basierend auf der Auflösung von Abhängigkeiten O Task-Next é uma habilidade que mostra tarefas prontas com base na resolução de dependência. Ele pode ser invocado explicitamente com `/task-next`. Task-Next - это навык, который показывает готовые задачи на основе разрешения зависимостей. Он может быть явно вызван с помощью `/task-next` для ИИ Агенты. Task-Next هو مهارة يعرض المهام الجاهزة بالاعتماد على حل الاعتماد. يمكن استدعاؤها явно باستخدام `/task-next` how to use task-next task-next alternative task-next setup guide what is task-next task-next vs dependency management tools task-next install dependency-aware task selection task-next skill for AI agents task management with task-next Task Next AIエージェント 依赖感知任务选择 命令行接口 任务管理 依赖关系解析 AI工具 Shows ready (unblocked) tasks using /task-next command Displays ready, blocked, and completed tasks with /task-next --all option Supports explicit invocation of /task-next for customized task selection Resolves dependencies to determine task readiness Provides a scope-based approach to task management, checking related skills for specific tasks task-next is a dependency-aware task selection skill that displays ready tasks based on dependency resolution, utilizing commands like /task-next and /task-next --all.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tkgally/je-dict-1/kanji-index', 'community', 'tkgally', 'je-dict-1', 'tkgally/je-dict-1', 'kanji-index', 0, 0, 48, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:22.336Z', 'acb8c46495f018bf2964a1f072ced2e851e7997860107c57f47cd84a3676c14d', '{"id":"tkgally/je-dict-1/kanji-index","name":"kanji-index","description":{"en":"The kanji-index skill is a Japanese-English learner''s dictionary that allows users to find all entries containing a specific kanji. It benefits language learners and educators by providing a comprehensive resource for kanji study","zh":"Kanji 索引工具允许用户点击任何头词汉字以找到包含相同汉字的所有其他条目","ja":"Kanji インデックス AIエージェントは、ユーザーが任意の頭詞漢字をクリックして同じ漢字を含むすべての他のエントリを探すことができる","ko":"Kanji 인덱스 도구는 사용자가任意の 헤드워드 한자를 클릭하여 동일한 한자를 포함하는 모든 다른 항목을 찾을 수 있게 함","es":"kanji-index es un índice de kanji para desarrolladores que permite a los usuarios encontrar entradas que contienen un kanji específico.","fr":"kanji-index est un index de kanji pour les développeurs qui permet aux utilisateurs de trouver des entrées contenant un kanji spécifique.","de":"kanji-index ist ein Kanji-Index für Entwickler, der es Benutzern ermöglicht, Einträge zu finden, die ein bestimmtes Kanji enthalten.","pt":"O índice de kanji é uma ferramenta de IA que permite aos usuários encontrar todas as entradas de dicionário que contêm um determinado kanji.","ru":"Индекс канзи - это инструмент ИИ Агентов, который позволяет пользователям найти все словарные статьи, содержащие определенный канзи.","ar":"فهرس الكانجي هو أداة ذكاء اصطناعي تمكن المستخدمين من العثور على جميع مدخلات القاموس التي تحتوي على كانجي معين."},"seo":{"title":{"en":"kanji-index: Japanese-English Dictionary Setup Guide | AI...","zh":"Kanji 索引工具 Setup Guide","ja":"Kanji インデックス AIエージェントの設定","ko":"Kanji 인덱스 도구 개발 가이드","es":"Guía de configuración de kanji-index para desarrolladores","fr":"Guide d''installation de kanji-index pour les développeurs","de":"Einrichtungsleitfaden für kanji-index-Entwickler","pt":"Guia de Configuração do Índice de Kanji para Ferramentas ...","ru":"Настройка ИИ Агентов: Руководство по Индексу Канзи","ar":"دليل إعداد فهرس الكانجي لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the power of kanji-index, a comprehensive Japanese-English learner''s dictionary. Discover how to navigate and utilize its features for enhanced langua...","zh":"了解 Kanji 索引工具的工作原理，包括头词汉字链接和汉字索引页面","ja":"Kanji インデックス AIエージェントの仕組みを学ぶ - 頭詞漢字のリンクと漢字索引ページ","ko":"Kanji 인덱스 도구의 작동 원리 및 기능을 확인해보세요 - 헤드워드 한자 연결 및 한자 인덱스 페이지","es":"Aprende a implementar kanji-index en tus proyectos de desarrollo con nuestra guía paso a paso","fr":"Découvrez comment intégrer kanji-index dans vos projets de développement avec notre guide étape par étape","de":"Erfahren Sie, wie Sie kanji-index in Ihre Entwicklungsprojekte integrieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o índice de kanji para melhorar a pesquisa de dicionários de japonês-inglês com ferramentas de IA","ru":"Узнайте, как настроить индекс канзи для улучшения поиска в японско-английских словарях с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد فهرس الكانجي لتحسين البحث في القواميس اليابانية-الإنجليزية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"kanji-index is a technical dictionary solution that enables users to click on any kanji in a dictionary headword to find all other entries containing that same kanji","zh":"Kanji 索引工具是一种在-progress的日英辞典","ja":"Kanji インデックス AIエージェントは、一つの進行中の日本語-英語学習者辞典","ko":"Kanji 인덱스 도구는 진행중인 일본어-영어 학습자 사전","es":"¿Qué es kanji-index? Un índice de kanji que vincula headwords a páginas de índice de kanji","fr":"Qu''est-ce que kanji-index ? Un index de kanji qui relie les headwords à des pages d''index de kanji","de":"Was ist kanji-index? Ein Kanji-Index, der Headwords mit Kanji-Indexseiten verknüpft","pt":"O que é índice de kanji? É uma ferramenta de IA que vincula kanjis a suas respectivas listas de entradas de dicionário.","ru":"Что такое индекс канзи? Это инструмент ИИ Агентов, который связывает канзи с их соответствующими списками словарных статей.","ar":"ما هو فهرس الكانجي? هو أداة ذكاء اصطناعي يربط الكانجي بقوائم مدخلات القاموس الخاصة بهم."},"features":{"en":["Links headword kanji to kanji index pages","Lists all entries containing a specific kanji, sorted by reading (hiragana order)","Utilizes a master list in JSON format (kanji_list.json) for kanji mapping","Employs a temporary extraction file (kanji_extracted.json) for data processing","Supports directory structure organization for efficient data management"],"zh":["头词汉字链接到汉字索引页面","汉字索引页面列出所有包含该汉字的条目","条目列表按读音（ひらがな顺序）排序","使用 JSON 文件存储汉字列表和索引数据","支持多语言开发"],"ja":["頭詞漢字のリンクから漢字索引ページにアクセス","漢字索引ページに同じ漢字を含むすべてのエントリをリスト","エントリーリストを読み（ひらがな順）でソート","JSON ファイルを使用して漢字リストとインデックスデータを保存","多言語開発に対応"],"ko":["헤드워드 한자 연결을 통해 한자 인덱스 페이지에 액세스","한자 인덱스 페이지에 동일한 한자를 포함하는 모든 항목을 나열","항목 목록을 읽기 (히라가나 순)로 정렬","JSON 파일을 사용하여 한자 목록 및 인덱스 데이터 저장","다중 언어 개발 지원"],"es":["Vínculos de headword kanji a páginas de índice de kanji","Listas de entradas ordenadas por lectura (orden hiragana)","Estructura de directorio con kanji_list.json y kanji_extracted.json","Integración con herramientas de desarrollo para un acceso más rápido","Soporte para múltiples plataformas de desarrollo"],"fr":["Liens de headword kanji vers des pages d''index de kanji","Listes d''entrées triées par lecture (ordre hiragana)","Structure de répertoire avec kanji_list.json et kanji_extracted.json","Intégration avec des outils de développement pour un accès plus rapide","Prise en charge de plusieurs plateformes de développement"],"de":["Verknüpfung von Headword-Kanji mit Kanji-Indexseiten","Eintragslisten sortiert nach Lesung (Hiragana-Reihenfolge)","Verzeichnisstruktur mit kanji_list.json und kanji_extracted.json","Integration mit Entwicklungstools für schnelleren Zugriff","Unterstützung für mehrere Entwicklungsumgebungen"],"pt":["Vinculação de kanjis a listas de entradas de dicionário","Listas de entradas ordenadas por leitura (ordem hiragana)","Estrutura de diretório personalizada com arquivos JSON","Suporte a pesquisas de kanjis em dicionários de japonês-inglês"],"ru":["Связывание канзи с списками словарных статей","Списки статей, упорядоченные по чтению (порядок хираганы)","Настроенная структура директории с файлами JSON","Поддержка поиска канзи в японско-английских словарях"],"ar":["ربط الكانجي bằngقوائم مدخلات القاموس","قوائم المدخلات المرتبة حسب القراءة (ترتيب هيراغانا)","هيكل دليل مخصص مع ملفات JSON","دعم البحث عن الكانجي في قواميس اليابانية-الإنجليزية"]},"keywords":{"en":["how to use kanji-index","kanji-index alternative","kanji-index setup guide","what is kanji-index","kanji-index vs other dictionaries","kanji-index install","japanese english dictionary","kanji study resources","language learning tools"],"zh":["Kanji 索引工具","日英辞典","汉字索引页面","头词汉字链接","JSON 文件存储","多语言开发","Kanji 学习","AIエージェント"],"ja":["Kanji インデックス AIエージェント","日本語-英語学習者辞典","漢字索引ページ","頭詞漢字のリンク","JSON ファイル保存","多言語開発","Kanji 学習","AIツール"],"ko":["Kanji 인덱스 도구","일본어-영어 학습자 사전","한자 인덱스 페이지","헤드워드 한자 연결","JSON 파일 저장","다중 언어 개발","Kanji 학습","AI 도구"],"es":["kanji-index","índice de kanji","desarrollo de software","herramientas de desarrollo","integración de kanji","headword kanji","páginas de índice de kanji","estructura de directorio","kanji_list.json","kanji_extracted.json"],"fr":["kanji-index","index de kanji","développement de logiciels","outils de développement","intégration de kanji","headword kanji","pages d''index de kanji","structure de répertoire","kanji_list.json","kanji_extracted.json"],"de":["kanji-index","Kanji-Index","Software-Entwicklung","Entwicklungstools","Kanji-Integration","Headword-Kanji","Kanji-Indexseiten","Verzeichnisstruktur","kanji_list.json","kanji_extracted.json"],"pt":["índice de kanji","ferramentas de IA","dicionários de japonês-inglês","kanji","leitura hiragana","estrutura de diretório","arquivos JSON","pesquisa de kanjis"],"ru":["индекс канзи","ИИ Агенты","японско-английские словари","канзи","чтение хираганы","структура директории","файлы JSON","поиск канзи"],"ar":["فهرس الكانجي","أدوات الذكاء الاصطناعي","قواميس اليابانية-الإنجليزية","الكانجي","قراءة هيراغانا","هيكل الدليل","ملفات JSON","بحث الكانجي"]}},"owner":"tkgally","repo":"je-dict-1","repoPath":"tkgally/je-dict-1","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"kanji-index","description":"Guidelines for maintaining the kanji index feature. Covers kanji ID assignment, index updates, and troubleshooting.","bodyPreview":"# Kanji Index Maintenance\n\nThe kanji index allows users to click on any kanji in a dictionary headword to find all other entries containing that same kanji.\n\n## How It Works\n\n1. **Headword kanji** are linked to kanji index pages\n2. **Kanji index pages** list all entries containing that kanji\n3. **Entry lists** are sorted by reading (hiragana order)\n\n## Directory Structure\n\n```\nkanji/\n├── kanji_list.json       # Master list: kanji → kanji_id mapping\n├── kanji_extracted.json  # Temporary: extracte","body":"# Kanji Index Maintenance\n\nThe kanji index allows users to click on any kanji in a dictionary headword to find all other entries containing that same kanji.\n\n## How It Works\n\n1. **Headword kanji** are linked to kanji index pages\n2. **Kanji index pages** list all entries containing that kanji\n3. **Entry lists** are sorted by reading (hiragana order)\n\n## Directory Structure\n\n```\nkanji/\n├── kanji_list.json       # Master list: kanji → kanji_id mapping\n├── kanji_extracted.json  # Temporary: extracted kanji needing IDs\n├── 00001_jin_hito_person.json  # Entry list for 人\n├── 00002_nichi_hi_day.json     # Entry list for 日\n└── ...\n\ndocs/kanji/\n├── 00001_jin_hito_person.html  # HTML page for 人\n├── 00002_nichi_hi_day.html     # HTML page for 日\n└── ...\n```\n\n## Kanji ID Format\n\nFormat: `{5-digit}_{onyomi}_{kunyomi}_{gloss}`\n\n- **5-digit**: Sequential number (00001, 00002, ...)\n- **onyomi**: Most common on''yomi in romaji (or \"none\")\n- **kunyomi**: Most common kun''yomi in romaji without okurigana (or \"none\")\n- **gloss**: Single English word for primary meaning\n\n### Examples\n\n| Kanji | Kanji ID |\n|-------|----------|\n| 人 | 00001_jin_hito_person |\n| 日 | 00002_nichi_hi_day |\n| 大 | 00003_dai_oo_big |\n| 畑 | 00004_none_hatake_field |\n| 茶 | 00005_cha_none_tea |\n\n### Romaji Rules\n\n- Long vowels: \"ou\" not \"ō\" (e.g., 高 → \"kou\")\n- Voiced: \"ga\", \"za\", \"da\", \"ba\" (e.g., 学 → \"gaku\")\n- No okurigana in kun''yomi (e.g., 高い → \"taka\", not \"takai\")\n\n## Assigning New Kanji IDs\n\nWhen new entries introduce kanji not in `kanji_list.json`:\n\n1. **Detect new kanji**:\n   ```bash\n   python3 build/update_kanji_index.py --check-new\n   ```\n\n2. **Assign readings and gloss** using your knowledge:\n   - Most common on''yomi\n   - Most common kun''yomi (without okurigana)\n   - Single-word English gloss\n\n3. **Update kanji_list.json**:\n   ```json\n   {\n     \"新\": {\n       \"kanji_id\": \"00123_shin_atara_new\",\n       \"onyomi\": \"shin\",\n       \"kunyomi\": \"atara\",\n       \"gloss\": \"new\"\n     }\n   }\n   ```\n\n4. **Rebuild**:\n   ```bash\n   python3 build/build_flat.py\n   ```\n\n## Common Tasks\n\n### Check for New Kanji\n```bash\npython3 build/update_kanji_index.py --check-new\n```\n\n### Rebuild All Kanji JSON Files\n```bash\npython3 build/update_kanji_index.py --rebuild-all\n```\n\n### Rebuild Kanji HTML Pages\n```bash\npython3 build/build_kanji_html.py\n```\n\n### Full Site Build (includes kanji)\n```bash\npython3 build/build_flat.py\n```\n\n## Troubleshooting\n\n### \"Warning: X kanji need IDs assigned\"\n\nNew kanji were found in entries. Assign IDs manually:\n1. Run `--check-new` to see the full list\n2. For each kanji, determine on''yomi, kun''yomi, gloss\n3. Add to `kanji/kanji_list.json`\n4. Rebuild\n\n### Missing kanji index page\n\nCheck that:\n1. Kanji is in `kanji/kanji_list.json`\n2. JSON file exists: `kanji/{kanji_id}.json`\n3. Run `python3 build/build_kanji_html.py`\n\n### Kanji link not appearing in headword\n\nCheck that:\n1. Kanji is in `kanji/kanji_list.json`\n2. Entry HTML was rebuilt after kanji was added\n\n### Entry count wrong on kanji page\n\nRebuild the kanji JSON file:\n```bash\npython3 build/update_kanji_index.py --rebuild-all\npython3 build/build_kanji_html.py\n```\n\n## File Formats\n\n### kanji_list.json\n```json\n{\n  \"metadata\": {\n    \"description\": \"Index mapping kanji characters to their kanji index IDs\",\n    \"generated\": \"2026-01-22T10:30:00Z\",\n    \"total_kanji\": 1500\n  },\n  \"kanji\": {\n    \"人\": {\n      \"kanji_id\": \"00001_jin_hito_person\",\n      \"onyomi\": \"jin\",\n      \"kunyomi\": \"hito\",\n      \"gloss\": \"person\"\n    }\n  }\n}\n```\n\n### Individual kanji JSON\n```json\n{\n  \"metadata\": {\n    \"kanji\": \"人\",\n    \"kanji_id\": \"00001_jin_hito_person\",\n    \"onyomi\": \"jin\",\n    \"kunyomi\": \"hito\",\n    \"gloss\": \"person\",\n    \"entry_count\": 245,\n    \"generated\": \"2026-01-22T10:30:00Z\"\n  },\n  \"entries\": [\n    {\n      \"id\": \"01234_akunin\",\n      \"headword\": \"{悪|あく}{人|にん}\",\n      \"reading\": \"あくにん\",\n      \"gloss\": \"villain, bad person\"\n    }\n  ]\n}\n```\n\n## Design Decisions\n\n### Why invisible links?\n- Preserves clean headword appearance\n- Users discover feature through tooltip\n- No visual clutter\n\n### Why romaji in kanji IDs?\n- ASCII-safe file names\n- Human-readable\n- Easy to search and sort\n\n### Why sort by reading?\n- Natural Japanese ordering (gojuon)\n- Consistent with how dictionaries organize entries\n- Helps users find related words\n"},"lastSynced":"2026-03-08T02:01:22.336Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Learning Agents needing advanced Japanese kanji analysis capabilities.","zh":"非常适合需要高级日语汉字分析功能的语言学习代理。","ja":"高度な日本語漢字分析機能が必要な言語学習エージェントに最適です。","ko":"고급 일본어 한자 분석 기능이 필요한 언어 학습 에이전트에게 적합합니다.","es":"Perfecto para agentes de aprendizaje de idiomas que necesitan capacidades de análisis de kanji japonés avanzadas.","fr":"Parfait pour les agents d''apprentissage des langues nécessitant des capacités d''analyse de kanji japonais avancées.","de":"Perfekt für Sprachlernagenten, die erweiterte Fähigkeiten zur Analyse von japanischen Kanji benötigen.","pt":"Perfeito para Agentes de Aprendizado de Linguagem que precisam de capacidades avançadas de análise de kanji japonês.","ru":"Идеально подходит для агентов по обучению языкам, требующих расширенных возможностей анализа японских иероглифов канзи.","ar":"مثالي لعميل تعلم اللغة الذي يحتاج إلى قدرات تحليل متقدمة للكانجي الياباني."},"recommendation":{"en":"Empowers agents to generate comprehensive kanji study resources using JSON data formats, providing linked headword kanji and sorted entry lists by reading in hiragana order.","zh":"使代理能够使用JSON数据格式生成全面汉字学习资源，提供链接的头词汉字和按平假名顺序排序的条目列表。","ja":"エージェントがJSONデータ形式を使用して包括的な漢字学習リソースを生成できるようにし、ヘッドワードの漢字をリンクし、ひらがな順でソートされたエントリーリストを提供します。","ko":"에이전트가 JSON 데이터 형식을 사용하여 포괄적인 한자 학습 리소스를 생성할 수 있도록 하며, 헤드워드 한자를 링크하고, 히라가나 순으로 정렬된 항목 목록을 제공합니다.","es":"Permite a los agentes generar recursos de estudio de kanji completos utilizando formatos de datos JSON, proporcionando kanji de cabeza de palabra enlazados y listas de entradas ordenadas por lectura en orden hiragana.","fr":"Permet aux agents de générer des ressources d''étude de kanji complètes en utilisant des formats de données JSON, en fournissant des kanji de tête de mot liés et des listes d''entrées triées par lecture dans l''ordre hiragana.","de":"Ermöglicht es Agenten, umfassende Kanji-Studienressourcen unter Verwendung von JSON-Datiformaten zu generieren, indem es verknüpfte Kopfwort-Kanji und sortierte Eintragslisten in Hiragana-Leseordnung bereitstellt.","pt":"Habilita os agentes a gerar recursos de estudo de kanji abrangentes usando formatos de dados JSON, fornecendo kanji de headword vinculado e listas de entradas classificadas por ordem de leitura em hiragana.","ru":"Наделяет агентов возможностью создавать комплексные ресурсы для изучения канзи, используя форматы данных JSON, обеспечивая связь иероглифов headword и отсортированные списки записей в порядке чтения хираганы.","ar":"تمكّن العميل من توليد موارد شاملة لدراسة الكانجي باستخدام تنسيقات بيانات JSON، مع توفير الكانجي المرتبط برأس الكلمة وقوائم الدخول المصنفة حسب ترتيب القراءة بالهيراغانا."},"useCases":{"en":["Automating kanji index maintenance","Generating sorted entry lists for language learners","Linking headword kanji to index pages for efficient study"],"zh":["自动维护汉字索引","为语言学习者生成排序后的条目列表","将头词汉字链接到索引页面以便于学习"],"ja":["漢字索引の自動メンテナンス","言語学習者向けのソートされたエントリーリストの生成","ヘッドワード漢字を索引ページにリンクして効率的な学習を可能に"],"ko":["한자 색인 자동 유지 보수","언어 학습자를 위한 정렬된 항목 목록 생성","헤드워드 한자를 색인 페이지에 연결하여 효율적인 학습을 가능하게"],"es":["Automatizar el mantenimiento del índice de kanji","Generar listas de entradas ordenadas para aprendices de idiomas","Enlazar kanji de cabeza de palabra a páginas de índice para un estudio eficiente"],"fr":["Automatiser la maintenance de l''index des kanji","Générer des listes d''entrées triées pour les apprenants de langues","Lier les kanji de tête de mot aux pages d''index pour une étude efficace"],"de":["Automatisieren der Wartung des Kanji-Index","Generieren sortierter Eintragslisten für Sprachlerner","Verknüpfen von Kopfwort-Kanji mit Indexseiten für effizientes Studieren"],"pt":["Automatizar a manutenção do índice de kanji","Gerar listas de entradas classificadas para aprendizes de línguas","Vincular kanji de headword a páginas de índice para estudo eficiente"],"ru":["Автоматизация обслуживания индекса канзи","Генерация отсортированных списков записей для изучающих языки","Связывание иероглифов headword с страницами индекса для эффективного изучения"],"ar":["آلية صيانة فهارس الكانجي"," توليد قوائم الدخول المصنفة للطلاب اللغويين"," ربط الكانجي برأس الكلمة بصفحات الفهارس لدراسة فعالة"]},"limitations":{"en":["Requires kanji_list.json and kanji_extracted.json files","Limited to Japanese-English language pairs"],"zh":["需要kanji_list.json和kanji_extracted.json文件","仅限于日英语言对"],"ja":["kanji_list.jsonとkanji_extracted.jsonファイルが必要","日本語-英語の言語ペアに限定"],"ko":["kanji_list.json 및 kanji_extracted.json 파일이 필요","일본어-영어 언어 쌍으로 제한"],"es":["Requiere archivos kanji_list.json y kanji_extracted.json","Limitado a pares de lenguas japonés-inglés"],"fr":["Nécessite des fichiers kanji_list.json et kanji_extracted.json","Limité aux paires de langues japonais-anglais"],"de":["Benötigt Dateien kanji_list.json und kanji_extracted.json","Begrenzt auf japanisch-englische Sprachpaare"],"pt":["Requer arquivos kanji_list.json e kanji_extracted.json","Limitado a pares de línguas japonês-inglês"],"ru":["Требует наличия файлов kanji_list.json и kanji_extracted.json","Ограничен парой языков японский-английский"],"ar":["يتطلب ملفات kanji_list.json و kanji_extracted.json","محدود بالأزواج اللغوية اليابانية-الإنجليزية"]},"version":4},"contentHash":"acb8c46495f018bf2964a1f072ced2e851e7997860107c57f47cd84a3676c14d","qualityScore":48}');
