INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tkgally/je-dict-1/kanji-index', 'kanji-index', 'tkgally', 'je-dict-1', 'community', 'kanji-index tkgally je-dict-1 community The kanji-index skill is a Japanese-English learner''s dictionary that allows users to find all entries containing a specific kanji. It benefits language learners and educators by providing a comprehensive resource for kanji study Kanji 索引工具允许用户点击任何头词汉字以找到包含相同汉字的所有其他条目 Kanji インデックス AIエージェントは、ユーザーが任意の頭詞漢字をクリックして同じ漢字を含むすべての他のエントリを探すことができる Kanji 인덱스 도구는 사용자가任意の 헤드워드 한자를 클릭하여 동일한 한자를 포함하는 모든 다른 항목을 찾을 수 있게 함 kanji-index es un índice de kanji para desarrolladores que permite a los usuarios encontrar entradas que contienen un kanji específico. kanji-index est un index de kanji pour les développeurs qui permet aux utilisateurs de trouver des entrées contenant un kanji spécifique. kanji-index ist ein Kanji-Index für Entwickler, der es Benutzern ermöglicht, Einträge zu finden, die ein bestimmtes Kanji enthalten. O índice de kanji é uma ferramenta de IA que permite aos usuários encontrar todas as entradas de dicionário que contêm um determinado kanji. Индекс канзи - это инструмент ИИ Агентов, который позволяет пользователям найти все словарные статьи, содержащие определенный канзи. فهرس الكانجي هو أداة ذكاء اصطناعي تمكن المستخدمين من العثور على جميع مدخلات القاموس التي تحتوي على كانجي معين. how to use kanji-index kanji-index alternative kanji-index setup guide what is kanji-index kanji-index vs other dictionaries kanji-index install japanese english dictionary kanji study resources language learning tools Kanji 索引工具 日英辞典 汉字索引页面 头词汉字链接 JSON 文件存储 多语言开发 Kanji 学习 AIエージェント Links headword kanji to kanji index pages Lists all entries containing a specific kanji, sorted by reading (hiragana order) Utilizes a master list in JSON format (kanji_list.json) for kanji mapping Employs a temporary extraction file (kanji_extracted.json) for data processing Supports directory structure organization for efficient data management kanji-index is a technical dictionary solution that enables users to click on any kanji in a dictionary headword to find all other entries containing that same kanji');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DonaldMurillo/momentum-cms/collection', 'community', 'DonaldMurillo', 'momentum-cms', 'DonaldMurillo/momentum-cms', 'collection', 0, 0, 48, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:31.459Z', 'a53a4a3d12e1aca2b7055518926174fa20911f2d3b7db517c7f0624c5397be5e', '{"id":"DonaldMurillo/momentum-cms/collection","name":"collection","description":{"en":"The collection skill generates a new collection file for Momentum CMS, following project conventions. It benefits developers by providing a standardized way of creating collections.","zh":"创建 Momentum CMS 集合文件，定义项目约定和集合位置","ja":"Momentum CMS コレクションファイルを作成し、プロジェクト規約とコレクションの位置を定義します","ko":"Momentum CMS 컬렉션 파일을 생성하여 프로젝트 규약과 컬렉션 위치를 정의합니다","es":"La colección en Momentum CMS se utiliza para definir conjuntos de datos. Se crea un nuevo archivo de colección en libs/example-config/src/collections/.","fr":"La collection dans Momentum CMS est utilisée pour définir des ensembles de données. Un nouveau fichier de collection est créé dans libs/example-config/src/collections/. ","de":"Die Sammlung in Momentum CMS wird verwendet, um Datensätze zu definieren. Eine neue Sammlungsdatei wird in libs/example-config/src/collections/ erstellt.","pt":"O skill de coleção permite criar novos arquivos de coleção seguindo as convenções do projeto no Momentum CMS.","ru":"Навык коллекции позволяет создавать новые файлы коллекции, следуя конвенциям проекта в Momentum CMS для ИИ Агентов.","ar":"مهمة المجموعة تمكن من إنشاء ملفات مجموعة جديدة متبعة الاتفاقيات المشروع في Momentum CMS للآليات الذكية."},"seo":{"title":{"en":"Collection: Setup Guide for Momentum CMS | AI Agent Skill","zh":"Momentum CMS 集合设置指南","ja":"Momentum CMS コレクション設定ガイド - AIエージェント","ko":"Momentum CMS 컬렉션 설정 가이드 - AI 도구","es":"Configuración de Colección en Momentum CMS: Guía de Imple...","fr":"Configurer une Collection dans Momentum CMS: Meilleures P...","de":"Momentum CMS Collection Einrichten: Schritt-für-Schritt-A...","pt":"Guia de Configuração de Coleção no Momentum CMS","ru":"Настройка коллекции в Momentum CMS: ИИ Агенты","ar":"دليل إعداد المجموعة في Momentum CMS للآليات الذكية"},"description":{"en":"Learn how to create a new collection file in Momentum CMS, following project conventions and best practices. Get started with our step-by-step guide.","zh":"了解如何创建 Momentum CMS 集合文件，定义项目约定和集合位置","ja":"Momentum CMS コレクションファイルの作成方法とプロジェクト規約、コレクションの位置について学びます - AIエージェント","ko":"Momentum CMS 컬렉션 파일 생성 방법과 프로젝트 규약, 컬렉션 위치에 대해 알아보세요 - AI 도구","es":"Aprende a crear y configurar colecciones en Momentum CMS. Obtenga información sobre las convenciones de proyecto y la ubicación de las colecciones.","fr":"Découvrez comment créer et configurer des collections dans Momentum CMS. Obtenez des informations sur les conventions de projet et l''emplacement des collecti...","de":"Erfahren Sie, wie Sie Sammlungen in Momentum CMS erstellen und konfigurieren. Informationen zu Projektkonventionen und SammlungsSpeicherort.","pt":"Aprenda a criar e configurar coleções no Momentum CMS com este guia passo a passo para desenvolvedores","ru":"Откройте для себя, как создать и настроить коллекции в Momentum CMS с помощью этого пошагового руководства для разработчиков и ИИ Агентов","ar":"تعلم كيفية إنشاء وتكوين المجموعات في Momentum CMS باستخدام هذا الدليل خطوة بخطوة لمطوري الآليات الذكية"},"definition":{"en":"Collection is a Momentum CMS feature that allows developers to create and manage data collections, defined in the libs/example-config/src/collections directory.","zh":"Momentum CMS 集合是指在 libs/example-config/src/collections/ 目录下定义的集合文件","ja":"Momentum CMS コレクションとは、libs/example-config/src/collections/ ディレクトリに定義されたコレクションファイルのことです","ko":"Momentum CMS 컬렉션은 libs/example-config/src/collections/ 디렉토리에 정의된 컬렉션 파일을 의미합니다","es":"Una colección en Momentum CMS es un conjunto de datos definido en un archivo específico.","fr":"Une collection dans Momentum CMS est un ensemble de données défini dans un fichier spécifique.","de":"Eine Sammlung in Momentum CMS ist ein Datensatz, der in einer bestimmten Datei definiert ist.","pt":"Coleção é um recurso do Momentum CMS que permite definir e gerenciar conjuntos de dados.","ru":"Коллекция - это функция Momentum CMS, которая позволяет определять и управлять наборами данных для ИИ Агентов.","ar":"المجموعة هي ميزة في Momentum CMS تمكن من تعريف وإدارة مجموعات البيانات للآليات الذكية."},"features":{"en":["Creates a new collection file at libs/example-config/src/collections/","Follows Momentum CMS project conventions for collection naming and location","Supports importing collections from @momentumcms/example-config/collections","Defines collections in a centralized location, avoiding individual app definitions","Uses the $ARGUMENTS variable to specify the collection name, such as posts or products"],"zh":["创建集合文件","定义项目约定","指定集合位置","使用 Momentum CMS","支持多语言","遵循项目规约"],"ja":["コレクションファイルの作成","プロジェクト規約の定義","コレクションの位置の指定","Momentum CMS の使用","多言語対応","プロジェクト規約の遵守"],"ko":["컬렉션 파일 생성","프로젝트 규약 정의","컬렉션 위치 지정","Momentum CMS 사용","다국어 지원","프로젝트 규약 준수"],"es":["Creación de un nuevo archivo de colección en libs/example-config/src/collections/","Definición de conjuntos de datos según las convenciones del proyecto","Importación de colecciones desde @momentumcms/example-config/collections","Compatibilidad con ejemplo de aplicaciones (example-angular, example-analog)","Nunca definir colecciones en aplicaciones individuales"],"fr":["Création d''un nouveau fichier de collection dans libs/example-config/src/collections/","Définition d''ensembles de données selon les conventions de projet","Importation de collections depuis @momentumcms/example-config/collections","Compatibilité avec les exemples d''applications (example-angular, example-analog)","Ne jamais définir des collections dans des applications individuelles"],"de":["Erstellung einer neuen Sammlungsdatei in libs/example-config/src/collections/","Definition von Datensätzen gemäß den Projektkonventionen","Import von Sammlungen aus @momentumcms/example-config/collections","Kompatibilität mit Beispielanwendungen (example-angular, example-analog)","Niemals Sammlungen in einzelnen Anwendungen definieren"],"pt":["Criação de arquivos de coleção seguindo convenções do projeto","Definição de coleções em libs/example-config/src/collections/","Importação de coleções em aplicativos via @momentumcms/example-config/collections","Suporte a criação de coleções personalizadas","Integração com aplicativos exemplo (example-angular, example-analog)"],"ru":["Создание файлов коллекции, следующих конвенциям проекта","Определение коллекций в libs/example-config/src/collections/","Импорт коллекций в приложения через @momentumcms/example-config/collections для ИИ Агентов","Поддержка создания пользовательских коллекций","Интеграция с примерами приложений (example-angular, example-analog)"],"ar":["إنشاء ملفات مجموعة متبعة الاتفاقيات المشروع","تعريف المجموعات في libs/example-config/src/collections/","استيراد المجموعات في التطبيقات عبر @momentumcms/example-config/collections للآليات الذكية","دعم إنشاء مجموعات مخصصة","التكامل مع تطبيقات مثال (example-angular, example-analog)"]},"keywords":{"en":["how to use collection in Momentum CMS","what is collection in Momentum CMS","collection setup guide","Momentum CMS collection alternative","collection vs custom data models","install collection in Momentum CMS","collection best practices for developers"],"zh":["Momentum CMS","集合文件","项目约定","集合位置","AI工具","Momentum CMS 集合设置","Momentum CMS 开发","Momentum CMS 教程"],"ja":["Momentum CMS","コレクションファイル","プロジェクト規約","コレクションの位置","AIエージェント","Momentum CMS コレクション設定","Momentum CMS 開発","Momentum CMS チュートリアル"],"ko":["Momentum CMS","컬렉션 파일","프로젝트 규약","컬렉션 위치","AI 도구","Momentum CMS 컬렉션 설정","Momentum CMS 개발","Momentum CMS 튜토리얼"],"es":["colección momentum cms","creación de colección","configuración de colección","convenciones de proyecto","herramientas de desarrollo","AI herramientas","desarrollo de aplicaciones","Momentum CMS"],"fr":["collection momentum cms","création de collection","configuration de collection","conventions de projet","outils de développement","Outils IA","développement d''applications","Momentum CMS"],"de":["Sammlung momentum cms","Erstellung von Sammlungen","Konfiguration von Sammlungen","Projektkonventionen","Entwicklungstools","KI-Tools","Anwendungsentwicklung","Momentum CMS"],"pt":["coleção momentum cms","configuração de coleção","criação de coleção","definição de coleção","importação de coleção","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["коллекция momentum cms","настройка коллекции","создание коллекции","определение коллекции","импорт коллекции","разработка программного обеспечения","инструменты разработки для ИИ Агентов"],"ar":["مجموعة momentum cms","إعداد المجموعة","إنشاء المجموعة","تعريف المجموعة","استيراد المجموعة","تطوير البرمجيات","أدوات التطوير للآليات الذكية"]}},"owner":"DonaldMurillo","repo":"momentum-cms","repoPath":"DonaldMurillo/momentum-cms","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"collection","description":"Generate a new Momentum CMS collection with fields, access control, and hooks","bodyPreview":"# Generate Momentum CMS Collection\n\nCreate a new collection file following project conventions.\n\n## Arguments\n\n- `$ARGUMENTS` - Collection name (e.g., \"posts\", \"products\", \"users\")\n\n## Important: Collection Location\n\nAll collections are defined in `libs/example-config/src/collections/`. Both example apps (`example-angular`, `example-analog`) import from `@momentumcms/example-config/collections`. **Never define collections in individual apps.**\n\n## Steps\n\n1. Create the collection file at `libs/ex","body":"# Generate Momentum CMS Collection\n\nCreate a new collection file following project conventions.\n\n## Arguments\n\n- `$ARGUMENTS` - Collection name (e.g., \"posts\", \"products\", \"users\")\n\n## Important: Collection Location\n\nAll collections are defined in `libs/example-config/src/collections/`. Both example apps (`example-angular`, `example-analog`) import from `@momentumcms/example-config/collections`. **Never define collections in individual apps.**\n\n## Steps\n\n1. Create the collection file at `libs/example-config/src/collections/<name>.collection.ts`\n\n2. Use this template:\n\n```typescript\nimport {\n  defineCollection,\n  text,\n  richText,\n  number,\n  date,\n  checkbox,\n  select,\n  relationship,\n} from ''@momentumcms/core'';\n\nexport const <PascalName> = defineCollection({\n  slug: ''<kebab-name>'',\n\n  admin: {\n    useAsTitle: ''title'', // or ''name'' - the field to display as title\n    defaultColumns: [''title'', ''createdAt''],\n    group: ''Content'', // Admin sidebar group\n  },\n\n  access: {\n    read: () => true,\n    create: ({ req }) => !!req.user,\n    update: ({ req }) => req.user?.role === ''admin'',\n    delete: ({ req }) => req.user?.role === ''admin'',\n  },\n\n  hooks: {\n    beforeChange: [],\n    afterChange: [],\n  },\n\n  fields: [\n    text(''title'', { required: true }),\n    // Add more fields as needed\n  ],\n});\n```\n\n3. Export from `libs/example-config/src/collections/index.ts`:\n\n```typescript\n// Add import at top\nimport { <PascalName> } from ''./<name>.collection'';\n\n// Add to the collections array\nexport const collections: CollectionConfig[] = [\n  // ... existing collections,\n  <PascalName>,\n];\n\n// Add to named exports\nexport {\n  // ... existing exports,\n  <PascalName>,\n};\n```\n\nBoth example apps automatically pick up changes since they import from `@momentumcms/example-config/collections`.\n\n4. Remind user: if migration mode is enabled, run `nx run <app>:migrate:generate` after collection changes to create a migration file.\n\n## Field Types Available\n\n### Text Input Fields\n- `text(name, options)` - Short text with optional min/max length\n- `textarea(name, options)` - Multi-line text with optional rows\n- `richText(name, options)` - Rich text editor\n- `email(name, options)` - Email input\n- `password(name, options)` - Password input with optional min length\n\n### Numeric & Date Fields\n- `number(name, options)` - Numeric value with optional min/max/step\n- `date(name, options)` - Date/datetime picker\n\n### Boolean & Selection Fields\n- `checkbox(name, options)` - Boolean checkbox\n- `select(name, { options: [...] })` - Dropdown select (supports `hasMany`)\n- `radio(name, { options: [...] })` - Radio button group\n\n### Media & Files\n- `upload(name, options)` - File upload with MIME type filtering\n\n### Relationship & Data Fields\n- `relationship(name, { collection: () => Ref })` - Reference to another collection (supports `hasMany`, polymorphic)\n- `array(name, { fields: [...] })` - Array of nested fields\n- `group(name, { fields: [...] })` - Nested object grouping\n- `blocks(name, { blocks: [...] })` - Block-based content\n- `json(name, options)` - Raw JSON field\n- `point(name, options)` - Geolocation point\n- `slug(name, { from: ''fieldName'' })` - Auto-generated slug from another field\n\n### Layout Fields (non-data storing)\n- `tabs(tabs: [...])` - Tabbed sections for organization\n- `collapsible(label, { fields: [...] })` - Collapsible section\n- `row(fields: [...])` - Horizontal row layout\n"},"lastSynced":"2026-03-08T02:01:31.459Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing standardized collection creation for Momentum CMS","zh":"非常适合需要为 Momentum CMS 创建标准化集合的开发者代理","ja":"Momentum CMS の標準化されたコレクション作成が必要な開発者エージェントに最適","ko":"Momentum CMS를 위한 표준화된 컬렉션 생성이 필요한 개발자 에이전트에게 적합","es":"Perfecto para Agentes de Desarrollador que necesitan creación de colecciones estandarizadas para Momentum CMS","fr":"Parfait pour les agents de développement nécessitant une création de collection standardisée pour Momentum CMS","de":"Perfekt für Developer-Agents, die eine standardisierte Sammlungserstellung für Momentum CMS benötigen","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de criação de coletânea padronizada para Momentum CMS","ru":"Идеально для агентов-разработчиков, которым требуется стандартизированная коллекция для Momentum CMS","ar":"مثالي للوكلاء المطورين الذين يحتاجون إلى إنشاء مجموعة موحدة لمomentum cms"},"recommendation":{"en":"Empowers agents to generate new collection files following project conventions, utilizing Momentum CMS and importing from @momentumcms/example-config/collections, while adhering to specific collection locations like libs/example-config/src/collections/","zh":"赋予代理生成新的集合文件，遵循项目惯例，利用 Momentum CMS 并从 @momentumcms/example-config/collections 导入，同时遵守特定的集合位置，如 libs/example-config/src/collections/","ja":"エージェントが新しいコレクションファイルを生成できるようにし、プロジェクトの規約に従い、Momentum CMS を使用し、@momentumcms/example-config/collections からインポートし、libs/example-config/src/collections/ のような特定のコレクションの場所に従う","ko":"에이전트가 새로운 컬렉션 파일을 생성할 수 있도록 해주며, 프로젝트 규약을 따르며, Momentum CMS를 사용하며, @momentumcms/example-config/collections에서 가져오고, libs/example-config/src/collections/와 같은 특정 컬렉션 위치를 따름","es":"Habilita a los agentes a generar nuevos archivos de colección siguiendo las convenciones del proyecto, utilizando Momentum CMS e importando desde @momentumcms/example-config/collections, mientras se adhiere a ubicaciones de colección específicas como libs/example-config/src/collections/","fr":"Permet aux agents de générer de nouveaux fichiers de collection en suivant les conventions de projet, en utilisant Momentum CMS et en important depuis @momentumcms/example-config/collections, tout en respectant des emplacements de collection spécifiques comme libs/example-config/src/collections/","de":"Ermöglicht es Agenten, neue Sammlungsdateien zu generieren, die den Projektübereinkünften folgen, Momentum CMS verwenden und von @momentumcms/example-config/collections importieren, während sie bestimmte Sammlungsstandorte wie libs/example-config/src/collections/ einhalten","pt":"Habilita os agentes a gerar novos arquivos de coletânea seguindo convenções de projeto, utilizando Momentum CMS e importando de @momentumcms/example-config/collections, enquanto adere a locais de coletânea específicos como libs/example-config/src/collections/","ru":"Наделяет агентов возможностью генерировать новые файлы коллекции в соответствии с проектными конвенциями, используя Momentum CMS и импортируя из @momentumcms/example-config/collections, при этом придерживаясь определенных мест расположения коллекций, таких как libs/example-config/src/collections/","ar":"يمكّن الوكلاء من إنشاء ملفات مجموعة جديدة متوافقة مع اتفاقيات المشروع، باستخدام Momentum CMS واستيرادها من @momentumcms/example-config/collections، مع الالتزام بمواقع المجموعة المحددة مثل libs/example-config/src/collections/"},"useCases":{"en":["Generating new collection files for Momentum CMS projects","Standardizing collection creation across multiple example apps","Automating collection imports from @momentumcms/example-config/collections"],"zh":["为 Momentum CMS 项目生成新的集合文件","跨多个示例应用标准化集合创建","自动从 @momentumcms/example-config/collections 导入集合"],"ja":["Momentum CMS プロジェクトの新しいコレクションファイルを生成する","複数のサンプルアプリケーションでコレクション作成を標準化する","@momentumcms/example-config/collections からコレクションを自動でインポートする"],"ko":["Momentum CMS 프로젝트를 위한 새로운 컬렉션 파일 생성","여러 예제 애플리케이션에서 컬렉션 생성을 표준화","@momentumcms/example-config/collections에서 컬렉션을 자동으로 가져오기"],"es":["Generación de nuevos archivos de colección para proyectos de Momentum CMS","Estandarización de la creación de colecciones en varias aplicaciones de ejemplo","Automatización de las importaciones de colecciones desde @momentumcms/example-config/collections"],"fr":["Génération de nouveaux fichiers de collection pour les projets Momentum CMS","Standardisation de la création de collection dans plusieurs applications exemples","Automatisation des imports de collection depuis @momentumcms/example-config/collections"],"de":["Generierung neuer Sammlungsdateien für Momentum-CMS-Projekte","Standardisierung der Sammlungserstellung in mehreren Beispiel-Apps","Automatisierung der Sammlungsimporte von @momentumcms/example-config/collections"],"pt":["Gerar novos arquivos de coletânea para projetos Momentum CMS","Padronizar a criação de coletâneas em vários aplicativos de exemplo","Automatizar a importação de coletâneas de @momentumcms/example-config/collections"],"ru":["Генерировать новые файлы коллекции для проектов Momentum CMS","Стандартизировать создание коллекций в нескольких примерах приложений","Автоматизировать импорт коллекций из @momentumcms/example-config/collections"],"ar":["إنشاء ملفات مجموعة جديدة لمشاريع momentum cms","توحيد إنشاء المجموعات عبر تطبيقات مثال متعددة","تأتمتة استيراد المجموعات من @momentumcms/example-config/collections"]},"limitations":{"en":["Collections must be defined in libs/example-config/src/collections/","Individual apps should not define collections","Requires adherence to Momentum CMS project conventions"],"zh":["集合必须定义在 libs/example-config/src/collections/ 中","单个应用不应定义集合","需要遵守 Momentum CMS 项目惯例"],"ja":["コレクションは libs/example-config/src/collections/ に定義する必要がある","個々のアプリケーションがコレクションを定義することはできない","Momentum CMS プロジェクトの規約に従う必要がある"],"ko":["컬렉션은 libs/example-config/src/collections/에 정의되어야 함","개별 애플리케이션이 컬렉션을 정의해서는 안 됨","Momentum CMS 프로젝트 규약을 따라야 함"],"es":["Las colecciones deben estar definidas en libs/example-config/src/collections/","Las aplicaciones individuales no deben definir colecciones","Requiere la adhesión a las convenciones del proyecto Momentum CMS"],"fr":["Les collections doivent être définies dans libs/example-config/src/collections/","Les applications individuelles ne doivent pas définir des collections","Nécessite le respect des conventions de projet Momentum CMS"],"de":["Die Sammlungen müssen in libs/example-config/src/collections/ definiert werden","Einzelne Apps sollten keine Sammlungen definieren","Erfordert die Einhaltung der Momentum-CMS-Projektübereinkünfte"],"pt":["As coletâneas devem ser definidas em libs/example-config/src/collections/","Os aplicativos individuais não devem definir coletâneas","Exige adesão às convenções de projeto Momentum CMS"],"ru":["Коллекции должны быть определены в libs/example-config/src/collections/","Индивидуальные приложения не должны определять коллекции","Требует соблюдения проектных конвенций Momentum CMS"],"ar":["يجب تعريف المجموعات في libs/example-config/src/collections/","لا ينبغي لتطبيقات الفرد تعريف المجموعات","يتطلب الالتزام باتفاقيات مشروع Momentum CMS"]},"version":4},"contentHash":"a53a4a3d12e1aca2b7055518926174fa20911f2d3b7db517c7f0624c5397be5e","qualityScore":48}');
