INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DonaldMurillo/momentum-cms/collection', 'collection', 'DonaldMurillo', 'momentum-cms', 'community', 'collection DonaldMurillo momentum-cms community The collection skill generates a new collection file for Momentum CMS, following project conventions. It benefits developers by providing a standardized way of creating collections. 创建 Momentum CMS 集合文件，定义项目约定和集合位置 Momentum CMS コレクションファイルを作成し、プロジェクト規約とコレクションの位置を定義します Momentum CMS 컬렉션 파일을 생성하여 프로젝트 규약과 컬렉션 위치를 정의합니다 La colección en Momentum CMS se utiliza para definir conjuntos de datos. Se crea un nuevo archivo de colección en libs/example-config/src/collections/. La collection dans Momentum CMS est utilisée pour définir des ensembles de données. Un nouveau fichier de collection est créé dans libs/example-config/src/collections/. Die Sammlung in Momentum CMS wird verwendet, um Datensätze zu definieren. Eine neue Sammlungsdatei wird in libs/example-config/src/collections/ erstellt. O skill de coleção permite criar novos arquivos de coleção seguindo as convenções do projeto no Momentum CMS. Навык коллекции позволяет создавать новые файлы коллекции, следуя конвенциям проекта в Momentum CMS для ИИ Агентов. مهمة المجموعة تمكن من إنشاء ملفات مجموعة جديدة متبعة الاتفاقيات المشروع في Momentum CMS للآليات الذكية. how to use collection in Momentum CMS what is collection in Momentum CMS collection setup guide Momentum CMS collection alternative collection vs custom data models install collection in Momentum CMS collection best practices for developers Momentum CMS 集合文件 项目约定 集合位置 AI工具 Momentum CMS 集合设置 Momentum CMS 开发 Momentum CMS 教程 Creates a new collection file at libs/example-config/src/collections/ Follows Momentum CMS project conventions for collection naming and location Supports importing collections from @momentumcms/example-config/collections Defines collections in a centralized location, avoiding individual app definitions Uses the $ARGUMENTS variable to specify the collection name, such as posts or products Collection is a Momentum CMS feature that allows developers to create and manage data collections, defined in the libs/example-config/src/collections directory.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mepuka/crate/effect-layers-services', 'community', 'mepuka', 'crate', 'mepuka/crate', 'effect-layers-services', 0, 0, 48, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:33.968Z', 'e1710922ad9a16b3e540930d561433ac1c6022b13ebeeecb50458e2ac2ac157d', '{"id":"mepuka/crate/effect-layers-services","name":"effect-layers-services","description":{"en":"The effect-layers-services skill enables developers to define services and provide layers for dependency injection and infrastructure composition, benefiting developers who need to swap test and live implementations.","zh":"Effect Layers Services 提供了 DI 边界和服务组合的能力，使用 TypeScript 实现","ja":"Effect Layers Services は DI 境界とサービス構成を可能にする、TypeScript で実装された機能です","ko":"Effect Layers Services는 DI 경계와 서비스 구성 기능을 제공하는 TypeScript로 구현된 기능입니다","es":"Effect-layers-services es una habilidad que permite a los desarrolladores definir servicios y capas en sus aplicaciones, mejorando la gestión de dependencias y la infraestructura","fr":"Effect-layers-services est une compétence qui permet aux développeurs de définir des services et des couches dans leurs applications, améliorant la gestion des dépendances et l''infrastructure","de":"Effect-layers-services ist eine Fähigkeit, die es Entwicklern ermöglicht, Dienste und Schichten in ihren Anwendungen zu definieren, verbessert die Verwaltung von Abhängigkeiten und Infrastruktur","pt":"O effect-layers-services é uma ferramenta para melhorar a composição de infraestrutura e serviços em aplicativos, permitindo a definição de serviços e camadas de forma eficaz.","ru":"Effect-layers-services - это инструмент для разработки масштабируемых приложений, позволяющий определять сервисы и слои инфраструктуры эффективно.","ar":"effect-layers-services هي أداة لتحسين بنية التطبيقات وتحقيق خدمات متميزة، تمكن من تعريف الخدمات والطبقات بفعالية"},"seo":{"title":{"en":"effect-layers-services: Dependency Injection Setup Guide ...","zh":"Effect Layers Services_SETUP GUIDE","ja":"Effect Layers Services_BEST PRACTICES - AIエージェント","ko":"Effect Layers Services_IMPLEMENTATION TIPS - AI 도구","es":"Guía de configuración de effect-layers-services para desa...","fr":"Mise en place d''effect-layers-services pour les développeurs","de":"Einrichtungsleitfaden für effect-layers-services für Entw...","pt":"Guia de Configuração do effect-layers-services para Desen...","ru":"ИИ Агенты: Настройка effect-layers-services для Разработч...","ar":"دليل إعداد effect-layers-services لمنشئي التطبيقات"},"description":{"en":"Discover how to leverage effect-layers-services for seamless dependency injection and infrastructure composition. Get started with our expert guide and optim...","zh":"了解 Effect Layers Services 的技术细节，实现 DI 边界和服务组合","ja":"Effect Layers Services のテクニカルな詳細を学び、DI 境界とサービス構成を実現する","ko":"Effect Layers Services의 기술적 세부 사항을 학습하고 DI 경계와 서비스 구성 구현","es":"Aprende a utilizar effect-layers-services para definir servicios y capas en tus aplicaciones, mejora la gestión de dependencias y la infraestructura","fr":"Découvrez comment utiliser effect-layers-services pour définir des services et des couches dans vos applications, améliorez la gestion des dépendances et l''i...","de":"Erfahren Sie, wie Sie effect-layers-services verwenden, um Dienste und Schichten in Ihren Anwendungen zu definieren, verbessern Sie die Verwaltung von Abhäng...","pt":"Aprenda a utilizar o effect-layers-services para melhorar a composição de infraestrutura e serviços em seus aplicativos","ru":"Откройте для себя возможности effect-layers-services для разработки масштабируемых приложений с помощью ИИ Агентов","ar":"اكتشف كيف يمكنك استخدام effect-layers-services لتحسين بنية التطبيقات وتحقيق خدمات متميزة"},"definition":{"en":"effect-layers-services is a skill that allows developers to define services and provide layers for dependency injection and infrastructure composition using TypeScript and Effect.","zh":"Effect Layers Services 是一种提供 DI 边界和服务组合的技术","ja":"Effect Layers Services は DI 境界とサービス構成を提供する技術です","ko":"Effect Layers Services는 DI 경계와 서비스 구성 기능을 제공하는 기술입니다","es":"Effect-layers-services es una habilidad que permite definir servicios y capas en aplicaciones, utilizando TypeScript y Effect","fr":"Effect-layers-services est une compétence qui permet de définir des services et des couches dans des applications, utilisant TypeScript et Effect","de":"Effect-layers-services ist eine Fähigkeit, die es ermöglicht, Dienste und Schichten in Anwendungen zu definieren, unter Verwendung von TypeScript und Effect","pt":"O effect-layers-services é uma técnica de programação que permite a definição de serviços e camadas de infraestrutura de forma modular e reutilizável","ru":"Effect-layers-services - это техника программирования, позволяющая определять сервисы и слои инфраструктуры модульно и повторно используя","ar":"effect-layers-services هي تقنية برمجية تمكن من تعريف الخدمات والطبقات بطرق متوافقة ومرتجعة"},"features":{"en":["Defines services using Effect.Service and TypeScript","Provides layers for infrastructure composition, including logger, db, and http","Enables dependency injection with DI boundaries and swapping test/live implementations","Supports composition of infrastructure once for the entire app","Utilizes Effect.gen and Effect.provide for program generation and layer provision"],"zh":["使用 TypeScript 实现 DI 边界","提供服务组合功能","支持 Effect.Service 和 Effect.gen","实现 logger、db 和 http 的组合","支持测试和生产环境的切换"],"ja":["TypeScript で DI 境界を実現","サービス構成機能を提供","Effect.Service と Effect.gen をサポート","logger、db と http の構成を実現","テストと生産環境の切り替えをサポート"],"ko":["TypeScript로 DI 경계 구현","서비스 구성 기능 제공","Effect.Service와 Effect.gen 지원","logger, db 및 http의 구성 구현","테스트 및 프로덕션 환경 전환 지원"],"es":["Definir servicios con Effect.Service","Proporcionar capas con Effect.provide","Utilizar TypeScript para definir servicios y capas","Mejorar la gestión de dependencias con DI","Componer infraestructura con logger, db y http"],"fr":["Définir des services avec Effect.Service","Fournir des couches avec Effect.provide","Utiliser TypeScript pour définir des services et des couches","Améliorer la gestion des dépendances avec DI","Composer l''infrastructure avec logger, db et http"],"de":["Dienste mit Effect.Service definieren","Schichten mit Effect.provide bereitstellen","TypeScript verwenden, um Dienste und Schichten zu definieren","Verwaltung von Abhängigkeiten mit DI verbessern","Infrastruktur mit logger, db und http komponieren"],"pt":["Definição de serviços com Effect.Service","Criação de camadas de infraestrutura com Effect.gen","Composição de serviços e camadas de forma eficaz","Suporte a testes e implementações ao vivo","Integração com logger, db e http"],"ru":["Определение сервисов с помощью Effect.Service","Создание слоев инфраструктуры с помощью Effect.gen","Композиция сервисов и слоев эффективно","Поддержка тестирования и реализации в режиме реального времени","Интеграция с logger, db и http"],"ar":["تعريف الخدمات باستخدام Effect.Service","إنشاء طبقات البنية التحتية باستخدام Effect.gen","دمج الخدمات والطبقات بفعالية","دعم الاختبارات والتنفيذ المباشر","تكامل مع logger و db و http"]},"keywords":{"en":["how to use effect-layers-services","effect-layers-services alternative","effect-layers-services setup guide","what is effect-layers-services","effect-layers-services vs dependency injection frameworks","effect-layers-services install","effect-layers-services tutorial","TypeScript dependency injection","Effect layers and services"],"zh":["Effect Layers Services","DI 边界","服务组合","TypeScript","Effect.Service","Effect.gen","logger","db","http"],"ja":["Effect Layers Services","DI 境界","サービス構成","TypeScript","Effect.Service","Effect.gen","logger","db","http","AIエージェント"],"ko":["Effect Layers Services","DI 경계","서비스 구성","TypeScript","Effect.Service","Effect.gen","logger","db","http","AI 도구"],"es":["effect-layers-services","TypeScript","Effect","DI","logger","db","http","desarrollo de aplicaciones","gestión de dependencias"],"fr":["effect-layers-services","TypeScript","Effect","DI","logger","db","http","développement d''applications","gestion des dépendances"],"de":["effect-layers-services","TypeScript","Effect","DI","logger","db","http","Anwendungsentwicklung","Abhängigkeitsverwaltung"],"pt":["effect-layers-services","desenvolvimento de aplicativos","composição de infraestrutura","serviços modulares","testes e implementações","logger","db","http","programação funcional"],"ru":["effect-layers-services","разработка приложений","композиция инфраструктуры","модульные сервисы","тестирование и реализация","logger","db","http","функциональное программирование"],"ar":["effect-layers-services","تحديث التطبيقات","بنية التطبيقات","خدمات متوافقة","اختبارات وتنفيذ","logger","db","http","برمجة وظيفية"]}},"owner":"mepuka","repo":"crate","repoPath":"mepuka/crate","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.301Z","topics":[],"category":"community","skillMd":{"name":"effect-layers-services","description":"Define services, provide layers, compose dependencies, and switch live/test. Use for DI boundaries and app composition.","bodyPreview":"# Layers & Services\n\n## When to use\n- You need DI boundaries or swapping test/live implementations\n- You want to compose infra (logger, db, http) once for the app\n\n## Define Service\n```ts\nclass UserRepo extends Effect.Service<UserRepo>()(\"UserRepo\", {\n  sync: () => ({ find: (id: string) => Effect.succeed({ id }) })\n}) {}\n```\n\n## Provide Layer\n```ts\nconst program = Effect.gen(function* () {\n  const repo = yield* UserRepo\n  return yield* repo.find(\"123\")\n}).pipe(Effect.provide(UserRepo.Default))\n`","body":"# Layers & Services\n\n## When to use\n- You need DI boundaries or swapping test/live implementations\n- You want to compose infra (logger, db, http) once for the app\n\n## Define Service\n```ts\nclass UserRepo extends Effect.Service<UserRepo>()(\"UserRepo\", {\n  sync: () => ({ find: (id: string) => Effect.succeed({ id }) })\n}) {}\n```\n\n## Provide Layer\n```ts\nconst program = Effect.gen(function* () {\n  const repo = yield* UserRepo\n  return yield* repo.find(\"123\")\n}).pipe(Effect.provide(UserRepo.Default))\n```\n\n## Compose\n```ts\nconst AppLayer = Layer.merge(UserRepo.Default, Logger.Default)\n```\n\n## Test vs Live\n```ts\nconst layer = process.env.NODE_ENV === \"test\" ? UserRepoTest : UserRepo.Default\n```\n\n## Guidance\n- Services define interfaces; Layers bind implementations\n- Compose layers at the app boundary; keep handlers unaware of wiring\n- Use `.Default` for quick live/test setup; add custom layers as needed\n\n## Pitfalls\n- Circular layer dependencies → split modules, provide from above\n- Providing layers too deep → centralize to avoid duplication and confusion\n\n## Cross-links\n- Foundations: requirement channel `R` and provisioning\n- Resources: scoped resources exposed via layers\n- EffectPatterns inspiration: https://github.com/PaulJPhilp/EffectPatterns\n\n## Local Source Reference\n\n**CRITICAL: Search local Effect source before implementing**\n\nThe full Effect source code is available at `docs/effect-source/`. Always search the actual implementation before writing Effect code.\n\n### Key Source Files\n- Layer: `docs/effect-source/effect/src/Layer.ts`\n- Effect: `docs/effect-source/effect/src/Effect.ts`\n- Context: `docs/effect-source/effect/src/Context.ts`\n\n### Example Searches\n```bash\n# Find Layer composition patterns\ngrep -F \"Layer.merge\" docs/effect-source/effect/src/Layer.ts\ngrep -F \"Layer.provide\" docs/effect-source/effect/src/Layer.ts\n\n# Study Effect.Service patterns\ngrep -F \"Effect.Service\" docs/effect-source/effect/src/Effect.ts\n\n# Find Context usage\ngrep -F \"Tag\" docs/effect-source/effect/src/Context.ts\ngrep -F \"make\" docs/effect-source/effect/src/Context.ts\n\n# Look at Layer test examples\ngrep -F \"Layer.\" docs/effect-source/effect/test/Layer.test.ts\n```\n\n### Workflow\n1. Identify the Layer or Service API you need\n2. Search `docs/effect-source/effect/src/Layer.ts` for the implementation\n3. Study the types and composition patterns\n4. Look at test files for usage examples\n5. Write your code based on real implementations\n\n**Real source code > documentation > assumptions**\n\n## References\n- Agent Skills overview: https://www.anthropic.com/news/skills\n- Skills guide: https://docs.claude.com/en/docs/claude-code/skills\n\n"},"lastSynced":"2026-03-08T02:01:33.968Z","agentAnalysis":{"suitability":{"en":"Perfect for TypeScript Agents needing advanced dependency injection and infrastructure composition capabilities.","zh":"非常适合需要高级依赖注入和基础设施组合功能的TypeScript Agents。","ja":"TypeScriptエージェントが高度な依存性の注入とインフラストラクチャの構成機能を必要とする場合に最適です。","ko":"고급 의존성 주입 및 인프라 구성 기능이 필요한 TypeScript 에이전트에 적합합니다.","es":"Ideal para agentes de TypeScript que necesitan capacidades de inyección de dependencias avanzadas y composición de infraestructura.","fr":"Parfait pour les agents TypeScript nécessitant une injection de dépendances avancée et des capacités de composition d''infrastructure.","de":"Perfekt für TypeScript-Agents, die erweiterte Abhängigkeitsinjektion und Infrastrukturzusammensetzungsfunktionen benötigen.","pt":"Perfeito para Agentes TypeScript que necessitam de injeção de dependência avançada e capacidades de composição de infraestrutura.","ru":"Идеально подходит для агентов TypeScript, требующих расширенной внедрения зависимостей и возможностей составления инфраструктуры.","ar":"مثالي لعميل TypeScript الذي يحتاج إلى حقن تبعيات متقدم و возможيات تركيب البنية التحتية."},"recommendation":{"en":"Empowers agents to define services and provide layers for dependency injection and infrastructure composition using Effect.Service and Effect.provide, enabling seamless swapping of test and live implementations with libraries like Effect.","zh":"使得代理能够使用Effect.Service和Effect.provide定义服务，并提供依赖注入和基础设施组合的层，实现使用Effect等库的测试和生產实现的无缝切换。","ja":"エージェントがEffect.ServiceとEffect.provideを使用してサービスを定義し、依存性の注入とインフラストラクチャの構成のレイヤーを提供できるようにし、Effectなどのライブラリを使用してテストと本番の実装をシームレスに切り替えることができる。","ko":"에이전트가 Effect.Service 및 Effect.provide를 사용하여 서비스를 정의하고, 의존성 주입 및 인프라 구성의 계층을 제공하여 Effect 등의 라이브러리를 사용하여 테스트 및 라이브 구현을無縫切换할 수 있도록 합니다.","es":"Habilita a los agentes a definir servicios y proporcionar capas para la inyección de dependencias y la composición de infraestructura utilizando Effect.Service y Effect.provide, lo que permite un intercambio sin problemas de implementaciones de prueba y en vivo con bibliotecas como Effect.","fr":"Permet aux agents de définir des services et de fournir des couches pour l''injection de dépendances et la composition d''infrastructure en utilisant Effect.Service et Effect.provide, ce qui permet un échange sans heurts des implementations de test et de production avec des bibliothèques comme Effect.","de":"Ermöglicht es Agenten, Dienste zu definieren und Schichten für die Abhängigkeitsinjektion und Infrastrukturzusammensetzung bereitzustellen, indem Effect.Service und Effect.provide verwendet werden, was ein nahtloses Umschalten zwischen Test- und Live-Implementierungen mit Bibliotheken wie Effect ermöglicht.","pt":"Habilita os agentes a definir serviços e fornecer camadas para injeção de dependência e composição de infraestrutura usando Effect.Service e Effect.provide, permitindo a substituição transparente de implementações de teste e ao vivo com bibliotecas como Effect.","ru":"Наделяет агентов возможностью определять сервисы и предоставлять слои для внедрения зависимостей и составления инфраструктуры с использованием Effect.Service и Effect.provide, что позволяет бесшовно заменять реализации тестирования и рабочие реализации с использованием библиотек типа Effect.","ar":"تمكّن الوكيل من تعريف الخدمات وتوفير طبقات لحقن التبعيات وتركيب البنية التحتية باستخدام Effect.Service و Effect.provide، مما يسمح بالاستبدال السلس لتنفيذ الاختبار والمباشر باستخدام مكتبات مثل Effect."},"useCases":{"en":["Defining services for dependency injection","Composing infrastructure layers for logging and database interactions","Swapping test and live implementations for robust testing"],"zh":["定义依赖注入的服务","为日志和数据库交互组成基础设施层","交换测试和生產实现以进行强大的测试"],"ja":["依存性の注入のサービスを定義する","ログとデータベースのインタラクションのためのインフラストラクチャ層を構成する","テストと本番の実装を交換して堅牢なテストを行う"],"ko":["의존성 주입을 위한 서비스 정의","로그 및 데이터베이스 상호 작용을 위한 인프라 계층 구성","강력한 테스트를 위한 테스트 및 라이브 구현 교체"],"es":["Definir servicios para la inyección de dependencias","Componer capas de infraestructura para las interacciones de registro y base de datos","Intercambiar implementaciones de prueba y en vivo para pruebas robustas"],"fr":["Définir des services pour l''injection de dépendances","Composer des couches d''infrastructure pour les interactions de journalisation et d''interaction avec la base de données","Échanger des implementations de test et de production pour des tests robustes"],"de":["Dienste für die Abhängigkeitsinjektion definieren","Infrastrukturschichten für Protokoll- und Datenbankinteraktionen zusammensetzen","Test- und Live-Implementierungen für robuste Tests austauschen"],"pt":["Definir serviços para injeção de dependência","Compor camadas de infraestrutura para interações de logging e banco de dados","Substituir implementações de teste e ao vivo para testes robustos"],"ru":["Определение сервисов для внедрения зависимостей","Составление слоев инфраструктуры для взаимодействия с логированием и базами данных","Замена реализаций тестирования и рабочих реализаций для надёжного тестирования"],"ar":["تحديد الخدمات لحقن التبعيات","تركيب طبقات البنية التحتية لمعاملات التسجيل والتفاعل مع قواعد البيانات","استبدال تنفيذ الاختبار والتنفيذ المباشر للاختبارات القوية"]},"limitations":{"en":["Requires Effect library integration","TypeScript compatibility only"],"zh":["需要Effect库集成","仅支持TypeScript兼容性"],"ja":["Effectライブラリの統合が必要","TypeScriptとの互換性のみをサポート"],"ko":["Effect 라이브러리 통합 필요","TypeScript와의 호환성만 지원"],"es":["Requiere la integración de la biblioteca Effect","Compatibilidad solo con TypeScript"],"fr":["Nécessite l''intégration de la bibliothèque Effect","Compatibilité uniquement avec TypeScript"],"de":["Benötigt die Integration der Effect-Bibliothek","Kompatibilität nur mit TypeScript"],"pt":["Requer integração com a biblioteca Effect","Compatibilidade apenas com TypeScript"],"ru":["Требует интеграции с библиотекой Effect","Совместимость только с TypeScript"],"ar":["يتطلب تكامل مع مكتبة Effect","التوافق فقط مع TypeScript"]},"version":4},"contentHash":"e1710922ad9a16b3e540930d561433ac1c6022b13ebeeecb50458e2ac2ac157d","qualityScore":48}');
